_SRC_C2_TRAIN = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""\nTrain multi-height, multi-variable WRF bias-correction models.\n\nMain purpose\n------------\nTrain on one tower/site CSV (A tower), then save all artifacts required for\nexternal generalization to another tower/site CSV (B tower):\n    - Keras model\n    - X scaler\n    - y scaler parameters\n    - selected feature list\n    - target definition list\n    - metadata/config JSON\n\nCompared with the original multi-height wind-speed-only script, this version:\n    1) predicts multiple target variables, not only wind speed;\n    2) supports direct WS/WD targets and legacy u/v targets; final C0-C8 uses direct WS/WD;\n    3) predicts TKE using a log residual: log1p(OBS_TKE)-log1p(WRF_TKE);\n    4) supports two noMOST feature modes:\n         a) all_features\n         b) corrFDR_selected_features using |Pearson r| >= 0.30 and BH-FDR q <= 0.10;\n    5) uses a masked Huber loss so missing targets do not remove the whole sample;\n    6) saves the fitted scalers and metadata for A-tower -> B-tower generalization.\n\nRecommended usage\n-----------------\nA-tower training:\n    python train_multivar_profile_bias_correction.py \\\n        --train_csv path/to/ML_ready_ref10_A_d03.csv \\\n        --output_root path/to/output \\\n        --network CNN_LSTM \\\n        --feature_modes all corrFDR\n\nThe generalization script should be kept in the same folder as this file, because\nit imports the common data-preparation utilities defined here.\n"""\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport math\nimport random\nimport re\nimport warnings\nimport textwrap\nfrom dataclasses import asdict, dataclass\nfrom pathlib import Path\nfrom typing import Dict, Iterable, List, Optional, Sequence, Tuple\n\nwarnings.filterwarnings("ignore")\n\nimport joblib\nimport numpy as np\nimport pandas as pd\nimport matplotlib.pyplot as plt\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.metrics import mean_absolute_error, mean_squared_error\n\n# ========================= User configuration =========================\n# Edit this block, then run directly:\n#     python train_multivar_profile_bias_correction_heads_pinn.py\n\nTIME_COL = "北京时间"\n\nUSE_CODE_CONFIG = True\n\n# A-tower training CSV. Change this to your real A-tower ML_ready file.\nCODE_TRAIN_CSV = r"D:\\wake\\WRF_RANS_wake\\xilinhaote\\result\\bias_correction\\1km\\inputdata\\data_post_new\\four_sites_full\\NO1_1159\\ML_ready_ref10_A_d03.csv"\n\n# Optional easier tower selection for xilinhaote.\n# If CODE_TRAIN_SITE_CONTAINS is not None, the script searches CODE_ML_READY_ROOT\n# with CODE_TRAIN_FILE_GLOB and uses the first file whose path contains this text.\n# Example: CODE_TRAIN_SITE_CONTAINS = "NO2_1107"\nCODE_ML_READY_ROOT = Path(r"D:\\wake\\WRF_RANS_wake\\xilinhaote\\result\\bias_correction\\1km\\inputdata\\data_post_new\\four_sites_full")\nCODE_TRAIN_FILE_GLOB = "**/ML_ready_ref10_*_d03.csv"\nCODE_TRAIN_SITE_CONTAINS = "NO1_1159"\n\n# Output folder for saved A-tower models.\nCODE_OUTPUT_ROOT = r"D:\\wake\\WRF_RANS_wake\\xilinhaote\\result\\bias_correction\\1km\\correction\\muti_height\\training\\tower1\\CNN_LSTM_new1\\output_A_train_heads_PINN"\n\n# Choose "CNN_LSTM" or "TCN".\nCODE_NETWORK = "CNN_LSTM"\n\n# Cases to run. Recommended full set:\n#   noMOST_all\n#   noMOST_corrFDR\n#   PINN_MOSTmag_all\n#   PINN_MOSTmag_corrFDR\nCODE_CASES = ["noMOST_all", "noMOST_corrFDR", "PINN_MOSTmag_all", "PINN_MOSTmag_corrFDR"]\n\n# Set to None for auto-detection.\n# Select profile training heights. Use a single value such as [80] for one-height\n# profile training, or multiple values for a true multi-height profile model.\n# None means auto-detect all available heights from the CSV.\nCODE_HEIGHTS_M: Optional[List[int]] = [4, 10, 30, 50, 70, 100]\n\n# Automatically crop the input CSV to the first/last valid OBS time for the\n# selected height(s). Invalid rows inside this span are masked target-by-target.\nAUTO_FILTER_TO_VALID_OBS_PERIOD = True\n# "any": use the span where at least one selected height has valid OBS.\n# "all": use the span where all selected heights have valid OBS at the same time.\nVALID_OBS_PERIOD_HEIGHT_MODE = "any"\nVALID_OBS_PERIOD_BUFFER_HOURS = 0.0\nAPPLY_OBS_VALID_FLAG_TO_TARGETS = True\n# Formal C0-C8 target groups chosen from the Code2 A0-A9 first-level diagnosis.\n# Final target structure:\n#   direct WS/WD + temperature + logTKE\n#\n# In Code2_drop, WD/U/V targets at 4 m and 50 m are still removed by the\n# drop-rule patch below. Therefore, with this setting the effective targets are:\n#   4 m   : WS + T/TKE, no WD\n#   10 m  : WS + WD + T/TKE\n#   30 m  : WS + WD + T/TKE\n#   50 m  : WS + T/TKE, no WD\n#   70 m  : WS + WD + T/TKE\n#   100 m : WS + WD + T/TKE\nCODE_TARGET_GROUPS = ["wind_wswd", "temp", "log_tke"]\nCODE_DATE_START: Optional[str] = None\nCODE_DATE_END: Optional[str] = None\n\n# Formal C0-C8 should not silently lose MOSTinput cases. If a MOSTinput case is\n# requested but no MOST input features are found, the code can raise an error.\n# The final runner sets this to True.\nCODE_REQUIRE_MOSTINPUT_CASES = globals().get("CODE_REQUIRE_MOSTINPUT_CASES", False)\n\n# MOST-magnitude PINN settings. The MOST physics loss is applied only to\n# wind-speed magnitude. With the final WSWD_TKE_T target structure, it uses the\n# direct-WS loss: Huber((WRF_WS + dWS) - U_MO).\nPINN_LAMBDA_MO_CANDIDATES = [\n    0.0,\n    0.001,\n    0.003,\n    0.005,\n    0.01,\n    0.03,\n    0.05,\n    0.1,\n    0.2,\n    0.5,\n    1.0,\n]\nPINN_LAMBDA_SMOOTH = 0.001\nPINN_GATE_QLOW = 0.05\nPINN_GATE_QHIGH = 0.95\nPINN_USE_HEIGHT_GATE = True\nPINN_HEIGHT_FULL_WEIGHT_M = 80.0\nPINN_HEIGHT_ZERO_WEIGHT_M = 160.0\nPINN_USE_PBLH_GATE = True\nPINN_FULL_Z_OVER_PBLH = 0.10\nPINN_ZERO_Z_OVER_PBLH = 0.30\n\n# Composite score used to select lambda_MO from validation results.\n# WD is in degrees, so its MAE is downweighted.\nPINN_SCORE_WEIGHTS = {\n    # Direct WS/WD are the formal C0-C8 wind targets.\n    "WS_direct_RMSE": 1.0,\n    "WD_direct_MAE": 0.02,\n\n    # Keep U/V-derived keys for backward compatibility with old A0-A5 runs.\n    "WS_from_uv_RMSE": 1.0,\n    "WD_from_uv_MAE": 0.02,\n\n    # Temperature and TKE are included in lambda selection with lower weights.\n    "T_RMSE": 0.2,\n    "TKE_RMSE": 0.2,\n}\n\n# Backward-compatible defaults for optional command-line mode.\nDEFAULT_TRAIN_CSV: Optional[str] = CODE_TRAIN_CSV\nDEFAULT_OUTPUT_ROOT = CODE_OUTPUT_ROOT\nDEFAULT_HEIGHTS_M: Optional[List[int]] = CODE_HEIGHTS_M\n\nWINDOW_SIZE = 24\nTRAIN_FRAC = 0.60\nVAL_FRAC = 0.20\nEPOCHS = 400\nBATCH_SIZE = 32\nLEARNING_RATE = 1e-3\nPATIENCE_EARLY_STOP = 25\nPATIENCE_LR = 10\nDROPOUT = 0.10\nSEED = 42\nINTERPOLATE_FEATURES = True\n\n# Targets to train if the corresponding OBS/WRF columns exist.\n# "wind_uv" means: generate/learn delta_u and delta_v from WS+WD or U/V columns.\nDEFAULT_TARGET_GROUPS = CODE_TARGET_GROUPS\n\n# Feature screening for corrFDR mode.\nCORR_ABS_R_MIN = 0.30\nFDR_Q_MAX = 0.10\nMIN_PAIR_N = 20\nMIN_TRAIN_SAMPLES_PER_TARGET = 20\n\n# Some variables may be weakly linear but physically/usefully important.\n# These are kept in corrFDR mode if available.\nFORCE_KEEP_TIME_FEATURES = True\nFORCE_KEEP_WIND_BASE_FEATURES = True\n\n# Surface / PBL / time variables added once, not repeated by height.\nSURFACE_FEATURES = [\n    "WRF_L (m)",\n    "WRF_PBLH (m)",\n    "WRF_Bulk_Ri",\n    "UST (m/s)",\n    "Z0 (m)",\n    "HFX (W/m2)",\n    "PSFC (Pa)",\n    "T2 (K)",\n    "hour_sin",\n    "hour_cos",\n    # month_sin/month_cos intentionally excluded from the main experiment.\n    # Keep month as an ablation only if needed later.\n]\n\n# Network choice.\nNETWORK = CODE_NETWORK  # or "TCN"\nTCN_FILTERS = 32\nTCN_KERNEL_SIZE = 5\nTCN_DILATIONS = None\nTCN_DROPOUT = 0.05\nTCN_DENSE_UNITS = 64\n\n# ========================= General utilities =========================\n\n\ndef reset_seed(seed: int = SEED) -> None:\n    random.seed(seed)\n    np.random.seed(seed)\n    try:\n        import tensorflow as tf\n        tf.random.set_seed(seed)\n    except Exception:\n        pass\n\n\ndef safe_name(text: str) -> str:\n    return re.sub(r"[^0-9A-Za-z_\\-\\.]+", "_", str(text))[:160]\n\n\ndef ensure_dir(path: Path) -> Path:\n    path.mkdir(parents=True, exist_ok=True)\n    return path\n\n\ndef import_tf():\n    try:\n        import tensorflow as tf\n        from tensorflow.keras import layers, models, callbacks, optimizers\n        return tf, layers, models, callbacks, optimizers\n    except Exception as e:\n        raise ImportError("TensorFlow is required. Please install tensorflow in your Python environment.") from e\n\n\ndef network_label(network: str = NETWORK) -> str:\n    tag = str(network).strip().upper().replace("-", "_")\n    if tag in ("CNN_LSTM", "CNNLSTM"):\n        return "CNN_LSTM"\n    if tag == "TCN":\n        return "TCN"\n    raise ValueError(f"Unknown network={network}. Use \'CNN_LSTM\' or \'TCN\'.")\n\n\ndef load_ml_ready(csv_path: Path, date_start: Optional[str] = None, date_end: Optional[str] = None) -> pd.DataFrame:\n    df = pd.read_csv(csv_path)\n    if TIME_COL not in df.columns:\n        raise ValueError(f"{csv_path} lacks required time column: {TIME_COL}")\n    df[TIME_COL] = pd.to_datetime(df[TIME_COL], errors="coerce")\n    df = df.dropna(subset=[TIME_COL]).sort_values(TIME_COL).reset_index(drop=True)\n    if date_start is not None:\n        df = df[df[TIME_COL] >= pd.Timestamp(date_start)]\n    if date_end is not None:\n        df = df[df[TIME_COL] <= pd.Timestamp(date_end)]\n    for c in df.columns:\n        if c != TIME_COL and df[c].dtype == object:\n            df[c] = pd.to_numeric(df[c], errors="ignore")\n    return add_time_features(df.reset_index(drop=True))\n\n\ndef add_time_features(df: pd.DataFrame) -> pd.DataFrame:\n    """Create cyclic hour/month features if they are absent."""\n    out = df.copy()\n    if TIME_COL in out.columns:\n        hour = out[TIME_COL].dt.hour.astype(float) + out[TIME_COL].dt.minute.astype(float) / 60.0\n        month = out[TIME_COL].dt.month.astype(float)\n        if "hour_sin" not in out.columns:\n            out["hour_sin"] = np.sin(2.0 * np.pi * hour / 24.0)\n        if "hour_cos" not in out.columns:\n            out["hour_cos"] = np.cos(2.0 * np.pi * hour / 24.0)\n        if "month_sin" not in out.columns:\n            out["month_sin"] = np.sin(2.0 * np.pi * (month - 1.0) / 12.0)\n        if "month_cos" not in out.columns:\n            out["month_cos"] = np.cos(2.0 * np.pi * (month - 1.0) / 12.0)\n    return out\n\n\ndef _norm_col_name(c: str) -> str:\n    s = str(c).replace("²", "2").replace("³", "3").lower()\n    return re.sub(r"[^a-z0-9]+", "", s)\n\n\ndef first_existing(df: pd.DataFrame, candidates: Sequence[str]) -> Optional[str]:\n    """Find a column by exact match first, then by relaxed normalized match.\n\n    This makes TKE columns robust to variants such as m2/s2 vs m²/s²,\n    extra spaces, underscores, and parentheses.\n    """\n    for c in candidates:\n        if c in df.columns:\n            return c\n    norm_map = {_norm_col_name(c): c for c in df.columns}\n    for c in candidates:\n        hit = norm_map.get(_norm_col_name(c))\n        if hit is not None:\n            return hit\n    return None\n\n\ndef available_features(df: pd.DataFrame, features: Sequence[str]) -> List[str]:\n    seen = set()\n    out = []\n    for c in features:\n        if c in df.columns and c not in seen:\n            out.append(c)\n            seen.add(c)\n    return out\n\n\ndef prepare_numeric(df: pd.DataFrame, cols: Sequence[str]) -> pd.DataFrame:\n    out = df.copy()\n    for c in cols:\n        if c in out.columns:\n            out[c] = pd.to_numeric(out[c], errors="coerce")\n    return out\n\n\ndef prepare_features(df: pd.DataFrame, feature_cols: Sequence[str], target_cols: Sequence[str], extra_cols: Sequence[str]) -> pd.DataFrame:\n    out = prepare_numeric(df, list(feature_cols) + list(target_cols) + list(extra_cols))\n    if INTERPOLATE_FEATURES and feature_cols:\n        out[list(feature_cols)] = out[list(feature_cols)].interpolate(method="linear", limit_direction="both").ffill().bfill()\n    return out\n\n# ========================= Column candidates and target construction =========================\n\n\ndef obs_ws_candidates(h: int) -> List[str]:\n    return [\n        f"OBS_WS{h} (m/s)", f"OBS_WS_{h}m (m/s)", f"OBS_WS_{h} (m/s)",\n        f"OBS_WS{h}m (m/s)", f"OBS_WS_{h}m", f"OBS_WS{h}",\n    ]\n\n\ndef wrf_ws_candidates(h: int) -> List[str]:\n    return [\n        f"WRF_WS{h}_interp (m/s)", f"WRF_WS_{h}m_interp (m/s)",\n        f"WRF_WS{h} (m/s)", f"WRF_WS_{h}m (m/s)",\n        f"WRF_WS{h}_interp", f"WRF_WS{h}",\n    ]\n\n\ndef obs_wd_candidates(h: int) -> List[str]:\n    return [\n        f"OBS_WD{h} (deg)", f"OBS_WD_{h}m (deg)", f"OBS_WD{h}", f"OBS_WD_{h}m",\n        f"OBS_DIR{h} (deg)", f"OBS_DIR{h}",\n    ]\n\n\ndef wrf_wd_candidates(h: int) -> List[str]:\n    return [\n        f"WRF_WD{h}_interp (deg)", f"WRF_WD_{h}m_interp (deg)",\n        f"WRF_WD{h} (deg)", f"WRF_WD_{h}m (deg)", f"WRF_WD{h}",\n    ]\n\n\ndef obs_u_candidates(h: int) -> List[str]:\n    return [f"OBS_U{h} (m/s)", f"OBS_U_{h}m (m/s)", f"OBS_U{h}", f"OBS_U_{h}m"]\n\n\ndef obs_v_candidates(h: int) -> List[str]:\n    return [f"OBS_V{h} (m/s)", f"OBS_V_{h}m (m/s)", f"OBS_V{h}", f"OBS_V_{h}m"]\n\n\ndef wrf_u_candidates(h: int) -> List[str]:\n    return [\n        f"WRF_U{h}_interp (m/s)", f"WRF_U_{h}m_interp (m/s)", f"WRF_U{h} (m/s)",\n        f"WRF_U_{h}m (m/s)", f"WRF_U{h}_interp", f"WRF_U{h}",\n        f"WRF_U{h}_auto_from_WS_WD (m/s)",\n    ]\n\n\ndef wrf_v_candidates(h: int) -> List[str]:\n    return [\n        f"WRF_V{h}_interp (m/s)", f"WRF_V_{h}m_interp (m/s)", f"WRF_V{h} (m/s)",\n        f"WRF_V_{h}m (m/s)", f"WRF_V{h}_interp", f"WRF_V{h}",\n        f"WRF_V{h}_auto_from_WS_WD (m/s)",\n    ]\n\n\ndef wd_sin_candidates(h: int) -> List[str]:\n    return [f"WRF_WD{h}_sin", f"WRF_WD_{h}m_sin"]\n\n\ndef wd_cos_candidates(h: int) -> List[str]:\n    return [f"WRF_WD{h}_cos", f"WRF_WD_{h}m_cos"]\n\n\ndef obs_temp_candidates(h: int) -> List[str]:\n    return [\n        f"OBS_T{h} (K)", f"OBS_T_{h}m (K)", f"OBS_TEMP{h} (K)", f"OBS_TEMP_{h}m (K)",\n        f"OBS_T{h}", f"OBS_TEMP{h}", f"OBS_TA{h}", f"OBS_TA_{h}m",\n    ]\n\n\ndef wrf_temp_candidates(h: int) -> List[str]:\n    return [\n        f"WRF_T{h}_interp (K)", f"WRF_T_{h}m_interp (K)",\n        f"WRF_TEMP{h}_interp (K)", f"WRF_TEMP_{h}m_interp (K)",\n        f"WRF_T{h} (K)", f"WRF_T{h}", f"WRF_TEMP{h}",\n    ]\n\n\ndef obs_tke_candidates(h: int) -> List[str]:\n    return [\n        f"OBS_TKE{h} (m2/s2)", f"OBS_TKE{h} (m²/s²)",\n        f"OBS_TKE{h}_from_TI (m2/s2)", f"OBS_TKE{h}_from_TI (m²/s²)",\n        f"OBS_TKE_{h}m (m2/s2)", f"OBS_TKE_{h}m (m²/s²)",\n        f"OBS_TKE{h}", f"OBS_TKE_{h}m",\n    ]\n\n\ndef wrf_tke_candidates(h: int) -> List[str]:\n    return [\n        f"WRF_TKE{h} (m2/s2)", f"WRF_TKE{h} (m²/s²)",\n        f"WRF_TKE_{h}m (m2/s2)", f"WRF_TKE_{h}m (m²/s²)",\n        f"WRF_TKE{h}_interp (m2/s2)", f"WRF_TKE{h}_interp (m²/s²)",\n        f"WRF_TKE_{h}m_interp (m2/s2)", f"WRF_TKE_{h}m_interp (m²/s²)",\n        f"WRF_TKE{h}",\n    ]\n\n\ndef auto_detect_heights(df: pd.DataFrame) -> List[int]:\n    heights = set()\n    patterns = [\n        r"OBS_WS_?(\\d+)m?",\n        r"WRF_WS_?(\\d+)m?_interp",\n        r"OBS_WD_?(\\d+)m?",\n        r"OBS_TKE_?(\\d+)m?",\n        r"WRF_TKE_?(\\d+)m?",\n        r"OBS_T_?(\\d+)m?",\n        r"WRF_T_?(\\d+)m?",\n    ]\n    for c in df.columns:\n        for pat in patterns:\n            m = re.search(pat, c)\n            if m:\n                heights.add(int(m.group(1)))\n    return sorted(heights)\n\n\ndef ws_wd_to_uv(ws, wd_deg):\n    """Meteorological WD convention: direction from which the wind blows."""\n    ws = np.asarray(ws, dtype=float)\n    wd_rad = np.deg2rad(np.asarray(wd_deg, dtype=float))\n    u = -ws * np.sin(wd_rad)\n    v = -ws * np.cos(wd_rad)\n    return u, v\n\n\ndef uv_to_ws_wd(u, v):\n    u = np.asarray(u, dtype=float)\n    v = np.asarray(v, dtype=float)\n    ws = np.sqrt(u ** 2 + v ** 2)\n    wd = (270.0 - np.rad2deg(np.arctan2(v, u))) % 360.0\n    return ws, wd\n\n\n@dataclass\nclass TargetRecord:\n    var: str          # "u", "v", "temp", "log_tke"\n    height: int\n    obs_col: str      # physical observed column used for evaluation\n    wrf_col: str      # physical WRF column used as baseline\n    target_col: str   # residual target column\n    unit: str\n\n\ndef create_uv_columns(df: pd.DataFrame, h: int) -> Tuple[pd.DataFrame, Optional[str], Optional[str], Optional[str], Optional[str]]:\n    """Find or create OBS/WRF u/v columns for one height."""\n    out = df.copy()\n\n    obs_u = first_existing(out, obs_u_candidates(h))\n    obs_v = first_existing(out, obs_v_candidates(h))\n    if obs_u is None or obs_v is None:\n        obs_ws = first_existing(out, obs_ws_candidates(h))\n        obs_wd = first_existing(out, obs_wd_candidates(h))\n        if obs_ws is not None and obs_wd is not None:\n            obs_u = f"OBS_U{h}_auto_from_WS_WD (m/s)"\n            obs_v = f"OBS_V{h}_auto_from_WS_WD (m/s)"\n            u, v = ws_wd_to_uv(pd.to_numeric(out[obs_ws], errors="coerce"), pd.to_numeric(out[obs_wd], errors="coerce"))\n            out[obs_u] = u\n            out[obs_v] = v\n\n    wrf_u = first_existing(out, wrf_u_candidates(h))\n    wrf_v = first_existing(out, wrf_v_candidates(h))\n    if wrf_u is None or wrf_v is None:\n        wrf_ws = first_existing(out, wrf_ws_candidates(h))\n        wrf_wd = first_existing(out, wrf_wd_candidates(h))\n        if wrf_wd is None:\n            sin_col = first_existing(out, wd_sin_candidates(h))\n            cos_col = first_existing(out, wd_cos_candidates(h))\n            if sin_col is not None and cos_col is not None:\n                wrf_wd = f"WRF_WD{h}_auto_from_sin_cos (deg)"\n                out[wrf_wd] = (np.rad2deg(np.arctan2(pd.to_numeric(out[sin_col], errors="coerce"),\n                                                      pd.to_numeric(out[cos_col], errors="coerce"))) % 360.0)\n        if wrf_ws is not None and wrf_wd is not None:\n            wrf_u = f"WRF_U{h}_auto_from_WS_WD (m/s)"\n            wrf_v = f"WRF_V{h}_auto_from_WS_WD (m/s)"\n            u, v = ws_wd_to_uv(pd.to_numeric(out[wrf_ws], errors="coerce"), pd.to_numeric(out[wrf_wd], errors="coerce"))\n            out[wrf_u] = u\n            out[wrf_v] = v\n\n    return out, obs_u, obs_v, wrf_u, wrf_v\n\n\ndef detect_targets_and_create_columns(\n    df: pd.DataFrame,\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n) -> Tuple[pd.DataFrame, List[TargetRecord], List[int]]:\n    """Create residual target columns and return target records."""\n    out = df.copy()\n    heights = list(heights_m) if heights_m is not None else auto_detect_heights(out)\n    target_groups = set(target_groups)\n    records: List[TargetRecord] = []\n\n    for h in heights:\n        if "wind_uv" in target_groups:\n            out, obs_u, obs_v, wrf_u, wrf_v = create_uv_columns(out, h)\n            if obs_u is not None and obs_v is not None and wrf_u is not None and wrf_v is not None:\n                tu = f"target_delta_u{h}_obs_minus_wrf (m/s)"\n                tv = f"target_delta_v{h}_obs_minus_wrf (m/s)"\n                out[tu] = pd.to_numeric(out[obs_u], errors="coerce") - pd.to_numeric(out[wrf_u], errors="coerce")\n                out[tv] = pd.to_numeric(out[obs_v], errors="coerce") - pd.to_numeric(out[wrf_v], errors="coerce")\n                records.append(TargetRecord("u", h, obs_u, wrf_u, tu, "m/s"))\n                records.append(TargetRecord("v", h, obs_v, wrf_v, tv, "m/s"))\n\n        if "wind_wswd" in target_groups:\n            obs_ws = first_existing(out, obs_ws_candidates(h))\n            wrf_ws = first_existing(out, wrf_ws_candidates(h))\n            if obs_ws is not None and wrf_ws is not None:\n                tws = f"target_delta_WS{h}_obs_minus_wrf (m/s)"\n                out[tws] = pd.to_numeric(out[obs_ws], errors="coerce") - pd.to_numeric(out[wrf_ws], errors="coerce")\n                records.append(TargetRecord("ws", h, obs_ws, wrf_ws, tws, "m/s"))\n\n            obs_wd = first_existing(out, obs_wd_candidates(h))\n            wrf_wd = first_existing(out, wrf_wd_candidates(h))\n            if obs_wd is not None and wrf_wd is not None:\n                twd = f"target_delta_WD{h}_circular_obs_minus_wrf (deg)"\n                out[twd] = ((pd.to_numeric(out[obs_wd], errors="coerce") - pd.to_numeric(out[wrf_wd], errors="coerce") + 180.0) % 360.0) - 180.0\n                records.append(TargetRecord("wd", h, obs_wd, wrf_wd, twd, "deg"))\n\n        if "temp" in target_groups:\n            obs_t = first_existing(out, obs_temp_candidates(h))\n            wrf_t = first_existing(out, wrf_temp_candidates(h))\n            if obs_t is not None and wrf_t is not None:\n                tt = f"target_delta_T{h}_obs_minus_wrf (K)"\n                out[tt] = pd.to_numeric(out[obs_t], errors="coerce") - pd.to_numeric(out[wrf_t], errors="coerce")\n                records.append(TargetRecord("temp", h, obs_t, wrf_t, tt, "K"))\n\n        if "log_tke" in target_groups:\n            obs_tke = first_existing(out, obs_tke_candidates(h))\n            wrf_tke = first_existing(out, wrf_tke_candidates(h))\n            if obs_tke is not None and wrf_tke is not None:\n                tk = f"target_delta_logTKE{h}_obs_minus_wrf"\n                obs_val = pd.to_numeric(out[obs_tke], errors="coerce").clip(lower=0.0)\n                wrf_val = pd.to_numeric(out[wrf_tke], errors="coerce").clip(lower=0.0)\n                out[tk] = np.log1p(obs_val) - np.log1p(wrf_val)\n                records.append(TargetRecord("log_tke", h, obs_tke, wrf_tke, tk, "log(m2/s2)"))\n\n    used_heights = sorted(set(r.height for r in records))\n    if not records:\n        raise ValueError("No valid target variables were detected. Check OBS/WRF WS/WD, T, and TKE column names.")\n    return out, records, used_heights\n\n\ndef wrf_feature_candidates_for_height(h: int) -> List[str]:\n    candidates = []\n    for var in ["WS", "U", "V"]:\n        candidates.extend([\n            f"WRF_{var}{h}_interp (m/s)",\n            f"WRF_{var}_{h}m_interp (m/s)",\n            f"WRF_{var}{h} (m/s)",\n            f"WRF_{var}_{h}m (m/s)",\n            f"WRF_{var}{h}_interp",\n            f"WRF_{var}{h}",\n        ])\n    candidates.extend([\n        f"WRF_U{h}_auto_from_WS_WD (m/s)",\n        f"WRF_V{h}_auto_from_WS_WD (m/s)",\n        f"WRF_WD{h}_interp (deg)", f"WRF_WD{h} (deg)", f"WRF_WD{h}",\n        f"WRF_WD{h}_sin", f"WRF_WD_{h}m_sin",\n        f"WRF_WD{h}_cos", f"WRF_WD_{h}m_cos",\n        f"WRF_T{h}_interp (K)", f"WRF_T_{h}m_interp (K)", f"WRF_T{h} (K)", f"WRF_T{h}",\n        f"WRF_TEMP{h}_interp (K)", f"WRF_TEMP{h}",\n        f"WRF_TKE{h} (m2/s2)", f"WRF_TKE_{h}m (m2/s2)",\n        f"WRF_TKE{h}_interp (m2/s2)", f"WRF_TKE_{h}m_interp (m2/s2)", f"WRF_TKE{h}",\n    ])\n    return candidates\n\n\ndef build_feature_set(df: pd.DataFrame, heights: Sequence[int]) -> List[str]:\n    profile_features: List[str] = []\n    for h in heights:\n        profile_features.extend(available_features(df, wrf_feature_candidates_for_height(h)))\n    return available_features(df, profile_features + SURFACE_FEATURES)\n\n# ========================= Windowing, scaling, and feature screening =========================\n\n\ndef make_windows_masked(\n    df: pd.DataFrame,\n    feature_cols: Sequence[str],\n    target_cols: Sequence[str],\n    require_any_target: bool = True,\n) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:\n    Xv = df[list(feature_cols)].astype(float).values\n    yv = df[list(target_cols)].astype(float).values if target_cols else np.empty((len(df), 0), dtype=float)\n    idxs, X_list, y_list, mask_list = [], [], [], []\n    for i in range(WINDOW_SIZE - 1, len(df)):\n        xwin = Xv[i - WINDOW_SIZE + 1: i + 1, :]\n        if not np.all(np.isfinite(xwin)):\n            continue\n        yrow = yv[i, :]\n        mask = np.isfinite(yrow).astype(float)\n        if WINDOW_TARGET_REQUIRE_MODE == "all":\n            if mask.sum() < len(target_cols):\n                continue\n        elif require_any_target and mask.sum() < 1:\n            continue\n        X_list.append(xwin)\n        y_list.append(yrow)\n        mask_list.append(mask)\n        idxs.append(i)\n    if not X_list:\n        return (np.empty((0, WINDOW_SIZE, len(feature_cols))),\n                np.empty((0, len(target_cols))),\n                np.empty((0, len(target_cols))),\n                np.empty((0,), dtype=int))\n    return (np.asarray(X_list, dtype=float),\n            np.asarray(y_list, dtype=float),\n            np.asarray(mask_list, dtype=float),\n            np.asarray(idxs, dtype=int))\n\n\ndef make_windows_application(df: pd.DataFrame, feature_cols: Sequence[str]) -> Tuple[np.ndarray, np.ndarray]:\n    Xv = df[list(feature_cols)].astype(float).values\n    idxs, X_list = [], []\n    for i in range(WINDOW_SIZE - 1, len(df)):\n        xwin = Xv[i - WINDOW_SIZE + 1: i + 1, :]\n        if not np.all(np.isfinite(xwin)):\n            continue\n        X_list.append(xwin)\n        idxs.append(i)\n    if not X_list:\n        return np.empty((0, WINDOW_SIZE, len(feature_cols))), np.empty((0,), dtype=int)\n    return np.asarray(X_list, dtype=float), np.asarray(idxs, dtype=int)\n\n\ndef split_chronological(n: int) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:\n    n_train = int(np.floor(n * TRAIN_FRAC))\n    n_val = int(np.floor(n * VAL_FRAC))\n    n_train = max(n_train, 1)\n    n_val = max(n_val, 1)\n    if n - n_train - n_val < 1:\n        raise ValueError("Not enough samples for train/val/test split after windowing.")\n    train = np.arange(0, n_train)\n    val = np.arange(n_train, n_train + n_val)\n    test = np.arange(n_train + n_val, n)\n    return train, val, test\n\n\ndef fit_x_scaler(X_train: np.ndarray) -> StandardScaler:\n    scaler = StandardScaler()\n    nfeat = X_train.shape[-1]\n    scaler.fit(X_train.reshape(-1, nfeat))\n    return scaler\n\n\ndef transform_windows(X: np.ndarray, scaler: StandardScaler) -> np.ndarray:\n    nfeat = X.shape[-1]\n    return scaler.transform(X.reshape(-1, nfeat)).reshape(X.shape)\n\n\ndef fit_y_scaler_params(y_train: np.ndarray, mask_train: np.ndarray) -> Tuple[np.ndarray, np.ndarray]:\n    y = np.asarray(y_train, dtype=float).copy()\n    y[mask_train <= 0] = np.nan\n    mean = np.nanmean(y, axis=0)\n    scale = np.nanstd(y, axis=0)\n    mean[~np.isfinite(mean)] = 0.0\n    scale[~np.isfinite(scale) | (scale < 1e-12)] = 1.0\n    return mean.astype(float), scale.astype(float)\n\n\ndef transform_y(y: np.ndarray, mean: np.ndarray, scale: np.ndarray) -> np.ndarray:\n    return (np.asarray(y, dtype=float) - mean[None, :]) / scale[None, :]\n\n\ndef inverse_y(y_scaled: np.ndarray, mean: np.ndarray, scale: np.ndarray) -> np.ndarray:\n    return np.asarray(y_scaled, dtype=float) * scale[None, :] + mean[None, :]\n\n\ndef fill_missing_scaled_targets(y_scaled: np.ndarray, mask: np.ndarray) -> np.ndarray:\n    out = np.asarray(y_scaled, dtype=float).copy()\n    out[mask <= 0] = 0.0\n    out[~np.isfinite(out)] = 0.0\n    return out\n\n\ndef bh_fdr_qvalues(p_values: Sequence[float]) -> np.ndarray:\n    p = np.asarray(p_values, dtype=float)\n    q = np.full_like(p, np.nan, dtype=float)\n    valid = np.isfinite(p)\n    if valid.sum() == 0:\n        return q\n    pv = p[valid]\n    m = len(pv)\n    order = np.argsort(pv)\n    ranked = pv[order]\n    q_ranked = ranked * m / np.arange(1, m + 1)\n    q_ranked = np.minimum.accumulate(q_ranked[::-1])[::-1]\n    q_ranked = np.clip(q_ranked, 0.0, 1.0)\n    valid_indices = np.where(valid)[0]\n    q[valid_indices[order]] = q_ranked\n    return q\n\n\ndef pearson_r_p(x: np.ndarray, y: np.ndarray) -> Tuple[float, float, int]:\n    m = np.isfinite(x) & np.isfinite(y)\n    n = int(m.sum())\n    if n < MIN_PAIR_N:\n        return np.nan, np.nan, n\n    x = x[m]\n    y = y[m]\n    if np.std(x) < 1e-12 or np.std(y) < 1e-12:\n        return np.nan, np.nan, n\n    try:\n        from scipy.stats import pearsonr\n        r, p = pearsonr(x, y)\n        return float(r), float(p), n\n    except Exception:\n        # Fallback: compute r only. Without scipy, q-values cannot be meaningful.\n        r = float(np.corrcoef(x, y)[0, 1])\n        return r, np.nan, n\n\n\ndef force_keep_feature(c: str) -> bool:\n    if FORCE_KEEP_TIME_FEATURES and c in {"hour_sin", "hour_cos"}:\n        return True\n    if FORCE_KEEP_WIND_BASE_FEATURES and re.search(r"WRF_(WS|U|V)\\d+", c):\n        return True\n    return False\n\n\ndef select_corr_fdr_features(\n    df: pd.DataFrame,\n    train_row_idx: np.ndarray,\n    candidate_features: Sequence[str],\n    target_records: Sequence[TargetRecord],\n    abs_r_min: float = CORR_ABS_R_MIN,\n    q_max: float = FDR_Q_MAX,\n) -> Tuple[List[str], pd.DataFrame]:\n    rows: List[Dict[str, object]] = []\n    for feat in candidate_features:\n        x = pd.to_numeric(df.loc[train_row_idx, feat], errors="coerce").values.astype(float)\n        for tr in target_records:\n            y = pd.to_numeric(df.loc[train_row_idx, tr.target_col], errors="coerce").values.astype(float)\n            r, p, n = pearson_r_p(x, y)\n            rows.append({\n                "feature": feat,\n                "target": tr.target_col,\n                "target_var": tr.var,\n                "height_m": tr.height,\n                "N_pair": n,\n                "Pearson_r": r,\n                "p_value": p,\n            })\n    report = pd.DataFrame(rows)\n    report["q_value_BH_FDR"] = bh_fdr_qvalues(report["p_value"].values)\n    report["selected_pair"] = (\n        (report["Pearson_r"].abs() >= abs_r_min) &\n        (report["q_value_BH_FDR"] <= q_max)\n    )\n    selected = sorted(report.loc[report["selected_pair"], "feature"].dropna().unique().tolist(),\n                      key=lambda c: list(candidate_features).index(c))\n    forced = [c for c in candidate_features if force_keep_feature(c)]\n    selected_final = []\n    seen = set()\n    for c in list(selected) + forced:\n        if c in candidate_features and c not in seen:\n            selected_final.append(c)\n            seen.add(c)\n    if not selected_final:\n        # Safe fallback: use all features rather than fail silently.\n        selected_final = list(candidate_features)\n        report["note"] = "No features passed corr/FDR; fell back to all candidate features."\n    report["selected_feature_final"] = report["feature"].isin(selected_final)\n    return selected_final, report\n\n# ========================= Models and losses =========================\n\n\ndef build_cnn_lstm(input_shape, n_outputs: int):\n    tf, layers, models, callbacks, optimizers = import_tf()\n    inp = layers.Input(shape=input_shape)\n    x = layers.Conv1D(64, kernel_size=3, padding="causal", activation="relu")(inp)\n    x = layers.Dropout(DROPOUT)(x)\n    x = layers.Conv1D(32, kernel_size=3, padding="causal", activation="relu")(x)\n    x = layers.Dropout(DROPOUT)(x)\n    x = layers.LSTM(64, return_sequences=False)(x)\n    x = layers.Dense(64, activation="relu")(x)\n    x = layers.Dropout(DROPOUT)(x)\n    x = layers.Dense(32, activation="relu")(x)\n    out = layers.Dense(n_outputs, name="delta_multivar_profile_scaled")(x)\n    return models.Model(inp, out, name="CNN_LSTM_multivar_profile")\n\n\ndef tcn_residual_block(x, filters: int, kernel_size: int, dilation_rate: int, dropout: float):\n    tf, layers, models, callbacks, optimizers = import_tf()\n    shortcut = x\n    x = layers.Conv1D(filters, kernel_size=kernel_size, padding="causal", dilation_rate=dilation_rate)(x)\n    x = layers.Activation("relu")(x)\n    x = layers.Dropout(dropout)(x)\n    x = layers.Conv1D(filters, kernel_size=kernel_size, padding="causal", dilation_rate=dilation_rate)(x)\n    x = layers.Activation("relu")(x)\n    x = layers.Dropout(dropout)(x)\n    if shortcut.shape[-1] != filters:\n        shortcut = layers.Conv1D(filters, kernel_size=1, padding="same")(shortcut)\n    x = layers.Add()([shortcut, x])\n    x = layers.Activation("relu")(x)\n    return x\n\n\ndef auto_tcn_dilations(window_size: int, kernel_size: int = TCN_KERNEL_SIZE, convs_per_block: int = 2, max_dilation: int = 32):\n    dilations = []\n    d = 1\n    denom = max(1, convs_per_block * (kernel_size - 1))\n    needed_sum = (window_size - 1) / float(denom)\n    current_sum = 0.0\n    while current_sum < needed_sum and d <= max_dilation:\n        dilations.append(int(d))\n        current_sum += d\n        d *= 2\n    if not dilations:\n        dilations = [1]\n    cand = dilations[-1] * 2\n    if cand <= max_dilation:\n        dilations.append(int(cand))\n    return tuple(dilations)\n\n\ndef build_tcn(input_shape, n_outputs: int):\n    tf, layers, models, callbacks, optimizers = import_tf()\n    window_size, n_features = input_shape\n    dilations = tuple(TCN_DILATIONS) if TCN_DILATIONS is not None else auto_tcn_dilations(window_size)\n    inp = layers.Input(shape=input_shape)\n    x = layers.Conv1D(TCN_FILTERS, kernel_size=1, padding="same")(inp)\n    x = layers.Activation("relu")(x)\n    for d in dilations:\n        x = tcn_residual_block(x, filters=TCN_FILTERS, kernel_size=TCN_KERNEL_SIZE,\n                               dilation_rate=int(d), dropout=TCN_DROPOUT)\n    x = layers.Lambda(lambda t: t[:, -1, :], name="take_last_time_step")(x)\n    x = layers.Dense(TCN_DENSE_UNITS, activation="relu")(x)\n    x = layers.Dense(max(32, TCN_DENSE_UNITS // 2), activation="relu")(x)\n    out = layers.Dense(n_outputs, name="delta_multivar_profile_scaled")(x)\n    return models.Model(inp, out, name="TCN_multivar_profile")\n\n\ndef build_prediction_model(input_shape, n_outputs: int, network: str):\n    tag = network_label(network)\n    if tag == "CNN_LSTM":\n        return build_cnn_lstm(input_shape, n_outputs)\n    if tag == "TCN":\n        return build_tcn(input_shape, n_outputs)\n    raise ValueError(network)\n\n\ndef masked_huber_loss(n_outputs: int, delta: float = 1.0):\n    tf, *_ = import_tf()\n\n    def loss(y_true_concat, y_pred):\n        y_true = y_true_concat[:, 0:n_outputs]\n        mask = y_true_concat[:, n_outputs:2 * n_outputs]\n        err = y_pred - y_true\n        abs_e = tf.abs(err)\n        huber = tf.where(abs_e <= delta, 0.5 * tf.square(err), delta * (abs_e - 0.5 * delta))\n        return tf.reduce_sum(mask * huber) / (tf.reduce_sum(mask) + 1e-6)\n\n    return loss\n\n\ndef compile_model(model, n_outputs: int):\n    tf, layers, models, callbacks, optimizers = import_tf()\n    model.compile(optimizer=optimizers.Adam(learning_rate=LEARNING_RATE), loss=masked_huber_loss(n_outputs, delta=1.0))\n    return model\n\n\ndef fit_model(model, X_train, y_train_concat, X_val, y_val_concat):\n    tf, layers, models, callbacks, optimizers = import_tf()\n\n    class LRLogger(callbacks.Callback):\n        def on_epoch_end(self, epoch, logs=None):\n            logs = logs or {}\n            opt = self.model.optimizer\n            lr_obj = getattr(opt, "learning_rate", getattr(opt, "lr", None))\n            try:\n                logs["lr"] = float(tf.keras.backend.get_value(lr_obj))\n            except Exception:\n                try:\n                    logs["lr"] = float(lr_obj)\n                except Exception:\n                    pass\n\n    cb = [\n        callbacks.EarlyStopping(monitor="val_loss", patience=PATIENCE_EARLY_STOP, restore_best_weights=True),\n        callbacks.ReduceLROnPlateau(monitor="val_loss", patience=PATIENCE_LR, factor=0.5, min_lr=1e-6),\n        LRLogger(),\n    ]\n    return model.fit(\n        X_train, y_train_concat,\n        validation_data=(X_val, y_val_concat),\n        epochs=EPOCHS,\n        batch_size=BATCH_SIZE,\n        shuffle=False,\n        verbose=1,\n        callbacks=cb,\n    )\n\n\ndef _history_to_dataframe(history) -> pd.DataFrame:\n    hist = history.history if hasattr(history, "history") else dict(history)\n    dfh = pd.DataFrame(hist)\n    if not dfh.empty:\n        dfh.insert(0, "epoch", np.arange(1, len(dfh) + 1))\n    return dfh\n\n\ndef plot_loss(history, out_png: Path, title: str) -> None:\n    """Save full training history CSV and readable loss/lr plots for every Code2 case."""\n    out_png = Path(out_png)\n    ensure_dir(out_png.parent)\n    hist = history.history if hasattr(history, "history") else dict(history)\n    dfh = _history_to_dataframe(history)\n    tag = safe_name(str(title))\n    if not dfh.empty:\n        dfh.to_csv(out_png.parent / f"training_history_{tag}.csv", index=False, encoding="utf-8-sig")\n\n    fig, ax = plt.subplots(figsize=(8.5, 4.8))\n    if "loss" in hist:\n        ax.plot(hist["loss"], label="train loss")\n    if "val_loss" in hist:\n        ax.plot(hist["val_loss"], label="val loss")\n    ax.set_xlabel("Epoch")\n    ax.set_ylabel("Loss")\n    ax.set_title(title)\n    ax.grid(True, alpha=0.3)\n    ax.legend()\n    fig.tight_layout()\n    fig.savefig(out_png, dpi=300)\n    plt.close(fig)\n\n    x = np.arange(1, len(dfh) + 1) if not dfh.empty else np.arange(len(hist.get("loss", []))) + 1\n    fig, ax1 = plt.subplots(figsize=(9.2, 5.2))\n    if "loss" in hist:\n        ax1.plot(x, hist["loss"], label="train loss")\n    if "val_loss" in hist:\n        ax1.plot(x, hist["val_loss"], label="val loss")\n    ax1.set_xlabel("Epoch")\n    ax1.set_ylabel("Loss")\n    ax1.grid(True, alpha=0.3)\n    lines, labels = ax1.get_legend_handles_labels()\n    if "lr" in hist:\n        ax2 = ax1.twinx()\n        ax2.plot(x, hist["lr"], linestyle="--", label="learning rate")\n        ax2.set_ylabel("Learning rate")\n        l2, lab2 = ax2.get_legend_handles_labels()\n        lines += l2; labels += lab2\n    ax1.legend(lines, labels, loc="best")\n    ax1.set_title(f"Training curve: {title}")\n    fig.tight_layout()\n    fig.savefig(out_png.parent / f"plot_training_loss_lr_{tag}.png", dpi=300)\n    plt.close(fig)\n\n    value_cols = [c for c in dfh.columns if c != "epoch" and pd.api.types.is_numeric_dtype(dfh[c])]\n    if value_cols:\n        fig, ax = plt.subplots(figsize=(9.5, 5.4))\n        for c in value_cols:\n            ax.plot(dfh["epoch"], dfh[c], label=c)\n        ax.set_xlabel("Epoch")\n        ax.set_ylabel("Value")\n        ax.set_title(f"Full training history: {title}")\n        ax.grid(True, alpha=0.3)\n        ax.legend(fontsize=8)\n        fig.tight_layout()\n        fig.savefig(out_png.parent / f"plot_training_history_all_{tag}.png", dpi=300)\n        plt.close(fig)\n\n# ========================= Prediction tables and metrics =========================\n\n\ndef standard_metrics(y_true, y_pred, y_base=None) -> Dict[str, float]:\n    yt = np.asarray(y_true, dtype=float).ravel()\n    yp = np.asarray(y_pred, dtype=float).ravel()\n    m = np.isfinite(yt) & np.isfinite(yp)\n    if m.sum() < 2:\n        return {"N": int(m.sum()), "RMSE": np.nan, "MAE": np.nan, "MBE": np.nan, "R": np.nan,\n                "NRMSE_pct": np.nan, "Skill_RMSE_pct": np.nan}\n    yt = yt[m]\n    yp = yp[m]\n    rmse = float(np.sqrt(mean_squared_error(yt, yp)))\n    mae = float(mean_absolute_error(yt, yp))\n    mbe = float(np.mean(yp - yt))\n    R = float(np.corrcoef(yt, yp)[0, 1]) if np.std(yt) > 0 and np.std(yp) > 0 else np.nan\n    mean_obs = float(np.mean(yt))\n    nrmse = float(rmse / mean_obs * 100.0) if abs(mean_obs) > 1e-12 else np.nan\n    skill = np.nan\n    if y_base is not None:\n        yb0 = np.asarray(y_base, dtype=float).ravel()\n        yb = yb0[m]\n        mb = np.isfinite(yb)\n        if mb.sum() >= 2:\n            rmse_base = float(np.sqrt(mean_squared_error(yt[mb], yb[mb])))\n            if rmse_base > 1e-12:\n                skill = float((rmse_base - rmse) / rmse_base * 100.0)\n    return {"N": int(len(yt)), "RMSE": rmse, "MAE": mae, "MBE": mbe, "R": R,\n            "NRMSE_pct": nrmse, "Skill_RMSE_pct": skill}\n\n\ndef circular_diff_deg(pred, obs):\n    return (np.asarray(pred, dtype=float) - np.asarray(obs, dtype=float) + 180.0) % 360.0 - 180.0\n\n\ndef direction_metrics(obs_wd, pred_wd, base_wd=None) -> Dict[str, float]:\n    obs = np.asarray(obs_wd, dtype=float).ravel()\n    pred = np.asarray(pred_wd, dtype=float).ravel()\n    m = np.isfinite(obs) & np.isfinite(pred)\n    if m.sum() < 2:\n        return {"N": int(m.sum()), "RMSE": np.nan, "MAE": np.nan, "MBE": np.nan, "R": np.nan,\n                "NRMSE_pct": np.nan, "Skill_RMSE_pct": np.nan}\n    err = circular_diff_deg(pred[m], obs[m])\n    rmse = float(np.sqrt(np.mean(err ** 2)))\n    mae = float(np.mean(np.abs(err)))\n    mbe = float(np.mean(err))\n    skill = np.nan\n    if base_wd is not None:\n        base = np.asarray(base_wd, dtype=float).ravel()\n        mb = m & np.isfinite(base)\n        if mb.sum() >= 2:\n            base_err = circular_diff_deg(base[mb], obs[mb])\n            rmse_base = float(np.sqrt(np.mean(base_err ** 2)))\n            if rmse_base > 1e-12:\n                pred_err2 = circular_diff_deg(pred[mb], obs[mb])\n                rmse_pred2 = float(np.sqrt(np.mean(pred_err2 ** 2)))\n                skill = float((rmse_base - rmse_pred2) / rmse_base * 100.0)\n    return {"N": int(m.sum()), "RMSE": rmse, "MAE": mae, "MBE": mbe, "R": np.nan,\n            "NRMSE_pct": np.nan, "Skill_RMSE_pct": skill}\n\n\ndef target_physical_arrays(df: pd.DataFrame, idx: np.ndarray, records: Sequence[TargetRecord], delta_pred: np.ndarray):\n    """Return dictionaries for obs/base/pred physical variables for each target record."""\n    data = []\n    for j, tr in enumerate(records):\n        obs = pd.to_numeric(df.loc[idx, tr.obs_col], errors="coerce").values.astype(float)\n        base = pd.to_numeric(df.loc[idx, tr.wrf_col], errors="coerce").values.astype(float)\n        if tr.var == "log_tke":\n            delta = delta_pred[:, j]\n            pred = np.expm1(np.log1p(np.clip(base, 0.0, None)) + delta)\n            pred = np.clip(pred, 0.0, None)\n            var_label = "TKE"\n        elif tr.var == "ws":\n            pred = np.maximum(base + delta_pred[:, j], 0.0)\n            var_label = "WS_direct"\n        elif tr.var == "wd":\n            pred = (base + delta_pred[:, j]) % 360.0\n            var_label = "WD_direct"\n        else:\n            pred = base + delta_pred[:, j]\n            var_label = {"u": "u", "v": "v", "temp": "T"}.get(tr.var, tr.var)\n        data.append({"record": tr, "var_label": var_label, "obs": obs, "base": base, "pred": pred, "delta_pred": delta_pred[:, j]})\n    return data\n\n\ndef add_metric_row(rows: List[Dict[str, object]], site: str, model_name: str, feature_mode: str,\n                   split: str, variable: str, height_m, obs, pred, base, metric_func=standard_metrics):\n    row = {"site": site, "model": model_name, "feature_mode": feature_mode,\n           "split": split, "variable": variable, "height_m": height_m}\n    row.update(metric_func(obs, pred, base))\n    rows.append(row)\n\n\ndef build_prediction_table_and_metrics(\n    df: pd.DataFrame,\n    idx: np.ndarray,\n    records: Sequence[TargetRecord],\n    delta_pred: np.ndarray,\n    split_labels: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n) -> Tuple[pd.DataFrame, pd.DataFrame]:\n    out = pd.DataFrame({TIME_COL: df.loc[idx, TIME_COL].values, "split": np.asarray(split_labels, dtype=object)})\n    rows: List[Dict[str, object]] = []\n    physical = target_physical_arrays(df, idx, records, delta_pred)\n\n    # Save per-target physical predictions and target metrics.\n    for item in physical:\n        tr = item["record"]\n        h = tr.height\n        var = item["var_label"]\n        prefix = f"{var}{h}"\n        delta_prefix = f"logTKE{h}" if tr.var == "log_tke" else prefix\n        out[f"OBS_{prefix}"] = item["obs"]\n        out[f"WRF_{prefix}"] = item["base"]\n        out[f"delta_{delta_prefix}_pred"] = item["delta_pred"]\n        out[f"{prefix}_corr_pred"] = item["pred"]\n\n    # Metrics by split for direct targets.\n    split_labels_arr = np.asarray(split_labels, dtype=object)\n    for split in sorted(pd.unique(split_labels_arr)):\n        m = split_labels_arr == split\n        for item in physical:\n            tr = item["record"]\n            metric_func = direction_metrics if item["var_label"] == "WD_direct" else standard_metrics\n            add_metric_row(rows, site_name, model_name, feature_mode, split, item["var_label"], tr.height,\n                           item["obs"][m], item["pred"][m], item["base"][m], metric_func)\n\n    # Derived wind-speed and wind-direction metrics from u/v pairs.\n    heights = sorted(set(r.height for r in records))\n    rec_map = {(r.var, r.height): k for k, r in enumerate(records)}\n    for h in heights:\n        if ("u", h) in rec_map and ("v", h) in rec_map:\n            ju, jv = rec_map[("u", h)], rec_map[("v", h)]\n            u_item, v_item = physical[ju], physical[jv]\n            obs_ws, obs_wd = uv_to_ws_wd(u_item["obs"], v_item["obs"])\n            base_ws, base_wd = uv_to_ws_wd(u_item["base"], v_item["base"])\n            pred_ws, pred_wd = uv_to_ws_wd(u_item["pred"], v_item["pred"])\n            out[f"OBS_WS{h}_from_uv (m/s)"] = obs_ws\n            out[f"WRF_WS{h}_from_uv (m/s)"] = base_ws\n            out[f"WS{h}_corr_pred_from_uv (m/s)"] = pred_ws\n            out[f"OBS_WD{h}_from_uv (deg)"] = obs_wd\n            out[f"WRF_WD{h}_from_uv (deg)"] = base_wd\n            out[f"WD{h}_corr_pred_from_uv (deg)"] = pred_wd\n            for split in sorted(pd.unique(split_labels_arr)):\n                m = split_labels_arr == split\n                add_metric_row(rows, site_name, model_name, feature_mode, split, "WS_from_uv", h,\n                               obs_ws[m], pred_ws[m], base_ws[m], standard_metrics)\n                add_metric_row(rows, site_name, model_name, feature_mode, split, "WD_from_uv", h,\n                               obs_wd[m], pred_wd[m], base_wd[m], direction_metrics)\n\n    # ALL_PROFILE metrics for each variable type by flattening all heights.\n    metrics_df = pd.DataFrame(rows)\n    if not metrics_df.empty:\n        # Build ALL_PROFILE from physical arrays per variable.\n        for split in sorted(pd.unique(split_labels_arr)):\n            m = split_labels_arr == split\n            for var in sorted(set(item["var_label"] for item in physical)):\n                obs_list, pred_list, base_list = [], [], []\n                for item in physical:\n                    if item["var_label"] == var:\n                        obs_list.append(item["obs"][m])\n                        pred_list.append(item["pred"][m])\n                        base_list.append(item["base"][m])\n                if obs_list:\n                    metric_func = direction_metrics if var == "WD_direct" else standard_metrics\n                    add_metric_row(rows, site_name, model_name, feature_mode, split, var, "ALL_PROFILE",\n                                   np.concatenate(obs_list), np.concatenate(pred_list), np.concatenate(base_list), metric_func)\n            # Derived ALL_PROFILE wind metrics.\n            ws_obs_list, ws_pred_list, ws_base_list = [], [], []\n            wd_obs_list, wd_pred_list, wd_base_list = [], [], []\n            for h in heights:\n                if ("u", h) in rec_map and ("v", h) in rec_map:\n                    ju, jv = rec_map[("u", h)], rec_map[("v", h)]\n                    u_item, v_item = physical[ju], physical[jv]\n                    obs_ws, obs_wd = uv_to_ws_wd(u_item["obs"], v_item["obs"])\n                    base_ws, base_wd = uv_to_ws_wd(u_item["base"], v_item["base"])\n                    pred_ws, pred_wd = uv_to_ws_wd(u_item["pred"], v_item["pred"])\n                    ws_obs_list.append(obs_ws[m]); ws_pred_list.append(pred_ws[m]); ws_base_list.append(base_ws[m])\n                    wd_obs_list.append(obs_wd[m]); wd_pred_list.append(pred_wd[m]); wd_base_list.append(base_wd[m])\n            if ws_obs_list:\n                add_metric_row(rows, site_name, model_name, feature_mode, split, "WS_from_uv", "ALL_PROFILE",\n                               np.concatenate(ws_obs_list), np.concatenate(ws_pred_list), np.concatenate(ws_base_list), standard_metrics)\n                add_metric_row(rows, site_name, model_name, feature_mode, split, "WD_from_uv", "ALL_PROFILE",\n                               np.concatenate(wd_obs_list), np.concatenate(wd_pred_list), np.concatenate(wd_base_list), direction_metrics)\n\n    return out, pd.DataFrame(rows)\n\n# ========================= Training orchestration =========================\n\n\ndef prune_targets_by_training_availability(\n    y: np.ndarray,\n    mask: np.ndarray,\n    train_i: np.ndarray,\n    records: Sequence[TargetRecord],\n    min_train_samples: int = MIN_TRAIN_SAMPLES_PER_TARGET,\n) -> Tuple[np.ndarray, np.ndarray, List[TargetRecord], List[int]]:\n    counts = mask[train_i].sum(axis=0)\n    keep = [j for j, n in enumerate(counts) if n >= min_train_samples]\n    if not keep:\n        raise ValueError("No target variable has enough finite training samples.")\n    return y[:, keep], mask[:, keep], [records[j] for j in keep], keep\n\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n) -> pd.DataFrame:\n    reset_seed()\n    ensure_dir(out_dir)\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n    dfp = prepare_features(df, feature_cols, target_cols_all, extra_cols)\n\n    X, y, mask, idx = make_windows_masked(dfp, feature_cols, target_cols_all, require_any_target=True)\n    if len(X) < 30:\n        raise ValueError(f"{feature_mode}: too few valid windows ({len(X)}).")\n    train_i, val_i, test_i = split_chronological(len(X))\n\n    y, mask, target_records, keep_target_idx = prune_targets_by_training_availability(y, mask, train_i, target_records_all)\n    n_outputs = len(target_records)\n\n    X_train, X_val, X_test = X[train_i], X[val_i], X[test_i]\n    y_train, y_val, y_test = y[train_i], y[val_i], y[test_i]\n    mask_train, mask_val, mask_test = mask[train_i], mask[val_i], mask[test_i]\n\n    x_scaler = fit_x_scaler(X_train)\n    X_train_s = transform_windows(X_train, x_scaler)\n    X_val_s = transform_windows(X_val, x_scaler)\n    X_test_s = transform_windows(X_test, x_scaler)\n\n    y_mean, y_scale = fit_y_scaler_params(y_train, mask_train)\n    y_train_s = fill_missing_scaled_targets(transform_y(y_train, y_mean, y_scale), mask_train)\n    y_val_s = fill_missing_scaled_targets(transform_y(y_val, y_mean, y_scale), mask_val)\n    y_train_concat = np.concatenate([y_train_s, mask_train], axis=1)\n    y_val_concat = np.concatenate([y_val_s, mask_val], axis=1)\n\n    model = build_prediction_model(X_train_s.shape[1:], n_outputs=n_outputs, network=network)\n    model = compile_model(model, n_outputs=n_outputs)\n    hist = fit_model(model, X_train_s, y_train_concat, X_val_s, y_val_concat)\n    plot_loss(hist, out_dir / "loss.png", f"{model_name}_{feature_mode}")\n\n    pred_train = inverse_y(model.predict(X_train_s, verbose=0), y_mean, y_scale)\n    pred_val = inverse_y(model.predict(X_val_s, verbose=0), y_mean, y_scale)\n    pred_test = inverse_y(model.predict(X_test_s, verbose=0), y_mean, y_scale)\n    delta_pred = np.full((len(idx), n_outputs), np.nan, dtype=float)\n    delta_pred[train_i, :] = pred_train\n    delta_pred[val_i, :] = pred_val\n    delta_pred[test_i, :] = pred_test\n\n    split_labels = np.asarray([""] * len(idx), dtype=object)\n    split_labels[train_i] = "train"\n    split_labels[val_i] = "val"\n    split_labels[test_i] = "test"\n\n    pred_table, metrics_df = build_prediction_table_and_metrics(\n        dfp, idx, target_records, delta_pred, split_labels, site_name, model_name, feature_mode\n    )\n    pred_table.to_csv(out_dir / "predictions_train_val_test.csv", index=False, encoding="utf-8-sig")\n    metrics_df.to_csv(out_dir / "metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n\n    model.save(out_dir / "model.keras")\n    joblib.dump(x_scaler, out_dir / "x_scaler.joblib")\n\n    metadata = {\n        "script_version": "multivar_profile_v1",\n        "site_name": site_name,\n        "model_name": model_name,\n        "network": network_label(network),\n        "feature_mode": feature_mode,\n        "time_col": TIME_COL,\n        "window_size": WINDOW_SIZE,\n        "feature_cols": list(feature_cols),\n        "target_records": [asdict(r) for r in target_records],\n        "y_mean": y_mean.tolist(),\n        "y_scale": y_scale.tolist(),\n        "train_frac": TRAIN_FRAC,\n        "val_frac": VAL_FRAC,\n        "epochs": EPOCHS,\n        "batch_size": BATCH_SIZE,\n        "learning_rate": LEARNING_RATE,\n        "note": "Predicts residuals: delta_u, delta_v, delta_T, and/or delta_logTKE depending on available columns.",\n    }\n    with open(out_dir / "metadata.json", "w", encoding="utf-8") as f:\n        json.dump(metadata, f, ensure_ascii=False, indent=2)\n    pd.Series(feature_cols, name="feature").to_csv(out_dir / "features_used.csv", index=False, encoding="utf-8-sig")\n    pd.DataFrame([asdict(r) for r in target_records]).to_csv(out_dir / "targets_used.csv", index=False, encoding="utf-8-sig")\n    return metrics_df\n\n\ndef train_for_csv(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = ("all", "corrFDR"),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    site_name = safe_name(train_csv.stem.replace("ML_ready_ref10_", ""))\n    base_out = ensure_dir(output_root / site_name)\n    precheck_dir = ensure_dir(base_out / "00_pre")\n    cases_root = ensure_dir(base_out / "cases")\n    comparison_dir = ensure_dir(base_out / "02_cmp")\n    print("=" * 100)\n    print(f"Training site/tower: {site_name}")\n    print(f"Input CSV: {train_csv}")\n    print(f"Output root: {base_out}")\n    print(f"  precheck:   {precheck_dir}")\n    print(f"  cases:      {cases_root}")\n    print(f"  comparison: {comparison_dir}")\n    print(f"Network: {network_label(network)}")\n\n    df = load_ml_ready(train_csv, date_start=date_start, date_end=date_end)\n    df, target_records_all, used_heights = detect_targets_and_create_columns(df, heights_m=heights_m, target_groups=target_groups)\n    all_features = build_feature_set(df, used_heights)\n    if not all_features:\n        raise ValueError("No WRF input features found.")\n\n    # Save detected information.\n    pd.DataFrame([asdict(r) for r in target_records_all]).to_csv(base_out / "detected_all_targets.csv", index=False, encoding="utf-8-sig")\n    pd.Series(all_features, name="all_candidate_feature").to_csv(base_out / "all_candidate_features.csv", index=False, encoding="utf-8-sig")\n\n    # Define train rows for feature screening using all candidate features.\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n    dfp_all = prepare_features(df, all_features, target_cols_all, extra_cols)\n    X0, y0, mask0, idx0 = make_windows_masked(dfp_all, all_features, target_cols_all, require_any_target=True)\n    if len(X0) < 30:\n        raise ValueError(f"Too few valid windows for initial split ({len(X0)}).")\n    train_i0, val_i0, test_i0 = split_chronological(len(X0))\n    train_row_idx = idx0[train_i0]\n\n    summaries = []\n    for mode in feature_modes:\n        mode_norm = mode.strip().lower()\n        if mode_norm in {"all", "all_features", "nomost_all_features"}:\n            feature_cols = all_features\n            feature_mode_name = "noMOST_all_features"\n        elif mode_norm in {"corrfdr", "corr_fdr", "selected", "corr_selected", "nomost_corrfdr"}:\n            feature_cols, report = select_corr_fdr_features(dfp_all, train_row_idx, all_features, target_records_all)\n            feature_mode_name = "noMOST_corrFDR_selected_features"\n            report.to_csv(base_out / "corrFDR_feature_screening_report.csv", index=False, encoding="utf-8-sig")\n            pd.Series(feature_cols, name="selected_feature").to_csv(base_out / "corrFDR_selected_features.csv", index=False, encoding="utf-8-sig")\n        else:\n            raise ValueError(f"Unknown feature mode: {mode}")\n\n        out_dir = ensure_dir(cases_root / f"{network_label(network)}_{feature_mode_name}")\n        print("-" * 100)\n        print(f"Training feature mode: {feature_mode_name}")\n        print(f"Number of features: {len(feature_cols)}")\n        print(f"Number of initial targets: {len(target_records_all)}")\n        metrics_df = train_one_feature_mode(\n            df=df,\n            target_records_all=target_records_all,\n            feature_cols=feature_cols,\n            site_name=site_name,\n            model_name=network_label(network),\n            feature_mode=feature_mode_name,\n            out_dir=out_dir,\n            network=network,\n        )\n        summaries.append(metrics_df)\n\n    all_metrics = pd.concat(summaries, ignore_index=True) if summaries else pd.DataFrame()\n    all_metrics.to_csv(base_out / "ALL_feature_modes_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    return all_metrics\n\n\ndef parse_heights(text: Optional[str]) -> Optional[List[int]]:\n    if text is None or str(text).strip().lower() in {"", "none", "auto"}:\n        return None\n    return [int(x.strip()) for x in str(text).split(",") if x.strip()]\n\n\ndef main():\n    parser = argparse.ArgumentParser(description="Train multi-variable multi-height profile bias-correction model.")\n    parser.add_argument("--train_csv", type=str, default=DEFAULT_TRAIN_CSV, help="A-tower ML_ready CSV used for training.")\n    parser.add_argument("--output_root", type=str, default=DEFAULT_OUTPUT_ROOT, help="Output root folder.")\n    parser.add_argument("--network", type=str, default=NETWORK, choices=["CNN_LSTM", "TCN"], help="Backbone network.")\n    parser.add_argument("--feature_modes", nargs="+", default=["all", "corrFDR"], help="Feature modes: all corrFDR")\n    parser.add_argument("--heights", type=str, default=",".join(map(str, DEFAULT_HEIGHTS_M)) if DEFAULT_HEIGHTS_M else "auto",\n                        help="Comma-separated heights, or \'auto\'.")\n    parser.add_argument("--target_groups", nargs="+", default=DEFAULT_TARGET_GROUPS,\n                        help="Targets to use if available: wind_uv temp log_tke")\n    parser.add_argument("--date_start", type=str, default=None)\n    parser.add_argument("--date_end", type=str, default=None)\n    args = parser.parse_args()\n\n    if not args.train_csv:\n        raise ValueError("Please provide --train_csv path/to/A_tower_ML_ready.csv")\n    train_for_csv(\n        train_csv=Path(args.train_csv),\n        output_root=Path(args.output_root),\n        network=args.network,\n        feature_modes=args.feature_modes,\n        heights_m=parse_heights(args.heights),\n        target_groups=args.target_groups,\n        date_start=args.date_start,\n        date_end=args.date_end,\n    )\n\n\n\n\n# =============================================================================\n# V2: shared-backbone + separate output heads + gated MOST-magnitude PINN\n# =============================================================================\n# This section overrides the earlier train_one_feature_mode(), train_for_csv(),\n# and main() functions. It keeps all data-preparation utilities above, but uses a\n# shared encoder with separate wind/temp/TKE heads. In PINN cases, the MOST loss\n# is applied only to wind-speed magnitude reconstructed from predicted u/v.\n\n# V2 functions below use the User configuration defined at the top of this file.\n\ndef u_mo_candidates(h: int) -> List[str]:\n    return [f"U_MO{h} (m/s)", f"U_MO_{h}m (m/s)", f"U_MO{h}", f"MOST_WS{h} (m/s)", f"MOST_WS{h}"]\n\n\ndef mo_minus_candidates(h: int) -> List[str]:\n    return [f"MO_minus_WRF{h} (m/s)", f"MO_minus_WRF_{h}m (m/s)", f"MO_minus_WRF{h}"]\n\n\ndef height_weight_vector_pinn(heights: Sequence[int]) -> np.ndarray:\n    if not PINN_USE_HEIGHT_GATE:\n        return np.ones(len(heights), dtype=float)\n    h = np.asarray(heights, dtype=float)\n    full = float(PINN_HEIGHT_FULL_WEIGHT_M)\n    zero = float(PINN_HEIGHT_ZERO_WEIGHT_M)\n    if zero <= full:\n        return (h <= full).astype(float)\n    w = np.ones_like(h, dtype=float)\n    w[h <= full] = 1.0\n    mid = (h > full) & (h < zero)\n    w[mid] = (zero - h[mid]) / (zero - full)\n    w[h >= zero] = 0.0\n    return np.clip(w, 0.0, 1.0)\n\n\ndef pblh_gate_matrix_pinn(df: pd.DataFrame, idx: np.ndarray, heights: Sequence[int]) -> np.ndarray:\n    if not PINN_USE_PBLH_GATE or "WRF_PBLH (m)" not in df.columns:\n        return np.ones((len(idx), len(heights)), dtype=float)\n    pblh = pd.to_numeric(df.loc[idx, "WRF_PBLH (m)"], errors="coerce").values.astype(float)\n    h = np.asarray(heights, dtype=float)[None, :]\n    p = pblh[:, None]\n    ratio = np.divide(h, p, out=np.full((len(idx), len(heights)), np.nan), where=np.isfinite(p) & (p > 1.0))\n    full = float(PINN_FULL_Z_OVER_PBLH)\n    zero = float(PINN_ZERO_Z_OVER_PBLH)\n    gate = np.ones_like(ratio, dtype=float)\n    if zero <= full:\n        gate = (ratio <= full).astype(float)\n    else:\n        gate[ratio <= full] = 1.0\n        mid = (ratio > full) & (ratio < zero)\n        gate[mid] = (zero - ratio[mid]) / (zero - full)\n        gate[ratio >= zero] = 0.0\n    gate[~np.isfinite(gate)] = 1.0\n    return np.clip(gate, 0.0, 1.0)\n\n\ndef order_targets_for_heads(y: np.ndarray, mask: np.ndarray, records: Sequence[TargetRecord]):\n    """Reorder targets so model output = [wind head, temp head, tke head, other]."""\n    def key_item(item):\n        j, r = item\n        group = 0 if r.var in {"u", "v", "ws", "wd"} else 1 if r.var == "temp" else 2 if r.var == "log_tke" else 3\n        var_order = {"u": 0, "v": 1, "ws": 2, "wd": 3, "temp": 4, "log_tke": 5}.get(r.var, 9)\n        return (group, int(r.height), var_order, j)\n    ordered = sorted(list(enumerate(records)), key=key_item)\n    order = [j for j, _ in ordered]\n    records2 = [records[j] for j in order]\n    return y[:, order], mask[:, order], records2, order\n\n\ndef output_group_indices(records: Sequence[TargetRecord]) -> Dict[str, List[int]]:\n    out = {"wind": [], "temp": [], "tke": [], "other": []}\n    for j, r in enumerate(records):\n        if r.var in {"u", "v", "ws", "wd"}:\n            out["wind"].append(j)\n        elif r.var == "temp":\n            out["temp"].append(j)\n        elif r.var == "log_tke":\n            out["tke"].append(j)\n        else:\n            out["other"].append(j)\n    return out\n\n\ndef wind_uv_pairs(records: Sequence[TargetRecord]) -> List[Tuple[int, int, int]]:\n    """Return list of (height, u_index, v_index) for heights having both u and v targets."""\n    by = {}\n    for j, r in enumerate(records):\n        if r.var in {"u", "v"}:\n            by.setdefault(int(r.height), {})[r.var] = j\n    pairs = []\n    for h in sorted(by):\n        if "u" in by[h] and "v" in by[h]:\n            pairs.append((h, by[h]["u"], by[h]["v"]))\n    return pairs\n\n\ndef build_encoder_heads_model(input_shape, target_records: Sequence[TargetRecord], network: str):\n    """Shared CNN-LSTM/TCN encoder with separate wind/temp/TKE heads."""\n    tf, layers, models, callbacks, optimizers = import_tf()\n    tag = network_label(network)\n    inp = layers.Input(shape=input_shape, name="profile_time_window")\n\n    if tag == "CNN_LSTM":\n        x = layers.Conv1D(64, kernel_size=3, padding="causal", activation="relu")(inp)\n        x = layers.Dropout(DROPOUT)(x)\n        x = layers.Conv1D(32, kernel_size=3, padding="causal", activation="relu")(x)\n        x = layers.Dropout(DROPOUT)(x)\n        enc = layers.LSTM(64, return_sequences=False, name="shared_lstm_encoder")(x)\n    elif tag == "TCN":\n        x = layers.Conv1D(TCN_FILTERS, kernel_size=1, padding="same")(inp)\n        x = layers.Activation("relu")(x)\n        dilations = tuple(TCN_DILATIONS) if TCN_DILATIONS is not None else auto_tcn_dilations(input_shape[0])\n        for d in dilations:\n            x = tcn_residual_block(x, filters=TCN_FILTERS, kernel_size=TCN_KERNEL_SIZE,\n                                   dilation_rate=int(d), dropout=TCN_DROPOUT)\n        enc = layers.Lambda(lambda t: t[:, -1, :], name="take_last_time_step")(x)\n        enc = layers.Dense(TCN_DENSE_UNITS, activation="relu", name="shared_tcn_dense")(enc)\n    else:\n        raise ValueError(network)\n\n    groups = output_group_indices(target_records)\n    heads = []\n\n    if groups["wind"]:\n        w = layers.Dense(64, activation="relu", name="wind_head_dense1")(enc)\n        w = layers.Dropout(DROPOUT, name="wind_head_dropout")(w)\n        heads.append(layers.Dense(len(groups["wind"]), name="wind_head_scaled")(w))\n\n    if groups["temp"]:\n        t = layers.Dense(32, activation="relu", name="temp_head_dense1")(enc)\n        t = layers.Dropout(DROPOUT, name="temp_head_dropout")(t)\n        heads.append(layers.Dense(len(groups["temp"]), name="temp_head_scaled")(t))\n\n    if groups["tke"]:\n        k = layers.Dense(32, activation="relu", name="tke_head_dense1")(enc)\n        k = layers.Dropout(DROPOUT, name="tke_head_dropout")(k)\n        heads.append(layers.Dense(len(groups["tke"]), name="tke_head_scaled")(k))\n\n    if groups["other"]:\n        o = layers.Dense(32, activation="relu", name="other_head_dense1")(enc)\n        heads.append(layers.Dense(len(groups["other"]), name="other_head_scaled")(o))\n\n    if not heads:\n        raise ValueError("No output heads were created. Check target_records.")\n    out = heads[0] if len(heads) == 1 else layers.Concatenate(name="delta_multivar_profile_scaled")(heads)\n    return models.Model(inp, out, name=f"{tag}_sharedBackbone_multiHead")\n\n\ndef masked_huber_loss_v2(n_outputs: int, delta: float = 1.0):\n    tf, *_ = import_tf()\n    def loss(y_true_concat, y_pred):\n        y_true = y_true_concat[:, 0:n_outputs]\n        mask = y_true_concat[:, n_outputs:2 * n_outputs]\n        err = y_pred - y_true\n        abs_e = tf.abs(err)\n        huber = tf.where(abs_e <= delta, 0.5 * tf.square(err), delta * (abs_e - 0.5 * delta))\n        return tf.reduce_sum(mask * huber) / (tf.reduce_sum(mask) + 1e-6)\n    return loss\n\n\ndef masked_mae_metric_v2(n_outputs: int):\n    tf, *_ = import_tf()\n    def masked_mae(y_true_concat, y_pred):\n        y_true = y_true_concat[:, 0:n_outputs]\n        mask = y_true_concat[:, n_outputs:2 * n_outputs]\n        err = tf.abs(y_pred - y_true)\n        return tf.reduce_sum(mask * err) / (tf.reduce_sum(mask) + 1e-6)\n    masked_mae.__name__ = "masked_mae"\n    return masked_mae\n\n\ndef pinn_mostmag_loss(n_outputs: int, y_mean: np.ndarray, y_scale: np.ndarray,\n                      records: Sequence[TargetRecord], lambda_mo: float, lambda_smooth: float):\n    """Supervised masked Huber + gated MOST wind-speed-magnitude loss.\n\n    y_true_concat = [y_data_scaled, mask_data, wrf_u, wrf_v, wrf_ws, u_mo, gate]\n    The aux terms have n_wind columns each, where n_wind is the number of heights\n    with both u and v targets.\n    """\n    tf, *_ = import_tf()\n    pairs = wind_uv_pairs(records)\n    n_wind = len(pairs)\n    u_idx = [p[1] for p in pairs]\n    v_idx = [p[2] for p in pairs]\n    heights = [p[0] for p in pairs]\n    y_mean_tf = tf.constant(np.asarray(y_mean, dtype=np.float32), dtype=tf.float32)\n    y_scale_tf = tf.constant(np.asarray(y_scale, dtype=np.float32), dtype=tf.float32)\n    u_idx_tf = tf.constant(u_idx, dtype=tf.int32)\n    v_idx_tf = tf.constant(v_idx, dtype=tf.int32)\n    heights_tf = tf.constant(np.asarray(heights, dtype=np.float32), dtype=tf.float32)\n\n    def huber(e, delta=1.0):\n        abs_e = tf.abs(e)\n        return tf.where(abs_e <= delta, 0.5 * tf.square(e), delta * (abs_e - 0.5 * delta))\n\n    def loss(y_true_concat, y_pred):\n        y_true = y_true_concat[:, 0:n_outputs]\n        mask = y_true_concat[:, n_outputs:2 * n_outputs]\n        err = y_pred - y_true\n        sup = huber(err, delta=1.0)\n        sup_loss = tf.reduce_sum(mask * sup) / (tf.reduce_sum(mask) + 1e-6)\n\n        if n_wind < 1 or lambda_mo <= 0.0:\n            return sup_loss\n\n        offset = 2 * n_outputs\n        wrf_u = y_true_concat[:, offset:offset + n_wind]\n        offset += n_wind\n        wrf_v = y_true_concat[:, offset:offset + n_wind]\n        offset += n_wind\n        wrf_ws = y_true_concat[:, offset:offset + n_wind]\n        offset += n_wind\n        u_mo = y_true_concat[:, offset:offset + n_wind]\n        offset += n_wind\n        gate = y_true_concat[:, offset:offset + n_wind]\n\n        y_pred_phys = y_pred * y_scale_tf[None, :] + y_mean_tf[None, :]\n        du = tf.gather(y_pred_phys, u_idx_tf, axis=1)\n        dv = tf.gather(y_pred_phys, v_idx_tf, axis=1)\n        u_corr = wrf_u + du\n        v_corr = wrf_v + dv\n        ws_corr = tf.sqrt(tf.maximum(tf.square(u_corr) + tf.square(v_corr), 1e-12))\n\n        pred_residual = ws_corr - wrf_ws\n        phys_residual = u_mo - wrf_ws\n        phys_each = huber(pred_residual - phys_residual, delta=1.0)\n        gate_sum = tf.reduce_sum(gate)\n        mo_loss = tf.cond(\n            gate_sum > 0.0,\n            lambda: tf.reduce_sum(gate * phys_each) / (gate_sum + 1e-6),\n            lambda: tf.constant(0.0, dtype=y_pred.dtype),\n        )\n\n        smooth_loss = tf.constant(0.0, dtype=y_pred.dtype)\n        if n_wind >= 3 and lambda_smooth > 0.0:\n            dz = heights_tf[1:] - heights_tf[:-1]\n            slopes = (pred_residual[:, 1:] - pred_residual[:, :-1]) / dz[None, :]\n            curvature = slopes[:, 1:] - slopes[:, :-1]\n            smooth_loss = tf.reduce_mean(tf.square(curvature))\n\n        return sup_loss + float(lambda_mo) * mo_loss + float(lambda_smooth) * smooth_loss\n\n    return loss\n\n\ndef compile_model_v2(model, n_outputs: int, y_mean=None, y_scale=None, records=None,\n                     use_pinn: bool = False, lambda_mo: float = 0.0, lambda_smooth: float = 0.0):\n    tf, layers, models, callbacks, optimizers = import_tf()\n    if use_pinn:\n        loss_fn = pinn_mostmag_loss(n_outputs, y_mean, y_scale, records, lambda_mo, lambda_smooth)\n    else:\n        loss_fn = masked_huber_loss_v2(n_outputs, delta=1.0)\n    model.compile(optimizer=optimizers.Adam(learning_rate=LEARNING_RATE),\n                  loss=loss_fn,\n                  metrics=[masked_mae_metric_v2(n_outputs)])\n    return model\n\n\ndef make_pinn_aux_and_gate_summary(df: pd.DataFrame, idx: np.ndarray, train_i: np.ndarray,\n                                   records: Sequence[TargetRecord]) -> Tuple[np.ndarray, pd.DataFrame]:\n    pairs = wind_uv_pairs(records)\n    n = len(idx)\n    if not pairs:\n        return np.empty((n, 0), dtype=float), pd.DataFrame()\n\n    wrf_u_list, wrf_v_list, wrf_ws_list, umo_list = [], [], [], []\n    heights = []\n    gate_cols = []\n    summary_rows = []\n\n    rec_by = {(r.var, int(r.height)): r for r in records}\n    for h, u_j, v_j in pairs:\n        heights.append(h)\n        u_rec = rec_by[("u", h)]\n        v_rec = rec_by[("v", h)]\n        wrf_u = pd.to_numeric(df.loc[idx, u_rec.wrf_col], errors="coerce").values.astype(float)\n        wrf_v = pd.to_numeric(df.loc[idx, v_rec.wrf_col], errors="coerce").values.astype(float)\n        wrf_ws_col = first_existing(df, wrf_ws_candidates(h))\n        if wrf_ws_col is not None:\n            wrf_ws = pd.to_numeric(df.loc[idx, wrf_ws_col], errors="coerce").values.astype(float)\n        else:\n            wrf_ws = np.sqrt(wrf_u ** 2 + wrf_v ** 2)\n\n        umo_col = first_existing(df, u_mo_candidates(h))\n        mo_minus_col = first_existing(df, mo_minus_candidates(h))\n        if umo_col is not None:\n            u_mo = pd.to_numeric(df.loc[idx, umo_col], errors="coerce").values.astype(float)\n        elif mo_minus_col is not None:\n            mo_minus = pd.to_numeric(df.loc[idx, mo_minus_col], errors="coerce").values.astype(float)\n            u_mo = wrf_ws + mo_minus\n        else:\n            u_mo = np.full(n, np.nan, dtype=float)\n\n        phys_residual = u_mo - wrf_ws\n        gate = (np.isfinite(wrf_u) & np.isfinite(wrf_v) & np.isfinite(wrf_ws) & np.isfinite(u_mo)).astype(float)\n        finite_train = phys_residual[train_i][np.isfinite(phys_residual[train_i])]\n        qlo, qhi = np.nan, np.nan\n        if finite_train.size >= 10:\n            qlo, qhi = np.nanquantile(finite_train, [PINN_GATE_QLOW, PINN_GATE_QHIGH])\n            gate *= ((phys_residual >= qlo) & (phys_residual <= qhi)).astype(float)\n        else:\n            gate *= 0.0\n\n        wrf_u_list.append(wrf_u)\n        wrf_v_list.append(wrf_v)\n        wrf_ws_list.append(wrf_ws)\n        umo_list.append(np.where(np.isfinite(u_mo), u_mo, wrf_ws))\n        gate_cols.append(gate)\n        summary_rows.append({\n            "height_m": h,\n            "umo_col": umo_col if umo_col is not None else "",\n            "mo_minus_col": mo_minus_col if mo_minus_col is not None else "",\n            "qlo_train_phys_residual": qlo,\n            "qhi_train_phys_residual": qhi,\n            "finite_MOST_ratio_all": float(np.isfinite(u_mo).mean()),\n            "quantile_gate_mean_before_height_pblh": float(np.nanmean(gate)),\n        })\n\n    wrf_u_arr = np.column_stack(wrf_u_list)\n    wrf_v_arr = np.column_stack(wrf_v_list)\n    wrf_ws_arr = np.column_stack(wrf_ws_list)\n    u_mo_arr = np.column_stack(umo_list)\n    gate_arr = np.column_stack(gate_cols)\n\n    hw = height_weight_vector_pinn(heights)[None, :]\n    pblh_gate = pblh_gate_matrix_pinn(df, idx, heights)\n    gate_arr = gate_arr * hw * pblh_gate\n    gate_arr[~np.isfinite(gate_arr)] = 0.0\n\n    summary = pd.DataFrame(summary_rows)\n    if not summary.empty:\n        summary["height_weight"] = height_weight_vector_pinn(heights)\n        summary["pblh_gate_mean"] = np.nanmean(pblh_gate, axis=0)\n        summary["final_gate_mean"] = np.nanmean(gate_arr, axis=0)\n        summary["final_gate_nonzero_ratio"] = (gate_arr > 0).mean(axis=0)\n\n    aux = np.concatenate([wrf_u_arr, wrf_v_arr, wrf_ws_arr, u_mo_arr, gate_arr], axis=1).astype(float)\n    aux[~np.isfinite(aux)] = 0.0\n    return aux, summary\n\n\ndef validation_selection_score(metrics_df: pd.DataFrame) -> float:\n    if metrics_df is None or metrics_df.empty:\n        return np.inf\n    sub = metrics_df[(metrics_df["split"] == "val") & (metrics_df["height_m"] == "ALL_PROFILE")]\n    if sub.empty:\n        return np.inf\n    score = 0.0\n    used = 0\n    for _, row in sub.iterrows():\n        var = str(row["variable"])\n        if var == "WS_from_uv" and np.isfinite(row.get("RMSE", np.nan)):\n            score += PINN_SCORE_WEIGHTS["WS_from_uv_RMSE"] * float(row["RMSE"]); used += 1\n        elif var == "WD_from_uv" and np.isfinite(row.get("MAE", np.nan)):\n            score += PINN_SCORE_WEIGHTS["WD_from_uv_MAE"] * float(row["MAE"]); used += 1\n        elif var == "T" and np.isfinite(row.get("RMSE", np.nan)):\n            score += PINN_SCORE_WEIGHTS["T_RMSE"] * float(row["RMSE"]); used += 1\n        elif var == "TKE" and np.isfinite(row.get("RMSE", np.nan)):\n            score += PINN_SCORE_WEIGHTS["TKE_RMSE"] * float(row["RMSE"]); used += 1\n    return score if used > 0 else np.inf\n\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    reset_seed()\n    ensure_dir(out_dir)\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n    dfp = prepare_features(df, feature_cols, target_cols_all, extra_cols)\n\n    X, y, mask, idx = make_windows_masked(dfp, feature_cols, target_cols_all, require_any_target=True)\n    if len(X) < 30:\n        raise ValueError(f"{feature_mode}: too few valid windows ({len(X)}).")\n    train_i, val_i, test_i = split_chronological(len(X))\n\n    y, mask, target_records, keep_target_idx = prune_targets_by_training_availability(y, mask, train_i, target_records_all)\n    y, mask, target_records, head_order = order_targets_for_heads(y, mask, target_records)\n    n_outputs = len(target_records)\n\n    X_train, X_val, X_test = X[train_i], X[val_i], X[test_i]\n    y_train, y_val, y_test = y[train_i], y[val_i], y[test_i]\n    mask_train, mask_val, mask_test = mask[train_i], mask[val_i], mask[test_i]\n\n    x_scaler = fit_x_scaler(X_train)\n    X_train_s = transform_windows(X_train, x_scaler)\n    X_val_s = transform_windows(X_val, x_scaler)\n    X_test_s = transform_windows(X_test, x_scaler)\n\n    y_mean, y_scale = fit_y_scaler_params(y_train, mask_train)\n    y_train_s = fill_missing_scaled_targets(transform_y(y_train, y_mean, y_scale), mask_train)\n    y_val_s = fill_missing_scaled_targets(transform_y(y_val, y_mean, y_scale), mask_val)\n\n    base_train_concat = np.concatenate([y_train_s, mask_train], axis=1)\n    base_val_concat = np.concatenate([y_val_s, mask_val], axis=1)\n\n    aux_all = np.empty((len(idx), 0), dtype=float)\n    gate_summary = pd.DataFrame()\n    if use_pinn_mostmag:\n        aux_all, gate_summary = make_pinn_aux_and_gate_summary(dfp, idx, train_i, target_records)\n        gate_summary.to_csv(out_dir / "pinn_gate_summary_by_height.csv", index=False, encoding="utf-8-sig")\n        base_train_concat = np.concatenate([base_train_concat, aux_all[train_i]], axis=1)\n        base_val_concat = np.concatenate([base_val_concat, aux_all[val_i]], axis=1)\n\n    best_payload = None\n    sweep_rows = []\n    lambda_list = PINN_LAMBDA_MO_CANDIDATES if use_pinn_mostmag else [0.0]\n\n    for lam in lambda_list:\n        reset_seed()\n        model = build_encoder_heads_model(X_train_s.shape[1:], target_records, network=network)\n        model = compile_model_v2(model, n_outputs=n_outputs, y_mean=y_mean, y_scale=y_scale,\n                                 records=target_records, use_pinn=use_pinn_mostmag,\n                                 lambda_mo=lam, lambda_smooth=PINN_LAMBDA_SMOOTH if use_pinn_mostmag else 0.0)\n        hist = fit_model(model, X_train_s, base_train_concat, X_val_s, base_val_concat)\n        pred_val = inverse_y(model.predict(X_val_s, verbose=0), y_mean, y_scale)\n        pred_table_val, metrics_val = build_prediction_table_and_metrics(\n            dfp, idx[val_i], target_records, pred_val, np.asarray(["val"] * len(val_i)),\n            site_name, model_name, feature_mode\n        )\n        score = validation_selection_score(metrics_val)\n        row = {"lambda_MO": lam, "lambda_smooth": PINN_LAMBDA_SMOOTH if use_pinn_mostmag else 0.0,\n               "selection_score": score}\n        for _, r in metrics_val[(metrics_val["height_m"] == "ALL_PROFILE")].iterrows():\n            var = str(r["variable"])\n            row[f"val_{var}_RMSE"] = r.get("RMSE", np.nan)\n            row[f"val_{var}_MAE"] = r.get("MAE", np.nan)\n            row[f"val_{var}_Skill_RMSE_pct"] = r.get("Skill_RMSE_pct", np.nan)\n        sweep_rows.append(row)\n        if best_payload is None or score < best_payload[0]:\n            best_payload = (score, lam, model, hist)\n\n    pd.DataFrame(sweep_rows).to_csv(out_dir / "pinn_lambda_sweep.csv" if use_pinn_mostmag else out_dir / "lambda_sweep_not_used.csv",\n                                    index=False, encoding="utf-8-sig")\n    if best_payload is None:\n        raise RuntimeError("No valid model was trained.")\n    best_score, best_lambda, model, hist = best_payload\n    plot_loss(hist, out_dir / "loss.png", f"{model_name}_{feature_mode}_lambda_{best_lambda}")\n\n    pred_train = inverse_y(model.predict(X_train_s, verbose=0), y_mean, y_scale)\n    pred_val = inverse_y(model.predict(X_val_s, verbose=0), y_mean, y_scale)\n    pred_test = inverse_y(model.predict(X_test_s, verbose=0), y_mean, y_scale)\n    delta_pred = np.full((len(idx), n_outputs), np.nan, dtype=float)\n    delta_pred[train_i, :] = pred_train\n    delta_pred[val_i, :] = pred_val\n    delta_pred[test_i, :] = pred_test\n\n    split_labels = np.asarray([""] * len(idx), dtype=object)\n    split_labels[train_i] = "train"\n    split_labels[val_i] = "val"\n    split_labels[test_i] = "test"\n\n    pred_table, metrics_df = build_prediction_table_and_metrics(\n        dfp, idx, target_records, delta_pred, split_labels, site_name, model_name, feature_mode\n    )\n    pred_table.to_csv(out_dir / "predictions_train_val_test.csv", index=False, encoding="utf-8-sig")\n    metrics_df.to_csv(out_dir / "metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n\n    model.save(out_dir / "model.keras")\n    joblib.dump(x_scaler, out_dir / "x_scaler.joblib")\n\n    metadata = {\n        "script_version": "code2_profile_C0C8_WSWD_TKE_T_directWS_PINN",\n        "site_name": site_name,\n        "model_name": model_name,\n        "network": network_label(network),\n        "feature_mode": feature_mode,\n        "use_pinn_mostmag": bool(use_pinn_mostmag),\n        "best_lambda_MO": float(best_lambda),\n        "lambda_smooth": float(PINN_LAMBDA_SMOOTH if use_pinn_mostmag else 0.0),\n        "selection_score": float(best_score),\n        "architecture": "shared_backbone_separate_heads_wind_temp_tke",\n        "time_col": TIME_COL,\n        "window_size": WINDOW_SIZE,\n        "feature_cols": list(feature_cols),\n        "target_records": [asdict(r) for r in target_records],\n        "y_mean": y_mean.tolist(),\n        "y_scale": y_scale.tolist(),\n        "train_frac": TRAIN_FRAC,\n        "val_frac": VAL_FRAC,\n        "epochs": EPOCHS,\n        "batch_size": BATCH_SIZE,\n        "learning_rate": LEARNING_RATE,\n        "pinn_note": "MOST loss, if enabled, constrains only wind-speed magnitude reconstructed from predicted u/v. T and TKE are supervised only.",\n    }\n    with open(out_dir / "metadata.json", "w", encoding="utf-8") as f:\n        json.dump(metadata, f, ensure_ascii=False, indent=2)\n    pd.Series(feature_cols, name="feature").to_csv(out_dir / "features_used.csv", index=False, encoding="utf-8-sig")\n    pd.DataFrame([asdict(r) for r in target_records]).to_csv(out_dir / "targets_used.csv", index=False, encoding="utf-8-sig")\n    return metrics_df\n\n\ndef parse_case_mode(case: str):\n    c = case.strip().lower()\n    if c in {"nomost_all", "all", "nomost_all_features"}:\n        return "all", "noMOST_all_features", False\n    if c in {"nomost_corrfdr", "corrfdr", "nomost_corrfdr_selected_features"}:\n        return "corrFDR", "noMOST_corrFDR_selected_features", False\n    if c in {"pinn_mostmag_all", "pinn_all", "mostmagpinn_all"}:\n        return "all", "PINN_MOSTmag_all_features", True\n    if c in {"pinn_mostmag_corrfdr", "pinn_corrfdr", "mostmagpinn_corrfdr"}:\n        return "corrFDR", "PINN_MOSTmag_corrFDR_selected_features", True\n    raise ValueError(f"Unknown case: {case}")\n\n\ndef train_for_csv(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = ("noMOST_all", "noMOST_corrFDR", "PINN_MOSTmag_all", "PINN_MOSTmag_corrFDR"),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    site_name = safe_name(train_csv.stem.replace("ML_ready_ref10_", ""))\n    base_out = ensure_dir(output_root / site_name)\n    precheck_dir = ensure_dir(base_out / "00_pre")\n    cases_root = ensure_dir(base_out / "cases")\n    comparison_dir = ensure_dir(base_out / "02_cmp")\n    print("=" * 100)\n    print(f"Training site/tower: {site_name}")\n    print(f"Input CSV: {train_csv}")\n    print(f"Output root: {base_out}")\n    print(f"  precheck:   {precheck_dir}")\n    print(f"  cases:      {cases_root}")\n    print(f"  comparison: {comparison_dir}")\n    print(f"Network: {network_label(network)}")\n\n    df = load_ml_ready(train_csv, date_start=date_start, date_end=date_end)\n    df, target_records_all, used_heights = detect_targets_and_create_columns(df, heights_m=heights_m, target_groups=target_groups)\n    all_features = build_feature_set(df, used_heights)\n    if not all_features:\n        raise ValueError("No WRF input features found.")\n\n    pd.DataFrame([asdict(r) for r in target_records_all]).to_csv(base_out / "detected_all_targets.csv", index=False, encoding="utf-8-sig")\n    pd.Series(all_features, name="all_candidate_feature").to_csv(base_out / "all_candidate_features.csv", index=False, encoding="utf-8-sig")\n\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n    dfp_all = prepare_features(df, all_features, target_cols_all, extra_cols)\n    X0, y0, mask0, idx0 = make_windows_masked(dfp_all, all_features, target_cols_all, require_any_target=True)\n    if len(X0) < 30:\n        raise ValueError(f"Too few valid windows for initial split ({len(X0)}).")\n    train_i0, val_i0, test_i0 = split_chronological(len(X0))\n    train_row_idx = idx0[train_i0]\n\n    # Cache corrFDR selection so noMOST and PINN use exactly the same selected features.\n    selected_features_cache = None\n    summaries = []\n    for case in feature_modes:\n        selection_mode, feature_mode_name, use_pinn = parse_case_mode(case)\n        if selection_mode == "all":\n            feature_cols = all_features\n        elif selection_mode == "corrFDR":\n            if selected_features_cache is None:\n                selected_features_cache, report = select_corr_fdr_features(dfp_all, train_row_idx, all_features, target_records_all)\n                report.to_csv(base_out / "corrFDR_feature_screening_report.csv", index=False, encoding="utf-8-sig")\n                pd.Series(selected_features_cache, name="selected_feature").to_csv(base_out / "corrFDR_selected_features.csv", index=False, encoding="utf-8-sig")\n            feature_cols = selected_features_cache\n        else:\n            raise ValueError(selection_mode)\n\n        out_dir = ensure_dir(cases_root / f"{network_label(network)}_{feature_mode_name}")\n        print("-" * 100)\n        print(f"Training case: {feature_mode_name}")\n        print(f"Use MOSTmag PINN: {use_pinn}")\n        print(f"Number of features: {len(feature_cols)}")\n        print(f"Number of initial targets: {len(target_records_all)}")\n        metrics_df = train_one_feature_mode(\n            df=df,\n            target_records_all=target_records_all,\n            feature_cols=feature_cols,\n            site_name=site_name,\n            model_name=network_label(network),\n            feature_mode=feature_mode_name,\n            out_dir=out_dir,\n            network=network,\n            use_pinn_mostmag=use_pinn,\n        )\n        summaries.append(metrics_df)\n\n    all_metrics = pd.concat(summaries, ignore_index=True) if summaries else pd.DataFrame()\n    all_metrics.to_csv(comparison_dir / "ALL_cases_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    all_metrics.to_csv(comparison_dir / "ALL_cases_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    all_metrics.to_csv(base_out / "ALL_cases_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    comp = all_metrics[(all_metrics["split"].isin(["test", "val"])) & (all_metrics["height_m"] == "ALL_PROFILE")].copy()\n    if not comp.empty:\n        comp.sort_values(["split", "variable", "RMSE"], na_position="last").to_csv(\n            comparison_dir / "case_comparison_ALL_PROFILE_val_test.csv", index=False, encoding="utf-8-sig"\n        )\n    return all_metrics\n\n\ndef main():\n    if USE_CODE_CONFIG:\n        if not CODE_TRAIN_CSV or "path\\\\to" in CODE_TRAIN_CSV or "path\\\\\\\\to" in CODE_TRAIN_CSV:\n            raise ValueError("Please edit CODE_TRAIN_CSV in the User configuration block before running.")\n        train_for_csv(\n            train_csv=Path(CODE_TRAIN_CSV),\n            output_root=Path(CODE_OUTPUT_ROOT),\n            network=CODE_NETWORK,\n            feature_modes=CODE_CASES,\n            heights_m=CODE_HEIGHTS_M,\n            target_groups=CODE_TARGET_GROUPS,\n            date_start=CODE_DATE_START,\n            date_end=CODE_DATE_END,\n        )\n        return\n\n    parser = argparse.ArgumentParser(description="Train shared-backbone multi-head MOSTmag-PINN model.")\n    parser.add_argument("--train_csv", type=str, default=DEFAULT_TRAIN_CSV)\n    parser.add_argument("--output_root", type=str, default=DEFAULT_OUTPUT_ROOT)\n    parser.add_argument("--network", type=str, default=NETWORK, choices=["CNN_LSTM", "TCN"])\n    parser.add_argument("--cases", nargs="+", default=CODE_CASES)\n    parser.add_argument("--heights", type=str, default=",".join(map(str, DEFAULT_HEIGHTS_M)) if DEFAULT_HEIGHTS_M else "auto")\n    parser.add_argument("--target_groups", nargs="+", default=DEFAULT_TARGET_GROUPS)\n    parser.add_argument("--date_start", type=str, default=None)\n    parser.add_argument("--date_end", type=str, default=None)\n    args = parser.parse_args()\n    train_for_csv(Path(args.train_csv), Path(args.output_root), network=args.network, feature_modes=args.cases,\n                  heights_m=parse_heights(args.heights), target_groups=args.target_groups,\n                  date_start=args.date_start, date_end=args.date_end)\n\n\n\n# =============================================================================\n# V3 PATCH: MOST input features + complete profile ablation + diagnostic plots\n# =============================================================================\n# This patch keeps the V2 shared-backbone/separate-head model, and adds:\n#   1) MOST profile features as optional model inputs.\n#   2) Complete ablation cases:\n#        raw_WRF\n#        noMOST_all\n#        noMOST_corrFDR\n#        MOSTinput_all\n#        MOSTinput_corrFDR\n#        PINN_MOSTmag_all\n#        PINN_MOSTmag_corrFDR\n#        MOSTinput_PINN_MOSTmag_all\n#        MOSTinput_PINN_MOSTmag_corrFDR\n#   3) Diagnostic plots for each case and profile-level ablation figures.\n\nCODE_CASES = [\n    "raw_WRF",\n    "noMOST_all",\n    "noMOST_corrFDR",\n    "MOSTinput_all",\n    "MOSTinput_corrFDR",\n    "PINN_MOSTmag_all",\n    "PINN_MOSTmag_corrFDR",\n    "MOSTinput_PINN_MOSTmag_all",\n    "MOSTinput_PINN_MOSTmag_corrFDR",\n]\n\n\ndef most_input_candidates_for_height(h: int) -> List[str]:\n    """MOST-related profile features that can be used as model inputs."""\n    return [\n        f"U_MO{h} (m/s)", f"U_MO_{h}m (m/s)", f"U_MO{h}",\n        f"MOST_WS{h} (m/s)", f"MOST_WS{h}",\n        f"MO_minus_WRF{h} (m/s)", f"MO_minus_WRF_{h}m (m/s)", f"MO_minus_WRF{h}",\n        f"MOST_minus_WRF{h} (m/s)", f"MOST_minus_WRF_{h}m (m/s)", f"MOST_minus_WRF{h}",\n    ]\n\n\ndef add_auto_most_columns_for_inputs(df: pd.DataFrame, heights: Sequence[int]) -> pd.DataFrame:\n    """Create U_MO_auto = WRF_WS + MO_minus_WRF when direct U_MO is absent."""\n    out = df.copy()\n    for h in heights:\n        direct = first_existing(out, u_mo_candidates(h))\n        if direct is not None:\n            continue\n        mo_minus = first_existing(out, mo_minus_candidates(h) + [\n            f"MOST_minus_WRF{h} (m/s)", f"MOST_minus_WRF_{h}m (m/s)", f"MOST_minus_WRF{h}",\n        ])\n        wrf_ws = first_existing(out, wrf_ws_candidates(h))\n        if mo_minus is not None and wrf_ws is not None:\n            c = f"U_MO{h}_auto_from_MO_minus_WRF (m/s)"\n            out[c] = pd.to_numeric(out[wrf_ws], errors="coerce") + pd.to_numeric(out[mo_minus], errors="coerce")\n    return out\n\n\ndef build_feature_set_with_most(df: pd.DataFrame, heights: Sequence[int], include_most: bool = False) -> List[str]:\n    """Build noMOST or MOSTinput feature set."""\n    base = build_feature_set(df, heights)\n    if not include_most:\n        return base\n    most_cols: List[str] = []\n    for h in heights:\n        most_cols.extend(available_features(df, most_input_candidates_for_height(h)))\n        auto_col = f"U_MO{h}_auto_from_MO_minus_WRF (m/s)"\n        if auto_col in df.columns:\n            most_cols.append(auto_col)\n    return list(dict.fromkeys(base + most_cols))\n\n\ndef plot_profile_prediction_diagnostics(pred_csv: Path, out_dir: Path, feature_mode: str) -> None:\n    """Save profile and time-series diagnostic plots for one trained profile case."""\n    try:\n        if not Path(pred_csv).exists():\n            return\n        dfp = pd.read_csv(pred_csv)\n        if dfp.empty:\n            return\n        dft = dfp[dfp["split"].astype(str).str.lower().eq("test")].copy() if "split" in dfp.columns else dfp.copy()\n        if dft.empty:\n            dft = dfp.copy()\n\n        # Mean vertical profile plots for WS, TKE, and T when available.\n        import re as _re\n        profile_specs = [\n            ("WS_from_uv", r"OBS_WS(\\d+)_from_uv \\(m/s\\)", "OBS_WS{h}_from_uv (m/s)", "WRF_WS{h}_from_uv (m/s)", "WS{h}_corr_pred_from_uv (m/s)", "m/s"),\n            ("TKE", r"OBS_TKE(\\d+)", "OBS_TKE{h}", "WRF_TKE{h}", "TKE{h}_corr_pred", "m2/s2"),\n            ("T", r"OBS_T(\\d+)", "OBS_T{h}", "WRF_T{h}", "T{h}_corr_pred", "K"),\n        ]\n\n        for label, pattern, obs_tpl, wrf_tpl, pred_tpl, unit in profile_specs:\n            heights = []\n            for c in dft.columns:\n                m = _re.match(pattern, str(c))\n                if m:\n                    heights.append(int(m.group(1)))\n            heights = sorted(set(heights))\n            rows = []\n            for h in heights:\n                obs_col, wrf_col, pred_col = obs_tpl.format(h=h), wrf_tpl.format(h=h), pred_tpl.format(h=h)\n                if all(c in dft.columns for c in [obs_col, wrf_col, pred_col]):\n                    rows.append((h,\n                                 pd.to_numeric(dft[obs_col], errors="coerce").mean(),\n                                 pd.to_numeric(dft[wrf_col], errors="coerce").mean(),\n                                 pd.to_numeric(dft[pred_col], errors="coerce").mean()))\n            if rows:\n                arr = np.asarray(rows, dtype=float)\n                plt.figure(figsize=(5.4, 6.2))\n                plt.plot(arr[:, 1], arr[:, 0], marker="o", label="OBS")\n                plt.plot(arr[:, 2], arr[:, 0], marker="o", label="WRF")\n                plt.plot(arr[:, 3], arr[:, 0], marker="o", label="Corrected")\n                plt.xlabel(f"{label} ({unit})")\n                plt.ylabel("Height (m)")\n                plt.title(f"Mean test profile: {feature_mode}")\n                plt.grid(True, alpha=0.3)\n                plt.legend()\n                plt.tight_layout()\n                plt.savefig(out_dir / f"plot_mean_test_profile_{safe_name(label)}.png", dpi=300)\n                plt.close()\n\n        # Time series for the first available WS height.\n        ws_heights = []\n        for c in dft.columns:\n            m = re.match(r"OBS_WS(\\d+)_from_uv \\(m/s\\)", str(c))\n            if m:\n                ws_heights.append(int(m.group(1)))\n        if ws_heights:\n            h = sorted(set(ws_heights))[0]\n            obs_col = f"OBS_WS{h}_from_uv (m/s)"\n            wrf_col = f"WRF_WS{h}_from_uv (m/s)"\n            pred_col = f"WS{h}_corr_pred_from_uv (m/s)"\n            if all(c in dft.columns for c in [obs_col, wrf_col, pred_col]):\n                x = pd.to_datetime(dft[TIME_COL], errors="coerce") if TIME_COL in dft.columns else np.arange(len(dft))\n                plt.figure(figsize=(11, 4.2))\n                plt.plot(x, dft[obs_col], label="OBS", linewidth=1.2)\n                plt.plot(x, dft[wrf_col], label="WRF", linewidth=1.0, alpha=0.8)\n                plt.plot(x, dft[pred_col], label="Corrected", linewidth=1.0, alpha=0.9)\n                plt.xlabel("Time")\n                plt.ylabel(f"WS at {h} m (m/s)")\n                plt.title(f"Test WS time series: {feature_mode}, {h} m")\n                plt.grid(True, alpha=0.3)\n                plt.legend()\n                plt.tight_layout()\n                plt.savefig(out_dir / f"plot_test_timeseries_WS{h}.png", dpi=300)\n                plt.close()\n    except Exception as e:\n        print(f"[plot] Failed to create profile diagnostics for {feature_mode}: {e}")\n\n\ndef _primary_metric_name_from_var_profile(var: str) -> str:\n    return "MAE" if str(var).upper().startswith("WD") or "WD" in str(var).upper() else "RMSE"\n\n\ndef _pretty_case_label_profile(label: str, width: int = 18) -> str:\n    return textwrap.fill(str(label).replace("_", " "), width=width)\n\n\ndef _annotate_bar_values_profile(ax, values, fmt: str = "{:.3f}") -> None:\n    vals = [float(v) for v in values if np.isfinite(v)]\n    if not vals:\n        return\n    ymax = max(vals)\n    offset = 0.015 * ymax if ymax > 0 else 0.02\n    for i, v in enumerate(values):\n        if not np.isfinite(v):\n            continue\n        ax.text(i, float(v) + offset, fmt.format(float(v)), ha="center", va="bottom", fontsize=8)\n\n\ndef export_code2_all_profile_tables(all_metrics: pd.DataFrame, out_dir: Path) -> None:\n    """Export ALL_PROFILE val/test tables for quick comparison (CSV + PNG)."""\n    try:\n        if all_metrics is None or all_metrics.empty:\n            return\n        sub = all_metrics[(all_metrics["height_m"] == "ALL_PROFILE") & (all_metrics["split"].isin(["val", "test"]))].copy()\n        if sub.empty:\n            return\n        sub["primary_metric"] = sub["variable"].astype(str).apply(_primary_metric_name_from_var_profile)\n        sub["primary_error"] = np.where(\n            sub["variable"].astype(str).str.contains("WD", case=False, na=False),\n            pd.to_numeric(sub.get("MAE", np.nan), errors="coerce"),\n            pd.to_numeric(sub.get("RMSE", np.nan), errors="coerce"),\n        )\n        cols = [c for c in ["split", "feature_mode", "variable", "primary_metric", "primary_error", "RMSE", "MAE", "Pearson_r"] if c in sub.columns]\n        table_df = sub[cols].copy().sort_values(["split", "variable", "primary_error"], na_position="last")\n        table_df.to_csv(out_dir / "code2_all_profile_error_metrics_table.csv", index=False, encoding="utf-8-sig")\n        for (split, var), g in table_df.groupby(["split", "variable"]):\n            show = g.copy().reset_index(drop=True)\n            for c in ["primary_error", "RMSE", "MAE", "Pearson_r"]:\n                if c in show.columns:\n                    show[c] = pd.to_numeric(show[c], errors="coerce").round(3)\n            fig_h = max(1.8, 0.42 * (len(show) + 2))\n            fig, ax = plt.subplots(figsize=(11.0, fig_h))\n            ax.axis("off")\n            tbl = ax.table(cellText=show.values, colLabels=show.columns, cellLoc="center", loc="center")\n            tbl.auto_set_font_size(False)\n            tbl.set_fontsize(8)\n            tbl.scale(1.0, 1.25)\n            ax.set_title(f"Code2 {split} ALL_PROFILE metrics table: {var}", pad=10)\n            plt.tight_layout()\n            plt.savefig(out_dir / f"code2_{split}_ALL_PROFILE_metrics_table_{safe_name(var)}.png", dpi=300, bbox_inches="tight")\n            plt.close(fig)\n    except Exception as e:\n        print(f"[plot] Failed to export Code2 metric tables: {e}")\n\n\ndef plot_profile_ablation_summary(all_metrics: pd.DataFrame, out_dir: Path) -> None:\n    """Plot ALL_PROFILE validation/test ablation bars."""\n    try:\n        if all_metrics is None or all_metrics.empty:\n            return\n        sub = all_metrics[(all_metrics["height_m"] == "ALL_PROFILE") & (all_metrics["split"].isin(["val", "test"]))].copy()\n        if sub.empty:\n            return\n        # Use RMSE except WD where MAE is more interpretable.\n        sub["primary_error"] = np.where(\n            sub["variable"].astype(str).str.contains("WD", case=False, na=False),\n            pd.to_numeric(sub.get("MAE", np.nan), errors="coerce"),\n            pd.to_numeric(sub.get("RMSE", np.nan), errors="coerce"),\n        )\n        for (split, var), g in sub.groupby(["split", "variable"]):\n            gg = g[np.isfinite(g["primary_error"])].sort_values("primary_error")\n            if gg.empty:\n                continue\n            x = np.arange(len(gg))\n            y = gg["primary_error"].values\n            labels = [_pretty_case_label_profile(s, width=18) for s in gg["feature_mode"].astype(str).values]\n            metric_name = _primary_metric_name_from_var_profile(var)\n            fig, ax = plt.subplots(figsize=(max(10.5, 0.82 * len(gg)), 6.4))\n            ax.bar(x, y)\n            ax.set_xticks(x)\n            ax.set_xticklabels(labels, rotation=32, ha="right")\n            ax.set_ylabel(f"Primary error ({metric_name})", fontsize=12)\n            ax.set_title(f"{split} ALL_PROFILE ablation: {var} ({metric_name})", fontsize=13)\n            ax.grid(True, axis="y", alpha=0.3)\n            _annotate_bar_values_profile(ax, y)\n            fig.subplots_adjust(bottom=0.40, left=0.18, right=0.98, top=0.90)\n            fig.savefig(out_dir / f"plot_ablation_{split}_ALL_PROFILE_{safe_name(var)}.png", dpi=300)\n            plt.close(fig)\n        export_code2_all_profile_tables(all_metrics, out_dir)\n    except Exception as e:\n        print(f"[plot] Failed to create profile ablation summary: {e}")\n\n\n# Add plots after each V2/V3 training case.\n_train_one_feature_mode_v2_core = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    metrics_df = _train_one_feature_mode_v2_core(\n        df=df,\n        target_records_all=target_records_all,\n        feature_cols=feature_cols,\n        site_name=site_name,\n        model_name=model_name,\n        feature_mode=feature_mode,\n        out_dir=out_dir,\n        network=network,\n        use_pinn_mostmag=use_pinn_mostmag,\n    )\n    plot_profile_prediction_diagnostics(out_dir / "predictions_train_val_test.csv", out_dir, feature_mode)\n    return metrics_df\n\n\ndef run_raw_wrf_profile_case(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    out_dir: Path,\n) -> pd.DataFrame:\n    """Raw WRF profile baseline using the same windowing/masked-target logic."""\n    ensure_dir(out_dir)\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n    dfp = prepare_features(df, feature_cols, target_cols_all, extra_cols)\n\n    X, y, mask, idx = make_windows_masked(dfp, feature_cols, target_cols_all, require_any_target=True)\n    if len(X) < 30:\n        raise ValueError(f"raw_WRF: too few valid windows ({len(X)}).")\n    train_i, val_i, test_i = split_chronological(len(X))\n\n    split_labels = np.asarray([""] * len(idx), dtype=object)\n    split_labels[train_i] = "train"\n    split_labels[val_i] = "val"\n    split_labels[test_i] = "test"\n    zero_delta = np.zeros((len(idx), len(target_records_all)), dtype=float)\n\n    pred_table, metrics_df = build_prediction_table_and_metrics(\n        dfp, idx, target_records_all, zero_delta, split_labels,\n        site_name=site_name, model_name="raw_WRF", feature_mode="raw_WRF"\n    )\n    pred_table.to_csv(out_dir / "predictions_raw_WRF_train_val_test.csv", index=False, encoding="utf-8-sig")\n    metrics_df.to_csv(out_dir / "metrics_raw_WRF_train_val_test.csv", index=False, encoding="utf-8-sig")\n    plot_profile_prediction_diagnostics(out_dir / "predictions_raw_WRF_train_val_test.csv", out_dir, "raw_WRF")\n    return metrics_df\n\n\ndef parse_case_mode(case: str):\n    """Return selection_mode, feature_mode_name, use_pinn, use_most_input, is_raw."""\n    c = case.strip().lower()\n    if c in {"raw", "raw_wrf", "wrf"}:\n        return "all", "raw_WRF", False, False, True\n\n    use_pinn = "pinn" in c or "mostmag" in c\n    use_most_input = "mostinput" in c or "most_input" in c\n    if "corrfdr" in c or "corr" in c:\n        selection = "corrFDR"\n    elif "all" in c or c in {"nomost", "mostinput", "pinn_mostmag"}:\n        selection = "all"\n    else:\n        raise ValueError(f"Unknown case: {case}")\n\n    if use_most_input and use_pinn:\n        feature_name = "MOSTinput_PINN_MOSTmag_corrFDR_selected_features" if selection == "corrFDR" else "MOSTinput_PINN_MOSTmag_all_features"\n    elif use_most_input:\n        feature_name = "MOSTinput_corrFDR_selected_features" if selection == "corrFDR" else "MOSTinput_all_features"\n    elif use_pinn:\n        feature_name = "PINN_MOSTmag_corrFDR_selected_features" if selection == "corrFDR" else "PINN_MOSTmag_all_features"\n    else:\n        feature_name = "noMOST_corrFDR_selected_features" if selection == "corrFDR" else "noMOST_all_features"\n\n    return selection, feature_name, use_pinn, use_most_input, False\n\n\ndef train_for_csv(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = tuple(CODE_CASES),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    """V3 train_for_csv with complete ablation and MOST input features."""\n    site_name = safe_name(train_csv.stem.replace("ML_ready_ref10_", ""))\n    base_out = ensure_dir(output_root / site_name)\n    precheck_dir = ensure_dir(base_out / "00_pre")\n    cases_root = ensure_dir(base_out / "cases")\n    comparison_dir = ensure_dir(base_out / "02_cmp")\n    print("=" * 100)\n    print(f"Training site/tower: {site_name}")\n    print(f"Input CSV: {train_csv}")\n    print(f"Output root: {base_out}")\n    print(f"  precheck:   {precheck_dir}")\n    print(f"  cases:      {cases_root}")\n    print(f"  comparison: {comparison_dir}")\n    print(f"Network: {network_label(network)}")\n\n    df = load_ml_ready(train_csv, date_start=date_start, date_end=date_end)\n    df, target_records_all, used_heights = detect_targets_and_create_columns(df, heights_m=heights_m, target_groups=target_groups)\n    df = apply_obs_target_qc_code2(df, target_records_all, precheck_dir, site_name)\n\n    # MOST columns can be direct U_MO(h) or reconstructed from MO_minus_WRF(h).\n    df = add_auto_most_columns_for_inputs(df, used_heights)\n\n    no_most_features = build_feature_set_with_most(df, used_heights, include_most=False)\n    most_input_features = build_feature_set_with_most(df, used_heights, include_most=True)\n    if not no_most_features:\n        raise ValueError("No WRF input features found.")\n\n    pd.DataFrame([asdict(r) for r in target_records_all]).to_csv(precheck_dir / "detected_all_targets.csv", index=False, encoding="utf-8-sig")\n    pd.Series(no_most_features, name="noMOST_candidate_feature").to_csv(precheck_dir / "noMOST_candidate_features.csv", index=False, encoding="utf-8-sig")\n    pd.Series(most_input_features, name="MOSTinput_candidate_feature").to_csv(precheck_dir / "MOSTinput_candidate_features.csv", index=False, encoding="utf-8-sig")\n    pd.DataFrame({\n        "height_m": used_heights,\n        "has_MOST_input_feature": [any(c in df.columns for c in most_input_candidates_for_height(h)) or f"U_MO{h}_auto_from_MO_minus_WRF (m/s)" in df.columns for h in used_heights],\n    }).to_csv(precheck_dir / "MOSTinput_availability_by_height.csv", index=False, encoding="utf-8-sig")\n    export_pretraining_input_audit_code2(\n        df=df,\n        records=target_records_all,\n        feature_cols=list(dict.fromkeys(no_most_features + most_input_features)),\n        used_heights=used_heights,\n        out_dir=precheck_dir,\n        site_name=site_name,\n    )\n    plot_pretraining_timeseries_code2(\n        df=df,\n        records=target_records_all,\n        feature_cols=list(dict.fromkeys(no_most_features + most_input_features)),\n        out_dir=precheck_dir,\n        site_name=site_name,\n    )\n    export_training_window_validity_audit_code2(\n        df=df,\n        records=target_records_all,\n        feature_cols=list(dict.fromkeys(no_most_features + most_input_features)),\n        out_dir=precheck_dir,\n        site_name=site_name,\n    )\n\n    # Prepare train indices separately for noMOST and MOSTinput feature pools.\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n\n    dfp_nomost = prepare_features(df, no_most_features, target_cols_all, extra_cols)\n    X0, y0, mask0, idx0 = make_windows_masked(dfp_nomost, no_most_features, target_cols_all, require_any_target=True)\n    if len(X0) < 30:\n        raise ValueError(f"Too few valid windows for initial split ({len(X0)}).")\n    train_i0, _, _ = split_chronological(len(X0))\n    train_row_idx_nomost = idx0[train_i0]\n\n    dfp_most = prepare_features(df, most_input_features, target_cols_all, extra_cols)\n    X1, y1, mask1, idx1 = make_windows_masked(dfp_most, most_input_features, target_cols_all, require_any_target=True)\n    if len(X1) < 30:\n        print("[warning] MOSTinput feature pool produced too few windows; MOSTinput cases may be skipped.")\n        train_row_idx_most = train_row_idx_nomost\n    else:\n        train_i1, _, _ = split_chronological(len(X1))\n        train_row_idx_most = idx1[train_i1]\n\n    selected_nomost_cache = None\n    selected_most_cache = None\n    summaries = []\n\n    for case in feature_modes:\n        selection_mode, feature_mode_name, use_pinn, use_most_input, is_raw = parse_case_mode(case)\n        if use_most_input and len(most_input_features) <= len(no_most_features):\n            msg = f"[{site_name}] MOSTinput case \'{feature_mode_name}\' requested, but no additional MOST input features were found."\n            if bool(globals().get("CODE_REQUIRE_MOSTINPUT_CASES", False)):\n                raise RuntimeError(msg + " Formal C0-C8 requires complete MOSTinput cases; check U_MO/MO_minus_WRF columns.")\n            print(msg + " Skip this case.")\n            continue\n\n        candidate_pool = most_input_features if use_most_input else no_most_features\n        dfp_pool = dfp_most if use_most_input else dfp_nomost\n        train_row_idx = train_row_idx_most if use_most_input else train_row_idx_nomost\n\n        if selection_mode == "all":\n            feature_cols = candidate_pool\n        elif selection_mode == "corrFDR":\n            if use_most_input:\n                if selected_most_cache is None:\n                    selected_most_cache, report = select_corr_fdr_features(dfp_pool, train_row_idx, candidate_pool, target_records_all)\n                    report.to_csv(precheck_dir / "corrFDR_feature_screening_report_MOSTinput.csv", index=False, encoding="utf-8-sig")\n                    pd.Series(selected_most_cache, name="selected_feature").to_csv(precheck_dir / "corrFDR_selected_features_MOSTinput.csv", index=False, encoding="utf-8-sig")\n                feature_cols = selected_most_cache\n            else:\n                if selected_nomost_cache is None:\n                    selected_nomost_cache, report = select_corr_fdr_features(dfp_pool, train_row_idx, candidate_pool, target_records_all)\n                    report.to_csv(precheck_dir / "corrFDR_feature_screening_report_noMOST.csv", index=False, encoding="utf-8-sig")\n                    pd.Series(selected_nomost_cache, name="selected_feature").to_csv(precheck_dir / "corrFDR_selected_features_noMOST.csv", index=False, encoding="utf-8-sig")\n                feature_cols = selected_nomost_cache\n        else:\n            raise ValueError(selection_mode)\n\n        out_dir = ensure_dir(cases_root / f"{network_label(network)}_{feature_mode_name}")\n        print("-" * 100)\n        print(f"Running case: {feature_mode_name}")\n        print(f"Use MOST input features: {use_most_input}")\n        print(f"Use MOSTmag PINN: {use_pinn}")\n        print(f"Number of features: {len(feature_cols)}")\n        print(f"Number of initial targets: {len(target_records_all)}")\n\n        if is_raw:\n            metrics_df = run_raw_wrf_profile_case(\n                df=df,\n                target_records_all=target_records_all,\n                feature_cols=feature_cols,\n                site_name=site_name,\n                out_dir=out_dir,\n            )\n        else:\n            metrics_df = train_one_feature_mode(\n                df=df,\n                target_records_all=target_records_all,\n                feature_cols=feature_cols,\n                site_name=site_name,\n                model_name=network_label(network),\n                feature_mode=feature_mode_name,\n                out_dir=out_dir,\n                network=network,\n                use_pinn_mostmag=use_pinn,\n            )\n        metrics_df["requested_case"] = case\n        metrics_df["uses_MOST_input_features"] = bool(use_most_input)\n        metrics_df["uses_PINN_MOSTmag"] = bool(use_pinn)\n        summaries.append(metrics_df)\n\n    all_metrics = pd.concat(summaries, ignore_index=True) if summaries else pd.DataFrame()\n    all_metrics.to_csv(comparison_dir / "ALL_cases_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    all_metrics.to_csv(base_out / "ALL_cases_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    comp = all_metrics[(all_metrics["split"].isin(["test", "val"])) & (all_metrics["height_m"] == "ALL_PROFILE")].copy() if not all_metrics.empty else pd.DataFrame()\n    if not comp.empty:\n        comp["primary_error"] = np.where(\n            comp["variable"].astype(str).str.contains("WD", case=False, na=False),\n            pd.to_numeric(comp.get("MAE", np.nan), errors="coerce"),\n            pd.to_numeric(comp.get("RMSE", np.nan), errors="coerce"),\n        )\n        comp.sort_values(["split", "variable", "primary_error"], na_position="last").to_csv(\n            comparison_dir / "case_comparison_ALL_PROFILE_val_test.csv", index=False, encoding="utf-8-sig"\n        )\n    plot_profile_ablation_summary(all_metrics, comparison_dir)\n    return all_metrics\n\n\n\n\n# =============================================================================\n# USER-SELECTION PATCH: explicit training tower/heights + OBS-valid time span\n# =============================================================================\n\ndef resolve_code2_train_csv() -> Path:\n    """Resolve training CSV from either explicit CODE_TRAIN_CSV or tower substring."""\n    if globals().get("CODE_TRAIN_SITE_CONTAINS", None):\n        root = Path(globals().get("CODE_ML_READY_ROOT", Path(CODE_TRAIN_CSV).parents[1]))\n        glob_pat = globals().get("CODE_TRAIN_FILE_GLOB", "**/ML_ready_ref10_*_d03.csv")\n        key = str(CODE_TRAIN_SITE_CONTAINS)\n        files = sorted(root.glob(glob_pat))\n        files = [f for f in files if key in str(f)]\n        if not files:\n            raise FileNotFoundError(f"No train CSV found under {root} with pattern={glob_pat} and CODE_TRAIN_SITE_CONTAINS={key!r}")\n        if len(files) > 1:\n            print(f"[resolve train CSV] Multiple files matched {key!r}; use the first one:")\n            for f in files:\n                print(f"  - {f}")\n        return files[0]\n    return Path(CODE_TRAIN_CSV)\n\n\ndef height_tag_from_list(heights_m: Optional[Sequence[int]]) -> str:\n    if heights_m is None:\n        return "h_auto"\n    hs = [int(h) for h in heights_m]\n    if len(hs) == 1:\n        return f"h{hs[0]}m"\n    return f"h{hs[0]}-{hs[-1]}m_n{len(hs)}"\n\n\ndef _first_existing_user_select(df: pd.DataFrame, candidates: Sequence[str]) -> Optional[str]:\n    for c in candidates:\n        if c in df.columns:\n            return c\n    return None\n\n\ndef _obs_valid_mask_for_height_user_select(df: pd.DataFrame, h: int) -> np.ndarray:\n    n = len(df)\n    if n == 0:\n        return np.zeros(0, dtype=bool)\n\n    flag_col = _first_existing_user_select(df, [\n        f"obs_valid_flag_{int(h)}", f"OBS_valid_flag_{int(h)}", f"valid_flag_{int(h)}",\n        "obs_valid_flag",\n    ])\n    if flag_col is not None:\n        flag = pd.to_numeric(df[flag_col], errors="coerce")\n        return (flag == 1).fillna(False).values.astype(bool)\n\n    obs_ws = _first_existing_user_select(df, obs_ws_candidates(int(h)))\n    obs_wd = _first_existing_user_select(df, obs_wd_candidates(int(h)))\n    obs_u = _first_existing_user_select(df, obs_u_candidates(int(h)))\n    obs_v = _first_existing_user_select(df, obs_v_candidates(int(h)))\n\n    masks = []\n    if obs_ws is not None:\n        m = pd.to_numeric(df[obs_ws], errors="coerce").notna().values\n        if obs_wd is not None:\n            m &= pd.to_numeric(df[obs_wd], errors="coerce").notna().values\n        masks.append(m)\n    if obs_u is not None and obs_v is not None:\n        masks.append(\n            pd.to_numeric(df[obs_u], errors="coerce").notna().values\n            & pd.to_numeric(df[obs_v], errors="coerce").notna().values\n        )\n\n    if not masks:\n        # No clear validity information; keep original rows for this height.\n        return np.ones(n, dtype=bool)\n\n    out = np.zeros(n, dtype=bool)\n    for m in masks:\n        out |= np.asarray(m, dtype=bool)\n    return out\n\n\ndef _selected_heights_for_filter(df: pd.DataFrame) -> List[int]:\n    hs = globals().get("CODE_HEIGHTS_M", None)\n    if hs is None:\n        hs = auto_detect_heights(df)\n    return [int(h) for h in hs]\n\n\n_load_ml_ready_code2_user_select_base = load_ml_ready\n\ndef load_ml_ready(csv_path: Path, date_start: Optional[str] = None, date_end: Optional[str] = None) -> pd.DataFrame:\n    """Load CSV and crop to selected-height OBS-valid span."""\n    df = _load_ml_ready_code2_user_select_base(csv_path, date_start=date_start, date_end=date_end)\n    if not globals().get("AUTO_FILTER_TO_VALID_OBS_PERIOD", True) or df.empty or TIME_COL not in df.columns:\n        return df\n\n    heights = _selected_heights_for_filter(df)\n    if not heights:\n        return df\n\n    masks = [_obs_valid_mask_for_height_user_select(df, h) for h in heights]\n    if not masks:\n        return df\n\n    mode = str(globals().get("VALID_OBS_PERIOD_HEIGHT_MODE", "any")).lower()\n    if mode == "all" and len(masks) > 1:\n        valid = np.logical_and.reduce(masks)\n    else:\n        valid = np.logical_or.reduce(masks)\n\n    if valid.sum() < 1:\n        print(f"[OBS-period filter] No valid OBS found for heights={heights} in {csv_path}; keep full CSV period.")\n        return df\n\n    t = pd.to_datetime(df[TIME_COL], errors="coerce")\n    valid_times = t[valid & t.notna().values]\n    if valid_times.empty:\n        return df\n\n    t0 = valid_times.min()\n    t1 = valid_times.max()\n    buf = pd.Timedelta(hours=float(globals().get("VALID_OBS_PERIOD_BUFFER_HOURS", 0.0)))\n    out = df[(t >= t0 - buf) & (t <= t1 + buf)].copy().reset_index(drop=True)\n    print(\n        f"[OBS-period filter] tower={Path(csv_path).parent.name} | heights={heights} | mode={mode} | "\n        f"valid OBS span: {t0} -> {t1} | rows {len(df)} -> {len(out)}"\n    )\n    return out\n\n\n_detect_targets_code2_user_select_base = detect_targets_and_create_columns\n\ndef detect_targets_and_create_columns(\n    df: pd.DataFrame,\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n) -> Tuple[pd.DataFrame, List[TargetRecord], List[int]]:\n    """Create targets, then mask invalid OBS/targets by height-specific valid flags."""\n    out, records, used_heights = _detect_targets_code2_user_select_base(df, heights_m=heights_m, target_groups=target_groups)\n\n    if globals().get("APPLY_OBS_VALID_FLAG_TO_TARGETS", True):\n        by_height: Dict[int, np.ndarray] = {}\n        for h in used_heights:\n            by_height[int(h)] = _obs_valid_mask_for_height_user_select(out, int(h))\n        for r in records:\n            valid = by_height.get(int(r.height))\n            if valid is None:\n                continue\n            if r.obs_col in out.columns:\n                out.loc[~valid, r.obs_col] = np.nan\n            if r.target_col in out.columns:\n                out.loc[~valid, r.target_col] = np.nan\n\n    return out, records, used_heights\n\n\n\n\ndef build_target_detection_report(df: pd.DataFrame, heights: Sequence[int]) -> pd.DataFrame:\n    """Report which OBS/WRF columns are found for each requested height."""\n    rows = []\n    for h in [int(x) for x in heights]:\n        obs_ws = first_existing(df, obs_ws_candidates(h)); wrf_ws = first_existing(df, wrf_ws_candidates(h))\n        obs_wd = first_existing(df, obs_wd_candidates(h)); wrf_wd = first_existing(df, wrf_wd_candidates(h))\n        obs_t = first_existing(df, obs_temp_candidates(h)); wrf_t = first_existing(df, wrf_temp_candidates(h))\n        obs_tke = first_existing(df, obs_tke_candidates(h)); wrf_tke = first_existing(df, wrf_tke_candidates(h))\n        rows.append({\n            "height_m": h,\n            "obs_ws_col": obs_ws, "wrf_ws_col": wrf_ws,\n            "obs_wd_col": obs_wd, "wrf_wd_col": wrf_wd,\n            "wind_wswd_possible": bool(obs_ws and wrf_ws and obs_wd and wrf_wd),\n            "obs_t_col": obs_t, "wrf_t_col": wrf_t, "temp_possible": bool(obs_t and wrf_t),\n            "obs_tke_col": obs_tke, "wrf_tke_col": wrf_tke, "tke_possible": bool(obs_tke and wrf_tke),\n        })\n    return pd.DataFrame(rows)\n\n_train_for_csv_code2_user_select_base = train_for_csv\n\n\n\ndef export_pretraining_input_audit_code2(df: pd.DataFrame, records: Sequence[TargetRecord], feature_cols: List[str], used_heights: Sequence[int], out_dir: Path, site_name: str) -> None:\n    """Before training, check OBS/WRF target and feature completeness by height/variable/time span."""\n    try:\n        out_dir = Path(out_dir)\n        ensure_dir(out_dir)\n        t = pd.to_datetime(df[TIME_COL], errors="coerce") if TIME_COL in df.columns else pd.Series(pd.NaT, index=df.index)\n        rows = []\n        for r in records:\n            for role, col in [("obs", r.obs_col), ("wrf", r.wrf_col), ("target", r.target_col)]:\n                vals = pd.to_numeric(df[col], errors="coerce") if col in df.columns else pd.Series(np.nan, index=df.index)\n                m = vals.notna() & t.notna()\n                rows.append({\n                    "site": site_name,\n                    "height_m": int(r.height),\n                    "variable": r.var,\n                    "role": role,\n                    "column": col,\n                    "column_exists": col in df.columns,\n                    "finite_count": int(vals.notna().sum()),\n                    "finite_ratio": float(vals.notna().mean()) if len(vals) else np.nan,\n                    "first_valid_time": str(t[m].min()) if m.any() else None,\n                    "last_valid_time": str(t[m].max()) if m.any() else None,\n                })\n        tdf = pd.DataFrame(rows)\n        tdf.to_csv(out_dir / "pretraining_input_audit_targets.csv", index=False, encoding="utf-8-sig")\n        if not tdf.empty:\n            mat = tdf[tdf["role"].eq("target")].pivot_table(index="height_m", columns="variable", values="finite_count", aggfunc="first")\n            mat.to_csv(out_dir / "pretraining_target_finite_count_by_height_variable.csv", encoding="utf-8-sig")\n            fig, ax = plt.subplots(figsize=(max(7.0, 0.45 * max(1, len(mat.columns))), max(4.5, 0.35 * max(1, len(mat.index)))))\n            im = ax.imshow(mat.fillna(0).values, aspect="auto")\n            ax.set_xticks(np.arange(len(mat.columns))); ax.set_xticklabels(mat.columns, rotation=35, ha="right")\n            ax.set_yticks(np.arange(len(mat.index))); ax.set_yticklabels(mat.index)\n            ax.set_xlabel("Variable")\n            ax.set_ylabel("Height (m)")\n            ax.set_title("Pretraining target finite-count matrix")\n            for i in range(len(mat.index)):\n                for j in range(len(mat.columns)):\n                    ax.text(j, i, str(int(mat.fillna(0).values[i, j])), ha="center", va="center", fontsize=8)\n            fig.colorbar(im, ax=ax, label="Finite target count")\n            fig.tight_layout()\n            fig.savefig(out_dir / "plot_pretraining_target_count_matrix.png", dpi=300)\n            plt.close(fig)\n\n        feat_rows = []\n        for col in feature_cols:\n            vals = pd.to_numeric(df[col], errors="coerce") if col in df.columns else pd.Series(np.nan, index=df.index)\n            m = vals.notna() & t.notna()\n            feat_rows.append({\n                "site": site_name,\n                "feature": col,\n                "column_exists": col in df.columns,\n                "finite_count": int(vals.notna().sum()),\n                "finite_ratio": float(vals.notna().mean()) if len(vals) else np.nan,\n                "first_valid_time": str(t[m].min()) if m.any() else None,\n                "last_valid_time": str(t[m].max()) if m.any() else None,\n            })\n        fdf = pd.DataFrame(feat_rows)\n        fdf.to_csv(out_dir / "pretraining_input_audit_features.csv", index=False, encoding="utf-8-sig")\n        if not fdf.empty:\n            top = fdf.sort_values("finite_ratio", ascending=True).copy()\n            fig, ax = plt.subplots(figsize=(11.0, max(5.0, 0.23 * len(top))))\n            ax.barh(np.arange(len(top)), top["finite_ratio"].values * 100.0)\n            ax.set_yticks(np.arange(len(top)))\n            ax.set_yticklabels([_pretty_case_label_profile(v, width=32) for v in top["feature"]], fontsize=7)\n            ax.set_xlabel("Finite data ratio (%)")\n            ax.set_title("Pretraining input feature availability")\n            ax.grid(True, axis="x", alpha=0.3)\n            fig.subplots_adjust(left=0.46, right=0.98, bottom=0.10, top=0.92)\n            fig.savefig(out_dir / "plot_pretraining_feature_availability.png", dpi=300)\n            plt.close(fig)\n\n        pd.DataFrame({"used_height_m": [int(h) for h in used_heights]}).to_csv(out_dir / "pretraining_used_heights.csv", index=False, encoding="utf-8-sig")\n    except Exception as e:\n        print(f"[audit] Failed Code2 pretraining input audit: {e}")\n\n\n\n# =============================================================================\n# PRECHECK TIMESERIES PATCH: all target/features with train/val/test shading\n# =============================================================================\n\ndef _split_ranges_from_window_indices_profile(time_values: pd.Series, train_i, val_i, test_i) -> pd.DataFrame:\n    rows = []\n    for split_name, ii in [("train", train_i), ("val", val_i), ("test", test_i)]:\n        if ii is None or len(ii) == 0:\n            rows.append({"split": split_name, "n_windows": 0, "start_time": None, "end_time": None})\n            continue\n        t = pd.to_datetime(time_values.iloc[ii], errors="coerce").dropna()\n        rows.append({\n            "split": split_name,\n            "n_windows": int(len(ii)),\n            "start_time": str(t.min()) if not t.empty else None,\n            "end_time": str(t.max()) if not t.empty else None,\n        })\n    return pd.DataFrame(rows)\n\n\ndef _shade_split_ranges_profile(ax, split_ranges: pd.DataFrame) -> None:\n    colors = {"train": "#cfe8ff", "val": "#fff3bf", "test": "#ffd6d6"}\n    for _, r in split_ranges.iterrows():\n        t0 = pd.to_datetime(r.get("start_time"), errors="coerce")\n        t1 = pd.to_datetime(r.get("end_time"), errors="coerce")\n        sp = str(r.get("split"))\n        if pd.isna(t0) or pd.isna(t1):\n            continue\n        ax.axvspan(t0, t1, color=colors.get(sp, "0.9"), alpha=0.22, label=f"{sp} period")\n\n\ndef _dedup_legend_profile(ax) -> None:\n    handles, labels = ax.get_legend_handles_labels()\n    seen = set(); h2 = []; l2 = []\n    for h, l in zip(handles, labels):\n        if l not in seen:\n            h2.append(h); l2.append(l); seen.add(l)\n    if h2:\n        ax.legend(h2, l2, fontsize=8, ncol=2)\n\n\ndef plot_pretraining_timeseries_code2(\n    df: pd.DataFrame,\n    records: Sequence[TargetRecord],\n    feature_cols: List[str],\n    out_dir: Path,\n    site_name: str,\n) -> None:\n    """Plot all target OBS/WRF series and all used input features before training."""\n    try:\n        out_dir = Path(out_dir)\n        target_dir = ensure_dir(out_dir / "timeseries_targets_with_split")\n        feature_dir = ensure_dir(out_dir / "timeseries_features_with_split")\n        target_cols = [r.target_col for r in records]\n        extra_cols = []\n        for r in records:\n            extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n        split_ranges = pd.DataFrame()\n        try:\n            dfp = prepare_features(df, feature_cols, target_cols, extra_cols)\n            X, y, mask, idx = make_windows_masked(dfp, feature_cols, target_cols, require_any_target=True)\n            tr, va, te = split_chronological(len(X))\n            time_win = pd.to_datetime(dfp.loc[idx, TIME_COL], errors="coerce").reset_index(drop=True)\n            split_ranges = _split_ranges_from_window_indices_profile(time_win, tr, va, te)\n            split_ranges.to_csv(out_dir / "pretraining_split_time_ranges_from_windows.csv", index=False, encoding="utf-8-sig")\n        except Exception as e:\n            print(f"[precheck plot] split ranges unavailable: {e}")\n        t = pd.to_datetime(df[TIME_COL], errors="coerce") if TIME_COL in df.columns else pd.Series(np.arange(len(df)))\n\n        # Target plots by height/variable.\n        # Important: WRF may exist where OBS is missing. Those timestamps are NOT supervised\n        # for this target, so plot WRF used-for-training only where the target OBS is finite.\n        for r in records:\n            obs_col = r.obs_col\n            wrf_col = r.wrf_col\n            if obs_col not in df.columns and wrf_col not in df.columns:\n                continue\n            label = f"{r.var}_h{int(r.height)}"\n            obs_vals = pd.to_numeric(df[obs_col], errors="coerce") if obs_col in df.columns else pd.Series(np.nan, index=df.index)\n            wrf_vals = pd.to_numeric(df[wrf_col], errors="coerce") if wrf_col in df.columns else pd.Series(np.nan, index=df.index)\n            valid_target = obs_vals.notna() & wrf_vals.notna()\n            missing_obs = obs_vals.isna() & wrf_vals.notna()\n            fig, ax = plt.subplots(figsize=(13.5, 4.8))\n            if not split_ranges.empty:\n                _shade_split_ranges_profile(ax, split_ranges)\n            if wrf_col in df.columns:\n                ax.plot(t, wrf_vals, label=f"WRF full context: {wrf_col}", linewidth=0.7, alpha=0.22, color="0.45")\n                ax.plot(t, wrf_vals.where(valid_target), label="WRF used only where OBS target is valid", linewidth=1.0, alpha=0.9)\n            if obs_col in df.columns:\n                ax.scatter(t[valid_target], obs_vals[valid_target], label=f"OBS valid: {obs_col}", s=6, alpha=0.65)\n            if missing_obs.any():\n                ax.scatter(t[missing_obs], wrf_vals[missing_obs], label="WRF exists but OBS missing: target masked", s=8, marker="x", alpha=0.35)\n            ax.set_xlabel("Time")\n            ax.set_ylabel(label)\n            ax.set_title(f"Precheck target time series: {site_name}, {label} | valid target N={int(valid_target.sum())}")\n            ax.grid(True, alpha=0.3)\n            _dedup_legend_profile(ax)\n            fig.tight_layout()\n            fig.savefig(target_dir / f"plot_precheck_target_{safe_name(label)}.png", dpi=300)\n            plt.close(fig)\n\n        # Input feature plots.\n        for col in list(dict.fromkeys(feature_cols)):\n            if col not in df.columns:\n                continue\n            vals = pd.to_numeric(df[col], errors="coerce")\n            if vals.notna().sum() < 1:\n                continue\n            fig, ax = plt.subplots(figsize=(13.5, 4.2))\n            if not split_ranges.empty:\n                _shade_split_ranges_profile(ax, split_ranges)\n            ax.plot(t, vals, label=col, linewidth=0.9)\n            ax.set_xlabel("Time")\n            ax.set_ylabel(col)\n            ax.set_title(f"Precheck input feature with train/val/test: {site_name}, {col}")\n            ax.grid(True, alpha=0.3)\n            _dedup_legend_profile(ax)\n            fig.tight_layout()\n            fig.savefig(feature_dir / f"plot_precheck_feature_{safe_name(col)}.png", dpi=300)\n            plt.close(fig)\n    except Exception as e:\n        print(f"[precheck plot] Code2 pretraining time-series plots failed: {e}")\n\n\n\n# =============================================================================\n# OBS TARGET QC PATCH: remove implausible OBS outliers before target masking/training\n# =============================================================================\nENABLE_OBS_TARGET_QC = globals().get("ENABLE_OBS_TARGET_QC", True)\nOBS_QC_WIND_ABS_MAX_MPS = float(globals().get("OBS_QC_WIND_ABS_MAX_MPS", 35.0))\nOBS_QC_TKE_MAX = float(globals().get("OBS_QC_TKE_MAX", 30.0))\nOBS_QC_TEMP_K_MIN = float(globals().get("OBS_QC_TEMP_K_MIN", 200.0))\nOBS_QC_TEMP_K_MAX = float(globals().get("OBS_QC_TEMP_K_MAX", 330.0))\nOBS_QC_HAMPEL_ENABLE = globals().get("OBS_QC_HAMPEL_ENABLE", True)\nOBS_QC_HAMPEL_WINDOW = int(globals().get("OBS_QC_HAMPEL_WINDOW", 25))\nOBS_QC_HAMPEL_NSIGMA = float(globals().get("OBS_QC_HAMPEL_NSIGMA", 8.0))\n\n# Target-window requirement mode:\n# "any" = train a window if at least one target is valid; invalid targets are masked.\n# "all" = train a window only if every target is valid. This is very strict for profile data.\nWINDOW_TARGET_REQUIRE_MODE = str(globals().get("WINDOW_TARGET_REQUIRE_MODE", "any")).lower()\n\n\ndef _hampel_bad_mask(series: pd.Series, window: int = OBS_QC_HAMPEL_WINDOW, nsigma: float = OBS_QC_HAMPEL_NSIGMA) -> pd.Series:\n    s = pd.to_numeric(series, errors="coerce")\n    if s.notna().sum() < max(20, window):\n        return pd.Series(False, index=s.index)\n    med = s.rolling(window=window, center=True, min_periods=max(5, window // 3)).median()\n    mad = (s - med).abs().rolling(window=window, center=True, min_periods=max(5, window // 3)).median()\n    sigma = 1.4826 * mad\n    bad = (s - med).abs() > (nsigma * sigma)\n    bad = bad & sigma.notna() & (sigma > 1e-9)\n    return bad.fillna(False)\n\n\ndef apply_obs_target_qc_code2(df: pd.DataFrame, records: Sequence[TargetRecord], out_dir: Path, site_name: str) -> pd.DataFrame:\n    """Set implausible OBS target values to NaN before training; target mask then excludes them."""\n    if not ENABLE_OBS_TARGET_QC:\n        return df\n    out = df.copy()\n    rows = []\n    for r in records:\n        if r.obs_col not in out.columns:\n            continue\n        obs = pd.to_numeric(out[r.obs_col], errors="coerce")\n        bad = pd.Series(False, index=out.index)\n        reason_parts = []\n        # Hard physical/range rules.\n        if r.var in {"u", "v", "ws"}:\n            b = obs.abs() > OBS_QC_WIND_ABS_MAX_MPS\n            bad |= b\n            if b.any(): reason_parts.append(f"abs>{OBS_QC_WIND_ABS_MAX_MPS:g}")\n        elif r.var == "wd":\n            b = (obs < 0.0) | (obs > 360.0)\n            bad |= b\n            if b.any(): reason_parts.append("outside_0_360")\n        elif r.var == "log_tke":\n            b = (obs < 0.0) | (obs > OBS_QC_TKE_MAX)\n            bad |= b\n            if b.any(): reason_parts.append(f"outside_0_{OBS_QC_TKE_MAX:g}")\n        elif r.var == "temp":\n            b = (obs < OBS_QC_TEMP_K_MIN) | (obs > OBS_QC_TEMP_K_MAX)\n            bad |= b\n            if b.any(): reason_parts.append(f"outside_{OBS_QC_TEMP_K_MIN:g}_{OBS_QC_TEMP_K_MAX:g}K")\n        # Height-level WS hard QC also masks u/v/wd at that height, because U/V/WD may be derived from bad WS.\n        if r.var in {"u", "v", "wd"}:\n            ws_col = first_existing(out, obs_ws_candidates(int(r.height)))\n            if ws_col is not None:\n                ws = pd.to_numeric(out[ws_col], errors="coerce")\n                b = ws > OBS_QC_WIND_ABS_MAX_MPS\n                bad |= b\n                if b.any(): reason_parts.append(f"height_WS>{OBS_QC_WIND_ABS_MAX_MPS:g}")\n        # Robust spike filter, but skip WD because circular jumps are common.\n        if OBS_QC_HAMPEL_ENABLE and r.var != "wd":\n            b = _hampel_bad_mask(obs)\n            bad |= b\n            if b.any(): reason_parts.append("hampel_spike")\n        n_bad = int(bad.sum())\n        if n_bad > 0:\n            out.loc[bad, r.obs_col] = np.nan\n            if r.target_col in out.columns:\n                out.loc[bad, r.target_col] = np.nan\n        rows.append({\n            "site": site_name,\n            "height_m": int(r.height),\n            "variable": r.var,\n            "obs_col": r.obs_col,\n            "target_col": r.target_col,\n            "n_before_finite": int(obs.notna().sum()),\n            "n_qc_removed": n_bad,\n            "n_after_finite": int(pd.to_numeric(out[r.obs_col], errors="coerce").notna().sum()),\n            "reasons": ";".join(sorted(set(reason_parts))) if reason_parts else "",\n        })\n    try:\n        pd.DataFrame(rows).to_csv(Path(out_dir) / "pretraining_obs_target_qc_report.csv", index=False, encoding="utf-8-sig")\n    except Exception as e:\n        print(f"[OBS QC] failed to write report: {e}")\n    return out\n\n\n\ndef export_training_window_validity_audit_code2(df: pd.DataFrame, records: Sequence[TargetRecord], feature_cols: List[str], out_dir: Path, site_name: str) -> None:\n    """Audit the actual supervised windows used after QC/missing masking."""\n    try:\n        target_cols = [r.target_col for r in records]\n        extra_cols = []\n        for r in records:\n            extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n        dfp = prepare_features(df, feature_cols, target_cols, extra_cols)\n        X, y, mask, idx = make_windows_masked(dfp, feature_cols, target_cols, require_any_target=True)\n        if len(X) < 1:\n            pd.DataFrame([{ "site": site_name, "note": "no_valid_windows_after_feature_target_QC" }]).to_csv(Path(out_dir) / "pretraining_split_target_validity_audit.csv", index=False, encoding="utf-8-sig")\n            return\n        train_i, val_i, test_i = split_chronological(len(X))\n        time_win = pd.to_datetime(dfp.loc[idx, TIME_COL], errors="coerce").reset_index(drop=True)\n        rows = []\n        for split_name, ii in [("train", train_i), ("val", val_i), ("test", test_i)]:\n            for j, r in enumerate(records):\n                m = mask[ii, j] > 0\n                rows.append({\n                    "site": site_name,\n                    "split": split_name,\n                    "height_m": int(r.height),\n                    "variable": r.var,\n                    "target_col": r.target_col,\n                    "n_windows_in_split": int(len(ii)),\n                    "n_target_valid_used_in_loss": int(m.sum()),\n                    "n_target_masked_missing_or_qc": int(len(ii) - m.sum()),\n                    "valid_ratio_pct": float(m.mean() * 100.0) if len(ii) else np.nan,\n                    "split_start_time": str(time_win.iloc[ii].min()) if len(ii) else None,\n                    "split_end_time": str(time_win.iloc[ii].max()) if len(ii) else None,\n                    "window_target_requirement_mode": WINDOW_TARGET_REQUIRE_MODE,\n                })\n        pd.DataFrame(rows).to_csv(Path(out_dir) / "pretraining_split_target_validity_audit.csv", index=False, encoding="utf-8-sig")\n    except Exception as e:\n        print(f"[audit] Code2 window validity audit failed: {e}")\n\ndef train_for_csv(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = tuple(CODE_CASES),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    """Wrapper: put outputs under tower + selected-height folder to avoid overwrite."""\n    train_csv = Path(train_csv)\n    tower_tag = safe_name(train_csv.parent.name)\n    htag = height_tag_from_list(heights_m)\n    wrapped_output_root = ensure_dir(Path(output_root) / safe_name(f"{tower_tag}_{htag}"))\n    info_path = wrapped_output_root / "cfg.json"\n    with open(info_path, "w", encoding="utf-8") as f:\n        json.dump({\n            "input_csv": str(train_csv),\n            "tower_folder": train_csv.parent.name,\n            "code_train_site_contains": globals().get("CODE_TRAIN_SITE_CONTAINS", None),\n            "selected_heights_m": None if heights_m is None else [int(h) for h in heights_m],\n            "auto_filter_to_valid_obs_period": bool(globals().get("AUTO_FILTER_TO_VALID_OBS_PERIOD", True)),\n            "valid_obs_period_height_mode": str(globals().get("VALID_OBS_PERIOD_HEIGHT_MODE", "any")),\n            "valid_obs_period_buffer_hours": float(globals().get("VALID_OBS_PERIOD_BUFFER_HOURS", 0.0)),\n            "apply_obs_valid_flag_to_targets": bool(globals().get("APPLY_OBS_VALID_FLAG_TO_TARGETS", True)),\n            "time_feature_mode": "hour_only",\n            "excluded_time_features": ["month_sin", "month_cos"],\n            "window_target_requirement_mode": WINDOW_TARGET_REQUIRE_MODE,\n        }, f, ensure_ascii=False, indent=2)\n\n    # Write a pre-training detection report so skipped heights/variables can be diagnosed.\n    try:\n        df_report = load_ml_ready(train_csv, date_start=date_start, date_end=date_end)\n        report_heights = heights_m if heights_m is not None else auto_detect_heights(df_report)\n        site_name_report = safe_name(train_csv.stem.replace("ML_ready_ref10_", ""))\n        report_dir = ensure_dir(wrapped_output_root / site_name_report / "00_pre")\n        build_target_detection_report(df_report, report_heights).to_csv(\n            report_dir / "target_detection_report.csv", index=False, encoding="utf-8-sig"\n        )\n    except Exception as e:\n        print(f"[target detection report] skipped: {e}")\n\n    return _train_for_csv_code2_user_select_base(\n        train_csv=train_csv,\n        output_root=wrapped_output_root,\n        network=network,\n        feature_modes=feature_modes,\n        heights_m=heights_m,\n        target_groups=target_groups,\n        date_start=date_start,\n        date_end=date_end,\n    )\n\n\n\n\n# =============================================================================\n# FINAL PATCH: split-wise plots, corrFDR feature plots, and all-case time series\n# =============================================================================\nCODE_CASES = list(dict.fromkeys(CODE_CASES))\n\ndef _code2_plot_split_timeline(pred_csv: Path, out_dir: Path, tag: str):\n    try:\n        dfp = pd.read_csv(pred_csv)\n        if "split" not in dfp.columns or TIME_COL not in dfp.columns:\n            return\n        dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n        order = ["train", "val", "test", "application"]\n        fig, ax = plt.subplots(figsize=(11.5, 2.8))\n        for i, sp in enumerate(order):\n            d = dfp[dfp["split"].astype(str).str.lower().eq(sp)]\n            if not d.empty:\n                ax.scatter(d[TIME_COL], np.full(len(d), i), s=3, label=sp)\n        ax.set_yticks(range(len(order))); ax.set_yticklabels(order)\n        ax.set_xlabel("Time"); ax.set_title(f"Train/val/test split timeline: {tag}")\n        ax.grid(True, axis="x", alpha=0.25); ax.legend(ncol=4, fontsize=8, loc="upper center", bbox_to_anchor=(0.5, -0.20))\n        fig.subplots_adjust(bottom=0.34, left=0.11, right=0.98, top=0.85)\n        fig.savefig(Path(out_dir) / f"plot_split_timeline_{safe_name(tag)}.png", dpi=300)\n        plt.close(fig)\n    except Exception as e:\n        print(f"[plot] split timeline failed: {e}")\n\ndef _code2_heights_from_cols(dfp):\n    hs=set()\n    for c in dfp.columns:\n        for pat in [r"OBS_WS(\\d+)_from_uv", r"OBS_WS_direct(\\d+)", r"OBS_TKE(\\d+)", r"OBS_T(\\d+)$"]:\n            m=re.match(pat, str(c))\n            if m: hs.add(int(m.group(1)))\n    return sorted(hs)\n\ndef plot_profile_prediction_diagnostics(pred_csv: Path, out_dir: Path, feature_mode: str) -> None:\n    """Override: draw train/val/test split-wise time series, scatter, and mean profile plots."""\n    try:\n        pred_csv = Path(pred_csv)\n        if not pred_csv.exists(): return\n        dfp = pd.read_csv(pred_csv)\n        if dfp.empty: return\n        if "split" not in dfp.columns: dfp["split"] = "all"\n        if TIME_COL in dfp.columns: dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n        _code2_plot_split_timeline(pred_csv, out_dir, feature_mode)\n        heights = _code2_heights_from_cols(dfp)\n        specs = [\n            ("WS_from_uv", "OBS_WS{h}_from_uv (m/s)", "WRF_WS{h}_from_uv (m/s)", "WS{h}_corr_pred_from_uv (m/s)", "m/s", False),\n            ("WD_from_uv", "OBS_WD{h}_from_uv (deg)", "WRF_WD{h}_from_uv (deg)", "WD{h}_corr_pred_from_uv (deg)", "deg", True),\n            ("WS_direct", "OBS_WS_direct{h}", "WRF_WS_direct{h}", "WS_direct{h}_corr_pred", "m/s", False),\n            ("WD_direct", "OBS_WD_direct{h}", "WRF_WD_direct{h}", "WD_direct{h}_corr_pred", "deg", True),\n            ("TKE", "OBS_TKE{h}", "WRF_TKE{h}", "TKE{h}_corr_pred", "m2/s2", False),\n            ("T", "OBS_T{h}", "WRF_T{h}", "T{h}_corr_pred", "K", False),\n        ]\n        for split in ["train","val","test"]:\n            dft = dfp[dfp["split"].astype(str).str.lower().eq(split)].copy()\n            if dft.empty: continue\n            x = dft[TIME_COL] if TIME_COL in dft.columns else np.arange(len(dft))\n            for label, ot, wt, pt, unit, is_wd in specs:\n                # mean profile\n                rows=[]\n                for h in heights:\n                    oc,wc,pc=ot.format(h=h),wt.format(h=h),pt.format(h=h)\n                    if all(c in dft.columns for c in [oc,wc,pc]):\n                        rows.append((h, pd.to_numeric(dft[oc],errors="coerce").mean(), pd.to_numeric(dft[wc],errors="coerce").mean(), pd.to_numeric(dft[pc],errors="coerce").mean()))\n                if rows and not is_wd:\n                    arr=np.asarray(rows,float); fig,ax=plt.subplots(figsize=(5.6,6.2))\n                    ax.plot(arr[:,1],arr[:,0],marker="o",label="OBS"); ax.plot(arr[:,2],arr[:,0],marker="o",label="WRF"); ax.plot(arr[:,3],arr[:,0],marker="o",label="Corrected")\n                    ax.set_xlabel(f"{label} ({unit})"); ax.set_ylabel("Height (m)"); ax.set_title(f"Mean {split} profile: {feature_mode}, {label}"); ax.grid(True,alpha=0.3); ax.legend(); fig.tight_layout()\n                    fig.savefig(Path(out_dir)/f"plot_mean_{split}_profile_{safe_name(label)}.png",dpi=300); plt.close(fig)\n                for h in heights:\n                    oc,wc,pc=ot.format(h=h),wt.format(h=h),pt.format(h=h)\n                    if not all(c in dft.columns for c in [oc,wc,pc]): continue\n                    fig,ax=plt.subplots(figsize=(12,4.4))\n                    ax.plot(x,pd.to_numeric(dft[oc],errors="coerce"),label="OBS",linewidth=1.2); ax.plot(x,pd.to_numeric(dft[wc],errors="coerce"),label="WRF",linewidth=1.0,alpha=0.85); ax.plot(x,pd.to_numeric(dft[pc],errors="coerce"),label="Corrected",linewidth=1.0,alpha=0.9)\n                    ax.set_xlabel("Time"); ax.set_ylabel(f"{label} at {h} m ({unit})"); ax.set_title(f"{feature_mode} {split}: {label}, {h} m"); ax.grid(True,alpha=0.3); ax.legend(); fig.tight_layout()\n                    fig.savefig(Path(out_dir)/f"plot_{split}_timeseries_{safe_name(label)}_h{h}.png",dpi=300); plt.close(fig)\n    except Exception as e:\n        print(f"[plot] profile diagnostics failed for {feature_mode}: {e}")\n\ndef plot_corrfdr_feature_screening_outputs(base_out: Path):\n    try:\n        for rp in Path(base_out).rglob("corrFDR_feature_screening_report*.csv"):\n            rep=pd.read_csv(rp)\n            if rep.empty or "feature" not in rep.columns: continue\n            vcols=[c for c in rep.columns if ("abs" in c.lower() and "r" in c.lower()) or c=="max_abs_r"]\n            if not vcols: continue\n            vc=vcols[0]; rank=rep.groupby("feature")[vc].max().dropna().sort_values(ascending=False).head(30).reset_index()\n            fig,ax=plt.subplots(figsize=(10.8,max(5.2,0.28*len(rank)))); y=np.arange(len(rank)); ax.barh(y,rank[vc].values); ax.set_yticks(y); ax.set_yticklabels([_pretty_case_label_profile(v,30) for v in rank["feature"]],fontsize=8); ax.invert_yaxis(); ax.set_xlabel(vc); ax.set_title(f"Feature screening: {rp.stem}"); ax.grid(True,axis="x",alpha=0.3); fig.subplots_adjust(left=0.42,right=0.98,top=0.90,bottom=0.10); fig.savefig(rp.parent/f"plot_feature_screening_{safe_name(rp.stem)}.png",dpi=300); plt.close(fig)\n    except Exception as e:\n        print(f"[plot] feature screening outputs failed: {e}")\n\ndef plot_code2_case_timeseries_comparison(base_out: Path):\n    try:\n        base_out=Path(base_out); pred_files=list(base_out.rglob("predictions_train_val_test.csv"))\n        loaded=[]\n        for f in pred_files:\n            dfp=pd.read_csv(f)\n            if not dfp.empty and TIME_COL in dfp.columns:\n                dfp[TIME_COL]=pd.to_datetime(dfp[TIME_COL],errors="coerce"); loaded.append((f.parent.name,dfp))\n        if not loaded: return\n        heights=sorted(set(h for _,d in loaded for h in _code2_heights_from_cols(d)))\n        specs=[("WS_from_uv","OBS_WS{h}_from_uv (m/s)","WRF_WS{h}_from_uv (m/s)","WS{h}_corr_pred_from_uv (m/s)","m/s"),("WS_direct","OBS_WS_direct{h}","WRF_WS_direct{h}","WS_direct{h}_corr_pred","m/s"),("TKE","OBS_TKE{h}","WRF_TKE{h}","TKE{h}_corr_pred","m2/s2"),("T","OBS_T{h}","WRF_T{h}","T{h}_corr_pred","K")]\n        comp_dirs = list(Path(base_out).rglob("02_cmp"))\n        comp_root = comp_dirs[0] if comp_dirs else ensure_dir(Path(base_out) / "02_cmp")\n        out=ensure_dir(comp_root/"all_case_timeseries_comparison")\n        for split in ["train","val","test"]:\n            for h in heights:\n                for label,ot,wt,pt,unit in specs:\n                    oc,wc,pc=ot.format(h=h),wt.format(h=h),pt.format(h=h)\n                    if not any(all(c in d.columns for c in [oc,wc,pc]) for _,d in loaded): continue\n                    fig,ax=plt.subplots(figsize=(12.5,4.8)); obs_done=wrf_done=False\n                    for case,d in loaded:\n                        dd=d[d["split"].astype(str).str.lower().eq(split)].copy() if "split" in d.columns else d.copy()\n                        if dd.empty or not all(c in dd.columns for c in [oc,wc,pc]): continue\n                        if not obs_done: ax.plot(dd[TIME_COL],pd.to_numeric(dd[oc],errors="coerce"),label="OBS",linewidth=1.2); obs_done=True\n                        if not wrf_done: ax.plot(dd[TIME_COL],pd.to_numeric(dd[wc],errors="coerce"),label="WRF",linewidth=1.0,alpha=0.75); wrf_done=True\n                        ax.plot(dd[TIME_COL],pd.to_numeric(dd[pc],errors="coerce"),label=case,linewidth=0.9,alpha=0.9)\n                    ax.set_xlabel("Time"); ax.set_ylabel(f"{label} at {h} m ({unit})"); ax.set_title(f"All-case comparison, {split}: {label}, {h} m"); ax.grid(True,alpha=0.3); ax.legend(fontsize=7,ncol=2); fig.tight_layout(); fig.savefig(out/f"plot_all_case_{split}_{safe_name(label)}_h{h}.png",dpi=300); plt.close(fig)\n    except Exception as e:\n        print(f"[plot] all-case time series failed: {e}")\n\n\n\n# =============================================================================\n# RAW-WRF PLOT FIX FOR CODE2\n# raw_WRF is a baseline and has no learned correction, so raw_WRF plots show\n# OBS and WRF only. Model cases still show OBS/WRF/Corrected. All-case plots\n# skip raw_WRF as a model line because WRF baseline is already plotted.\n# =============================================================================\n\ndef plot_profile_prediction_diagnostics(pred_csv: Path, out_dir: Path, feature_mode: str) -> None:\n    try:\n        pred_csv = Path(pred_csv)\n        if not pred_csv.exists():\n            return\n        dfp = pd.read_csv(pred_csv)\n        if dfp.empty:\n            return\n        if "split" not in dfp.columns:\n            dfp["split"] = "all"\n        if TIME_COL in dfp.columns:\n            dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n        _code2_plot_split_timeline(pred_csv, out_dir, feature_mode)\n\n        is_raw = str(feature_mode).lower().startswith("raw_wrf")\n        heights = _code2_heights_from_cols(dfp)\n        specs = [\n            ("WS_from_uv", "OBS_WS{h}_from_uv (m/s)", "WRF_WS{h}_from_uv (m/s)", "WS{h}_corr_pred_from_uv (m/s)", "m/s", False),\n            ("WD_from_uv", "OBS_WD{h}_from_uv (deg)", "WRF_WD{h}_from_uv (deg)", "WD{h}_corr_pred_from_uv (deg)", "deg", True),\n            ("WS_direct", "OBS_WS_direct{h}", "WRF_WS_direct{h}", "WS_direct{h}_corr_pred", "m/s", False),\n            ("WD_direct", "OBS_WD_direct{h}", "WRF_WD_direct{h}", "WD_direct{h}_corr_pred", "deg", True),\n            ("TKE", "OBS_TKE{h}", "WRF_TKE{h}", "TKE{h}_corr_pred", "m2/s2", False),\n            ("T", "OBS_T{h}", "WRF_T{h}", "T{h}_corr_pred", "K", False),\n        ]\n        for split in ["train", "val", "test"]:\n            dft = dfp[dfp["split"].astype(str).str.lower().eq(split)].copy()\n            if dft.empty:\n                continue\n            x = dft[TIME_COL] if TIME_COL in dft.columns else np.arange(len(dft))\n            for label, ot, wt, pt, unit, is_wd in specs:\n                rows = []\n                for h in heights:\n                    oc, wc, pc = ot.format(h=h), wt.format(h=h), pt.format(h=h)\n                    need_cols = [oc, wc] if is_raw else [oc, wc, pc]\n                    if all(c in dft.columns for c in need_cols):\n                        obs_mean = pd.to_numeric(dft[oc], errors="coerce").mean()\n                        wrf_mean = pd.to_numeric(dft[wc], errors="coerce").mean()\n                        if is_raw:\n                            rows.append((h, obs_mean, wrf_mean))\n                        else:\n                            rows.append((h, obs_mean, wrf_mean, pd.to_numeric(dft[pc], errors="coerce").mean()))\n                if rows and not is_wd:\n                    arr = np.asarray(rows, float)\n                    fig, ax = plt.subplots(figsize=(5.6, 6.2))\n                    ax.plot(arr[:, 1], arr[:, 0], marker="o", label="OBS")\n                    ax.plot(arr[:, 2], arr[:, 0], marker="o", label="WRF")\n                    if not is_raw and arr.shape[1] >= 4:\n                        ax.plot(arr[:, 3], arr[:, 0], marker="o", label="Corrected")\n                    ax.set_xlabel(f"{label} ({unit})")\n                    ax.set_ylabel("Height (m)")\n                    title_prefix = "raw_WRF baseline" if is_raw else str(feature_mode)\n                    ax.set_title(f"Mean {split} profile: {title_prefix}, {label}")\n                    ax.grid(True, alpha=0.3)\n                    ax.legend()\n                    fig.tight_layout()\n                    fig.savefig(Path(out_dir) / f"plot_mean_{split}_profile_{safe_name(label)}.png", dpi=300)\n                    plt.close(fig)\n\n                for h in heights:\n                    oc, wc, pc = ot.format(h=h), wt.format(h=h), pt.format(h=h)\n                    need_cols = [oc, wc] if is_raw else [oc, wc, pc]\n                    if not all(c in dft.columns for c in need_cols):\n                        continue\n                    fig, ax = plt.subplots(figsize=(12, 4.4))\n                    ax.plot(x, pd.to_numeric(dft[oc], errors="coerce"), label="OBS", linewidth=1.2)\n                    ax.plot(x, pd.to_numeric(dft[wc], errors="coerce"), label="WRF", linewidth=1.0, alpha=0.85)\n                    if not is_raw and pc in dft.columns:\n                        ax.plot(x, pd.to_numeric(dft[pc], errors="coerce"), label="Corrected", linewidth=1.0, alpha=0.9)\n                    ax.set_xlabel("Time")\n                    ax.set_ylabel(f"{label} at {h} m ({unit})")\n                    title_prefix = "raw_WRF baseline" if is_raw else str(feature_mode)\n                    ax.set_title(f"{title_prefix} {split}: {label}, {h} m")\n                    ax.grid(True, alpha=0.3)\n                    ax.legend()\n                    fig.tight_layout()\n                    fig.savefig(Path(out_dir) / f"plot_{split}_timeseries_{safe_name(label)}_h{h}.png", dpi=300)\n                    plt.close(fig)\n    except Exception as e:\n        print(f"[plot] profile diagnostics failed for {feature_mode}: {e}")\n\n\ndef plot_code2_case_timeseries_comparison(base_out: Path):\n    try:\n        pred_files = sorted(Path(base_out).rglob("predictions_*train_val_test.csv"))\n        if not pred_files:\n            return\n        loaded = []\n        for f in pred_files:\n            try:\n                dfp = pd.read_csv(f)\n                if not dfp.empty and TIME_COL in dfp.columns:\n                    dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n                    loaded.append((f.parent.name, dfp))\n            except Exception:\n                pass\n        if not loaded:\n            return\n        heights = sorted(set(h for _, d in loaded for h in _code2_heights_from_cols(d)))\n        specs = [\n            ("WS_from_uv", "OBS_WS{h}_from_uv (m/s)", "WRF_WS{h}_from_uv (m/s)", "WS{h}_corr_pred_from_uv (m/s)", "m/s"),\n            ("WS_direct", "OBS_WS_direct{h}", "WRF_WS_direct{h}", "WS_direct{h}_corr_pred", "m/s"),\n            ("TKE", "OBS_TKE{h}", "WRF_TKE{h}", "TKE{h}_corr_pred", "m2/s2"),\n            ("T", "OBS_T{h}", "WRF_T{h}", "T{h}_corr_pred", "K"),\n        ]\n        comp_dirs = list(Path(base_out).rglob("02_cmp"))\n        comp_root = comp_dirs[0] if comp_dirs else ensure_dir(Path(base_out) / "02_cmp")\n        out = ensure_dir(comp_root / "all_case_timeseries_comparison")\n        non_raw_loaded = [(case, d) for case, d in loaded if not str(case).lower().startswith("raw_wrf")]\n        baseline_pool = loaded\n        for split in ["train", "val", "test"]:\n            for h in heights:\n                for label, ot, wt, pt, unit in specs:\n                    oc, wc, pc = ot.format(h=h), wt.format(h=h), pt.format(h=h)\n                    if not any(all(c in d.columns for c in [oc, wc]) for _, d in baseline_pool):\n                        continue\n                    if not any(all(c in d.columns for c in [oc, wc, pc]) for _, d in non_raw_loaded):\n                        continue\n                    fig, ax = plt.subplots(figsize=(12.5, 4.8))\n                    obs_done = wrf_done = False\n                    for case, d in baseline_pool:\n                        dd = d[d["split"].astype(str).str.lower().eq(split)].copy() if "split" in d.columns else d.copy()\n                        if dd.empty or not all(c in dd.columns for c in [oc, wc]):\n                            continue\n                        if not obs_done:\n                            ax.plot(dd[TIME_COL], pd.to_numeric(dd[oc], errors="coerce"), label="OBS", linewidth=1.2)\n                            obs_done = True\n                        if not wrf_done:\n                            ax.plot(dd[TIME_COL], pd.to_numeric(dd[wc], errors="coerce"), label="WRF", linewidth=1.0, alpha=0.75)\n                            wrf_done = True\n                        if obs_done and wrf_done:\n                            break\n                    for case, d in non_raw_loaded:\n                        dd = d[d["split"].astype(str).str.lower().eq(split)].copy() if "split" in d.columns else d.copy()\n                        if dd.empty or not all(c in dd.columns for c in [pc]):\n                            continue\n                        ax.plot(dd[TIME_COL], pd.to_numeric(dd[pc], errors="coerce"), label=case, linewidth=0.9, alpha=0.9)\n                    ax.set_xlabel("Time")\n                    ax.set_ylabel(f"{label} at {h} m ({unit})")\n                    ax.set_title(f"All-case comparison, {split}: {label}, {h} m")\n                    ax.grid(True, alpha=0.3)\n                    ax.legend(fontsize=7, ncol=2)\n                    fig.tight_layout()\n                    fig.savefig(out / f"plot_all_case_{split}_{safe_name(label)}_h{h}.png", dpi=300)\n                    plt.close(fig)\n    except Exception as e:\n        print(f"[plot] all-case time series failed: {e}")\n\n\n\n# =============================================================================\n# EFFECTIVE TRAIN/VAL/TEST RANGE REPORT FOR CODE2\n# Reads prediction CSVs after QC/masking and writes, per case, the actual target-valid\n# time ranges used for metrics/loss (finite OBS + finite WRF after QC).\n# =============================================================================\n\ndef _prediction_obs_wrf_pairs_profile(dfp: pd.DataFrame) -> List[Tuple[str, str, str]]:\n    pairs = []\n    for obs_col in dfp.columns:\n        if not str(obs_col).startswith("OBS_"):\n            continue\n        wrf_col = str(obs_col).replace("OBS_", "WRF_", 1)\n        if wrf_col in dfp.columns:\n            label = str(obs_col).replace("OBS_", "")\n            pairs.append((safe_name(label)[:90], obs_col, wrf_col))\n    return pairs\n\n\ndef _target_valid_segments_for_split_profile(d: pd.DataFrame, time_col: str, obs_col: str, wrf_col: str) -> List[Dict[str, object]]:\n    valid = pd.to_numeric(d[obs_col], errors="coerce").notna() & pd.to_numeric(d[wrf_col], errors="coerce").notna()\n    times = pd.to_datetime(d[time_col], errors="coerce") if time_col in d.columns else pd.Series(pd.NaT, index=d.index)\n    segments = []\n    in_seg = False\n    start = end = None\n    count = 0\n    for ok, tt in zip(valid.values, times.values):\n        if ok and pd.notna(tt):\n            if not in_seg:\n                start = pd.Timestamp(tt)\n                count = 1\n                in_seg = True\n            else:\n                count += 1\n            end = pd.Timestamp(tt)\n        else:\n            if in_seg:\n                segments.append({"segment_start": str(start), "segment_end": str(end), "n_valid_points": int(count)})\n                in_seg = False\n    if in_seg:\n        segments.append({"segment_start": str(start), "segment_end": str(end), "n_valid_points": int(count)})\n    return segments\n\n\ndef _write_effective_range_report_for_prediction_csv_profile(pred_csv: Path, case_dir: Path, case_name: str) -> pd.DataFrame:\n    dfp = pd.read_csv(pred_csv)\n    if dfp.empty or TIME_COL not in dfp.columns or "split" not in dfp.columns:\n        return pd.DataFrame()\n    dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n    rows = []\n    pairs = _prediction_obs_wrf_pairs_profile(dfp)\n    for split in ["train", "val", "test"]:\n        d = dfp[dfp["split"].astype(str).str.lower().eq(split)].copy()\n        if d.empty:\n            continue\n        split_start = d[TIME_COL].min()\n        split_end = d[TIME_COL].max()\n        for label, obs_col, wrf_col in pairs:\n            valid = pd.to_numeric(d[obs_col], errors="coerce").notna() & pd.to_numeric(d[wrf_col], errors="coerce").notna()\n            segs = _target_valid_segments_for_split_profile(d, TIME_COL, obs_col, wrf_col)\n            base = {\n                "case": case_name,\n                "split": split,\n                "target": label,\n                "obs_col": obs_col,\n                "wrf_col": wrf_col,\n                "split_window_start": str(split_start),\n                "split_window_end": str(split_end),\n                "n_rows_in_split": int(len(d)),\n                "n_valid_target_rows_used": int(valid.sum()),\n                "n_masked_missing_or_qc_rows": int(len(d) - valid.sum()),\n                "valid_ratio_pct": float(valid.mean() * 100.0) if len(d) else np.nan,\n                "n_valid_segments": int(len(segs)),\n            }\n            if segs:\n                for iseg, seg in enumerate(segs, start=1):\n                    row = dict(base)\n                    row.update({"segment_id": iseg, **seg})\n                    rows.append(row)\n            else:\n                row = dict(base)\n                row.update({"segment_id": 0, "segment_start": None, "segment_end": None, "n_valid_points": 0})\n                rows.append(row)\n    out_df = pd.DataFrame(rows)\n    if out_df.empty:\n        return out_df\n    out_df.to_csv(case_dir / "effective_train_val_test_time_ranges.csv", index=False, encoding="utf-8-sig")\n    txt = []\n    txt.append(f"Effective train/val/test target-valid time ranges for case: {case_name}")\n    txt.append(f"Prediction CSV: {pred_csv.name}")\n    txt.append("Definition: target-valid = finite OBS after QC + finite WRF. Missing/QC-rejected OBS rows are not used for this target\'s loss/metrics.")\n    txt.append("Note: split_window_start/end is the chronological split window; segment_start/end below excludes missing/QC-rejected target rows.")\n    txt.append("")\n    summary_cols = ["split", "target", "n_rows_in_split", "n_valid_target_rows_used", "n_masked_missing_or_qc_rows", "valid_ratio_pct", "n_valid_segments"]\n    summary = out_df.drop_duplicates(["split", "target"])[summary_cols]\n    txt.append(summary.to_string(index=False))\n    txt.append("\\nContiguous valid segments (first 100 rows; full list in CSV):")\n    seg_cols = ["split", "target", "segment_id", "segment_start", "segment_end", "n_valid_points"]\n    txt.append(out_df[seg_cols].head(100).to_string(index=False))\n    if len(out_df) > 100:\n        txt.append(f"... {len(out_df) - 100} more segment rows in effective_train_val_test_time_ranges.csv")\n    (case_dir / "effective_train_val_test_time_ranges.txt").write_text("\\n".join(txt), encoding="utf-8")\n    return out_df\n\n\ndef export_effective_train_val_test_ranges_code2(base_out: Path) -> None:\n    base_out = Path(base_out)\n    all_rows = []\n    for cases_root in base_out.rglob("cases"):\n        comp_dir = ensure_dir(cases_root.parent / "02_cmp")\n        for case_dir in sorted([p for p in cases_root.iterdir() if p.is_dir()]):\n            pred_files = sorted(case_dir.glob("predictions*train_val_test.csv"))\n            if not pred_files:\n                continue\n            pred_csv = pred_files[0]\n            try:\n                df_case = _write_effective_range_report_for_prediction_csv_profile(pred_csv, case_dir, case_dir.name)\n                if not df_case.empty:\n                    all_rows.append(df_case)\n            except Exception as e:\n                (case_dir / "effective_train_val_test_time_ranges_ERROR.txt").write_text(repr(e), encoding="utf-8")\n        if all_rows:\n            agg = pd.concat(all_rows, ignore_index=True)\n            agg.to_csv(comp_dir / "ALL_cases_effective_train_val_test_time_ranges.csv", index=False, encoding="utf-8-sig")\n            (comp_dir / "ALL_cases_effective_train_val_test_time_ranges.txt").write_text(\n                "Full per-case target-valid train/val/test time ranges are saved in ALL_cases_effective_train_val_test_time_ranges.csv.\\n"\n                "Each case folder also has effective_train_val_test_time_ranges.txt.\\n"\n                "Target-valid means finite OBS after QC + finite WRF; missing/QC-rejected OBS is excluded for that target.\\n",\n                encoding="utf-8"\n            )\n\n_train_for_csv_code2_final_base = train_for_csv\n\ndef train_for_csv(train_csv: Path, output_root: Path, network: str = NETWORK, feature_modes: Sequence[str] = tuple(CODE_CASES), heights_m: Optional[Sequence[int]] = None, target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS, date_start: Optional[str] = None, date_end: Optional[str] = None) -> pd.DataFrame:\n    result=_train_for_csv_code2_final_base(train_csv, output_root, network=network, feature_modes=feature_modes, heights_m=heights_m, target_groups=target_groups, date_start=date_start, date_end=date_end)\n    try:\n        tower_tag=safe_name(Path(train_csv).parent.name); htag=height_tag_from_list(heights_m); root=Path(output_root)/safe_name(f"{tower_tag}_{htag}")\n        plot_corrfdr_feature_screening_outputs(root)\n        plot_code2_case_timeseries_comparison(root)\n        export_effective_train_val_test_ranges_code2(root)\n        export_case_metrics_and_feature_audit_code2(root)\n        write_case_metrics_output_check_code2(root)\n    except Exception as e:\n        print(f"[postplot] Code2 final comparison plots skipped: {e}")\n    return result\n\n\n\n# =============================================================================\n# FINAL USER FIX: robust/simple precheck timeseries plots for Code2\n# - no special missing-marker plotting; invalid/missing OBS remains masked in loss\n# - uses short PNG names and writes a plot report\n# =============================================================================\n\ndef plot_pretraining_timeseries_code2(\n    df: pd.DataFrame,\n    records: Sequence[TargetRecord],\n    feature_cols: List[str],\n    out_dir: Path,\n    site_name: str,\n) -> None:\n    """Robust pretraining plots for Code2.\n\n    Missing/QC-rejected OBS is not plotted as a special marker because it is already\n    excluded from target loss through NaN target + mask=0. The plot only shows:\n      - WRF full context as a faint reference line;\n      - WRF values only where this target OBS is valid;\n      - valid OBS points.\n    """\n    out_dir = Path(out_dir)\n    target_dir = ensure_dir(out_dir / "timeseries_targets_with_split")\n    feature_dir = ensure_dir(out_dir / "timeseries_features_with_split")\n    report_rows = []\n\n    split_ranges = pd.DataFrame()\n    try:\n        target_cols = [r.target_col for r in records]\n        extra_cols = []\n        for r in records:\n            extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n        dfp = prepare_features(df, feature_cols, target_cols, extra_cols)\n        X, y, mask, idx = make_windows_masked(dfp, feature_cols, target_cols, require_any_target=True)\n        if len(X) >= 1:\n            tr, va, te = split_chronological(len(X))\n            time_win = pd.to_datetime(dfp.loc[idx, TIME_COL], errors="coerce").reset_index(drop=True)\n            split_ranges = _split_ranges_from_window_indices_profile(time_win, tr, va, te)\n            split_ranges.to_csv(out_dir / "pretraining_split_time_ranges_from_windows.csv", index=False, encoding="utf-8-sig")\n        else:\n            report_rows.append({"type": "split", "name": "all", "status": "warning", "message": "no supervised windows available for split shading"})\n    except Exception as e:\n        report_rows.append({"type": "split", "name": "all", "status": "failed", "message": repr(e)})\n\n    t = pd.to_datetime(df[TIME_COL], errors="coerce") if TIME_COL in df.columns else pd.Series(np.arange(len(df)), index=df.index)\n\n    for k, r in enumerate(records, start=1):\n        try:\n            obs_col, wrf_col = r.obs_col, r.wrf_col\n            label = f"{r.var}_h{int(r.height)}"\n            if obs_col not in df.columns and wrf_col not in df.columns:\n                report_rows.append({"type": "target", "name": label, "status": "skipped", "message": "obs/wrf columns absent"})\n                continue\n            obs_vals = pd.to_numeric(df[obs_col], errors="coerce") if obs_col in df.columns else pd.Series(np.nan, index=df.index)\n            wrf_vals = pd.to_numeric(df[wrf_col], errors="coerce") if wrf_col in df.columns else pd.Series(np.nan, index=df.index)\n            valid_target = obs_vals.notna() & wrf_vals.notna()\n            fig, ax = plt.subplots(figsize=(13.5, 4.8))\n            if not split_ranges.empty:\n                _shade_split_ranges_profile(ax, split_ranges)\n            if wrf_col in df.columns:\n                ax.plot(t, wrf_vals, label=f"WRF full context: {wrf_col}", linewidth=0.7, alpha=0.20, color="0.45")\n                ax.plot(t, wrf_vals.where(valid_target), label="WRF with valid OBS target", linewidth=1.0, alpha=0.9)\n            if obs_col in df.columns:\n                ax.scatter(t[valid_target], obs_vals[valid_target], label=f"OBS valid after QC: {obs_col}", s=6, alpha=0.65)\n            ax.set_xlabel("Time")\n            ax.set_ylabel(label)\n            ax.set_title(f"Precheck target time series: {site_name}, {label} | valid target N={int(valid_target.sum())}")\n            ax.grid(True, alpha=0.3)\n            _dedup_legend_profile(ax)\n            fig.tight_layout()\n            out_png = target_dir / f"target_{k:02d}_{safe_name(label)[:35]}.png"\n            fig.savefig(out_png, dpi=300)\n            plt.close(fig)\n            report_rows.append({"type": "target", "name": label, "status": "written", "file": out_png.name, "valid_n": int(valid_target.sum()), "note": "Only finite/QC-valid OBS+WRF target points are used in loss"})\n        except Exception as e:\n            report_rows.append({"type": "target", "name": getattr(r, "var", "unknown"), "status": "failed", "message": repr(e)})\n\n    for k, col in enumerate(list(dict.fromkeys(feature_cols)), start=1):\n        try:\n            if col not in df.columns:\n                report_rows.append({"type": "feature", "name": col, "status": "skipped", "message": "column absent"})\n                continue\n            vals = pd.to_numeric(df[col], errors="coerce")\n            if vals.notna().sum() < 1:\n                report_rows.append({"type": "feature", "name": col, "status": "skipped", "message": "all NaN"})\n                continue\n            fig, ax = plt.subplots(figsize=(13.5, 4.2))\n            if not split_ranges.empty:\n                _shade_split_ranges_profile(ax, split_ranges)\n            ax.plot(t, vals, label=col, linewidth=0.9)\n            ax.set_xlabel("Time")\n            ax.set_ylabel(col)\n            ax.set_title(f"Precheck input feature with train/val/test: {site_name}, {col}")\n            ax.grid(True, alpha=0.3)\n            _dedup_legend_profile(ax)\n            fig.tight_layout()\n            out_png = feature_dir / f"feature_{k:02d}_{safe_name(col)[:45]}.png"\n            fig.savefig(out_png, dpi=300)\n            plt.close(fig)\n            report_rows.append({"type": "feature", "name": col, "status": "written", "file": out_png.name, "valid_n": int(vals.notna().sum())})\n        except Exception as e:\n            report_rows.append({"type": "feature", "name": col, "status": "failed", "message": repr(e)})\n\n    pd.DataFrame(report_rows).to_csv(out_dir / "pretraining_timeseries_plot_report.csv", index=False, encoding="utf-8-sig")\n\n\n\n# =============================================================================\n# FINAL PATH-LENGTH FIX FOR CODE2\n# Use short case names and short training-history filenames to avoid Windows MAX_PATH.\n# =============================================================================\n\ndef parse_case_mode(case: str):\n    """Return selection_mode, short feature_mode_name, use_pinn, use_most_input, is_raw."""\n    c = case.strip().lower()\n    if c in {"raw", "raw_wrf", "wrf"}:\n        return "all", "raw_WRF", False, False, True\n\n    use_pinn = "pinn" in c or "mostmag" in c\n    use_most_input = "mostinput" in c or "most_input" in c\n    if "corrfdr" in c or "corr" in c:\n        selection = "corrFDR"\n    elif "all" in c or c in {"nomost", "mostinput", "pinn_mostmag"}:\n        selection = "all"\n    else:\n        raise ValueError(f"Unknown case: {case}")\n\n    if use_most_input and use_pinn:\n        feature_name = "MOSTinput_PINN_corrFDR" if selection == "corrFDR" else "MOSTinput_PINN_all"\n    elif use_most_input:\n        feature_name = "MOSTinput_corrFDR" if selection == "corrFDR" else "MOSTinput_all"\n    elif use_pinn:\n        feature_name = "PINN_corrFDR" if selection == "corrFDR" else "PINN_all"\n    else:\n        feature_name = "noMOST_corrFDR" if selection == "corrFDR" else "noMOST_all"\n\n    return selection, feature_name, use_pinn, use_most_input, False\n\n\ndef plot_loss(history, out_png: Path, title: str) -> None:\n    """Save training history and loss curves with short filenames."""\n    out_dir = ensure_dir(Path(out_png).parent)\n    hist = history.history if hasattr(history, "history") else dict(history)\n    dfh = pd.DataFrame(hist)\n    if not dfh.empty:\n        dfh.insert(0, "epoch", np.arange(1, len(dfh) + 1))\n        dfh.to_csv(out_dir / "training_history.csv", index=False, encoding="utf-8-sig")\n\n    fig, ax = plt.subplots(figsize=(8.5, 4.8))\n    if "loss" in hist:\n        ax.plot(hist["loss"], label="train loss")\n    if "val_loss" in hist:\n        ax.plot(hist["val_loss"], label="val loss")\n    ax.set_xlabel("Epoch")\n    ax.set_ylabel("Loss")\n    ax.set_title(str(title))\n    ax.grid(True, alpha=0.3)\n    ax.legend()\n    fig.tight_layout()\n    fig.savefig(out_dir / "loss.png", dpi=300)\n    plt.close(fig)\n\n    if not dfh.empty:\n        fig, ax1 = plt.subplots(figsize=(9.2, 5.2))\n        x = dfh["epoch"].values\n        if "loss" in dfh:\n            ax1.plot(x, dfh["loss"], label="train loss")\n        if "val_loss" in dfh:\n            ax1.plot(x, dfh["val_loss"], label="val loss")\n        ax1.set_xlabel("Epoch")\n        ax1.set_ylabel("Loss")\n        ax1.grid(True, alpha=0.3)\n        lines, labels = ax1.get_legend_handles_labels()\n        if "lr" in dfh:\n            ax2 = ax1.twinx()\n            ax2.plot(x, dfh["lr"], linestyle="--", label="learning rate")\n            ax2.set_ylabel("Learning rate")\n            l2, lab2 = ax2.get_legend_handles_labels()\n            lines += l2\n            labels += lab2\n        ax1.legend(lines, labels, loc="best")\n        ax1.set_title(f"Training curve: {title}")\n        fig.tight_layout()\n        fig.savefig(out_dir / "training_loss_lr.png", dpi=300)\n        plt.close(fig)\n\n        value_cols = [c for c in dfh.columns if c != "epoch" and pd.api.types.is_numeric_dtype(dfh[c])]\n        if value_cols:\n            fig, ax = plt.subplots(figsize=(9.5, 5.4))\n            for c in value_cols:\n                ax.plot(dfh["epoch"], dfh[c], label=c)\n            ax.set_xlabel("Epoch")\n            ax.set_ylabel("Value")\n            ax.set_title(f"Full training history: {title}")\n            ax.grid(True, alpha=0.3)\n            ax.legend(fontsize=8)\n            fig.tight_layout()\n            fig.savefig(out_dir / "training_history_all.png", dpi=300)\n            plt.close(fig)\n\n\n\n# =============================================================================\n# PER-CASE METRICS + FEATURE-SELECTION AUDIT OUTPUTS FOR CODE2\n# =============================================================================\n\ndef _code2_primary_metric_for_variable(var: str) -> str:\n    v = str(var).upper()\n    return "MAE" if "WD" in v else "RMSE"\n\n\ndef _code2_case_short_name(case_dir_name: str) -> str:\n    s = str(case_dir_name)\n    for prefix in ["CNN_LSTM_", "TCN_"]:\n        if s.startswith(prefix):\n            return s[len(prefix):]\n    return s\n\n\ndef _code2_case_feature_standard_text(case_name: str, case_dir: Path, site_root: Path) -> str:\n    short = _code2_case_short_name(case_name)\n    lines = []\n    lines.append(f"Case folder: {case_name}")\n    lines.append(f"Case short name: {short}")\n    lines.append(f"Network: {network_label()}")\n    lines.append("Time features: hour_sin/hour_cos only; month_sin/month_cos are excluded from the main experiment.")\n    lines.append("")\n    if short == "raw_WRF":\n        lines.append("Input-feature standard: raw WRF baseline; no ML input features and no trained correction model.")\n    elif "corrFDR" in short:\n        lines.append("Input-feature standard: train-only Pearson correlation screening with BH-FDR control.")\n        lines.append(f"Criterion: |Pearson r| >= {CORR_ABS_R_MIN}, BH-FDR q <= {FDR_Q_MAX}; pair minimum N >= {MIN_PAIR_N}.")\n        lines.append("FORCE_KEEP_TIME_FEATURES keeps hour_sin/hour_cos if available.")\n        lines.append("FORCE_KEEP_WIND_BASE_FEATURES keeps physically important WRF WS/U/V base features if available.")\n    else:\n        lines.append("Input-feature standard: all available candidate features for this case after availability check.")\n    if "MOSTinput" in short:\n        lines.append("MOSTinput: MOST-related features are included as ordinary input features.")\n    if "PINN" in short:\n        lines.append("PINN/MOSTmag: MOST wind-speed magnitude is used in the gated physics loss; lambda is selected by validation composite score.")\n    if short.startswith("noMOST"):\n        lines.append("noMOST: MOST input features are not included as ordinary input predictors.")\n    lines.append("")\n    precheck = site_root / "00_pre"\n    candidate_files = []\n    if "MOSTinput" in short:\n        candidate_files.append(precheck / "MOSTinput_candidate_features.csv")\n        if "corrFDR" in short:\n            candidate_files.insert(0, precheck / "corrFDR_selected_features_MOSTinput.csv")\n    else:\n        candidate_files.append(precheck / "noMOST_candidate_features.csv")\n        if "corrFDR" in short:\n            candidate_files.insert(0, precheck / "corrFDR_selected_features_noMOST.csv")\n    for ff in candidate_files:\n        if ff.exists():\n            try:\n                fdf = pd.read_csv(ff)\n                vals = fdf.iloc[:, 0].dropna().astype(str).tolist() if not fdf.empty else []\n                lines.append(f"Feature file: {ff.name}")\n                lines.append(f"Number of features listed: {len(vals)}")\n                for x in vals:\n                    lines.append(f"  - {x}")\n                break\n            except Exception as e:\n                lines.append(f"Could not read feature file {ff.name}: {e}")\n    return "\\n".join(lines)\n\n\ndef _code2_plot_case_metrics(case_metrics: pd.DataFrame, case_dir: Path, case_name: str) -> None:\n    if case_metrics.empty or "split" not in case_metrics.columns or "variable" not in case_metrics.columns:\n        return\n    df = case_metrics.copy()\n    df["primary_metric"] = df["variable"].astype(str).apply(_code2_primary_metric_for_variable)\n    df["primary_error"] = np.where(df["primary_metric"].eq("MAE"), pd.to_numeric(df.get("MAE"), errors="coerce"), pd.to_numeric(df.get("RMSE"), errors="coerce"))\n    for split in ["train", "val", "test"]:\n        sub = df[df["split"].astype(str).str.lower().eq(split)].copy()\n        if sub.empty:\n            continue\n        allprof = sub[sub["height_m"].astype(str).eq("ALL_PROFILE")].copy() if "height_m" in sub.columns else sub\n        plot_df = allprof if not allprof.empty else sub\n        plot_df = plot_df.dropna(subset=["primary_error"]).sort_values(["variable", "height_m"] if "height_m" in plot_df.columns else ["variable"])\n        if plot_df.empty:\n            continue\n        labels = (plot_df["variable"].astype(str) + ("_h" + plot_df["height_m"].astype(str) if "height_m" in plot_df.columns else "")).values\n        fig, ax = plt.subplots(figsize=(max(8.5, 0.42 * len(plot_df)), 4.8))\n        x = np.arange(len(plot_df))\n        ax.bar(x, plot_df["primary_error"].values)\n        ax.set_xticks(x)\n        ax.set_xticklabels(labels, rotation=40, ha="right", fontsize=7)\n        ax.set_ylabel("Primary error (RMSE except WD uses MAE)")\n        ax.set_title(f"{case_name}: {split} metrics by variable")\n        ax.grid(True, axis="y", alpha=0.3)\n        fig.tight_layout()\n        fig.savefig(case_dir / f"plot_metrics_{split}_by_variable.png", dpi=300)\n        plt.close(fig)\n\n\ndef export_case_metrics_and_feature_audit_code2(base_out: Path) -> None:\n    base_out = Path(base_out)\n    for cases_root in base_out.rglob("cases"):\n        site_root = cases_root.parent\n        for case_dir in sorted([p for p in cases_root.iterdir() if p.is_dir()]):\n            metric_files = sorted(case_dir.glob("metrics*train_val_test.csv"))\n            if metric_files:\n                try:\n                    metrics = pd.read_csv(metric_files[0])\n                except Exception:\n                    metrics = pd.DataFrame()\n                if not metrics.empty:\n                    metrics.to_csv(case_dir / "metrics_by_variable_train_val_test.csv", index=False, encoding="utf-8-sig")\n                    cols = [c for c in ["model", "feature_mode", "split", "variable", "height_m", "N", "RMSE", "MAE", "MBE", "Pearson_r", "Skill_RMSE_pct"] if c in metrics.columns]\n                    (case_dir / "metrics_by_variable_train_val_test.txt").write_text(metrics[cols].to_string(index=False), encoding="utf-8")\n                    _code2_plot_case_metrics(metrics, case_dir, case_dir.name)\n            (case_dir / "feature_input_selection_standard.txt").write_text(_code2_case_feature_standard_text(case_dir.name, case_dir, site_root), encoding="utf-8")\n\n\n\n# =============================================================================\n# WIND-DIRECTION PROFILE PLOT FIX FOR CODE2\n# Add vertical wind-direction profiles using circular means, not arithmetic means.\n# =============================================================================\n\ndef _circular_mean_deg_profile(values) -> float:\n    arr = pd.to_numeric(pd.Series(values), errors="coerce").astype(float).values\n    arr = arr[np.isfinite(arr)]\n    if arr.size < 1:\n        return np.nan\n    rad = np.deg2rad(arr % 360.0)\n    s = np.nanmean(np.sin(rad))\n    c = np.nanmean(np.cos(rad))\n    if not np.isfinite(s) or not np.isfinite(c) or (abs(s) < 1e-12 and abs(c) < 1e-12):\n        return np.nan\n    return float((np.rad2deg(np.arctan2(s, c)) + 360.0) % 360.0)\n\n\ndef plot_profile_prediction_diagnostics(pred_csv: Path, out_dir: Path, feature_mode: str) -> None:\n    try:\n        pred_csv = Path(pred_csv)\n        if not pred_csv.exists():\n            return\n        dfp = pd.read_csv(pred_csv)\n        if dfp.empty:\n            return\n        if "split" not in dfp.columns:\n            dfp["split"] = "all"\n        if TIME_COL in dfp.columns:\n            dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n        _code2_plot_split_timeline(pred_csv, out_dir, feature_mode)\n\n        is_raw = str(feature_mode).lower().startswith("raw_wrf")\n        heights = _code2_heights_from_cols(dfp)\n        specs = [\n            ("WS_from_uv", "OBS_WS{h}_from_uv (m/s)", "WRF_WS{h}_from_uv (m/s)", "WS{h}_corr_pred_from_uv (m/s)", "m/s", False),\n            ("WD_from_uv", "OBS_WD{h}_from_uv (deg)", "WRF_WD{h}_from_uv (deg)", "WD{h}_corr_pred_from_uv (deg)", "deg", True),\n            ("WS_direct", "OBS_WS_direct{h}", "WRF_WS_direct{h}", "WS_direct{h}_corr_pred", "m/s", False),\n            ("WD_direct", "OBS_WD_direct{h}", "WRF_WD_direct{h}", "WD_direct{h}_corr_pred", "deg", True),\n            ("TKE", "OBS_TKE{h}", "WRF_TKE{h}", "TKE{h}_corr_pred", "m2/s2", False),\n            ("T", "OBS_T{h}", "WRF_T{h}", "T{h}_corr_pred", "K", False),\n        ]\n        for split in ["train", "val", "test"]:\n            dft = dfp[dfp["split"].astype(str).str.lower().eq(split)].copy()\n            if dft.empty:\n                continue\n            x = dft[TIME_COL] if TIME_COL in dft.columns else np.arange(len(dft))\n            for label, ot, wt, pt, unit, is_wd in specs:\n                rows = []\n                for h in heights:\n                    oc, wc, pc = ot.format(h=h), wt.format(h=h), pt.format(h=h)\n                    need_cols = [oc, wc] if is_raw else [oc, wc, pc]\n                    if not all(c in dft.columns for c in need_cols):\n                        continue\n                    if is_wd:\n                        obs_mean = _circular_mean_deg_profile(dft[oc])\n                        wrf_mean = _circular_mean_deg_profile(dft[wc])\n                        if is_raw:\n                            rows.append((h, obs_mean, wrf_mean))\n                        else:\n                            corr_mean = _circular_mean_deg_profile(dft[pc])\n                            rows.append((h, obs_mean, wrf_mean, corr_mean))\n                    else:\n                        obs_mean = pd.to_numeric(dft[oc], errors="coerce").mean()\n                        wrf_mean = pd.to_numeric(dft[wc], errors="coerce").mean()\n                        if is_raw:\n                            rows.append((h, obs_mean, wrf_mean))\n                        else:\n                            rows.append((h, obs_mean, wrf_mean, pd.to_numeric(dft[pc], errors="coerce").mean()))\n\n                # Mean vertical profile for all variables, including WD.\n                if rows:\n                    arr = np.asarray(rows, float)\n                    fig, ax = plt.subplots(figsize=(5.8, 6.2))\n                    ax.plot(arr[:, 1], arr[:, 0], marker="o", label="OBS")\n                    ax.plot(arr[:, 2], arr[:, 0], marker="o", label="WRF")\n                    if not is_raw and arr.shape[1] >= 4:\n                        ax.plot(arr[:, 3], arr[:, 0], marker="o", label="Corrected")\n                    ax.set_xlabel(f"{label} ({unit})")\n                    ax.set_ylabel("Height (m)")\n                    if is_wd:\n                        ax.set_xlim(0, 360)\n                        ax.set_xticks(np.arange(0, 361, 60))\n                        ax.set_xlabel(f"{label} circular mean ({unit})")\n                    title_prefix = "raw_WRF baseline" if is_raw else str(feature_mode)\n                    ax.set_title(f"Mean {split} profile: {title_prefix}, {label}")\n                    ax.grid(True, alpha=0.3)\n                    ax.legend()\n                    fig.tight_layout()\n                    fig.savefig(Path(out_dir) / f"plot_mean_{split}_profile_{safe_name(label)}.png", dpi=300)\n                    plt.close(fig)\n\n                # Time series for every available height.\n                for h in heights:\n                    oc, wc, pc = ot.format(h=h), wt.format(h=h), pt.format(h=h)\n                    need_cols = [oc, wc] if is_raw else [oc, wc, pc]\n                    if not all(c in dft.columns for c in need_cols):\n                        continue\n                    fig, ax = plt.subplots(figsize=(12, 4.4))\n                    ax.plot(x, pd.to_numeric(dft[oc], errors="coerce"), label="OBS", linewidth=1.2)\n                    ax.plot(x, pd.to_numeric(dft[wc], errors="coerce"), label="WRF", linewidth=1.0, alpha=0.85)\n                    if not is_raw and pc in dft.columns:\n                        ax.plot(x, pd.to_numeric(dft[pc], errors="coerce"), label="Corrected", linewidth=1.0, alpha=0.9)\n                    ax.set_xlabel("Time")\n                    ax.set_ylabel(f"{label} at {h} m ({unit})")\n                    if is_wd:\n                        ax.set_ylim(0, 360)\n                    title_prefix = "raw_WRF baseline" if is_raw else str(feature_mode)\n                    ax.set_title(f"{title_prefix} {split}: {label}, {h} m")\n                    ax.grid(True, alpha=0.3)\n                    ax.legend()\n                    fig.tight_layout()\n                    fig.savefig(Path(out_dir) / f"plot_{split}_timeseries_{safe_name(label)}_h{h}.png", dpi=300)\n                    plt.close(fig)\n    except Exception as e:\n        print(f"[plot] profile diagnostics failed for {feature_mode}: {e}")\n\n\n\n# =============================================================================\n# FINAL CHECK: ensure every case, including raw_WRF, has metrics for train/val/test.\n# =============================================================================\n\ndef write_case_metrics_output_check_code2(base_out: Path) -> None:\n    base_out = Path(base_out)\n    for cases_root in base_out.rglob("cases"):\n        comp_dir = ensure_dir(cases_root.parent / "02_cmp")\n        rows = []\n        for case_dir in sorted([p for p in cases_root.iterdir() if p.is_dir()]):\n            metrics_csv = case_dir / "metrics_by_variable_train_val_test.csv"\n            eff_txt = case_dir / "effective_train_val_test_time_ranges.txt"\n            feature_txt = case_dir / "feature_input_selection_standard.txt"\n            row = {\n                "case": case_dir.name,\n                "metrics_csv": metrics_csv.exists(),\n                "effective_ranges_txt": eff_txt.exists(),\n                "feature_standard_txt": feature_txt.exists(),\n                "plot_train": (case_dir / "plot_metrics_train_by_variable.png").exists(),\n                "plot_val": (case_dir / "plot_metrics_val_by_variable.png").exists(),\n                "plot_test": (case_dir / "plot_metrics_test_by_variable.png").exists(),\n                "note": "Metrics use finite OBS after QC + finite WRF/prediction only; missing/QC-invalid OBS is excluded target-by-target.",\n            }\n            if metrics_csv.exists():\n                try:\n                    m = pd.read_csv(metrics_csv)\n                    row["has_train"] = bool((m["split"].astype(str).str.lower() == "train").any()) if "split" in m.columns else False\n                    row["has_val"] = bool((m["split"].astype(str).str.lower() == "val").any()) if "split" in m.columns else False\n                    row["has_test"] = bool((m["split"].astype(str).str.lower() == "test").any()) if "split" in m.columns else False\n                    row["n_metric_rows"] = int(len(m))\n                except Exception as e:\n                    row["read_error"] = repr(e)\n            rows.append(row)\n        if rows:\n            df = pd.DataFrame(rows)\n            df.to_csv(comp_dir / "case_metrics_output_check.csv", index=False, encoding="utf-8-sig")\n            (comp_dir / "case_metrics_output_check.txt").write_text(df.to_string(index=False), encoding="utf-8")\n\n_code2_original_main_user_select = main\n\ndef main():\n    if USE_CODE_CONFIG:\n        train_csv = resolve_code2_train_csv()\n        if not train_csv.exists():\n            raise FileNotFoundError(f"CODE_TRAIN_CSV does not exist: {train_csv}")\n        train_for_csv(\n            train_csv=train_csv,\n            output_root=Path(CODE_OUTPUT_ROOT),\n            network=CODE_NETWORK,\n            feature_modes=CODE_CASES,\n            heights_m=CODE_HEIGHTS_M,\n            target_groups=CODE_TARGET_GROUPS,\n            date_start=CODE_DATE_START,\n            date_end=CODE_DATE_END,\n        )\n        return\n    _code2_original_main_user_select()\n\n\n\n\n# =============================================================================\n# FINAL PATCH V19: PER-CASE FEATURE-SELECTION STATISTICS AND PLOTS\n# =============================================================================\n\ndef _read_single_col_list(path: Path) -> list:\n    path = Path(path)\n    if not path.exists():\n        return []\n    try:\n        df = pd.read_csv(path)\n        if df.empty:\n            return []\n        col = \'feature\' if \'feature\' in df.columns else (\'selected_feature\' if \'selected_feature\' in df.columns else df.columns[0])\n        return [str(x) for x in df[col].dropna().astype(str).tolist()]\n    except Exception:\n        return []\n\n\ndef _code2_plot_feature_selection_counts(out_path: Path, n_candidate: int, n_used: int, n_selected: int, title: str):\n    fig, ax = plt.subplots(figsize=(5.4, 4.2))\n    labels = [\'Candidates\', \'Used\', \'Selected\']\n    vals = [n_candidate, n_used, n_selected]\n    x = np.arange(len(labels))\n    ax.bar(x, vals)\n    ax.set_xticks(x)\n    ax.set_xticklabels(labels)\n    ax.set_ylabel(\'Count\')\n    ax.set_title(title)\n    ax.grid(True, axis=\'y\', alpha=0.3)\n    for i, v in enumerate(vals):\n        ax.text(i, float(v) + max(0.5, 0.01 * max(vals + [1])), str(int(v)), ha=\'center\', va=\'bottom\', fontsize=8)\n    fig.tight_layout()\n    fig.savefig(out_path, dpi=300)\n    plt.close(fig)\n\n\ndef _code2_plot_feature_selection_status(df_status: pd.DataFrame, out_path: Path, title: str):\n    if df_status.empty:\n        return\n    dfp = df_status.copy()\n    score_cols = [c for c in [\'score\', \'max_abs_r\'] if c in dfp.columns]\n    if score_cols:\n        dfp = dfp.sort_values(score_cols[0], ascending=False)\n    else:\n        dfp = dfp.sort_values([\'selected\', \'used\', \'feature\'], ascending=[False, False, True])\n    max_show = 45\n    if len(dfp) > max_show:\n        selected = dfp[dfp[\'selected\']].copy()\n        others = dfp[~dfp[\'selected\']].copy().head(max(0, max_show - len(selected)))\n        dfp = pd.concat([selected, others], ignore_index=True).head(max_show)\n    dfp[\'status_value\'] = np.where(dfp[\'selected\'], 2, np.where(dfp[\'used\'], 1, 0))\n    fig, ax = plt.subplots(figsize=(10.8, max(5.2, 0.28 * len(dfp))))\n    y = np.arange(len(dfp))\n    ax.barh(y, dfp[\'status_value\'].values)\n    ax.set_yticks(y)\n    ax.set_yticklabels([_pretty_case_label_profile(v, 30) for v in dfp[\'feature\'].astype(str)], fontsize=8)\n    ax.invert_yaxis()\n    ax.set_xlabel(\'0=not used, 1=used, 2=selected\')\n    ax.set_xlim(-0.1, 2.4)\n    ax.set_title(title)\n    ax.grid(True, axis=\'x\', alpha=0.3)\n    for i, (_, row) in enumerate(dfp.iterrows()):\n        txt = \'selected\' if bool(row[\'selected\']) else (\'used\' if bool(row[\'used\']) else \'candidate only\')\n        ax.text(float(row[\'status_value\']) + 0.03, i, txt, va=\'center\', fontsize=7)\n    fig.subplots_adjust(left=0.40, right=0.98, top=0.92, bottom=0.08)\n    fig.savefig(out_path, dpi=300)\n    plt.close(fig)\n\n\ndef _code2_plot_feature_ranking(report_path: Path, selected_features: list, out_path: Path, title: str):\n    try:\n        rep = pd.read_csv(report_path)\n        if rep.empty:\n            return\n        feature_col = \'feature\' if \'feature\' in rep.columns else rep.columns[0]\n        score_col = None\n        for c in [\'max_abs_r\', \'abs_r\', \'abs_r_max\', \'score\', \'max_abs_corr\']:\n            if c in rep.columns:\n                score_col = c\n                break\n        if score_col is None:\n            num_cols = [c for c in rep.columns if c != feature_col and pd.api.types.is_numeric_dtype(rep[c])]\n            score_col = num_cols[0] if num_cols else None\n        if score_col is None:\n            return\n        rank = rep[[feature_col, score_col]].copy().dropna().groupby(feature_col)[score_col].max().sort_values(ascending=False).head(30).reset_index()\n        if rank.empty:\n            return\n        rank[\'selected\'] = rank[feature_col].astype(str).isin(selected_features)\n        fig, ax = plt.subplots(figsize=(10.8, max(5.4, 0.28 * len(rank))))\n        y = np.arange(len(rank))\n        ax.barh(y, rank[score_col].values)\n        ax.set_yticks(y)\n        ax.set_yticklabels([_pretty_case_label_profile(v, 30) for v in rank[feature_col].astype(str)], fontsize=8)\n        ax.invert_yaxis()\n        ax.set_xlabel(score_col)\n        ax.set_title(title)\n        ax.grid(True, axis=\'x\', alpha=0.3)\n        for i, (val, sel) in enumerate(zip(rank[score_col], rank[\'selected\'])):\n            ax.text(float(val) + 0.01, i, \'selected\' if sel else \'\', va=\'center\', fontsize=7)\n        fig.subplots_adjust(left=0.40, right=0.98, top=0.92, bottom=0.08)\n        fig.savefig(out_path, dpi=300)\n        plt.close(fig)\n    except Exception as e:\n        print(f\'[feature-audit] Failed ranking plot for {report_path}: {e}\')\n\n\ndef export_case_feature_selection_outputs_code2(base_out: Path) -> None:\n    base_out = Path(base_out)\n    for cases_root in base_out.rglob(\'cases\'):\n        site_root = cases_root.parent\n        precheck = site_root / \'00_pre\'\n        summary_rows = []\n        for case_dir in sorted([p for p in cases_root.iterdir() if p.is_dir()]):\n            short = _code2_case_short_name(case_dir.name)\n            if short == \'raw_WRF\':\n                candidate_features = []\n                used_features = []\n                selected_features = []\n                mode = \'raw\'\n                report_path = None\n            else:\n                mostinput = \'MOSTinput\' in short\n                corr = \'corrFDR\' in short\n                if mostinput:\n                    candidate_path = precheck / \'MOSTinput_candidate_features.csv\'\n                    selected_path = precheck / \'corrFDR_selected_features_MOSTinput.csv\'\n                    report_path = precheck / \'corrFDR_feature_screening_report_MOSTinput.csv\'\n                else:\n                    candidate_path = precheck / \'noMOST_candidate_features.csv\'\n                    selected_path = precheck / \'corrFDR_selected_features_noMOST.csv\'\n                    report_path = precheck / \'corrFDR_feature_screening_report_noMOST.csv\'\n                candidate_features = _read_single_col_list(candidate_path)\n                used_features = _read_single_col_list(case_dir / \'features_used.csv\')\n                if corr:\n                    selected_features = _read_single_col_list(selected_path)\n                    mode = \'corrFDR\'\n                else:\n                    selected_features = list(used_features)\n                    mode = \'all_features\'\n                if \'PINN\' in short:\n                    mode = \'PINN_\' + mode\n            all_feats = sorted(set(candidate_features) | set(used_features) | set(selected_features))\n            rows = []\n            for f in all_feats:\n                if mode == \'raw\':\n                    reason = \'raw_WRF baseline; no ML feature selection\'\n                elif \'corrFDR\' in mode:\n                    reason = \'Passed train-only corr/FDR screening or force-keep rule.\' if f in selected_features else (\'Candidate available but not selected by corr/FDR screening.\' if f in candidate_features else \'Not selected.\')\n                else:\n                    reason = \'Included because feature was available for this case.\' if f in used_features else (\'Available candidate but not used in this case.\' if f in candidate_features else \'Not used.\')\n                rows.append({\'feature\': f, \'candidate\': f in candidate_features, \'used\': f in used_features, \'selected\': f in selected_features, \'reason\': reason})\n            dfd = pd.DataFrame(rows)\n            if not dfd.empty:\n                if report_path is not None and report_path.exists():\n                    try:\n                        rep = pd.read_csv(report_path)\n                        feature_col = \'feature\' if \'feature\' in rep.columns else rep.columns[0]\n                        score_col = None\n                        for c in [\'max_abs_r\', \'score\', \'abs_r\', \'max_abs_corr\']:\n                            if c in rep.columns:\n                                score_col = c\n                                break\n                        if score_col is not None:\n                            score_map = rep.groupby(feature_col)[score_col].max().to_dict()\n                            dfd[\'score\'] = dfd[\'feature\'].map(score_map)\n                    except Exception:\n                        pass\n                dfd.to_csv(case_dir / \'feature_selection_decision_table.csv\', index=False, encoding=\'utf-8-sig\')\n                dfd[dfd[\'selected\']].to_csv(case_dir / \'feature_selected.csv\', index=False, encoding=\'utf-8-sig\')\n                dfd[dfd[\'candidate\']].to_csv(case_dir / \'feature_candidates.csv\', index=False, encoding=\'utf-8-sig\')\n                _code2_plot_feature_selection_counts(case_dir / \'plot_feature_selection_counts.png\', int(len(candidate_features)), int(len(used_features)), int(len(selected_features)), f\'{case_dir.name}: feature counts\')\n                _code2_plot_feature_selection_status(dfd, case_dir / \'plot_feature_selection_status.png\', f\'{case_dir.name}: selected vs candidate features\')\n                if report_path is not None and report_path.exists():\n                    _code2_plot_feature_ranking(report_path, selected_features, case_dir / \'plot_feature_selection_ranking_case.png\', f\'{case_dir.name}: train-only feature ranking\')\n            lines = []\n            lines.append(f\'Case: {case_dir.name}\')\n            lines.append(f\'Selection mode: {mode}\')\n            lines.append(f\'Candidate feature count: {len(candidate_features)}\')\n            lines.append(f\'Used feature count: {len(used_features)}\')\n            lines.append(f\'Selected feature count: {len(selected_features)}\')\n            lines.append(\'Why selected:\')\n            if mode == \'raw\':\n                lines.append(\'  raw_WRF is a baseline and has no ML input features.\')\n            elif \'corrFDR\' in mode:\n                lines.append(f\'  Features are screened on the train split only using |Pearson r| >= {CORR_ABS_R_MIN}, BH-FDR q <= {FDR_Q_MAX}, with minimum pair N >= {MIN_PAIR_N}.\')\n                lines.append(\'  hour_sin/hour_cos and core WRF wind features can be force-kept when the corresponding switches are enabled.\')\n            else:\n                lines.append(\'  All available candidate features are used after availability checking; no correlation screening is applied.\')\n            if \'PINN\' in mode:\n                lines.append(\'  MOST wind-speed magnitude is used in the physics loss; this is not an ordinary predictor unless the case name contains MOSTinput.\')\n            if \'MOSTinput\' in short:\n                lines.append(\'  MOST-related predictors are included as ordinary input features in this case.\')\n            lines.append(\'Selected features:\')\n            if selected_features:\n                for f in selected_features:\n                    lines.append(f\'  - {f}\')\n            else:\n                lines.append(\'  (none)\')\n            (case_dir / \'feature_selection_summary.txt\').write_text(\'\\n\'.join(lines), encoding=\'utf-8\')\n            summary_rows.append({\'case\': case_dir.name, \'selection_mode\': mode, \'candidate_count\': len(candidate_features), \'used_count\': len(used_features), \'selected_count\': len(selected_features), \'selected_features\': \'; \'.join(selected_features)})\n        if summary_rows:\n            comp_dir = ensure_dir(site_root / \'02_cmp\')\n            sdf = pd.DataFrame(summary_rows)\n            sdf.to_csv(comp_dir / \'feature_selection_case_summary.csv\', index=False, encoding=\'utf-8-sig\')\n            (comp_dir / \'feature_selection_case_summary.txt\').write_text(sdf.to_string(index=False), encoding=\'utf-8\')\n\n_code2_original_main_v19 = main\n\ndef main():\n    _code2_original_main_v19()\n    export_case_feature_selection_outputs_code2(Path(CODE_OUTPUT_ROOT))\n    print(f"[feature-audit] Code2 feature-selection outputs written under: {CODE_OUTPUT_ROOT}")\n\n\n# =============================================================================\n# V21 IMMEDIATE METRICS OUTPUT: write metrics and metric plots right after each case finishes\n# =============================================================================\n\ndef _write_case_metrics_outputs_now_code2(metrics_df: pd.DataFrame, out_dir: Path, case_name: str) -> None:\n    try:\n        out_dir = ensure_dir(Path(out_dir))\n        if metrics_df is None or metrics_df.empty:\n            return\n        metrics_df.to_csv(out_dir / "metrics_by_variable_train_val_test.csv", index=False, encoding="utf-8-sig")\n        cols = [c for c in ["model", "feature_mode", "split", "variable", "height_m", "N", "RMSE", "MAE", "MBE", "Pearson_r", "Skill_RMSE_pct"] if c in metrics_df.columns]\n        (out_dir / "metrics_by_variable_train_val_test.txt").write_text(metrics_df[cols].to_string(index=False), encoding="utf-8")\n        _code2_plot_case_metrics(metrics_df, out_dir, case_name)\n        (out_dir / "metrics_written_immediately.txt").write_text(\n            "Metrics and metric plots were written immediately after this case finished.\\n"\n            "Metric calculation uses only finite OBS after QC plus finite WRF/prediction.\\n"\n            "OBS missing/QC-invalid rows are excluded target-by-target from train/val/test metrics.\\n",\n            encoding="utf-8"\n        )\n    except Exception as e:\n        print(f"[metrics-now] Code2 failed to write case metrics for {case_name}: {e}")\n\n_train_one_feature_mode_v21_base = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    metrics_df = _train_one_feature_mode_v21_base(\n        df=df,\n        target_records_all=target_records_all,\n        feature_cols=feature_cols,\n        site_name=site_name,\n        model_name=model_name,\n        feature_mode=feature_mode,\n        out_dir=out_dir,\n        network=network,\n        use_pinn_mostmag=use_pinn_mostmag,\n    )\n    _write_case_metrics_outputs_now_code2(metrics_df, out_dir, f"{model_name}_{feature_mode}")\n    return metrics_df\n\n_run_raw_wrf_profile_case_v21_base = run_raw_wrf_profile_case\n\ndef run_raw_wrf_profile_case(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    out_dir: Path,\n) -> pd.DataFrame:\n    metrics_df = _run_raw_wrf_profile_case_v21_base(df, target_records_all, feature_cols, site_name, out_dir)\n    _write_case_metrics_outputs_now_code2(metrics_df, out_dir, "raw_WRF")\n    return metrics_df\n\n\n# =============================================================================\n# V22 METRIC BAR LABEL FIX: add numeric labels above metric bars\n# =============================================================================\n\ndef _metric_bar_value_text(v) -> str:\n    try:\n        v = float(v)\n    except Exception:\n        return ""\n    if not np.isfinite(v):\n        return ""\n    av = abs(v)\n    if av >= 100:\n        return f"{v:.0f}"\n    if av >= 10:\n        return f"{v:.1f}"\n    return f"{v:.2f}"\n\n\ndef _code2_plot_case_metrics(case_metrics: pd.DataFrame, case_dir: Path, case_name: str) -> None:\n    if case_metrics.empty or "split" not in case_metrics.columns or "variable" not in case_metrics.columns:\n        return\n    df = case_metrics.copy()\n    df["primary_metric"] = df["variable"].astype(str).apply(_code2_primary_metric_for_variable)\n    df["primary_error"] = np.where(\n        df["primary_metric"].eq("MAE"),\n        pd.to_numeric(df.get("MAE"), errors="coerce"),\n        pd.to_numeric(df.get("RMSE"), errors="coerce"),\n    )\n    for split in ["train", "val", "test"]:\n        sub = df[df["split"].astype(str).str.lower().eq(split)].copy()\n        if sub.empty:\n            continue\n        allprof = sub[sub["height_m"].astype(str).eq("ALL_PROFILE")].copy() if "height_m" in sub.columns else sub\n        plot_df = allprof if not allprof.empty else sub\n        sort_cols = ["variable", "height_m"] if "height_m" in plot_df.columns else ["variable"]\n        plot_df = plot_df.dropna(subset=["primary_error"]).sort_values(sort_cols)\n        if plot_df.empty:\n            continue\n        if "height_m" in plot_df.columns:\n            labels = (plot_df["variable"].astype(str) + "_h" + plot_df["height_m"].astype(str)).values\n        else:\n            labels = plot_df["variable"].astype(str).values\n        fig, ax = plt.subplots(figsize=(max(8.5, 0.50 * len(plot_df)), 5.0))\n        x = np.arange(len(plot_df))\n        vals = plot_df["primary_error"].astype(float).values\n        bars = ax.bar(x, vals)\n        ymax = float(np.nanmax(vals)) if len(vals) else 1.0\n        offset = max(0.03 * ymax, 0.02)\n        for b, v in zip(bars, vals):\n            txt = _metric_bar_value_text(v)\n            if txt:\n                ax.text(b.get_x() + b.get_width()/2.0, b.get_height() + offset, txt,\n                        ha="center", va="bottom", fontsize=7, rotation=0)\n        ax.set_ylim(0, ymax + offset * 5.0)\n        ax.set_xticks(x)\n        ax.set_xticklabels(labels, rotation=40, ha="right", fontsize=7)\n        ax.set_ylabel("Primary error (RMSE except WD uses MAE)")\n        ax.set_title(f"{case_name}: {split} metrics by variable")\n        ax.grid(True, axis="y", alpha=0.3)\n        fig.tight_layout()\n        fig.savefig(Path(case_dir) / f"plot_metrics_{split}_by_variable.png", dpi=300)\n        plt.close(fig)\n\n\n# =============================================================================\n# V22+ CODE2 METRIC PLOT PATCH\n# Add per-variable/per-height metric plots without changing any QC logic.\n# =============================================================================\n\ndef _plot_code2_metric_bar_with_labels(plot_df: pd.DataFrame, out_png: Path, title: str, x_col: Optional[str] = None) -> None:\n    plot_df = plot_df.dropna(subset=["primary_error"]).copy()\n    if plot_df.empty:\n        return\n    if x_col is None:\n        labels = plot_df["variable"].astype(str).values\n    else:\n        labels = (plot_df[x_col].astype(str) + " m").values\n    vals = plot_df["primary_error"].astype(float).values\n    fig, ax = plt.subplots(figsize=(max(8.5, 0.58 * len(plot_df)), 5.0))\n    x = np.arange(len(plot_df))\n    bars = ax.bar(x, vals)\n    ymax = float(np.nanmax(vals)) if len(vals) else 1.0\n    offset = max(0.03 * ymax, 0.02)\n    for b, v in zip(bars, vals):\n        txt = _metric_bar_value_text(v)\n        if txt:\n            ax.text(b.get_x() + b.get_width()/2.0, b.get_height() + offset, txt, ha="center", va="bottom", fontsize=8)\n    ax.set_ylim(0, ymax + offset * 5.0)\n    ax.set_xticks(x)\n    ax.set_xticklabels(labels, rotation=40 if len(labels) > 5 else 0, ha="right" if len(labels) > 5 else "center", fontsize=8)\n    ax.set_ylabel("Primary error (RMSE except WD uses MAE)")\n    ax.set_title(title)\n    ax.grid(True, axis="y", alpha=0.3)\n    fig.tight_layout()\n    fig.savefig(out_png, dpi=300)\n    plt.close(fig)\n\n\ndef _code2_plot_case_metrics(case_metrics: pd.DataFrame, case_dir: Path, case_name: str) -> None:\n    """Create ALL_PROFILE and per-height metric plots, with labels above bars."""\n    if case_metrics.empty or "split" not in case_metrics.columns or "variable" not in case_metrics.columns:\n        return\n    df = case_metrics.copy()\n    df["primary_metric"] = df["variable"].astype(str).apply(_code2_primary_metric_for_variable)\n    df["primary_error"] = np.where(\n        df["primary_metric"].eq("MAE"),\n        pd.to_numeric(df.get("MAE"), errors="coerce"),\n        pd.to_numeric(df.get("RMSE"), errors="coerce"),\n    )\n    for split in ["train", "val", "test"]:\n        sub = df[df["split"].astype(str).str.lower().eq(split)].copy()\n        if sub.empty:\n            continue\n        # 1) ALL_PROFILE summary plot, if present.\n        allprof = sub[sub["height_m"].astype(str).eq("ALL_PROFILE")].copy() if "height_m" in sub.columns else pd.DataFrame()\n        if not allprof.empty:\n            _plot_code2_metric_bar_with_labels(allprof, Path(case_dir) / f"plot_metrics_{split}_ALL_PROFILE_by_variable.png", f"{case_name}: {split} ALL_PROFILE metrics")\n            # Keep old file name too.\n            _plot_code2_metric_bar_with_labels(allprof, Path(case_dir) / f"plot_metrics_{split}_by_variable.png", f"{case_name}: {split} ALL_PROFILE metrics")\n        else:\n            # Fallback old behavior if no ALL_PROFILE rows exist.\n            fallback = sub.dropna(subset=["primary_error"]).copy()\n            if not fallback.empty:\n                _plot_code2_metric_bar_with_labels(fallback, Path(case_dir) / f"plot_metrics_{split}_by_variable.png", f"{case_name}: {split} metrics")\n        # 2) Per-height plot for each variable.\n        if "height_m" in sub.columns:\n            per_h = sub[~sub["height_m"].astype(str).eq("ALL_PROFILE")].copy()\n            per_h = per_h[pd.to_numeric(per_h["height_m"], errors="coerce").notna()]\n            for var, g in per_h.groupby("variable"):\n                gg = g.dropna(subset=["primary_error"]).copy()\n                if gg.empty:\n                    continue\n                gg["height_m_numeric"] = pd.to_numeric(gg["height_m"], errors="coerce")\n                gg = gg.sort_values("height_m_numeric")\n                _plot_code2_metric_bar_with_labels(\n                    gg,\n                    Path(case_dir) / f"plot_metrics_{split}_{safe_name(var)}_by_height.png",\n                    f"{case_name}: {split} {var} metrics by height",\n                    x_col="height_m",\n                )\n\n\n# =============================================================================\n# FINAL USER PATCH: exclude unreliable 4 m / 50 m WD-related wind targets\n# =============================================================================\n# Reason:\n#   At 4 m and 50 m, WD is not used for the later training cases. Because U/V\n#   wind-component targets are created from WS+WD when direct U/V is unavailable,\n#   these WD-related U/V targets are also removed at the same two heights.\n#\n# Kept:\n#   - direct WS residual targets at 4 m and 50 m, if available;\n#   - T and TKE targets at 4 m and 50 m, if available;\n#   - all variables at the other selected heights.\n#\n# Also removed from the model input feature pool:\n#   - WRF_WD4 / WRF_WD50 and their sin/cos variants;\n#   - WRF_U4 / WRF_V4 / WRF_U50 / WRF_V50 and their auto-derived variants.\n# This prevents corrFDR/forced-keep logic from bringing these WD-related wind\n# component features back into the later cases.\n\nCODE_EXCLUDE_WD_UV_HEIGHTS_M = [4, 50]\nCODE_EXCLUDE_WD_UV_VARS = {"wd", "u", "v"}\n\n\ndef _excluded_wd_uv_heights_code2() -> set:\n    try:\n        return {int(h) for h in globals().get("CODE_EXCLUDE_WD_UV_HEIGHTS_M", [4, 50])}\n    except Exception:\n        return {4, 50}\n\n\ndef _is_excluded_wd_uv_target_code2(record: TargetRecord) -> bool:\n    return int(record.height) in _excluded_wd_uv_heights_code2() and str(record.var).lower() in CODE_EXCLUDE_WD_UV_VARS\n\n\ndef _filter_wd_uv_target_records_code2(records: Sequence[TargetRecord]) -> Tuple[List[TargetRecord], List[TargetRecord]]:\n    kept: List[TargetRecord] = []\n    dropped: List[TargetRecord] = []\n    for r in records:\n        if _is_excluded_wd_uv_target_code2(r):\n            dropped.append(r)\n        else:\n            kept.append(r)\n    return kept, dropped\n\n\ndef _is_excluded_wd_uv_feature_code2(col: str) -> bool:\n    """Return True for WD/U/V input features at excluded heights only."""\n    s = str(col)\n    # Only remove WRF profile input features. OBS columns are handled through targets.\n    if "WRF_" not in s:\n        return False\n    for h in sorted(_excluded_wd_uv_heights_code2()):\n        # Matches examples:\n        #   WRF_U4_interp (m/s), WRF_U_4m_interp (m/s), WRF_U4_auto_from_WS_WD (m/s)\n        #   WRF_V50_interp (m/s), WRF_WD50_sin, WRF_WD_50m_cos, WRF_WD50_interp (deg)\n        if re.search(rf"\\bWRF_(?:U|V|WD)_?{h}(?:m)?(?:_|\\b|\\s|\\(|$)", s):\n            return True\n    return False\n\n\ndef _filter_wd_uv_feature_cols_code2(cols: Sequence[str]) -> Tuple[List[str], List[str]]:\n    kept: List[str] = []\n    dropped: List[str] = []\n    for c in cols:\n        if _is_excluded_wd_uv_feature_code2(c):\n            dropped.append(c)\n        else:\n            kept.append(c)\n    return kept, dropped\n\n\n_detect_targets_code2_drop_wd_uv_base = detect_targets_and_create_columns\n\n\ndef detect_targets_and_create_columns(\n    df: pd.DataFrame,\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n) -> Tuple[pd.DataFrame, List[TargetRecord], List[int]]:\n    """Create targets, then remove 4/50 m WD and WD-related U/V targets."""\n    out, records, used_heights = _detect_targets_code2_drop_wd_uv_base(\n        df, heights_m=heights_m, target_groups=target_groups\n    )\n    kept_records, dropped_records = _filter_wd_uv_target_records_code2(records)\n    if dropped_records:\n        drop_report = ", ".join([f"{r.var}@{r.height}m" for r in dropped_records])\n        print(f"[target exclusion] Removed WD-related targets at heights {_excluded_wd_uv_heights_code2()}: {drop_report}")\n    used_heights_new = sorted(set(int(r.height) for r in kept_records))\n    if not kept_records:\n        raise ValueError("All detected targets were excluded by CODE_EXCLUDE_WD_UV_HEIGHTS_M; check selected heights/target groups.")\n    return out, kept_records, used_heights_new\n\n\n_build_feature_set_code2_drop_wd_uv_base = build_feature_set\n\n\ndef build_feature_set(df: pd.DataFrame, heights: Sequence[int]) -> List[str]:\n    """Build feature list, then remove 4/50 m WD and WD-related U/V features."""\n    cols = _build_feature_set_code2_drop_wd_uv_base(df, heights)\n    kept, dropped = _filter_wd_uv_feature_cols_code2(cols)\n    if dropped:\n        print(f"[feature exclusion] Removed {len(dropped)} WD-related U/V/WD input features at heights {_excluded_wd_uv_heights_code2()}.")\n    return kept\n\n\n# build_feature_set_with_most() calls build_feature_set() at runtime, so the wrapper\n# above also applies to MOSTinput feature pools. This extra wrapper guarantees that\n# any future MOST-feature patch cannot accidentally re-add WRF_U/V/WD at 4/50 m.\n_build_feature_set_with_most_code2_drop_wd_uv_base = build_feature_set_with_most\n\n\ndef build_feature_set_with_most(df: pd.DataFrame, heights: Sequence[int], include_most: bool = False) -> List[str]:\n    cols = _build_feature_set_with_most_code2_drop_wd_uv_base(df, heights, include_most=include_most)\n    kept, dropped = _filter_wd_uv_feature_cols_code2(cols)\n    if dropped:\n        print(f"[feature exclusion] Removed {len(dropped)} WD-related U/V/WD input features from MOSTinput={include_most} pool.")\n    return kept\n\n\n_build_target_detection_report_code2_drop_wd_uv_base = build_target_detection_report\n\n\ndef build_target_detection_report(df: pd.DataFrame, heights: Sequence[int]) -> pd.DataFrame:\n    """Add explicit exclusion flags to the pre-training detection report."""\n    rep = _build_target_detection_report_code2_drop_wd_uv_base(df, heights)\n    if "height_m" in rep.columns:\n        rep["wd_uv_excluded_for_training"] = rep["height_m"].astype(int).isin(_excluded_wd_uv_heights_code2())\n        rep["excluded_target_vars_at_this_height"] = np.where(\n            rep["wd_uv_excluded_for_training"],\n            "wd,u,v",\n            "",\n        )\n    return rep\n\n# =============================================================================\n# A8/A9 PATCH: direct-WS MOST wind-magnitude PINN for Code2/Code2_drop\n# =============================================================================\n#\n# Original Code2 PINN uses U/V targets:\n#     WS_corr = sqrt((WRF_U + dU)^2 + (WRF_V + dV)^2)\n#\n# For WS/WD-only A8/A9 cases, there may be no u/v targets. This patch adds\n# direct-WS physics:\n#     WS_corr_direct = WRF_WS + dWS\n#     physics_loss   = Huber(WS_corr_direct - U_MO)\n#\n# If both U/V and direct WS are present for the same height, U/V is preferred\n# for that height to preserve previous behavior.\n\ndef wind_ws_records_for_direct_pinn(records: Sequence[TargetRecord]) -> List[Tuple[int, int]]:\n    """Return (height, ws_index) for direct WS targets not already covered by U/V pairs."""\n    uv_heights = {int(h) for h, _, _ in wind_uv_pairs(records)}\n    out = []\n    for j, r in enumerate(records):\n        if r.var == "ws" and int(r.height) not in uv_heights:\n            out.append((int(r.height), j))\n    return out\n\n\ndef pinn_mostmag_loss(n_outputs: int, y_mean: np.ndarray, y_scale: np.ndarray,\n                      records: Sequence[TargetRecord], lambda_mo: float, lambda_smooth: float):\n    """Supervised masked Huber + gated MOST wind-speed-magnitude loss.\n\n    Aux layout:\n        [wrf_u_uv, wrf_v_uv, wrf_ws_uv, u_mo_uv, gate_uv,\n         wrf_ws_direct, u_mo_direct, gate_direct]\n\n    U/V physics is used where u/v target pairs exist.\n    Direct-WS physics is used where only ws target exists.\n    """\n    tf, *_ = import_tf()\n\n    uv_pairs = wind_uv_pairs(records)\n    ws_pairs = wind_ws_records_for_direct_pinn(records)\n\n    n_uv = len(uv_pairs)\n    n_ws = len(ws_pairs)\n\n    u_idx = [p[1] for p in uv_pairs]\n    v_idx = [p[2] for p in uv_pairs]\n    ws_idx = [p[1] for p in ws_pairs]\n    uv_heights = [p[0] for p in uv_pairs]\n    ws_heights = [p[0] for p in ws_pairs]\n\n    y_mean_tf = tf.constant(np.asarray(y_mean, dtype=np.float32), dtype=tf.float32)\n    y_scale_tf = tf.constant(np.asarray(y_scale, dtype=np.float32), dtype=tf.float32)\n\n    u_idx_tf = tf.constant(u_idx, dtype=tf.int32) if n_uv else tf.constant([], dtype=tf.int32)\n    v_idx_tf = tf.constant(v_idx, dtype=tf.int32) if n_uv else tf.constant([], dtype=tf.int32)\n    ws_idx_tf = tf.constant(ws_idx, dtype=tf.int32) if n_ws else tf.constant([], dtype=tf.int32)\n\n    uv_heights_tf = tf.constant(np.asarray(uv_heights, dtype=np.float32), dtype=tf.float32) if n_uv else tf.constant([], dtype=tf.float32)\n    ws_heights_tf = tf.constant(np.asarray(ws_heights, dtype=np.float32), dtype=tf.float32) if n_ws else tf.constant([], dtype=tf.float32)\n\n    def huber(e, delta=1.0):\n        abs_e = tf.abs(e)\n        return tf.where(abs_e <= delta, 0.5 * tf.square(e), delta * (abs_e - 0.5 * delta))\n\n    def _smooth_profile_loss(pred_residual, heights_tf):\n        n_h = int(pred_residual.shape[1]) if pred_residual.shape[1] is not None else 0\n        if n_h < 3:\n            return tf.constant(0.0, dtype=pred_residual.dtype)\n        dz = heights_tf[1:] - heights_tf[:-1]\n        slopes = (pred_residual[:, 1:] - pred_residual[:, :-1]) / dz[None, :]\n        curvature = slopes[:, 1:] - slopes[:, :-1]\n        return tf.reduce_mean(tf.square(curvature))\n\n    def loss(y_true_concat, y_pred):\n        y_true = y_true_concat[:, 0:n_outputs]\n        mask = y_true_concat[:, n_outputs:2 * n_outputs]\n        err = y_pred - y_true\n        sup = huber(err, delta=1.0)\n        sup_loss = tf.reduce_sum(mask * sup) / (tf.reduce_sum(mask) + 1e-6)\n\n        if lambda_mo <= 0.0 or (n_uv + n_ws) < 1:\n            return sup_loss\n\n        offset = 2 * n_outputs\n        y_pred_phys = y_pred * y_scale_tf[None, :] + y_mean_tf[None, :]\n\n        phys_losses = []\n        gate_sums = []\n        smooth_loss = tf.constant(0.0, dtype=y_pred.dtype)\n\n        if n_uv > 0:\n            wrf_u = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            wrf_v = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            wrf_ws = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            u_mo = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            gate = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n\n            du = tf.gather(y_pred_phys, u_idx_tf, axis=1)\n            dv = tf.gather(y_pred_phys, v_idx_tf, axis=1)\n            u_corr = wrf_u + du\n            v_corr = wrf_v + dv\n            ws_corr = tf.sqrt(tf.maximum(tf.square(u_corr) + tf.square(v_corr), 1e-12))\n            pred_residual = ws_corr - wrf_ws\n            phys_residual = u_mo - wrf_ws\n            phys_each = huber(pred_residual - phys_residual, delta=1.0)\n            phys_losses.append(tf.reduce_sum(gate * phys_each))\n            gate_sums.append(tf.reduce_sum(gate))\n            if lambda_smooth > 0.0 and n_uv >= 3:\n                smooth_loss = smooth_loss + _smooth_profile_loss(pred_residual, uv_heights_tf)\n        else:\n            # No U/V aux block.\n            pass\n\n        if n_ws > 0:\n            wrf_ws_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n            u_mo_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n            gate_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n\n            dws = tf.gather(y_pred_phys, ws_idx_tf, axis=1)\n            ws_corr_d = tf.maximum(wrf_ws_d + dws, 0.0)\n            pred_residual_d = ws_corr_d - wrf_ws_d\n            phys_residual_d = u_mo_d - wrf_ws_d\n            phys_each_d = huber(pred_residual_d - phys_residual_d, delta=1.0)\n            phys_losses.append(tf.reduce_sum(gate_d * phys_each_d))\n            gate_sums.append(tf.reduce_sum(gate_d))\n            if lambda_smooth > 0.0 and n_ws >= 3:\n                smooth_loss = smooth_loss + _smooth_profile_loss(pred_residual_d, ws_heights_tf)\n\n        total_gate = tf.add_n(gate_sums) if gate_sums else tf.constant(0.0, dtype=y_pred.dtype)\n        total_phys = tf.add_n(phys_losses) if phys_losses else tf.constant(0.0, dtype=y_pred.dtype)\n        mo_loss = tf.cond(\n            total_gate > 0.0,\n            lambda: total_phys / (total_gate + 1e-6),\n            lambda: tf.constant(0.0, dtype=y_pred.dtype),\n        )\n\n        return sup_loss + float(lambda_mo) * mo_loss + float(lambda_smooth) * smooth_loss\n\n    return loss\n\n\ndef make_pinn_aux_and_gate_summary(df: pd.DataFrame, idx: np.ndarray, train_i: np.ndarray,\n                                   records: Sequence[TargetRecord]) -> Tuple[np.ndarray, pd.DataFrame]:\n    """Build PINN aux array for both U/V-based and direct-WS-based MOST losses."""\n    uv_pairs = wind_uv_pairs(records)\n    ws_pairs = wind_ws_records_for_direct_pinn(records)\n    n = len(idx)\n\n    if not uv_pairs and not ws_pairs:\n        return np.empty((n, 0), dtype=float), pd.DataFrame()\n\n    rec_by = {(r.var, int(r.height)): r for r in records}\n\n    uv_wrf_u_list, uv_wrf_v_list, uv_wrf_ws_list, uv_umo_list, uv_gate_cols = [], [], [], [], []\n    ws_wrf_ws_list, ws_umo_list, ws_gate_cols = [], [], []\n    uv_heights, ws_heights = [], []\n    summary_rows = []\n\n    def _umo_for_height(h: int, wrf_ws: np.ndarray):\n        umo_col = first_existing(df, u_mo_candidates(h))\n        mo_minus_col = first_existing(df, mo_minus_candidates(h))\n        if umo_col is not None:\n            u_mo = pd.to_numeric(df.loc[idx, umo_col], errors="coerce").values.astype(float)\n        elif mo_minus_col is not None:\n            mo_minus = pd.to_numeric(df.loc[idx, mo_minus_col], errors="coerce").values.astype(float)\n            u_mo = wrf_ws + mo_minus\n        else:\n            u_mo = np.full(n, np.nan, dtype=float)\n        return u_mo, umo_col, mo_minus_col\n\n    def _gate_for_height(h: int, wrf_ws: np.ndarray, u_mo: np.ndarray, extra_finite: Optional[np.ndarray] = None):\n        phys_residual = u_mo - wrf_ws\n        gate = (np.isfinite(wrf_ws) & np.isfinite(u_mo)).astype(float)\n        if extra_finite is not None:\n            gate *= extra_finite.astype(float)\n        finite_train = phys_residual[train_i][np.isfinite(phys_residual[train_i])]\n        qlo, qhi = np.nan, np.nan\n        if finite_train.size >= 10:\n            qlo, qhi = np.nanquantile(finite_train, [PINN_GATE_QLOW, PINN_GATE_QHIGH])\n            gate *= ((phys_residual >= qlo) & (phys_residual <= qhi)).astype(float)\n        else:\n            gate *= 0.0\n        return gate, qlo, qhi\n\n    # U/V-based physics heights.\n    for h, u_j, v_j in uv_pairs:\n        uv_heights.append(h)\n        u_rec = rec_by[("u", int(h))]\n        v_rec = rec_by[("v", int(h))]\n        wrf_u = pd.to_numeric(df.loc[idx, u_rec.wrf_col], errors="coerce").values.astype(float)\n        wrf_v = pd.to_numeric(df.loc[idx, v_rec.wrf_col], errors="coerce").values.astype(float)\n        wrf_ws_col = first_existing(df, wrf_ws_candidates(int(h)))\n        if wrf_ws_col is not None:\n            wrf_ws = pd.to_numeric(df.loc[idx, wrf_ws_col], errors="coerce").values.astype(float)\n        else:\n            wrf_ws = np.sqrt(wrf_u ** 2 + wrf_v ** 2)\n\n        u_mo, umo_col, mo_minus_col = _umo_for_height(int(h), wrf_ws)\n        extra = np.isfinite(wrf_u) & np.isfinite(wrf_v)\n        gate, qlo, qhi = _gate_for_height(int(h), wrf_ws, u_mo, extra)\n\n        uv_wrf_u_list.append(wrf_u)\n        uv_wrf_v_list.append(wrf_v)\n        uv_wrf_ws_list.append(wrf_ws)\n        uv_umo_list.append(np.where(np.isfinite(u_mo), u_mo, wrf_ws))\n        uv_gate_cols.append(gate)\n        summary_rows.append({\n            "height_m": int(h),\n            "pinn_source": "uv",\n            "umo_col": umo_col if umo_col is not None else "",\n            "mo_minus_col": mo_minus_col if mo_minus_col is not None else "",\n            "qlo_train_phys_residual": qlo,\n            "qhi_train_phys_residual": qhi,\n            "finite_MOST_ratio_all": float(np.isfinite(u_mo).mean()),\n            "quantile_gate_mean_before_height_pblh": float(np.nanmean(gate)),\n        })\n\n    # Direct-WS physics heights not covered by U/V.\n    for h, ws_j in ws_pairs:\n        ws_heights.append(h)\n        ws_rec = rec_by[("ws", int(h))]\n        wrf_ws = pd.to_numeric(df.loc[idx, ws_rec.wrf_col], errors="coerce").values.astype(float)\n        u_mo, umo_col, mo_minus_col = _umo_for_height(int(h), wrf_ws)\n        gate, qlo, qhi = _gate_for_height(int(h), wrf_ws, u_mo, None)\n\n        ws_wrf_ws_list.append(wrf_ws)\n        ws_umo_list.append(np.where(np.isfinite(u_mo), u_mo, wrf_ws))\n        ws_gate_cols.append(gate)\n        summary_rows.append({\n            "height_m": int(h),\n            "pinn_source": "direct_ws",\n            "umo_col": umo_col if umo_col is not None else "",\n            "mo_minus_col": mo_minus_col if mo_minus_col is not None else "",\n            "qlo_train_phys_residual": qlo,\n            "qhi_train_phys_residual": qhi,\n            "finite_MOST_ratio_all": float(np.isfinite(u_mo).mean()),\n            "quantile_gate_mean_before_height_pblh": float(np.nanmean(gate)),\n        })\n\n    arrays = []\n    if uv_heights:\n        wrf_u_arr = np.column_stack(uv_wrf_u_list)\n        wrf_v_arr = np.column_stack(uv_wrf_v_list)\n        wrf_ws_arr = np.column_stack(uv_wrf_ws_list)\n        u_mo_arr = np.column_stack(uv_umo_list)\n        gate_arr = np.column_stack(uv_gate_cols)\n        hw = height_weight_vector_pinn(uv_heights)[None, :]\n        pblh_gate = pblh_gate_matrix_pinn(df, idx, uv_heights)\n        gate_arr = gate_arr * hw * pblh_gate\n        arrays.extend([wrf_u_arr, wrf_v_arr, wrf_ws_arr, u_mo_arr, gate_arr])\n\n    if ws_heights:\n        wrf_ws_d_arr = np.column_stack(ws_wrf_ws_list)\n        u_mo_d_arr = np.column_stack(ws_umo_list)\n        gate_d_arr = np.column_stack(ws_gate_cols)\n        hw_d = height_weight_vector_pinn(ws_heights)[None, :]\n        pblh_gate_d = pblh_gate_matrix_pinn(df, idx, ws_heights)\n        gate_d_arr = gate_d_arr * hw_d * pblh_gate_d\n        arrays.extend([wrf_ws_d_arr, u_mo_d_arr, gate_d_arr])\n\n    aux = np.concatenate(arrays, axis=1).astype(float) if arrays else np.empty((n, 0), dtype=float)\n    aux[~np.isfinite(aux)] = 0.0\n\n    summary = pd.DataFrame(summary_rows)\n    if not summary.empty:\n        # Fill final gate diagnostics separately by source.\n        final_gate_mean = []\n        final_gate_nonzero = []\n        for _, row in summary.iterrows():\n            h = int(row["height_m"])\n            src = str(row["pinn_source"])\n            if src == "uv" and h in uv_heights:\n                j = uv_heights.index(h)\n                # Recompute gated array position from local block.\n                gate_val = arrays[4][:, j] if len(uv_heights) else np.zeros(n)\n            elif src == "direct_ws" and h in ws_heights:\n                j = ws_heights.index(h)\n                # Direct gate is last array in direct block.\n                gate_val = arrays[-1][:, j] if len(ws_heights) else np.zeros(n)\n            else:\n                gate_val = np.zeros(n)\n            final_gate_mean.append(float(np.nanmean(gate_val)))\n            final_gate_nonzero.append(float((gate_val > 0).mean()))\n        summary["height_weight"] = [\n            float(height_weight_vector_pinn([int(h)])[0]) for h in summary["height_m"].values\n        ]\n        # PBLH mean is not split by source here; use source-specific height.\n        summary["pblh_gate_mean"] = [\n            float(np.nanmean(pblh_gate_matrix_pinn(df, idx, [int(h)]))) for h in summary["height_m"].values\n        ]\n        summary["final_gate_mean"] = final_gate_mean\n        summary["final_gate_nonzero_ratio"] = final_gate_nonzero\n\n    return aux, summary\n\n\ndef validation_selection_score(metrics_df: pd.DataFrame) -> float:\n    """Lambda selection score supporting both U/V and direct WS/WD outputs."""\n    if metrics_df is None or metrics_df.empty:\n        return np.inf\n    sub = metrics_df[(metrics_df["split"] == "val") & (metrics_df["height_m"] == "ALL_PROFILE")]\n    if sub.empty:\n        return np.inf\n\n    weights = {\n        "WS_from_uv": float(PINN_SCORE_WEIGHTS.get("WS_from_uv_RMSE", 1.0)),\n        "WD_from_uv": float(PINN_SCORE_WEIGHTS.get("WD_from_uv_MAE", 0.02)),\n        "WS_direct": float(PINN_SCORE_WEIGHTS.get("WS_direct_RMSE", PINN_SCORE_WEIGHTS.get("WS_from_uv_RMSE", 1.0))),\n        "WD_direct": float(PINN_SCORE_WEIGHTS.get("WD_direct_MAE", PINN_SCORE_WEIGHTS.get("WD_from_uv_MAE", 0.02))),\n        "T": float(PINN_SCORE_WEIGHTS.get("T_RMSE", 0.2)),\n        "TKE": float(PINN_SCORE_WEIGHTS.get("TKE_RMSE", 0.2)),\n    }\n\n    score = 0.0\n    used = 0\n    for _, row in sub.iterrows():\n        var = str(row["variable"])\n        if var in {"WS_from_uv", "WS_direct", "T", "TKE"} and np.isfinite(row.get("RMSE", np.nan)):\n            w = weights.get(var, 0.0)\n            if w > 0:\n                score += w * float(row["RMSE"]); used += 1\n        elif var in {"WD_from_uv", "WD_direct"} and np.isfinite(row.get("MAE", np.nan)):\n            w = weights.get(var, 0.0)\n            if w > 0:\n                score += w * float(row["MAE"]); used += 1\n\n    return score if used > 0 else np.inf\n\n\n# =============================================================================\n# FINAL PATCH 2026-06-23\n# - runner filename issue handled in fixed runner script\n# - metrics use Pearson_r instead of R\n# - raw_WRF baseline uses target-only windows\n# - WD supervised loss uses cosine angular loss\n# - optional group-balanced multi-task loss aggregation\n# - corrFDR gains redundancy-pruned hybrid selection\n# - profile diagnostics and case sample consistency reports are exported\n# =============================================================================\n\n# ---- Patch configuration ----\nUSE_WD_COSINE_ANGULAR_LOSS = bool(globals().get("USE_WD_COSINE_ANGULAR_LOSS", True))\nWD_COSINE_LOSS_WEIGHT = float(globals().get("WD_COSINE_LOSS_WEIGHT", 1.0))\n\n# "group_balanced" gives each physical task group a comparable role after target scaling.\n# Set to "sample_weighted" to recover the old behavior.\nLOSS_AGGREGATION_MODE = str(globals().get("LOSS_AGGREGATION_MODE", "group_balanced")).lower()\nTASK_GROUP_WEIGHTS = dict(globals().get("TASK_GROUP_WEIGHTS", {\n    "wind": 1.0,\n    "temp": 1.0,\n    "tke": 1.0,\n    "other": 1.0,\n}))\n\n# More robust than plain corrFDR: keep significant/forced features, then remove strongly\n# redundant predictors based on train-period feature-feature correlation.\nUSE_HYBRID_CORRFDR_SELECTION = bool(globals().get("USE_HYBRID_CORRFDR_SELECTION", True))\nFEATURE_REDUNDANCY_ABS_R_MAX = float(globals().get("FEATURE_REDUNDANCY_ABS_R_MAX", 0.98))\nMAX_CORRFDR_FEATURES = globals().get("MAX_CORRFDR_FEATURES", None)\nif MAX_CORRFDR_FEATURES is not None:\n    MAX_CORRFDR_FEATURES = int(MAX_CORRFDR_FEATURES)\n\n\ndef standard_metrics(y_true, y_pred, y_base=None) -> Dict[str, float]:\n    """Standard scalar metrics. Use Pearson_r explicitly, not ambiguous R."""\n    yt = np.asarray(y_true, dtype=float).ravel()\n    yp = np.asarray(y_pred, dtype=float).ravel()\n    m = np.isfinite(yt) & np.isfinite(yp)\n    if m.sum() < 2:\n        return {"N": int(m.sum()), "RMSE": np.nan, "MAE": np.nan, "MBE": np.nan,\n                "Pearson_r": np.nan, "NRMSE_pct": np.nan, "Skill_RMSE_pct": np.nan}\n    yt = yt[m]\n    yp = yp[m]\n    rmse = float(np.sqrt(mean_squared_error(yt, yp)))\n    mae = float(mean_absolute_error(yt, yp))\n    mbe = float(np.mean(yp - yt))\n    pearson_r = float(np.corrcoef(yt, yp)[0, 1]) if np.std(yt) > 0 and np.std(yp) > 0 else np.nan\n    mean_obs = float(np.mean(yt))\n    nrmse = float(rmse / mean_obs * 100.0) if abs(mean_obs) > 1e-12 else np.nan\n    skill = np.nan\n    if y_base is not None:\n        yb0 = np.asarray(y_base, dtype=float).ravel()\n        yb = yb0[m]\n        mb = np.isfinite(yb)\n        if mb.sum() >= 2:\n            rmse_base = float(np.sqrt(mean_squared_error(yt[mb], yb[mb])))\n            if rmse_base > 1e-12:\n                skill = float((rmse_base - rmse) / rmse_base * 100.0)\n    return {"N": int(len(yt)), "RMSE": rmse, "MAE": mae, "MBE": mbe,\n            "Pearson_r": pearson_r, "NRMSE_pct": nrmse, "Skill_RMSE_pct": skill}\n\n\ndef direction_metrics(obs_wd, pred_wd, base_wd=None) -> Dict[str, float]:\n    """Circular wind-direction metrics. Pearson_r is intentionally NaN for angles."""\n    obs = np.asarray(obs_wd, dtype=float).ravel()\n    pred = np.asarray(pred_wd, dtype=float).ravel()\n    m = np.isfinite(obs) & np.isfinite(pred)\n    if m.sum() < 2:\n        return {"N": int(m.sum()), "RMSE": np.nan, "MAE": np.nan, "MBE": np.nan,\n                "Pearson_r": np.nan, "NRMSE_pct": np.nan, "Skill_RMSE_pct": np.nan}\n    err = circular_diff_deg(pred[m], obs[m])\n    rmse = float(np.sqrt(np.mean(err ** 2)))\n    mae = float(np.mean(np.abs(err)))\n    mbe = float(np.mean(err))\n    skill = np.nan\n    if base_wd is not None:\n        base = np.asarray(base_wd, dtype=float).ravel()\n        mb = m & np.isfinite(base)\n        if mb.sum() >= 2:\n            base_err = circular_diff_deg(base[mb], obs[mb])\n            rmse_base = float(np.sqrt(np.mean(base_err ** 2)))\n            if rmse_base > 1e-12:\n                pred_err2 = circular_diff_deg(pred[mb], obs[mb])\n                rmse_pred2 = float(np.sqrt(np.mean(pred_err2 ** 2)))\n                skill = float((rmse_base - rmse_pred2) / rmse_base * 100.0)\n    return {"N": int(m.sum()), "RMSE": rmse, "MAE": mae, "MBE": mbe,\n            "Pearson_r": np.nan, "NRMSE_pct": np.nan, "Skill_RMSE_pct": skill}\n\n\ndef _task_group_from_record(r: TargetRecord) -> str:\n    if r.var in {"u", "v", "ws", "wd"}:\n        return "wind"\n    if r.var == "temp":\n        return "temp"\n    if r.var == "log_tke":\n        return "tke"\n    return "other"\n\n\ndef _supervised_multitask_loss_tf(y_true_concat, y_pred, n_outputs: int,\n                                  y_mean: np.ndarray, y_scale: np.ndarray,\n                                  records: Sequence[TargetRecord]):\n    """Masked supervised loss with cosine angular loss for WD and optional group balance."""\n    tf, *_ = import_tf()\n    y_true = y_true_concat[:, 0:n_outputs]\n    mask = y_true_concat[:, n_outputs:2 * n_outputs]\n\n    y_mean_tf = tf.constant(np.asarray(y_mean, dtype=np.float32), dtype=tf.float32)\n    y_scale_tf = tf.constant(np.asarray(y_scale, dtype=np.float32), dtype=tf.float32)\n    y_true_phys = y_true * y_scale_tf[None, :] + y_mean_tf[None, :]\n    y_pred_phys = y_pred * y_scale_tf[None, :] + y_mean_tf[None, :]\n\n    def huber(e, delta=1.0):\n        abs_e = tf.abs(e)\n        return tf.where(abs_e <= delta, 0.5 * tf.square(e), delta * (abs_e - 0.5 * delta))\n\n    loss_cols = []\n    group_names = []\n    for j, r in enumerate(records):\n        if USE_WD_COSINE_ANGULAR_LOSS and r.var == "wd":\n            # y_true_phys/y_pred_phys are circular residuals in degrees.\n            # 1-cos(delta) is periodic and removes the 0/360 discontinuity.\n            angle_err_rad = (y_pred_phys[:, j] - y_true_phys[:, j]) * (math.pi / 180.0)\n            lj = WD_COSINE_LOSS_WEIGHT * (1.0 - tf.cos(angle_err_rad))\n        else:\n            lj = huber(y_pred[:, j] - y_true[:, j], delta=1.0)\n        loss_cols.append(lj)\n        group_names.append(_task_group_from_record(r))\n\n    loss_mat = tf.stack(loss_cols, axis=1) if loss_cols else tf.zeros_like(y_pred)\n\n    if LOSS_AGGREGATION_MODE == "sample_weighted":\n        return tf.reduce_sum(mask * loss_mat) / (tf.reduce_sum(mask) + 1e-6)\n\n    # Group-balanced mode: first average per target, then average per physical group.\n    group_losses = []\n    group_weights = []\n    for g in ["wind", "temp", "tke", "other"]:\n        idx = [j for j, gg in enumerate(group_names) if gg == g]\n        if not idx:\n            continue\n        target_losses = []\n        valid_flags = []\n        for j in idx:\n            mj = mask[:, j]\n            denom = tf.reduce_sum(mj)\n            valid = tf.cast(denom > 0.0, tf.float32)\n            target_losses.append(valid * tf.reduce_sum(mj * loss_mat[:, j]) / (denom + 1e-6))\n            valid_flags.append(valid)\n        valid_sum = tf.add_n(valid_flags) if valid_flags else tf.constant(0.0, dtype=tf.float32)\n        gl = tf.cond(\n            valid_sum > 0.0,\n            lambda tl=target_losses, vs=valid_sum: tf.add_n(tl) / (vs + 1e-6),\n            lambda: tf.constant(0.0, dtype=tf.float32),\n        )\n        gw = float(TASK_GROUP_WEIGHTS.get(g, 1.0))\n        group_losses.append(gl)\n        group_weights.append(tf.cast(gw, tf.float32) * tf.cast(valid_sum > 0.0, tf.float32))\n\n    if not group_losses:\n        return tf.reduce_sum(mask * loss_mat) / (tf.reduce_sum(mask) + 1e-6)\n\n    weighted = [w * l for w, l in zip(group_weights, group_losses)]\n    return tf.add_n(weighted) / (tf.add_n(group_weights) + 1e-6)\n\n\ndef masked_huber_loss_v2(n_outputs: int, delta: float = 1.0):\n    """Backward-compatible name; now uses final supervised loss if records are unavailable it falls back."""\n    tf, *_ = import_tf()\n    def loss(y_true_concat, y_pred):\n        y_true = y_true_concat[:, 0:n_outputs]\n        mask = y_true_concat[:, n_outputs:2 * n_outputs]\n        err = y_pred - y_true\n        abs_e = tf.abs(err)\n        huber = tf.where(abs_e <= delta, 0.5 * tf.square(err), delta * (abs_e - 0.5 * delta))\n        return tf.reduce_sum(mask * huber) / (tf.reduce_sum(mask) + 1e-6)\n    return loss\n\n\ndef pinn_mostmag_loss(n_outputs: int, y_mean: np.ndarray, y_scale: np.ndarray,\n                      records: Sequence[TargetRecord], lambda_mo: float, lambda_smooth: float):\n    """Supervised multi-task loss + gated MOST wind-speed-magnitude regularization.\n\n    Supervised part:\n      - WD targets use cosine angular loss when USE_WD_COSINE_ANGULAR_LOSS=True.\n      - Other targets use Huber loss in scaled residual space.\n      - Group-balanced aggregation avoids wind/T/TKE target-count domination.\n\n    Physics part:\n      - U/V physics where u/v target pairs exist.\n      - Direct-WS physics where only ws targets exist.\n    """\n    tf, *_ = import_tf()\n\n    uv_pairs = wind_uv_pairs(records)\n    ws_pairs = wind_ws_records_for_direct_pinn(records)\n\n    n_uv = len(uv_pairs)\n    n_ws = len(ws_pairs)\n\n    u_idx = [p[1] for p in uv_pairs]\n    v_idx = [p[2] for p in uv_pairs]\n    ws_idx = [p[1] for p in ws_pairs]\n    uv_heights = [p[0] for p in uv_pairs]\n    ws_heights = [p[0] for p in ws_pairs]\n\n    y_mean_tf = tf.constant(np.asarray(y_mean, dtype=np.float32), dtype=tf.float32)\n    y_scale_tf = tf.constant(np.asarray(y_scale, dtype=np.float32), dtype=tf.float32)\n\n    u_idx_tf = tf.constant(u_idx, dtype=tf.int32) if n_uv else tf.constant([], dtype=tf.int32)\n    v_idx_tf = tf.constant(v_idx, dtype=tf.int32) if n_uv else tf.constant([], dtype=tf.int32)\n    ws_idx_tf = tf.constant(ws_idx, dtype=tf.int32) if n_ws else tf.constant([], dtype=tf.int32)\n\n    uv_heights_tf = tf.constant(np.asarray(uv_heights, dtype=np.float32), dtype=tf.float32) if n_uv else tf.constant([], dtype=tf.float32)\n    ws_heights_tf = tf.constant(np.asarray(ws_heights, dtype=np.float32), dtype=tf.float32) if n_ws else tf.constant([], dtype=tf.float32)\n\n    def huber(e, delta=1.0):\n        abs_e = tf.abs(e)\n        return tf.where(abs_e <= delta, 0.5 * tf.square(e), delta * (abs_e - 0.5 * delta))\n\n    def _smooth_profile_loss(pred_residual, heights_tf):\n        n_h = int(pred_residual.shape[1]) if pred_residual.shape[1] is not None else 0\n        if n_h < 3:\n            return tf.constant(0.0, dtype=pred_residual.dtype)\n        dz = heights_tf[1:] - heights_tf[:-1]\n        slopes = (pred_residual[:, 1:] - pred_residual[:, :-1]) / dz[None, :]\n        curvature = slopes[:, 1:] - slopes[:, :-1]\n        return tf.reduce_mean(tf.square(curvature))\n\n    def loss(y_true_concat, y_pred):\n        sup_loss = _supervised_multitask_loss_tf(\n            y_true_concat=y_true_concat,\n            y_pred=y_pred,\n            n_outputs=n_outputs,\n            y_mean=y_mean,\n            y_scale=y_scale,\n            records=records,\n        )\n\n        if lambda_mo <= 0.0 or (n_uv + n_ws) < 1:\n            return sup_loss\n\n        offset = 2 * n_outputs\n        y_pred_phys = y_pred * y_scale_tf[None, :] + y_mean_tf[None, :]\n\n        phys_losses = []\n        gate_sums = []\n        smooth_loss = tf.constant(0.0, dtype=y_pred.dtype)\n\n        if n_uv > 0:\n            wrf_u = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            wrf_v = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            wrf_ws = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            u_mo = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            gate = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n\n            du = tf.gather(y_pred_phys, u_idx_tf, axis=1)\n            dv = tf.gather(y_pred_phys, v_idx_tf, axis=1)\n            u_corr = wrf_u + du\n            v_corr = wrf_v + dv\n            ws_corr = tf.sqrt(tf.maximum(tf.square(u_corr) + tf.square(v_corr), 1e-12))\n            pred_residual = ws_corr - wrf_ws\n            phys_residual = u_mo - wrf_ws\n            phys_each = huber(pred_residual - phys_residual, delta=1.0)\n            phys_losses.append(tf.reduce_sum(gate * phys_each))\n            gate_sums.append(tf.reduce_sum(gate))\n            if lambda_smooth > 0.0 and n_uv >= 3:\n                smooth_loss = smooth_loss + _smooth_profile_loss(pred_residual, uv_heights_tf)\n\n        if n_ws > 0:\n            wrf_ws_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n            u_mo_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n            gate_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n\n            dws = tf.gather(y_pred_phys, ws_idx_tf, axis=1)\n            ws_corr_d = tf.maximum(wrf_ws_d + dws, 0.0)\n            pred_residual_d = ws_corr_d - wrf_ws_d\n            phys_residual_d = u_mo_d - wrf_ws_d\n            phys_each_d = huber(pred_residual_d - phys_residual_d, delta=1.0)\n            phys_losses.append(tf.reduce_sum(gate_d * phys_each_d))\n            gate_sums.append(tf.reduce_sum(gate_d))\n            if lambda_smooth > 0.0 and n_ws >= 3:\n                smooth_loss = smooth_loss + _smooth_profile_loss(pred_residual_d, ws_heights_tf)\n\n        total_gate = tf.add_n(gate_sums) if gate_sums else tf.constant(0.0, dtype=y_pred.dtype)\n        total_phys = tf.add_n(phys_losses) if phys_losses else tf.constant(0.0, dtype=y_pred.dtype)\n        mo_loss = tf.cond(\n            total_gate > 0.0,\n            lambda: total_phys / (total_gate + 1e-6),\n            lambda: tf.constant(0.0, dtype=y_pred.dtype),\n        )\n\n        return sup_loss + float(lambda_mo) * mo_loss + float(lambda_smooth) * smooth_loss\n\n    return loss\n\n\ndef compile_model_v2(model, n_outputs: int, y_mean=None, y_scale=None, records=None,\n                     use_pinn: bool = False, lambda_mo: float = 0.0, lambda_smooth: float = 0.0):\n    """Compile with final supervised loss, plus optional MOSTmag PINN loss."""\n    tf, layers, models, callbacks, optimizers = import_tf()\n    if use_pinn:\n        loss_fn = pinn_mostmag_loss(n_outputs, y_mean, y_scale, records, lambda_mo, lambda_smooth)\n    else:\n        if records is not None and y_mean is not None and y_scale is not None:\n            def loss_fn(y_true_concat, y_pred):\n                return _supervised_multitask_loss_tf(y_true_concat, y_pred, n_outputs, y_mean, y_scale, records)\n        else:\n            loss_fn = masked_huber_loss_v2(n_outputs, delta=1.0)\n    model.compile(optimizer=optimizers.Adam(learning_rate=LEARNING_RATE),\n                  loss=loss_fn,\n                  metrics=[masked_mae_metric_v2(n_outputs)])\n    return model\n\n\n# ---- Hybrid corrFDR selection patch ----\n_select_corr_fdr_features_before_final_patch = select_corr_fdr_features\n\ndef _feature_physics_priority_code2(c: str) -> int:\n    """Higher value = harder to drop during redundancy pruning."""\n    if c in {"hour_sin", "hour_cos"}:\n        return 100\n    if re.search(r"WRF_WS\\d+|WRF_WS_\\d+m", str(c)):\n        return 90\n    if any(k in str(c) for k in ["WRF_PBLH", "WRF_Bulk_Ri", "WRF_L", "UST", "Z0"]):\n        return 80\n    if re.search(r"WRF_TKE\\d+|WRF_TKE_\\d+m", str(c)):\n        return 70\n    if re.search(r"WRF_T\\d+|WRF_TEMP\\d+|WRF_T_\\d+m", str(c)):\n        return 60\n    if any(k in str(c) for k in ["U_MO", "MOST", "MO_minus"]):\n        return 55\n    return 0\n\n\ndef _target_relevance_scores_from_report(report: pd.DataFrame) -> Dict[str, float]:\n    if report is None or report.empty or "feature" not in report.columns:\n        return {}\n    tmp = report.copy()\n    tmp["abs_r"] = pd.to_numeric(tmp.get("Pearson_r", np.nan), errors="coerce").abs()\n    tmp["q"] = pd.to_numeric(tmp.get("q_value_BH_FDR", np.nan), errors="coerce")\n    # Prefer high |r| and significant q. Non-significant pairs still keep small score.\n    tmp["score"] = tmp["abs_r"].fillna(0.0) * np.where(tmp["q"].fillna(1.0) <= FDR_Q_MAX, 1.0, 0.25)\n    return tmp.groupby("feature")["score"].max().to_dict()\n\n\ndef _redundancy_prune_features(df: pd.DataFrame, train_row_idx: np.ndarray,\n                               selected_features: Sequence[str], report: pd.DataFrame) -> Tuple[List[str], pd.DataFrame]:\n    selected_features = [c for c in selected_features if c in df.columns]\n    if not USE_HYBRID_CORRFDR_SELECTION or len(selected_features) <= 2:\n        return list(selected_features), pd.DataFrame({"feature": selected_features, "hybrid_selected_final": True})\n\n    scores = _target_relevance_scores_from_report(report)\n    priority = {c: _feature_physics_priority_code2(c) for c in selected_features}\n\n    # Sort: keep physically essential features first, then target relevance.\n    ordered = sorted(\n        selected_features,\n        key=lambda c: (priority.get(c, 0), scores.get(c, 0.0), -selected_features.index(c)),\n        reverse=True,\n    )\n\n    x = df.loc[train_row_idx, selected_features].apply(pd.to_numeric, errors="coerce")\n    corr = x.corr().abs()\n\n    kept = []\n    dropped_rows = []\n    for c in ordered:\n        if MAX_CORRFDR_FEATURES is not None and len(kept) >= MAX_CORRFDR_FEATURES and priority.get(c, 0) < 80:\n            dropped_rows.append({"feature": c, "hybrid_selected_final": False, "drop_reason": "max_feature_limit",\n                                 "target_relevance_score": scores.get(c, np.nan), "physics_priority": priority.get(c, 0)})\n            continue\n\n        drop = False\n        drop_against = ""\n        for k in kept:\n            ck = corr.loc[c, k] if (c in corr.index and k in corr.columns) else np.nan\n            if np.isfinite(ck) and ck >= FEATURE_REDUNDANCY_ABS_R_MAX:\n                # If both are redundant, keep the one with stronger physics priority/relevance.\n                if priority.get(c, 0) <= priority.get(k, 0):\n                    drop = True\n                    drop_against = k\n                    break\n        if drop:\n            dropped_rows.append({"feature": c, "hybrid_selected_final": False,\n                                 "drop_reason": f"redundant_with:{drop_against}",\n                                 "target_relevance_score": scores.get(c, np.nan),\n                                 "physics_priority": priority.get(c, 0)})\n        else:\n            kept.append(c)\n            dropped_rows.append({"feature": c, "hybrid_selected_final": True,\n                                 "drop_reason": "",\n                                 "target_relevance_score": scores.get(c, np.nan),\n                                 "physics_priority": priority.get(c, 0)})\n\n    # Restore the original candidate order for reproducibility/readability.\n    kept_ordered = [c for c in selected_features if c in kept]\n    audit = pd.DataFrame(dropped_rows)\n    return kept_ordered, audit\n\n\ndef select_corr_fdr_features(\n    df: pd.DataFrame,\n    train_row_idx: np.ndarray,\n    candidate_features: Sequence[str],\n    target_records: Sequence[TargetRecord],\n    abs_r_min: float = CORR_ABS_R_MIN,\n    q_max: float = FDR_Q_MAX,\n) -> Tuple[List[str], pd.DataFrame]:\n    selected, report = _select_corr_fdr_features_before_final_patch(\n        df=df,\n        train_row_idx=train_row_idx,\n        candidate_features=candidate_features,\n        target_records=target_records,\n        abs_r_min=abs_r_min,\n        q_max=q_max,\n    )\n    if USE_HYBRID_CORRFDR_SELECTION:\n        selected2, audit = _redundancy_prune_features(df, train_row_idx, selected, report)\n        if selected2:\n            selected = selected2\n        report = report.copy()\n        report["hybrid_corrFDR_enabled"] = True\n        report["hybrid_selected_final"] = report["feature"].isin(selected)\n        if not audit.empty:\n            audit_cols = ["feature", "drop_reason", "target_relevance_score", "physics_priority"]\n            audit2 = audit[audit_cols].drop_duplicates("feature")\n            report = report.merge(audit2, on="feature", how="left")\n    else:\n        report = report.copy()\n        report["hybrid_corrFDR_enabled"] = False\n        report["hybrid_selected_final"] = report.get("selected_feature_final", report["feature"].isin(selected))\n    return selected, report\n\n\n# ---- Raw-WRF target-only baseline patch ----\ndef _make_target_only_baseline_indices(df: pd.DataFrame, target_cols: Sequence[str]) -> Tuple[np.ndarray, np.ndarray]:\n    yv = df[list(target_cols)].astype(float).values if target_cols else np.empty((len(df), 0), dtype=float)\n    idxs, masks = [], []\n    for i in range(WINDOW_SIZE - 1, len(df)):\n        yrow = yv[i, :]\n        mask = np.isfinite(yrow).astype(float)\n        if WINDOW_TARGET_REQUIRE_MODE == "all":\n            if mask.sum() < len(target_cols):\n                continue\n        elif mask.sum() < 1:\n            continue\n        idxs.append(i)\n        masks.append(mask)\n    if not idxs:\n        return np.empty((0,), dtype=int), np.empty((0, len(target_cols)), dtype=float)\n    return np.asarray(idxs, dtype=int), np.asarray(masks, dtype=float)\n\n\ndef run_raw_wrf_profile_case(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    out_dir: Path,\n) -> pd.DataFrame:\n    """Evaluate raw WRF on target-only windows, not ML feature-valid windows."""\n    ensure_dir(out_dir)\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n    dfp = prepare_numeric(df.copy(), list(dict.fromkeys(extra_cols)))\n    idx, mask = _make_target_only_baseline_indices(dfp, target_cols_all)\n    if len(idx) < 3:\n        raise ValueError(f"raw_WRF target-only baseline: too few valid target windows ({len(idx)}).")\n    train_i, val_i, test_i = split_chronological(len(idx))\n    split_labels = np.asarray([""] * len(idx), dtype=object)\n    split_labels[train_i] = "train"\n    split_labels[val_i] = "val"\n    split_labels[test_i] = "test"\n\n    # Zero residual means corrected prediction equals raw WRF baseline.\n    delta_pred = np.zeros((len(idx), len(target_records_all)), dtype=float)\n    pred_table, metrics_df = build_prediction_table_and_metrics(\n        dfp, idx, target_records_all, delta_pred, split_labels,\n        site_name=site_name, model_name="raw_WRF", feature_mode="raw_WRF"\n    )\n    pred_csv = out_dir / "predictions_raw_WRF_train_val_test.csv"\n    pred_table.to_csv(pred_csv, index=False, encoding="utf-8-sig")\n    metrics_df.to_csv(out_dir / "metrics_raw_WRF_train_val_test.csv", index=False, encoding="utf-8-sig")\n    _write_case_metrics_outputs_now_code2(metrics_df, out_dir, "raw_WRF")\n    with open(out_dir / "raw_WRF_window_policy.json", "w", encoding="utf-8") as f:\n        json.dump({\n            "policy": "target_only_windows",\n            "note": "raw_WRF baseline is evaluated using target validity only; ML feature columns do not filter baseline samples.",\n            "window_target_requirement_mode": WINDOW_TARGET_REQUIRE_MODE,\n            "n_windows": int(len(idx)),\n            "n_train": int(len(train_i)),\n            "n_val": int(len(val_i)),\n            "n_test": int(len(test_i)),\n        }, f, ensure_ascii=False, indent=2)\n    try:\n        plot_profile_prediction_diagnostics(pred_csv, out_dir, "raw_WRF")\n        export_profile_physical_diagnostics(pred_csv, out_dir, "raw_WRF")\n    except Exception as e:\n        print(f"[raw_WRF diagnostics] skipped: {e}")\n    return metrics_df\n\n\n# ---- Profile diagnostics patch ----\ndef _regex_heights_from_prediction_cols(df: pd.DataFrame, prefix: str) -> List[int]:\n    hs = set()\n    pat = re.compile(rf"^{re.escape(prefix)}(\\d+)$")\n    for c in df.columns:\n        m = pat.match(str(c))\n        if m:\n            hs.add(int(m.group(1)))\n    return sorted(hs)\n\n\ndef _series_metrics_row(split: str, diagnostic: str, obs, pred, base=None, circular: bool = False) -> Dict[str, object]:\n    met = direction_metrics(obs, pred, base) if circular else standard_metrics(obs, pred, base)\n    row = {"split": split, "diagnostic": diagnostic}\n    row.update(met)\n    return row\n\n\ndef _power_law_alpha(ws_low, ws_high, z_low: float, z_high: float):\n    ws_low = np.asarray(ws_low, dtype=float)\n    ws_high = np.asarray(ws_high, dtype=float)\n    out = np.full_like(ws_low, np.nan, dtype=float)\n    m = np.isfinite(ws_low) & np.isfinite(ws_high) & (ws_low > 0.05) & (ws_high > 0.05) & (z_high > z_low) & (z_low > 0)\n    out[m] = np.log(ws_high[m] / ws_low[m]) / np.log(float(z_high) / float(z_low))\n    return out\n\n\ndef _linear_gradient(low, high, z_low: float, z_high: float):\n    low = np.asarray(low, dtype=float)\n    high = np.asarray(high, dtype=float)\n    return (high - low) / float(z_high - z_low) if z_high > z_low else np.full_like(low, np.nan, dtype=float)\n\n\ndef _profile_rmse_timeseries(df: pd.DataFrame, obs_cols: List[str], pred_cols: List[str], base_cols: List[str]):\n    obs = df[obs_cols].apply(pd.to_numeric, errors="coerce").values.astype(float)\n    pred = df[pred_cols].apply(pd.to_numeric, errors="coerce").values.astype(float)\n    base = df[base_cols].apply(pd.to_numeric, errors="coerce").values.astype(float)\n    mp = np.isfinite(obs) & np.isfinite(pred)\n    mb = np.isfinite(obs) & np.isfinite(base)\n    pred_rmse = np.sqrt(np.divide(np.nansum(np.where(mp, (pred - obs) ** 2, np.nan), axis=1),\n                                  np.maximum(np.sum(mp, axis=1), 1)))\n    base_rmse = np.sqrt(np.divide(np.nansum(np.where(mb, (base - obs) ** 2, np.nan), axis=1),\n                                  np.maximum(np.sum(mb, axis=1), 1)))\n    pred_rmse[np.sum(mp, axis=1) < 1] = np.nan\n    base_rmse[np.sum(mb, axis=1) < 1] = np.nan\n    return pred_rmse, base_rmse\n\n\ndef _mean_profile_plot(dfp: pd.DataFrame, out_dir: Path, split: str, var: str, heights: List[int], case_name: str) -> None:\n    if not heights:\n        return\n    obs_means, wrf_means, pred_means = [], [], []\n    for h in heights:\n        if var == "WS":\n            obs_c, wrf_c, pred_c = f"OBS_WS_direct{h}", f"WRF_WS_direct{h}", f"WS_direct{h}_corr_pred"\n        elif var == "WD":\n            obs_c, wrf_c, pred_c = f"OBS_WD_direct{h}", f"WRF_WD_direct{h}", f"WD_direct{h}_corr_pred"\n        elif var == "T":\n            obs_c, wrf_c, pred_c = f"OBS_T{h}", f"WRF_T{h}", f"T{h}_corr_pred"\n        elif var == "TKE":\n            obs_c, wrf_c, pred_c = f"OBS_TKE{h}", f"WRF_TKE{h}", f"TKE{h}_corr_pred"\n        else:\n            return\n        if not all(c in dfp.columns for c in [obs_c, wrf_c, pred_c]):\n            obs_means.append(np.nan); wrf_means.append(np.nan); pred_means.append(np.nan); continue\n        if var == "WD":\n            obs_means.append(_circular_mean_deg_profile(pd.to_numeric(dfp[obs_c], errors="coerce").values))\n            wrf_means.append(_circular_mean_deg_profile(pd.to_numeric(dfp[wrf_c], errors="coerce").values))\n            pred_means.append(_circular_mean_deg_profile(pd.to_numeric(dfp[pred_c], errors="coerce").values))\n        else:\n            obs_means.append(float(np.nanmean(pd.to_numeric(dfp[obs_c], errors="coerce").values)))\n            wrf_means.append(float(np.nanmean(pd.to_numeric(dfp[wrf_c], errors="coerce").values)))\n            pred_means.append(float(np.nanmean(pd.to_numeric(dfp[pred_c], errors="coerce").values)))\n\n    if np.isfinite(obs_means).sum() < 1:\n        return\n    fig, ax = plt.subplots(figsize=(6.2, 7.0))\n    ax.plot(obs_means, heights, marker="o", label="OBS")\n    ax.plot(wrf_means, heights, marker="s", label="WRF")\n    ax.plot(pred_means, heights, marker="^", label="Corrected")\n    ax.set_xlabel(var)\n    ax.set_ylabel("Height (m)")\n    ax.set_title(f"{case_name}: mean {split} {var} profile")\n    ax.grid(True, alpha=0.3)\n    ax.legend()\n    fig.tight_layout()\n    fig.savefig(Path(out_dir) / f"plot_mean_profile_{split}_{safe_name(case_name)}_{var}.png", dpi=300)\n    plt.close(fig)\n\n\ndef export_profile_physical_diagnostics(pred_csv: Path, out_dir: Path, case_name: str) -> None:\n    """Export profile-level diagnostics: shear, veer, gradients, profile RMSE, clipping checks."""\n    pred_csv = Path(pred_csv)\n    out_dir = Path(out_dir)\n    if not pred_csv.exists():\n        return\n    dfp = pd.read_csv(pred_csv)\n    if dfp.empty or "split" not in dfp.columns:\n        return\n\n    ws_h = _regex_heights_from_prediction_cols(dfp, "OBS_WS_direct")\n    wd_h = _regex_heights_from_prediction_cols(dfp, "OBS_WD_direct")\n    t_h = _regex_heights_from_prediction_cols(dfp, "OBS_T")\n    tke_h = _regex_heights_from_prediction_cols(dfp, "OBS_TKE")\n\n    rows = []\n    ts_rows = []\n\n    for split in sorted(dfp["split"].dropna().astype(str).unique()):\n        sub = dfp[dfp["split"].astype(str).eq(split)].copy()\n        if sub.empty:\n            continue\n\n        # WS profile RMSE across all available heights at each time.\n        if ws_h:\n            obs_cols = [f"OBS_WS_direct{h}" for h in ws_h if f"OBS_WS_direct{h}" in sub.columns]\n            wrf_cols = [f"WRF_WS_direct{h}" for h in ws_h if f"WRF_WS_direct{h}" in sub.columns]\n            pred_cols = [f"WS_direct{h}_corr_pred" for h in ws_h if f"WS_direct{h}_corr_pred" in sub.columns]\n            if len(obs_cols) == len(wrf_cols) == len(pred_cols) and obs_cols:\n                pr, br = _profile_rmse_timeseries(sub, obs_cols, pred_cols, wrf_cols)\n                rows.append({"split": split, "diagnostic": "WS_profile_RMSE_time_mean",\n                             "N": int(np.isfinite(pr).sum()),\n                             "WRF_profile_RMSE_mean": float(np.nanmean(br)),\n                             "Corrected_profile_RMSE_mean": float(np.nanmean(pr)),\n                             "Skill_RMSE_pct": float((np.nanmean(br) - np.nanmean(pr)) / np.nanmean(br) * 100.0) if np.nanmean(br) > 1e-12 else np.nan})\n                for time_val, b, p in zip(sub.get(TIME_COL, pd.Series(range(len(sub)))).values, br, pr):\n                    ts_rows.append({"split": split, TIME_COL: time_val, "diagnostic": "WS_profile_RMSE", "WRF": b, "Corrected": p})\n\n        # TKE profile RMSE.\n        if tke_h:\n            obs_cols = [f"OBS_TKE{h}" for h in tke_h if f"OBS_TKE{h}" in sub.columns]\n            wrf_cols = [f"WRF_TKE{h}" for h in tke_h if f"WRF_TKE{h}" in sub.columns]\n            pred_cols = [f"TKE{h}_corr_pred" for h in tke_h if f"TKE{h}_corr_pred" in sub.columns]\n            if len(obs_cols) == len(wrf_cols) == len(pred_cols) and obs_cols:\n                pr, br = _profile_rmse_timeseries(sub, obs_cols, pred_cols, wrf_cols)\n                rows.append({"split": split, "diagnostic": "TKE_profile_RMSE_time_mean",\n                             "N": int(np.isfinite(pr).sum()),\n                             "WRF_profile_RMSE_mean": float(np.nanmean(br)),\n                             "Corrected_profile_RMSE_mean": float(np.nanmean(pr)),\n                             "Skill_RMSE_pct": float((np.nanmean(br) - np.nanmean(pr)) / np.nanmean(br) * 100.0) if np.nanmean(br) > 1e-12 else np.nan})\n\n                # Check how often raw logTKE reconstruction would be negative before clipping.\n                n_preclip, n_total = 0, 0\n                for h in tke_h:\n                    dc = f"delta_logTKE{h}_pred"\n                    bc = f"WRF_TKE{h}"\n                    if dc in sub.columns and bc in sub.columns:\n                        raw = np.expm1(np.log1p(np.clip(pd.to_numeric(sub[bc], errors="coerce").values.astype(float), 0.0, None))\n                                      + pd.to_numeric(sub[dc], errors="coerce").values.astype(float))\n                        n_preclip += int(np.isfinite(raw).sum() and np.sum(raw < 0.0))\n                        n_total += int(np.isfinite(raw).sum())\n                rows.append({"split": split, "diagnostic": "TKE_negative_before_clip_fraction",\n                             "N": n_total, "fraction": float(n_preclip / n_total) if n_total else np.nan})\n\n        # Power-law shear alpha using lowest/highest WS height.\n        if len(ws_h) >= 2:\n            zl, zh = float(min(ws_h)), float(max(ws_h))\n            hl, hh = int(zl), int(zh)\n            needed = [f"OBS_WS_direct{hl}", f"WRF_WS_direct{hl}", f"WS_direct{hl}_corr_pred",\n                      f"OBS_WS_direct{hh}", f"WRF_WS_direct{hh}", f"WS_direct{hh}_corr_pred"]\n            if all(c in sub.columns for c in needed):\n                obs_alpha = _power_law_alpha(sub[f"OBS_WS_direct{hl}"], sub[f"OBS_WS_direct{hh}"], zl, zh)\n                wrf_alpha = _power_law_alpha(sub[f"WRF_WS_direct{hl}"], sub[f"WRF_WS_direct{hh}"], zl, zh)\n                pred_alpha = _power_law_alpha(sub[f"WS_direct{hl}_corr_pred"], sub[f"WS_direct{hh}_corr_pred"], zl, zh)\n                rows.append(_series_metrics_row(split, f"WS_power_law_alpha_{hl}_{hh}m", obs_alpha, pred_alpha, wrf_alpha, circular=False))\n\n        # Wind veer using lowest/highest retained WD height.\n        if len(wd_h) >= 2:\n            zl, zh = min(wd_h), max(wd_h)\n            needed = [f"OBS_WD_direct{zl}", f"WRF_WD_direct{zl}", f"WD_direct{zl}_corr_pred",\n                      f"OBS_WD_direct{zh}", f"WRF_WD_direct{zh}", f"WD_direct{zh}_corr_pred"]\n            if all(c in sub.columns for c in needed):\n                obs_veer = circular_diff_deg(sub[f"OBS_WD_direct{zh}"], sub[f"OBS_WD_direct{zl}"])\n                wrf_veer = circular_diff_deg(sub[f"WRF_WD_direct{zh}"], sub[f"WRF_WD_direct{zl}"])\n                pred_veer = circular_diff_deg(sub[f"WD_direct{zh}_corr_pred"], sub[f"WD_direct{zl}_corr_pred"])\n                rows.append(_series_metrics_row(split, f"WD_veer_{zl}_{zh}m", obs_veer, pred_veer, wrf_veer, circular=False))\n\n        # Temperature vertical gradient using lowest/highest T height.\n        if len(t_h) >= 2:\n            zl, zh = float(min(t_h)), float(max(t_h))\n            hl, hh = int(zl), int(zh)\n            needed = [f"OBS_T{hl}", f"WRF_T{hl}", f"T{hl}_corr_pred",\n                      f"OBS_T{hh}", f"WRF_T{hh}", f"T{hh}_corr_pred"]\n            if all(c in sub.columns for c in needed):\n                obs_grad = _linear_gradient(sub[f"OBS_T{hl}"], sub[f"OBS_T{hh}"], zl, zh)\n                wrf_grad = _linear_gradient(sub[f"WRF_T{hl}"], sub[f"WRF_T{hh}"], zl, zh)\n                pred_grad = _linear_gradient(sub[f"T{hl}_corr_pred"], sub[f"T{hh}_corr_pred"], zl, zh)\n                rows.append(_series_metrics_row(split, f"T_vertical_gradient_{hl}_{hh}m_K_per_m", obs_grad, pred_grad, wrf_grad, circular=False))\n\n        # Mean profile plots.\n        for var, hs in [("WS", ws_h), ("WD", wd_h), ("T", t_h), ("TKE", tke_h)]:\n            try:\n                _mean_profile_plot(sub, out_dir, split, var, hs, case_name)\n            except Exception as e:\n                print(f"[profile plot] {case_name} {split} {var} skipped: {e}")\n\n    if rows:\n        pd.DataFrame(rows).to_csv(out_dir / "profile_physical_diagnostics_summary.csv", index=False, encoding="utf-8-sig")\n    if ts_rows:\n        pd.DataFrame(ts_rows).to_csv(out_dir / "profile_physical_diagnostics_timeseries.csv", index=False, encoding="utf-8-sig")\n\n\n# Wrap trained cases to export profile diagnostics.\n_train_one_feature_mode_before_final_patch2 = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    metrics_df = _train_one_feature_mode_before_final_patch2(\n        df=df,\n        target_records_all=target_records_all,\n        feature_cols=feature_cols,\n        site_name=site_name,\n        model_name=model_name,\n        feature_mode=feature_mode,\n        out_dir=out_dir,\n        network=network,\n        use_pinn_mostmag=use_pinn_mostmag,\n    )\n    try:\n        export_profile_physical_diagnostics(out_dir / "predictions_train_val_test.csv", out_dir, feature_mode)\n    except Exception as e:\n        print(f"[profile diagnostics] {feature_mode} skipped: {e}")\n    return metrics_df\n\n\n# ---- Sample consistency check patch ----\ndef _prediction_csv_for_case_dir(case_dir: Path) -> Optional[Path]:\n    p1 = case_dir / "predictions_train_val_test.csv"\n    p2 = case_dir / "predictions_raw_WRF_train_val_test.csv"\n    if p1.exists():\n        return p1\n    if p2.exists():\n        return p2\n    return None\n\n\ndef export_case_sample_consistency_check(root: Path) -> None:\n    """Check whether C0-C8 use identical timestamps/splits after windowing."""\n    root = Path(root)\n    cases_root = root / "cases"\n    out_dir = ensure_dir(root / "02_cmp")\n    if not cases_root.exists():\n        # root may be tower_height/site_name parent.\n        sites = [p for p in root.iterdir() if p.is_dir() and (p / "cases").exists()] if root.exists() else []\n        for s in sites:\n            export_case_sample_consistency_check(s)\n        return\n\n    rows = []\n    split_sets: Dict[Tuple[str, str], set] = {}\n    all_time_sets: Dict[str, set] = {}\n    for case_dir in sorted([p for p in cases_root.iterdir() if p.is_dir()]):\n        pred = _prediction_csv_for_case_dir(case_dir)\n        if pred is None:\n            continue\n        try:\n            d = pd.read_csv(pred, usecols=lambda c: c in {TIME_COL, "split"})\n        except Exception:\n            d = pd.read_csv(pred)\n        if TIME_COL not in d.columns or "split" not in d.columns:\n            continue\n        d[TIME_COL] = pd.to_datetime(d[TIME_COL], errors="coerce")\n        case = case_dir.name\n        allset = set(d[TIME_COL].dropna().astype(str).values.tolist())\n        all_time_sets[case] = allset\n        for split, g in d.groupby(d["split"].astype(str)):\n            times = set(g[TIME_COL].dropna().astype(str).values.tolist())\n            split_sets[(case, split)] = times\n            rows.append({\n                "case": case,\n                "split": split,\n                "n_rows": int(len(g)),\n                "n_unique_times": int(len(times)),\n                "start_time": str(g[TIME_COL].min()),\n                "end_time": str(g[TIME_COL].max()),\n                "prediction_csv": str(pred),\n            })\n\n    if rows:\n        pd.DataFrame(rows).to_csv(out_dir / "case_sample_windows_by_case_split.csv", index=False, encoding="utf-8-sig")\n\n    # Pairwise overlap ratios.\n    overlap_rows = []\n    cases = sorted(all_time_sets)\n    for i, c1 in enumerate(cases):\n        for c2 in cases[i+1:]:\n            a, b = all_time_sets[c1], all_time_sets[c2]\n            inter = len(a & b)\n            union = len(a | b)\n            overlap_rows.append({\n                "case_1": c1, "case_2": c2,\n                "intersection_n": inter,\n                "union_n": union,\n                "jaccard_all_times": float(inter / union) if union else np.nan,\n                "case1_coverage_by_case2_pct": float(inter / len(a) * 100.0) if a else np.nan,\n                "case2_coverage_by_case1_pct": float(inter / len(b) * 100.0) if b else np.nan,\n            })\n    if overlap_rows:\n        pd.DataFrame(overlap_rows).to_csv(out_dir / "case_sample_pairwise_time_overlap.csv", index=False, encoding="utf-8-sig")\n\n    # Split-specific common time set summary.\n    common_rows = []\n    splits = sorted({sp for _, sp in split_sets.keys()})\n    for sp in splits:\n        items = {case: times for (case, split), times in split_sets.items() if split == sp}\n        if not items:\n            continue\n        common = set.intersection(*items.values()) if len(items) > 1 else next(iter(items.values()))\n        union = set.union(*items.values()) if len(items) > 1 else next(iter(items.values()))\n        common_rows.append({\n            "split": sp,\n            "n_cases": int(len(items)),\n            "common_times_n": int(len(common)),\n            "union_times_n": int(len(union)),\n            "common_over_union_pct": float(len(common) / len(union) * 100.0) if union else np.nan,\n            "note": "If this percentage is far below 100, compare C0-C8 also on common timestamps.",\n        })\n    if common_rows:\n        pd.DataFrame(common_rows).to_csv(out_dir / "case_common_time_summary_by_split.csv", index=False, encoding="utf-8-sig")\n\n\n_train_for_csv_before_final_patch2 = train_for_csv\n\ndef train_for_csv(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = tuple(CODE_CASES),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    result = _train_for_csv_before_final_patch2(\n        train_csv=train_csv,\n        output_root=output_root,\n        network=network,\n        feature_modes=feature_modes,\n        heights_m=heights_m,\n        target_groups=target_groups,\n        date_start=date_start,\n        date_end=date_end,\n    )\n    try:\n        train_csv2 = Path(train_csv)\n        tower_tag = safe_name(train_csv2.parent.name)\n        htag = height_tag_from_list(heights_m)\n        root = Path(output_root) / safe_name(f"{tower_tag}_{htag}")\n        export_case_sample_consistency_check(root)\n    except Exception as e:\n        print(f"[sample consistency] skipped: {e}")\n    return result\n\n\n\n# =============================================================================\n# FINAL PATCH v2: low-wind wind-direction mask\n# =============================================================================\n# Rationale:\n#   Wind direction is not physically robust in calm/near-calm conditions.\n#   EPA regulatory meteorological guidance commonly treats wind speed < 0.5 m/s as calm;\n#   aviation/METAR practice treats <=3 kt (~1.54 m/s) as calm in forecast coding.\n#   For tower/NWP bias-correction, 1.0 m/s is a conservative middle threshold.\nENABLE_WD_LOW_WIND_MASK = bool(globals().get("ENABLE_WD_LOW_WIND_MASK", True))\nWD_LOW_WIND_MASK_THRESHOLD_MPS = float(globals().get("WD_LOW_WIND_MASK_THRESHOLD_MPS", 1.0))\n# "obs" is recommended: observed WD is masked only when observed wind speed is too weak.\n# Other options: "obs_or_wrf", "obs_and_wrf".\nWD_LOW_WIND_MASK_SOURCE = str(globals().get("WD_LOW_WIND_MASK_SOURCE", "obs")).lower()\n\n\n_apply_obs_target_qc_code2_before_wd_low_wind_patch = apply_obs_target_qc_code2\n\ndef _low_wind_mask_for_wd_target(df: pd.DataFrame, h: int) -> Tuple[np.ndarray, str, str]:\n    obs_ws_col = first_existing(df, obs_ws_candidates(int(h)))\n    wrf_ws_col = first_existing(df, wrf_ws_candidates(int(h)))\n    n = len(df)\n\n    obs_low = np.zeros(n, dtype=bool)\n    wrf_low = np.zeros(n, dtype=bool)\n\n    if obs_ws_col is not None:\n        obs_ws = pd.to_numeric(df[obs_ws_col], errors="coerce").values.astype(float)\n        obs_low = np.isfinite(obs_ws) & (obs_ws < WD_LOW_WIND_MASK_THRESHOLD_MPS)\n\n    if wrf_ws_col is not None:\n        wrf_ws = pd.to_numeric(df[wrf_ws_col], errors="coerce").values.astype(float)\n        wrf_low = np.isfinite(wrf_ws) & (wrf_ws < WD_LOW_WIND_MASK_THRESHOLD_MPS)\n\n    if WD_LOW_WIND_MASK_SOURCE == "obs_or_wrf":\n        low = obs_low | wrf_low\n    elif WD_LOW_WIND_MASK_SOURCE == "obs_and_wrf":\n        low = obs_low & wrf_low\n    else:\n        low = obs_low\n\n    return low.astype(bool), obs_ws_col or "", wrf_ws_col or ""\n\n\ndef apply_obs_target_qc_code2(df: pd.DataFrame, records: Sequence[TargetRecord], out_dir: Path, site_name: str) -> pd.DataFrame:\n    """OBS QC plus low-wind WD masking for loss/evaluation consistency."""\n    out = _apply_obs_target_qc_code2_before_wd_low_wind_patch(df, records, out_dir, site_name)\n\n    if not ENABLE_WD_LOW_WIND_MASK:\n        return out\n\n    rows = []\n    for r in records:\n        if r.var != "wd":\n            continue\n        h = int(r.height)\n        low, obs_ws_col, wrf_ws_col = _low_wind_mask_for_wd_target(out, h)\n        n_low = int(np.sum(low))\n        n_before = int(pd.to_numeric(out[r.obs_col], errors="coerce").notna().sum()) if r.obs_col in out.columns else 0\n\n        if n_low > 0:\n            if r.obs_col in out.columns:\n                out.loc[low, r.obs_col] = np.nan\n            if r.target_col in out.columns:\n                out.loc[low, r.target_col] = np.nan\n\n        n_after = int(pd.to_numeric(out[r.obs_col], errors="coerce").notna().sum()) if r.obs_col in out.columns else 0\n        rows.append({\n            "site": site_name,\n            "height_m": h,\n            "variable": "wd",\n            "obs_wd_col": r.obs_col,\n            "target_col": r.target_col,\n            "obs_ws_col_used": obs_ws_col,\n            "wrf_ws_col_used": wrf_ws_col,\n            "low_wind_mask_source": WD_LOW_WIND_MASK_SOURCE,\n            "threshold_mps": WD_LOW_WIND_MASK_THRESHOLD_MPS,\n            "n_wd_before_low_wind_mask": n_before,\n            "n_low_wind_masked_rows": n_low,\n            "n_wd_after_low_wind_mask": n_after,\n            "note": "WD target/OBS are set to NaN for low-wind rows; masked targets are excluded from WD loss and WD metrics.",\n        })\n\n    try:\n        pd.DataFrame(rows).to_csv(Path(out_dir) / "pretraining_wd_low_wind_mask_report.csv", index=False, encoding="utf-8-sig")\n    except Exception as e:\n        print(f"[WD low-wind mask] failed to write report: {e}")\n\n    return out\n\n\n\n# =============================================================================\n# FINAL PATCH v3: metadata correction for final direct-WS/WD loss setup\n# =============================================================================\n_train_one_feature_mode_before_v3_metadata_patch = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    metrics_df = _train_one_feature_mode_before_v3_metadata_patch(\n        df=df,\n        target_records_all=target_records_all,\n        feature_cols=feature_cols,\n        site_name=site_name,\n        model_name=model_name,\n        feature_mode=feature_mode,\n        out_dir=out_dir,\n        network=network,\n        use_pinn_mostmag=use_pinn_mostmag,\n    )\n    # The original core metadata text came from an older U/V-only PINN version.\n    # Update it after training so saved artifacts describe the actual final setup.\n    try:\n        meta_path = Path(out_dir) / "metadata.json"\n        if meta_path.exists():\n            with open(meta_path, "r", encoding="utf-8") as f:\n                meta = json.load(f)\n            meta["script_version"] = "code2_profile_C0C8_WSWD_TKE_T_fixed_v3"\n            meta["final_target_structure"] = "direct WS/WD + T + logTKE, with 4/50 m WD-related targets excluded"\n            meta["supervised_loss_note"] = (\n                "Group-balanced multi-task supervised loss. WD targets use cosine angular loss "\n                "when USE_WD_COSINE_ANGULAR_LOSS=True; other targets use Huber loss in scaled residual space."\n            )\n            meta["loss_aggregation_mode"] = LOSS_AGGREGATION_MODE\n            meta["task_group_weights"] = TASK_GROUP_WEIGHTS\n            meta["wd_low_wind_mask"] = {\n                "enabled": ENABLE_WD_LOW_WIND_MASK,\n                "threshold_mps": WD_LOW_WIND_MASK_THRESHOLD_MPS,\n                "source": WD_LOW_WIND_MASK_SOURCE,\n                "meaning": "WD target/OBS are masked when observed wind speed is below the threshold."\n            }\n            meta["feature_selection_note"] = (\n                "corrFDR cases use hybrid corrFDR screening with optional redundancy pruning "\n                "when USE_HYBRID_CORRFDR_SELECTION=True."\n            )\n            meta["pinn_note"] = (\n                "MOST loss, if enabled, constrains wind-speed magnitude. It uses U/V reconstruction "\n                "where U/V targets exist and direct WS residuals where direct WS targets exist. "\n                "T and TKE are supervised by data loss only."\n            )\n            with open(meta_path, "w", encoding="utf-8") as f:\n                json.dump(meta, f, ensure_ascii=False, indent=2)\n    except Exception as e:\n        print(f"[metadata v3] update skipped: {e}")\n    return metrics_df\n\n\n\n# =============================================================================\n# FINAL PATCH v4: force-kept MOST corrFDR diagnostics + raw-normalized PINN score\n# =============================================================================\n# Purpose\n# -------\n# This patch keeps the original C0-C8 design and adds diagnostic C4b/C8b cases:\n#   C4b = MOSTinput_corrFDR_forceMOST\n#   C8b = MOSTinput_PINN_corrFDR_forceMOST\n# It also changes PINN lambda selection to a raw-WRF-normalized validation score\n# and writes PINN diagnostic summaries for every PINN case.\n\nFORCE_KEEP_MOST_FEATURES_IN_MOST_CORRFDR = bool(globals().get("FORCE_KEEP_MOST_FEATURES_IN_MOST_CORRFDR", True))\nPINN_LAMBDA_SELECTION_SCORE_MODE = str(globals().get("PINN_LAMBDA_SELECTION_SCORE_MODE", "raw_normalized")).lower()\n# Keep the old candidate list; this patch only changes how the best lambda is scored.\nPINN_RAWNORM_FALLBACK_PENALTY = float(globals().get("PINN_RAWNORM_FALLBACK_PENALTY", 999.0))\n\n\ndef _is_most_input_feature_code2(c: str) -> bool:\n    """Return True for MOST-derived predictors that should be force-kept in C4b/C8b."""\n    s = str(c)\n    return (\n        "U_MO" in s\n        or "MO_minus_WRF" in s\n        or "MOST_WS" in s\n        or "auto_from_MO_minus_WRF" in s\n    )\n\n\ndef _case_mode_v4(case: str):\n    """Return selection_mode, feature_mode_name, use_pinn, use_most_input, is_raw, force_most."""\n    c = str(case).strip().lower()\n    c = c.replace("-", "_")\n    if c in {"raw", "raw_wrf", "wrf", "c0"}:\n        return "all", "raw_WRF", False, False, True, False\n\n    force_most = ("forcemost" in c) or ("force_most" in c) or c in {"c4b", "c8b"}\n    use_pinn = ("pinn" in c) or ("mostmag" in c) or c in {"c5", "c6", "c7", "c8", "c8b"}\n    use_most_input = ("mostinput" in c) or ("most_input" in c) or c in {"c3", "c4", "c4b", "c7", "c8", "c8b"}\n\n    if ("corrfdr" in c) or ("corr" in c) or c in {"c2", "c4", "c4b", "c6", "c8", "c8b"}:\n        selection = "corrFDR"\n    elif ("all" in c) or c in {"nomost", "mostinput", "pinn_mostmag", "c1", "c3", "c5", "c7"}:\n        selection = "all"\n    else:\n        raise ValueError(f"Unknown Code2 case: {case}")\n\n    if use_most_input and use_pinn:\n        if selection == "corrFDR":\n            feature_name = "MOSTinput_PINN_corrFDR_forceMOST" if force_most else "MOSTinput_PINN_corrFDR"\n        else:\n            feature_name = "MOSTinput_PINN_all"\n    elif use_most_input:\n        if selection == "corrFDR":\n            feature_name = "MOSTinput_corrFDR_forceMOST" if force_most else "MOSTinput_corrFDR"\n        else:\n            feature_name = "MOSTinput_all"\n    elif use_pinn:\n        feature_name = "PINN_corrFDR" if selection == "corrFDR" else "PINN_all"\n    else:\n        feature_name = "noMOST_corrFDR" if selection == "corrFDR" else "noMOST_all"\n\n    return selection, feature_name, use_pinn, use_most_input, False, bool(force_most)\n\n\ndef _select_corr_fdr_features_code2_v4(\n    df: pd.DataFrame,\n    train_row_idx: np.ndarray,\n    candidate_features: Sequence[str],\n    target_records: Sequence[TargetRecord],\n    force_keep_most: bool = False,\n) -> Tuple[List[str], pd.DataFrame]:\n    """Train-only corrFDR selection with optional MOST-feature force-keep for C4b/C8b."""\n    selected, report = select_corr_fdr_features(df, train_row_idx, candidate_features, target_records)\n    report = report.copy()\n    candidate_features = list(candidate_features)\n\n    forced_most = []\n    if force_keep_most and FORCE_KEEP_MOST_FEATURES_IN_MOST_CORRFDR:\n        forced_most = [c for c in candidate_features if _is_most_input_feature_code2(c)]\n\n    selected_final = []\n    seen = set()\n    for c in list(selected) + forced_most:\n        if c in candidate_features and c not in seen:\n            selected_final.append(c)\n            seen.add(c)\n\n    if not selected_final:\n        # This should rarely happen because the base selector has its own fallback.\n        selected_final = list(selected) if selected else list(candidate_features)\n\n    report["force_keep_MOST_enabled_v4"] = bool(force_keep_most and FORCE_KEEP_MOST_FEATURES_IN_MOST_CORRFDR)\n    report["force_keep_MOST_feature_v4"] = report["feature"].astype(str).isin(forced_most) if "feature" in report.columns else False\n    report["selected_feature_final_v4"] = report["feature"].astype(str).isin(selected_final) if "feature" in report.columns else False\n    report["v4_note"] = (\n        "MOST predictors were force-kept after train-only corrFDR/hybrid selection. "\n        "This diagnostic branch is intended to test MOSTinput under selected features."\n        if force_keep_most else\n        "Standard corrFDR/hybrid selection without MOST force-keep."\n    )\n    return selected_final, report\n\n\ndef _row_primary_error_ratio_to_raw(row: pd.Series) -> float:\n    """Return model/raw ratio from Skill_RMSE_pct when available.\n\n    Skill_RMSE_pct = (raw_RMSE - model_RMSE) / raw_RMSE * 100, so\n    ratio = model_RMSE / raw_RMSE = 1 - Skill_RMSE_pct/100.\n    This is dimensionless and makes WS/WD/T/TKE comparable for lambda selection.\n    """\n    skill = pd.to_numeric(pd.Series([row.get("Skill_RMSE_pct", np.nan)]), errors="coerce").iloc[0]\n    if np.isfinite(skill):\n        return float(max(0.0, 1.0 - float(skill) / 100.0))\n    return np.nan\n\n\ndef validation_selection_score(metrics_df: pd.DataFrame) -> float:\n    """Raw-WRF-normalized validation score for selecting PINN lambda.\n\n    Lower is better. A value below 1 for a component means the model improves over\n    raw WRF for that variable on the validation split. This avoids mixing units\n    such as m/s, degrees, K, and m2/s2 in one unnormalized score.\n    """\n    if metrics_df is None or metrics_df.empty:\n        return np.inf\n    sub = metrics_df[(metrics_df["split"].astype(str).str.lower() == "val") & (metrics_df["height_m"].astype(str) == "ALL_PROFILE")]\n    if sub.empty:\n        return np.inf\n\n    if PINN_LAMBDA_SELECTION_SCORE_MODE not in {"raw_normalized", "rawnorm", "ratio"}:\n        # Backward-compatible absolute-error mode.\n        score = 0.0; wsum = 0.0\n        for _, row in sub.iterrows():\n            var = str(row.get("variable", ""))\n            if var in {"WS_from_uv", "WS_direct", "T", "TKE"}:\n                err = pd.to_numeric(pd.Series([row.get("RMSE", np.nan)]), errors="coerce").iloc[0]\n                key = {"WS_from_uv":"WS_from_uv_RMSE", "WS_direct":"WS_direct_RMSE", "T":"T_RMSE", "TKE":"TKE_RMSE"}.get(var)\n            elif var in {"WD_from_uv", "WD_direct"}:\n                err = pd.to_numeric(pd.Series([row.get("MAE", np.nan)]), errors="coerce").iloc[0]\n                key = {"WD_from_uv":"WD_from_uv_MAE", "WD_direct":"WD_direct_MAE"}.get(var)\n            else:\n                continue\n            w = float(PINN_SCORE_WEIGHTS.get(key, 0.0)) if key else 0.0\n            if w > 0 and np.isfinite(err):\n                score += w * float(err); wsum += w\n        return score / wsum if wsum > 0 else np.inf\n\n    var_to_key = {\n        "WS_direct": "WS_direct_RMSE",\n        "WD_direct": "WD_direct_MAE",\n        "WS_from_uv": "WS_from_uv_RMSE",\n        "WD_from_uv": "WD_from_uv_MAE",\n        "T": "T_RMSE",\n        "TKE": "TKE_RMSE",\n    }\n    score = 0.0\n    wsum = 0.0\n    for _, row in sub.iterrows():\n        var = str(row.get("variable", ""))\n        key = var_to_key.get(var)\n        if key is None:\n            continue\n        w = float(PINN_SCORE_WEIGHTS.get(key, 0.0))\n        if w <= 0:\n            continue\n        ratio = _row_primary_error_ratio_to_raw(row)\n        if not np.isfinite(ratio):\n            ratio = PINN_RAWNORM_FALLBACK_PENALTY\n        score += w * float(ratio)\n        wsum += w\n    return score / wsum if wsum > 0 else np.inf\n\n\ndef _export_pinn_diagnostics_v4(out_dir: Path, feature_mode: str, metrics_df: Optional[pd.DataFrame]) -> None:\n    """Write compact PINN diagnostics for one trained PINN case."""\n    out_dir = Path(out_dir)\n    rows = []\n    meta = {}\n    meta_path = out_dir / "metadata.json"\n    if meta_path.exists():\n        try:\n            meta = json.loads(meta_path.read_text(encoding="utf-8"))\n        except Exception:\n            meta = {}\n    best_lambda = meta.get("best_lambda_MO", meta.get("best_lambda", np.nan))\n    selection_score = meta.get("selection_score", np.nan)\n\n    sweep_path = out_dir / "pinn_lambda_sweep.csv"\n    if sweep_path.exists():\n        try:\n            sw = pd.read_csv(sweep_path)\n            if not sw.empty:\n                sw2 = sw.copy()\n                score_col = "selection_score" if "selection_score" in sw2.columns else None\n                if score_col:\n                    sw2[score_col] = pd.to_numeric(sw2[score_col], errors="coerce")\n                    best_row = sw2.sort_values(score_col, na_position="last").head(1)\n                    if not best_row.empty:\n                        rows.append({\n                            "diagnostic_type": "lambda_selection",\n                            "case": feature_mode,\n                            "best_lambda_MO_metadata": best_lambda,\n                            "best_lambda_MO_from_sweep": best_row.iloc[0].get("lambda_MO", np.nan),\n                            "selection_score": best_row.iloc[0].get(score_col, np.nan),\n                            "selection_score_mode": PINN_LAMBDA_SELECTION_SCORE_MODE,\n                            "n_lambda_candidates": int(len(sw2)),\n                            "lambda_zero_selected": bool(float(best_row.iloc[0].get("lambda_MO", np.nan)) == 0.0) if np.isfinite(pd.to_numeric(pd.Series([best_row.iloc[0].get("lambda_MO", np.nan)]), errors="coerce").iloc[0]) else np.nan,\n                        })\n        except Exception as e:\n            rows.append({"diagnostic_type": "lambda_selection", "case": feature_mode, "read_error": repr(e)})\n\n    gate_path = out_dir / "pinn_gate_summary_by_height.csv"\n    if gate_path.exists():\n        try:\n            gd = pd.read_csv(gate_path)\n            if not gd.empty:\n                for _, r in gd.iterrows():\n                    rows.append({\n                        "diagnostic_type": "gate_by_height",\n                        "case": feature_mode,\n                        "height_m": r.get("height_m", np.nan),\n                        "umo_col": r.get("umo_col", ""),\n                        "mo_minus_col": r.get("mo_minus_col", ""),\n                        "finite_MOST_ratio_all": r.get("finite_MOST_ratio_all", np.nan),\n                        "quantile_gate_mean_before_height_pblh": r.get("quantile_gate_mean_before_height_pblh", np.nan),\n                        "height_weight": r.get("height_weight", np.nan),\n                        "pblh_gate_mean": r.get("pblh_gate_mean", np.nan),\n                        "final_gate_mean": r.get("final_gate_mean", np.nan),\n                        "final_gate_nonzero_ratio": r.get("final_gate_nonzero_ratio", np.nan),\n                    })\n        except Exception as e:\n            rows.append({"diagnostic_type": "gate_by_height", "case": feature_mode, "read_error": repr(e)})\n\n    if metrics_df is not None and not metrics_df.empty:\n        try:\n            sub = metrics_df[(metrics_df["split"].astype(str).str.lower() == "test") & (metrics_df["height_m"].astype(str) == "ALL_PROFILE")]\n            for _, r in sub.iterrows():\n                rows.append({\n                    "diagnostic_type": "test_ALL_PROFILE_metric",\n                    "case": feature_mode,\n                    "variable": r.get("variable", ""),\n                    "RMSE": r.get("RMSE", np.nan),\n                    "MAE": r.get("MAE", np.nan),\n                    "Skill_RMSE_pct": r.get("Skill_RMSE_pct", np.nan),\n                })\n        except Exception:\n            pass\n\n    if rows:\n        dfdiag = pd.DataFrame(rows)\n        dfdiag.to_csv(out_dir / "pinn_diagnostics_summary_v4.csv", index=False, encoding="utf-8-sig")\n        try:\n            (out_dir / "pinn_diagnostics_summary_v4.txt").write_text(dfdiag.to_string(index=False), encoding="utf-8")\n        except Exception:\n            pass\n\n\n_train_one_feature_mode_before_v4_diagnostics = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    metrics_df = _train_one_feature_mode_before_v4_diagnostics(\n        df=df,\n        target_records_all=target_records_all,\n        feature_cols=feature_cols,\n        site_name=site_name,\n        model_name=model_name,\n        feature_mode=feature_mode,\n        out_dir=out_dir,\n        network=network,\n        use_pinn_mostmag=use_pinn_mostmag,\n    )\n    try:\n        # Update metadata with v4 settings.\n        meta_path = Path(out_dir) / "metadata.json"\n        if meta_path.exists():\n            meta = json.loads(meta_path.read_text(encoding="utf-8"))\n            meta["script_version"] = "code2_profile_C0C8_WSWD_TKE_T_fixed_v4_forceMOST_rawnormPINN"\n            meta["pinn_lambda_selection_score_mode"] = PINN_LAMBDA_SELECTION_SCORE_MODE\n            meta["pinn_score_weights"] = dict(PINN_SCORE_WEIGHTS)\n            meta["force_keep_MOST_features_in_MOST_corrFDR"] = bool(FORCE_KEEP_MOST_FEATURES_IN_MOST_CORRFDR)\n            meta_path.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")\n        if use_pinn_mostmag:\n            _export_pinn_diagnostics_v4(Path(out_dir), feature_mode, metrics_df)\n    except Exception as e:\n        print(f"[PINN diagnostics v4] skipped for {feature_mode}: {e}")\n    return metrics_df\n\n\ndef _code2_v4_write_selected_config(wrapped_output_root: Path, train_csv: Path, heights_m: Optional[Sequence[int]]) -> None:\n    info_path = Path(wrapped_output_root) / "cfg.json"\n    with open(info_path, "w", encoding="utf-8") as f:\n        json.dump({\n            "input_csv": str(train_csv),\n            "tower_folder": train_csv.parent.name,\n            "code_train_site_contains": globals().get("CODE_TRAIN_SITE_CONTAINS", None),\n            "selected_heights_m": None if heights_m is None else [int(h) for h in heights_m],\n            "auto_filter_to_valid_obs_period": bool(globals().get("AUTO_FILTER_TO_VALID_OBS_PERIOD", True)),\n            "valid_obs_period_height_mode": str(globals().get("VALID_OBS_PERIOD_HEIGHT_MODE", "any")),\n            "valid_obs_period_buffer_hours": float(globals().get("VALID_OBS_PERIOD_BUFFER_HOURS", 0.0)),\n            "apply_obs_valid_flag_to_targets": bool(globals().get("APPLY_OBS_VALID_FLAG_TO_TARGETS", True)),\n            "time_feature_mode": "hour_only",\n            "excluded_time_features": ["month_sin", "month_cos"],\n            "window_target_requirement_mode": WINDOW_TARGET_REQUIRE_MODE,\n            "v4_changes": [\n                "C4b/C8b force-keep MOST input features in corrFDR branch",\n                "PINN lambda selection uses raw-WRF-normalized validation score",\n                "PINN diagnostics are exported for every PINN case",\n            ],\n        }, f, ensure_ascii=False, indent=2)\n\n\ndef _train_for_csv_code2_v4_core(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = tuple(CODE_CASES),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    """Code2 v4 core with C4b/C8b forceMOST and raw-normalized PINN scoring."""\n    site_name = safe_name(Path(train_csv).stem.replace("ML_ready_ref10_", ""))\n    base_out = ensure_dir(Path(output_root) / site_name)\n    precheck_dir = ensure_dir(base_out / "00_pre")\n    cases_root = ensure_dir(base_out / "cases")\n    comparison_dir = ensure_dir(base_out / "02_cmp")\n\n    print("=" * 100)\n    print(f"Training site/tower: {site_name}")\n    print(f"Input CSV: {train_csv}")\n    print(f"Output root: {base_out}")\n    print(f"Network: {network_label(network)}")\n    print(f"Code2 v4 cases: {list(feature_modes)}")\n    print(f"PINN lambda score mode: {PINN_LAMBDA_SELECTION_SCORE_MODE}")\n\n    df = load_ml_ready(Path(train_csv), date_start=date_start, date_end=date_end)\n    df, target_records_all, used_heights = detect_targets_and_create_columns(df, heights_m=heights_m, target_groups=target_groups)\n    df = apply_obs_target_qc_code2(df, target_records_all, precheck_dir, site_name)\n    df = add_auto_most_columns_for_inputs(df, used_heights)\n\n    no_most_features = build_feature_set_with_most(df, used_heights, include_most=False)\n    most_input_features = build_feature_set_with_most(df, used_heights, include_most=True)\n    if not no_most_features:\n        raise ValueError("No WRF input features found.")\n\n    most_features_only = [c for c in most_input_features if c not in no_most_features and _is_most_input_feature_code2(c)]\n\n    pd.DataFrame([asdict(r) for r in target_records_all]).to_csv(precheck_dir / "detected_all_targets.csv", index=False, encoding="utf-8-sig")\n    pd.Series(no_most_features, name="noMOST_candidate_feature").to_csv(precheck_dir / "noMOST_candidate_features.csv", index=False, encoding="utf-8-sig")\n    pd.Series(most_input_features, name="MOSTinput_candidate_feature").to_csv(precheck_dir / "MOSTinput_candidate_features.csv", index=False, encoding="utf-8-sig")\n    pd.Series(most_features_only, name="MOST_only_feature").to_csv(precheck_dir / "MOSTinput_extra_MOST_features.csv", index=False, encoding="utf-8-sig")\n    pd.DataFrame({\n        "height_m": used_heights,\n        "has_MOST_input_feature": [any(c in df.columns for c in most_input_candidates_for_height(h)) or f"U_MO{h}_auto_from_MO_minus_WRF (m/s)" in df.columns for h in used_heights],\n    }).to_csv(precheck_dir / "MOSTinput_availability_by_height.csv", index=False, encoding="utf-8-sig")\n\n    export_pretraining_input_audit_code2(df, target_records_all, list(dict.fromkeys(no_most_features + most_input_features)), used_heights, precheck_dir, site_name)\n    plot_pretraining_timeseries_code2(df, target_records_all, list(dict.fromkeys(no_most_features + most_input_features)), precheck_dir, site_name)\n    export_training_window_validity_audit_code2(df, target_records_all, list(dict.fromkeys(no_most_features + most_input_features)), precheck_dir, site_name)\n\n    target_cols_all = [r.target_col for r in target_records_all]\n    extra_cols = []\n    for r in target_records_all:\n        extra_cols.extend([r.obs_col, r.wrf_col, r.target_col])\n\n    dfp_nomost = prepare_features(df, no_most_features, target_cols_all, extra_cols)\n    X0, y0, mask0, idx0 = make_windows_masked(dfp_nomost, no_most_features, target_cols_all, require_any_target=True)\n    if len(X0) < 30:\n        raise ValueError(f"Too few valid windows for noMOST split ({len(X0)}).")\n    train_i0, _, _ = split_chronological(len(X0))\n    train_row_idx_nomost = idx0[train_i0]\n\n    dfp_most = prepare_features(df, most_input_features, target_cols_all, extra_cols)\n    X1, y1, mask1, idx1 = make_windows_masked(dfp_most, most_input_features, target_cols_all, require_any_target=True)\n    if len(X1) < 30:\n        print("[warning] MOSTinput feature pool produced too few windows; MOSTinput cases may be skipped.")\n        train_row_idx_most = train_row_idx_nomost\n    else:\n        train_i1, _, _ = split_chronological(len(X1))\n        train_row_idx_most = idx1[train_i1]\n\n    selected_nomost_cache = None\n    selected_most_cache = None\n    selected_most_force_cache = None\n    summaries = []\n    case_feature_rows = []\n\n    for case in feature_modes:\n        selection_mode, feature_mode_name, use_pinn, use_most_input, is_raw, force_most = _case_mode_v4(case)\n        if use_most_input and len(most_input_features) <= len(no_most_features):\n            msg = f"[{site_name}] MOSTinput case \'{feature_mode_name}\' requested, but no additional MOST input features were found."\n            if bool(globals().get("CODE_REQUIRE_MOSTINPUT_CASES", False)):\n                raise RuntimeError(msg + " Formal C0-C8 requires complete MOSTinput cases; check U_MO/MO_minus_WRF columns.")\n            print(msg + " Skip this case.")\n            continue\n\n        candidate_pool = most_input_features if use_most_input else no_most_features\n        dfp_pool = dfp_most if use_most_input else dfp_nomost\n        train_row_idx = train_row_idx_most if use_most_input else train_row_idx_nomost\n\n        report = pd.DataFrame()\n        if selection_mode == "all":\n            feature_cols = list(candidate_pool)\n        elif selection_mode == "corrFDR":\n            if use_most_input and force_most:\n                if selected_most_force_cache is None:\n                    selected_most_force_cache, report = _select_corr_fdr_features_code2_v4(\n                        dfp_pool, train_row_idx, candidate_pool, target_records_all, force_keep_most=True\n                    )\n                    report.to_csv(precheck_dir / "corrFDR_feature_screening_report_MOSTinput_forceMOST.csv", index=False, encoding="utf-8-sig")\n                    pd.Series(selected_most_force_cache, name="selected_feature").to_csv(precheck_dir / "corrFDR_selected_features_MOSTinput_forceMOST.csv", index=False, encoding="utf-8-sig")\n                feature_cols = selected_most_force_cache\n            elif use_most_input:\n                if selected_most_cache is None:\n                    selected_most_cache, report = _select_corr_fdr_features_code2_v4(\n                        dfp_pool, train_row_idx, candidate_pool, target_records_all, force_keep_most=False\n                    )\n                    report.to_csv(precheck_dir / "corrFDR_feature_screening_report_MOSTinput.csv", index=False, encoding="utf-8-sig")\n                    pd.Series(selected_most_cache, name="selected_feature").to_csv(precheck_dir / "corrFDR_selected_features_MOSTinput.csv", index=False, encoding="utf-8-sig")\n                feature_cols = selected_most_cache\n            else:\n                if selected_nomost_cache is None:\n                    selected_nomost_cache, report = _select_corr_fdr_features_code2_v4(\n                        dfp_pool, train_row_idx, candidate_pool, target_records_all, force_keep_most=False\n                    )\n                    report.to_csv(precheck_dir / "corrFDR_feature_screening_report_noMOST.csv", index=False, encoding="utf-8-sig")\n                    pd.Series(selected_nomost_cache, name="selected_feature").to_csv(precheck_dir / "corrFDR_selected_features_noMOST.csv", index=False, encoding="utf-8-sig")\n                feature_cols = selected_nomost_cache\n        else:\n            raise ValueError(selection_mode)\n\n        out_dir = ensure_dir(cases_root / f"{network_label(network)}_{feature_mode_name}")\n        print("-" * 100)\n        print(f"Running case: {feature_mode_name}")\n        print(f"Requested case: {case}")\n        print(f"Use MOST input features: {use_most_input}")\n        print(f"Force-keep MOST features in corrFDR: {force_most}")\n        print(f"Use MOSTmag PINN: {use_pinn}")\n        print(f"Number of features: {len(feature_cols)}")\n        print(f"Number of MOST-only input features used: {sum(_is_most_input_feature_code2(c) for c in feature_cols)}")\n\n        # Per-case traceability of feature strategy.\n        pd.DataFrame({"feature": list(feature_cols)}).to_csv(out_dir / "features_used_v4.csv", index=False, encoding="utf-8-sig")\n        with open(out_dir / "case_v4_config.json", "w", encoding="utf-8") as f:\n            json.dump({\n                "requested_case": str(case),\n                "feature_mode_name": feature_mode_name,\n                "selection_mode": selection_mode,\n                "use_most_input": bool(use_most_input),\n                "force_keep_most": bool(force_most),\n                "use_pinn_mostmag": bool(use_pinn),\n                "n_candidate_features": int(len(candidate_pool)),\n                "n_features_used": int(len(feature_cols)),\n                "n_most_features_used": int(sum(_is_most_input_feature_code2(c) for c in feature_cols)),\n                "most_features_used": [c for c in feature_cols if _is_most_input_feature_code2(c)],\n                "pinn_lambda_selection_score_mode": PINN_LAMBDA_SELECTION_SCORE_MODE,\n                "pinn_score_weights": dict(PINN_SCORE_WEIGHTS),\n            }, f, ensure_ascii=False, indent=2)\n\n        if is_raw:\n            metrics_df = run_raw_wrf_profile_case(df, target_records_all, feature_cols, site_name, out_dir)\n        else:\n            metrics_df = train_one_feature_mode(\n                df=df,\n                target_records_all=target_records_all,\n                feature_cols=feature_cols,\n                site_name=site_name,\n                model_name=network_label(network),\n                feature_mode=feature_mode_name,\n                out_dir=out_dir,\n                network=network,\n                use_pinn_mostmag=use_pinn,\n            )\n        metrics_df["requested_case"] = case\n        metrics_df["uses_MOST_input_features"] = bool(use_most_input)\n        metrics_df["force_keep_MOST_features"] = bool(force_most)\n        metrics_df["uses_PINN_MOSTmag"] = bool(use_pinn)\n        summaries.append(metrics_df)\n        case_feature_rows.append({\n            "case": feature_mode_name,\n            "requested_case": str(case),\n            "selection_mode": selection_mode,\n            "use_most_input": bool(use_most_input),\n            "force_keep_most": bool(force_most),\n            "use_pinn": bool(use_pinn),\n            "candidate_count": int(len(candidate_pool)),\n            "used_count": int(len(feature_cols)),\n            "most_feature_used_count": int(sum(_is_most_input_feature_code2(c) for c in feature_cols)),\n            "most_features_used": "; ".join([c for c in feature_cols if _is_most_input_feature_code2(c)]),\n        })\n\n    all_metrics = pd.concat(summaries, ignore_index=True) if summaries else pd.DataFrame()\n    all_metrics.to_csv(comparison_dir / "ALL_cases_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    all_metrics.to_csv(base_out / "ALL_cases_metrics_train_val_test.csv", index=False, encoding="utf-8-sig")\n    if case_feature_rows:\n        pd.DataFrame(case_feature_rows).to_csv(comparison_dir / "case_feature_strategy_summary_v4.csv", index=False, encoding="utf-8-sig")\n\n    comp = all_metrics[(all_metrics["split"].isin(["test", "val"])) & (all_metrics["height_m"].astype(str) == "ALL_PROFILE")].copy() if not all_metrics.empty else pd.DataFrame()\n    if not comp.empty:\n        comp["primary_error"] = np.where(\n            comp["variable"].astype(str).str.contains("WD", case=False, na=False),\n            pd.to_numeric(comp.get("MAE", np.nan), errors="coerce"),\n            pd.to_numeric(comp.get("RMSE", np.nan), errors="coerce"),\n        )\n        comp.sort_values(["split", "variable", "primary_error"], na_position="last").to_csv(\n            comparison_dir / "case_comparison_ALL_PROFILE_val_test.csv", index=False, encoding="utf-8-sig"\n        )\n    try:\n        plot_profile_ablation_summary(all_metrics, comparison_dir)\n    except Exception as e:\n        print(f"[v4] plot_profile_ablation_summary skipped: {e}")\n    return all_metrics\n\n\ndef train_for_csv(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = tuple(CODE_CASES),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    """Final v4 wrapper: tower/height subfolder + v4 core + post diagnostics."""\n    train_csv = Path(train_csv)\n    tower_tag = safe_name(train_csv.parent.name)\n    htag = height_tag_from_list(heights_m)\n    wrapped_output_root = ensure_dir(Path(output_root) / safe_name(f"{tower_tag}_{htag}"))\n    _code2_v4_write_selected_config(wrapped_output_root, train_csv, heights_m)\n\n    try:\n        df_report = load_ml_ready(train_csv, date_start=date_start, date_end=date_end)\n        report_heights = heights_m if heights_m is not None else auto_detect_heights(df_report)\n        site_name_report = safe_name(train_csv.stem.replace("ML_ready_ref10_", ""))\n        report_dir = ensure_dir(wrapped_output_root / site_name_report / "00_pre")\n        build_target_detection_report(df_report, report_heights).to_csv(report_dir / "target_detection_report.csv", index=False, encoding="utf-8-sig")\n    except Exception as e:\n        print(f"[target detection report v4] skipped: {e}")\n\n    result = _train_for_csv_code2_v4_core(\n        train_csv=train_csv,\n        output_root=wrapped_output_root,\n        network=network,\n        feature_modes=feature_modes,\n        heights_m=heights_m,\n        target_groups=target_groups,\n        date_start=date_start,\n        date_end=date_end,\n    )\n    try:\n        root = wrapped_output_root\n        plot_corrfdr_feature_screening_outputs(root)\n        plot_code2_case_timeseries_comparison(root)\n        export_effective_train_val_test_ranges_code2(root)\n        export_case_metrics_and_feature_audit_code2(root)\n        write_case_metrics_output_check_code2(root)\n        export_case_sample_consistency_check(root)\n    except Exception as e:\n        print(f"[postplot v4] Code2 final comparison plots skipped: {e}")\n    return result\n\n\n# =============================================================================\n# FINAL PATCH v5: independent profile-constraint diagnostic cases\n# =============================================================================\n# Purpose\n# -------\n# v4 already adds C4b/C8b and raw-normalized PINN lambda selection.\n# This v5 patch adds independent profile-constraint cases:\n#   C9  = ProfileConstraint_corrFDR\n#   C10 = MOSTinput_ProfileConstraint_corrFDR_forceMOST\n# These cases use a profile smoothness loss only:\n#   L = L_data + lambda_profile * L_profile_smooth\n# They do NOT apply the MOST magnitude target loss (lambda_MO = 0).\n# C10 uses MOST-derived predictors as inputs and force-keeps them under corrFDR.\n\nPROFILE_CONSTRAINT_LAMBDA = float(globals().get("PROFILE_CONSTRAINT_LAMBDA", 0.001))\nPROFILE_CONSTRAINT_LAMBDA_CANDIDATES = list(globals().get("PROFILE_CONSTRAINT_LAMBDA_CANDIDATES", [PROFILE_CONSTRAINT_LAMBDA]))\n\n\ndef _is_profile_constraint_case_code2(case_name: str) -> bool:\n    s = str(case_name).lower().replace("-", "_")\n    return (\n        "profileconstraint" in s\n        or "profile_constraint" in s\n        or "profilesmooth" in s\n        or "profile_smooth" in s\n        or s in {"c9", "c10"}\n    )\n\n\n# Override the v4/v3 MOSTmag PINN loss so lambda_mo=0 and lambda_smooth>0\n# still gives a valid profile-smoothness-only loss. The earlier version returned\n# supervised loss immediately when lambda_mo <= 0, which prevented C9/C10.\ndef pinn_mostmag_loss(n_outputs: int, y_mean: np.ndarray, y_scale: np.ndarray,\n                      records: Sequence[TargetRecord], lambda_mo: float, lambda_smooth: float):\n    """Supervised loss + optional MOST-magnitude loss + optional profile smoothness.\n\n    This final version supports three modes:\n      1) lambda_mo > 0, lambda_smooth >= 0: MOSTmag-PINN, optionally smoothed.\n      2) lambda_mo = 0, lambda_smooth > 0: profile-constraint-only case.\n      3) lambda_mo = 0, lambda_smooth = 0: ordinary supervised DNN.\n\n    Aux layout:\n        [wrf_u_uv, wrf_v_uv, wrf_ws_uv, u_mo_uv, gate_uv,\n         wrf_ws_direct, u_mo_direct, gate_direct]\n    """\n    tf, *_ = import_tf()\n\n    uv_pairs = wind_uv_pairs(records)\n    ws_pairs = wind_ws_records_for_direct_pinn(records)\n\n    n_uv = len(uv_pairs)\n    n_ws = len(ws_pairs)\n\n    u_idx = [p[1] for p in uv_pairs]\n    v_idx = [p[2] for p in uv_pairs]\n    ws_idx = [p[1] for p in ws_pairs]\n    uv_heights = [p[0] for p in uv_pairs]\n    ws_heights = [p[0] for p in ws_pairs]\n\n    y_mean_tf = tf.constant(np.asarray(y_mean, dtype=np.float32), dtype=tf.float32)\n    y_scale_tf = tf.constant(np.asarray(y_scale, dtype=np.float32), dtype=tf.float32)\n\n    u_idx_tf = tf.constant(u_idx, dtype=tf.int32) if n_uv else tf.constant([], dtype=tf.int32)\n    v_idx_tf = tf.constant(v_idx, dtype=tf.int32) if n_uv else tf.constant([], dtype=tf.int32)\n    ws_idx_tf = tf.constant(ws_idx, dtype=tf.int32) if n_ws else tf.constant([], dtype=tf.int32)\n\n    uv_heights_tf = tf.constant(np.asarray(uv_heights, dtype=np.float32), dtype=tf.float32) if n_uv else tf.constant([], dtype=tf.float32)\n    ws_heights_tf = tf.constant(np.asarray(ws_heights, dtype=np.float32), dtype=tf.float32) if n_ws else tf.constant([], dtype=tf.float32)\n\n    def huber(e, delta=1.0):\n        abs_e = tf.abs(e)\n        return tf.where(abs_e <= delta, 0.5 * tf.square(e), delta * (abs_e - 0.5 * delta))\n\n    def _smooth_profile_loss(pred_residual, heights_tf):\n        n_h = int(pred_residual.shape[1]) if pred_residual.shape[1] is not None else 0\n        if n_h < 3:\n            return tf.constant(0.0, dtype=pred_residual.dtype)\n        dz = heights_tf[1:] - heights_tf[:-1]\n        slopes = (pred_residual[:, 1:] - pred_residual[:, :-1]) / dz[None, :]\n        curvature = slopes[:, 1:] - slopes[:, :-1]\n        return tf.reduce_mean(tf.square(curvature))\n\n    def loss(y_true_concat, y_pred):\n        sup_loss = _supervised_multitask_loss_tf(\n            y_true_concat=y_true_concat,\n            y_pred=y_pred,\n            n_outputs=n_outputs,\n            y_mean=y_mean,\n            y_scale=y_scale,\n            records=records,\n        )\n\n        if (n_uv + n_ws) < 1 or (float(lambda_mo) <= 0.0 and float(lambda_smooth) <= 0.0):\n            return sup_loss\n\n        offset = 2 * n_outputs\n        y_pred_phys = y_pred * y_scale_tf[None, :] + y_mean_tf[None, :]\n\n        phys_losses = []\n        gate_sums = []\n        smooth_loss = tf.constant(0.0, dtype=y_pred.dtype)\n\n        if n_uv > 0:\n            wrf_u = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            wrf_v = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            wrf_ws = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            u_mo = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n            gate = y_true_concat[:, offset:offset + n_uv]; offset += n_uv\n\n            du = tf.gather(y_pred_phys, u_idx_tf, axis=1)\n            dv = tf.gather(y_pred_phys, v_idx_tf, axis=1)\n            u_corr = wrf_u + du\n            v_corr = wrf_v + dv\n            ws_corr = tf.sqrt(tf.maximum(tf.square(u_corr) + tf.square(v_corr), 1e-12))\n            pred_residual = ws_corr - wrf_ws\n\n            if float(lambda_mo) > 0.0:\n                phys_residual = u_mo - wrf_ws\n                phys_each = huber(pred_residual - phys_residual, delta=1.0)\n                phys_losses.append(tf.reduce_sum(gate * phys_each))\n                gate_sums.append(tf.reduce_sum(gate))\n            if float(lambda_smooth) > 0.0 and n_uv >= 3:\n                smooth_loss = smooth_loss + _smooth_profile_loss(pred_residual, uv_heights_tf)\n\n        if n_ws > 0:\n            wrf_ws_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n            u_mo_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n            gate_d = y_true_concat[:, offset:offset + n_ws]; offset += n_ws\n\n            dws = tf.gather(y_pred_phys, ws_idx_tf, axis=1)\n            ws_corr_d = tf.maximum(wrf_ws_d + dws, 0.0)\n            pred_residual_d = ws_corr_d - wrf_ws_d\n\n            if float(lambda_mo) > 0.0:\n                phys_residual_d = u_mo_d - wrf_ws_d\n                phys_each_d = huber(pred_residual_d - phys_residual_d, delta=1.0)\n                phys_losses.append(tf.reduce_sum(gate_d * phys_each_d))\n                gate_sums.append(tf.reduce_sum(gate_d))\n            if float(lambda_smooth) > 0.0 and n_ws >= 3:\n                smooth_loss = smooth_loss + _smooth_profile_loss(pred_residual_d, ws_heights_tf)\n\n        if float(lambda_mo) > 0.0 and gate_sums:\n            total_gate = tf.add_n(gate_sums)\n            total_phys = tf.add_n(phys_losses) if phys_losses else tf.constant(0.0, dtype=y_pred.dtype)\n            mo_loss = tf.cond(\n                total_gate > 0.0,\n                lambda: total_phys / (total_gate + 1e-6),\n                lambda: tf.constant(0.0, dtype=y_pred.dtype),\n            )\n        else:\n            mo_loss = tf.constant(0.0, dtype=y_pred.dtype)\n\n        return sup_loss + float(lambda_mo) * mo_loss + float(lambda_smooth) * smooth_loss\n\n    return loss\n\n\n# Override the case parser used by the v4 core so C9/C10 are recognized.\ndef _case_mode_v4(case: str):\n    """Return selection_mode, feature_mode_name, use_pinn, use_most_input, is_raw, force_most.\n\n    use_pinn=True is used for profile-constraint cases because the training core\n    routes all non-supervised profile losses through the same auxiliary-loss path.\n    Profile-only cases are detected later from the feature_mode_name and set\n    lambda_MO=0 while keeping lambda_smooth>0.\n    """\n    c = str(case).strip().lower().replace("-", "_")\n    if c in {"raw", "raw_wrf", "wrf", "c0"}:\n        return "all", "raw_WRF", False, False, True, False\n\n    # Independent profile-constraint diagnostics.\n    if c in {"c9", "profileconstraint_corrfdr", "profile_constraint_corrfdr", "profilesmooth_corrfdr", "profile_smooth_corrfdr"}:\n        return "corrFDR", "ProfileConstraint_corrFDR", True, False, False, False\n    if c in {"c10", "mostinput_profileconstraint_corrfdr_forcemost", "mostinput_profile_constraint_corrfdr_forcemost", "mostinput_profilesmooth_corrfdr_forcemost", "mostinput_profile_smooth_corrfdr_forcemost"}:\n        return "corrFDR", "MOSTinput_ProfileConstraint_corrFDR_forceMOST", True, True, False, True\n\n    force_most = ("forcemost" in c) or ("force_most" in c) or c in {"c4b", "c8b"}\n    use_pinn = ("pinn" in c) or ("mostmag" in c) or c in {"c5", "c6", "c7", "c8", "c8b"}\n    use_most_input = ("mostinput" in c) or ("most_input" in c) or c in {"c3", "c4", "c4b", "c7", "c8", "c8b"}\n\n    if ("corrfdr" in c) or ("corr" in c) or c in {"c2", "c4", "c4b", "c6", "c8", "c8b"}:\n        selection = "corrFDR"\n    elif ("all" in c) or c in {"nomost", "mostinput", "pinn_mostmag", "c1", "c3", "c5", "c7"}:\n        selection = "all"\n    else:\n        raise ValueError(f"Unknown Code2 case: {case}")\n\n    if use_most_input and use_pinn:\n        if selection == "corrFDR":\n            feature_name = "MOSTinput_PINN_corrFDR_forceMOST" if force_most else "MOSTinput_PINN_corrFDR"\n        else:\n            feature_name = "MOSTinput_PINN_all"\n    elif use_most_input:\n        if selection == "corrFDR":\n            feature_name = "MOSTinput_corrFDR_forceMOST" if force_most else "MOSTinput_corrFDR"\n        else:\n            feature_name = "MOSTinput_all"\n    elif use_pinn:\n        feature_name = "PINN_corrFDR" if selection == "corrFDR" else "PINN_all"\n    else:\n        feature_name = "noMOST_corrFDR" if selection == "corrFDR" else "noMOST_all"\n\n    return selection, feature_name, use_pinn, use_most_input, False, bool(force_most)\n\n\n_train_one_feature_mode_before_v5_profile_constraint = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    """v5 wrapper adding profile-constraint-only cases.\n\n    The v4 core passes use_pinn_mostmag=True for C9/C10 so the auxiliary profile\n    arrays are prepared. For C9/C10, this wrapper temporarily forces\n    lambda_MO=0 and lambda_smooth=PROFILE_CONSTRAINT_LAMBDA.\n    """\n    profile_only = _is_profile_constraint_case_code2(feature_mode)\n\n    old_lambda_candidates = list(globals().get("PINN_LAMBDA_MO_CANDIDATES", []))\n    old_lambda_smooth = globals().get("PINN_LAMBDA_SMOOTH", 0.0)\n    if profile_only:\n        globals()["PINN_LAMBDA_MO_CANDIDATES"] = [0.0]\n        # Use the first candidate for now. Keep the list in metadata for traceability.\n        globals()["PINN_LAMBDA_SMOOTH"] = float(PROFILE_CONSTRAINT_LAMBDA_CANDIDATES[0])\n        use_pinn_mostmag = True\n\n    try:\n        metrics_df = _train_one_feature_mode_before_v5_profile_constraint(\n            df=df,\n            target_records_all=target_records_all,\n            feature_cols=feature_cols,\n            site_name=site_name,\n            model_name=model_name,\n            feature_mode=feature_mode,\n            out_dir=out_dir,\n            network=network,\n            use_pinn_mostmag=use_pinn_mostmag,\n        )\n    finally:\n        if profile_only:\n            globals()["PINN_LAMBDA_MO_CANDIDATES"] = old_lambda_candidates\n            globals()["PINN_LAMBDA_SMOOTH"] = old_lambda_smooth\n\n    try:\n        if profile_only:\n            meta_path = Path(out_dir) / "metadata.json"\n            meta = {}\n            if meta_path.exists():\n                try:\n                    meta = json.loads(meta_path.read_text(encoding="utf-8"))\n                except Exception:\n                    meta = {}\n            meta.update({\n                "script_version": "code2_profile_C0C8_WSWD_TKE_T_fixed_v5_profileConstraint",\n                "profile_constraint_case": True,\n                "profile_constraint_type": "wind_speed_residual_vertical_smoothness_only",\n                "uses_MOST_magnitude_loss": False,\n                "lambda_MO_forced_to_zero": True,\n                "lambda_profile_smooth": float(PROFILE_CONSTRAINT_LAMBDA_CANDIDATES[0]),\n                "profile_constraint_lambda_candidates": [float(x) for x in PROFILE_CONSTRAINT_LAMBDA_CANDIDATES],\n                "profile_constraint_note": (\n                    "This case does not force WS_corr to match U_MO. It only penalizes "\n                    "vertical curvature of the wind-speed correction residual profile. "\n                    "MOST may enter as input features only when the case name contains MOSTinput."\n                ),\n            })\n            meta_path.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")\n\n            # Compact profile-constraint diagnostic summary.\n            rows = []\n            if metrics_df is not None and not metrics_df.empty:\n                sub = metrics_df[(metrics_df["split"].astype(str).str.lower() == "test") & (metrics_df["height_m"].astype(str) == "ALL_PROFILE")]\n                for _, r in sub.iterrows():\n                    rows.append({\n                        "diagnostic_type": "test_ALL_PROFILE_metric",\n                        "case": feature_mode,\n                        "profile_constraint_lambda": float(PROFILE_CONSTRAINT_LAMBDA_CANDIDATES[0]),\n                        "variable": r.get("variable", ""),\n                        "RMSE": r.get("RMSE", np.nan),\n                        "MAE": r.get("MAE", np.nan),\n                        "Skill_RMSE_pct": r.get("Skill_RMSE_pct", np.nan),\n                    })\n            if rows:\n                pd.DataFrame(rows).to_csv(Path(out_dir) / "profile_constraint_diagnostics_v5.csv", index=False, encoding="utf-8-sig")\n    except Exception as e:\n        print(f"[profile constraint v5] diagnostics skipped for {feature_mode}: {e}")\n\n    return metrics_df\n\n\n_train_for_csv_before_v5_profile_post = train_for_csv\n\ndef _patch_profile_constraint_outputs_v5(root: Path) -> None:\n    """Fix summary flags for profile-constraint cases after the v4 core finishes."""\n    root = Path(root)\n    if not root.exists():\n        return\n    profile_names = {"ProfileConstraint_corrFDR", "MOSTinput_ProfileConstraint_corrFDR_forceMOST"}\n    for csv_path in root.rglob("ALL_cases_metrics_train_val_test.csv"):\n        try:\n            dfm = pd.read_csv(csv_path)\n            if "feature_mode" in dfm.columns:\n                m = dfm["feature_mode"].astype(str).isin(profile_names)\n                if m.any():\n                    dfm.loc[m, "uses_profile_constraint"] = True\n                    dfm.loc[~m, "uses_profile_constraint"] = dfm.loc[~m, "uses_profile_constraint"].fillna(False) if "uses_profile_constraint" in dfm.columns else False\n                    if "uses_PINN_MOSTmag" in dfm.columns:\n                        dfm.loc[m, "uses_PINN_MOSTmag"] = False\n                    dfm.loc[m, "uses_MOST_magnitude_loss"] = False\n                    dfm.loc[~m, "uses_MOST_magnitude_loss"] = dfm.loc[~m, "uses_MOST_magnitude_loss"].fillna(dfm.get("uses_PINN_MOSTmag", False)) if "uses_MOST_magnitude_loss" in dfm.columns else dfm.get("uses_PINN_MOSTmag", False)\n                    dfm.to_csv(csv_path, index=False, encoding="utf-8-sig")\n        except Exception as e:\n            print(f"[v5 post] metrics flag patch skipped for {csv_path}: {e}")\n\n    for csv_path in root.rglob("case_feature_strategy_summary_v4.csv"):\n        try:\n            dfs = pd.read_csv(csv_path)\n            if "case" in dfs.columns:\n                m = dfs["case"].astype(str).isin(profile_names)\n                if m.any():\n                    dfs["use_profile_constraint"] = dfs.get("use_profile_constraint", False)\n                    dfs.loc[m, "use_profile_constraint"] = True\n                    if "use_pinn" in dfs.columns:\n                        dfs.loc[m, "use_pinn"] = False\n                    dfs.loc[m, "use_MOST_magnitude_loss"] = False\n                    dfs.to_csv(csv_path, index=False, encoding="utf-8-sig")\n        except Exception as e:\n            print(f"[v5 post] feature summary flag patch skipped for {csv_path}: {e}")\n\n\ndef train_for_csv(\n    train_csv: Path,\n    output_root: Path,\n    network: str = NETWORK,\n    feature_modes: Sequence[str] = tuple(CODE_CASES),\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n    date_start: Optional[str] = None,\n    date_end: Optional[str] = None,\n) -> pd.DataFrame:\n    result = _train_for_csv_before_v5_profile_post(\n        train_csv=train_csv,\n        output_root=output_root,\n        network=network,\n        feature_modes=feature_modes,\n        heights_m=heights_m,\n        target_groups=target_groups,\n        date_start=date_start,\n        date_end=date_end,\n    )\n    try:\n        train_csv2 = Path(train_csv)\n        tower_tag = safe_name(train_csv2.parent.name)\n        htag = height_tag_from_list(heights_m)\n        root = Path(output_root) / safe_name(f"{tower_tag}_{htag}")\n        _patch_profile_constraint_outputs_v5(root)\n    except Exception as e:\n        print(f"[v5 post] profile-constraint output patch skipped: {e}")\n    return result\n\n\n\n\n# =============================================================================\n# FINAL PATCH v6: profile-lambda sweep + C8c MOST-OBS consistency gate\n# =============================================================================\n# Purpose\n# -------\n# v5 added independent C9/C10 profile-constraint cases but used the first fixed\n# PROFILE_CONSTRAINT_LAMBDA. This v6 patch makes profile constraint lambda a\n# validation-selected sweep. It also adds C8c, a diagnostic combined case with\n# MOST input force-kept and an additional MOST-OBS consistency gate for the MOST\n# magnitude loss.\n#\n# New diagnostic case:\n#   C8c = MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_consistencyGate\n#\n# Interpretation:\n#   C8b = selected + force-kept MOST input + MOSTmag loss + profile smoothness\n#   C8c = C8b + MOST-OBS consistency gate\n#\n# C9/C10 profile-only cases now sweep PROFILE_CONSTRAINT_LAMBDA_CANDIDATES and\n# choose the best value using the same raw-normalized validation score.\n\nimport shutil as _shutil_v6\n\n# Multiple lambda candidates for profile-constraint-only cases. Runner can override.\n# v5 defined a single candidate [PROFILE_CONSTRAINT_LAMBDA]; replace that default\n# with a real sweep unless the runner/user explicitly provides another list.\n_PROFILE_CONSTRAINT_LAMBDA_CANDIDATES_DEFAULT_V6 = [0.0, 0.0003, 0.001, 0.003, 0.01]\n_existing_profile_candidates_v6 = list(globals().get("PROFILE_CONSTRAINT_LAMBDA_CANDIDATES", []))\n_existing_lam_v6 = float(globals().get("PROFILE_CONSTRAINT_LAMBDA", 0.001))\nif (not _existing_profile_candidates_v6) or (len(_existing_profile_candidates_v6) == 1 and abs(float(_existing_profile_candidates_v6[0]) - _existing_lam_v6) < 1e-15):\n    PROFILE_CONSTRAINT_LAMBDA_CANDIDATES = list(_PROFILE_CONSTRAINT_LAMBDA_CANDIDATES_DEFAULT_V6)\nelse:\n    PROFILE_CONSTRAINT_LAMBDA_CANDIDATES = [float(x) for x in _existing_profile_candidates_v6]\nPROFILE_CONSTRAINT_LAMBDA = float(globals().get("PROFILE_CONSTRAINT_LAMBDA", 0.001))\n\n# MOST-OBS consistency gate settings. Enabled only for C8c by wrapper below.\nENABLE_MOST_OBS_CONSISTENCY_GATE = bool(globals().get("ENABLE_MOST_OBS_CONSISTENCY_GATE", False))\nMOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID = float(globals().get("MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID", 0.25))\nMOST_OBS_CONSISTENCY_ABS_TOL = float(globals().get("MOST_OBS_CONSISTENCY_ABS_TOL", 1.0))\nMOST_OBS_CONSISTENCY_GATE_MODE = str(globals().get("MOST_OBS_CONSISTENCY_GATE_MODE", "sign_or_absdiff")).lower()\n\n\ndef _is_consistency_gate_case_code2(case_name: str) -> bool:\n    s = str(case_name).lower().replace("-", "_")\n    return (\n        "consistencygate" in s\n        or "consistency_gate" in s\n        or s in {"c8c"}\n    )\n\n\n# Extend the v5 parser to recognize C8c.\n_case_mode_before_v6 = _case_mode_v4\n\ndef _case_mode_v4(case: str):\n    c = str(case).strip().lower().replace("-", "_")\n    if c in {\n        "c8c",\n        "mostinput_pinn_mostmag_corrfdr_forcemost_consistencygate",\n        "mostinput_pinn_mostmag_corrfdr_force_most_consistency_gate",\n        "mostinput_pinn_corrfdr_forcemost_consistencygate",\n        "mostinput_pinn_corrfdr_force_most_consistency_gate",\n    }:\n        return "corrFDR", "MOSTinput_PINN_corrFDR_forceMOST_consistencyGate", True, True, False, True\n    return _case_mode_before_v6(case)\n\n\ndef _ws_obs_residual_for_height_code2(df: pd.DataFrame, idx: np.ndarray, h: int, wrf_ws: np.ndarray) -> np.ndarray:\n    """OBS_WS - WRF_WS for consistency gating; returns NaN when unavailable."""\n    obs_col = first_existing(df, obs_ws_candidates(int(h)))\n    if obs_col is None:\n        return np.full(len(idx), np.nan, dtype=float)\n    obs_ws = pd.to_numeric(df.loc[idx, obs_col], errors="coerce").values.astype(float)\n    return obs_ws - wrf_ws\n\n\ndef _most_obs_consistency_gate_code2(phys_residual: np.ndarray, obs_residual: np.ndarray) -> np.ndarray:\n    """Gate where MOST correction direction/magnitude is broadly consistent with OBS correction.\n\n    sign_or_absdiff mode:\n      keep when MOST and OBS correction directions agree for non-small OBS residuals,\n      or when MOST residual is within an absolute tolerance of OBS residual.\n    This avoids hard-rejecting near-zero residual cases where sign is noisy.\n    """\n    phys = np.asarray(phys_residual, dtype=float)\n    obs = np.asarray(obs_residual, dtype=float)\n    finite = np.isfinite(phys) & np.isfinite(obs)\n    if not finite.any():\n        return np.zeros_like(phys, dtype=float)\n    sign_ok = (phys * obs) >= 0.0\n    obs_large = np.abs(obs) >= float(MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID)\n    absdiff_ok = np.abs(phys - obs) <= float(MOST_OBS_CONSISTENCY_ABS_TOL)\n    mode = str(MOST_OBS_CONSISTENCY_GATE_MODE).lower()\n    if mode in {"sign", "sign_only"}:\n        keep = finite & sign_ok & obs_large\n    elif mode in {"absdiff", "abs_diff", "difference"}:\n        keep = finite & absdiff_ok\n    else:\n        keep = finite & ((sign_ok & obs_large) | absdiff_ok)\n    return keep.astype(float)\n\n\n# Preserve the v5 direct-aware aux builder, then wrap it with optional C8c consistency gate.\n_make_pinn_aux_and_gate_summary_before_v6_consistency = make_pinn_aux_and_gate_summary\n\ndef make_pinn_aux_and_gate_summary(df: pd.DataFrame, idx: np.ndarray, train_i: np.ndarray,\n                                   records: Sequence[TargetRecord]) -> Tuple[np.ndarray, pd.DataFrame]:\n    aux, summary = _make_pinn_aux_and_gate_summary_before_v6_consistency(df, idx, train_i, records)\n    if not bool(globals().get("ENABLE_MOST_OBS_CONSISTENCY_GATE", False)):\n        return aux, summary\n    if aux is None or aux.size == 0:\n        return aux, summary\n\n    try:\n        uv_pairs = wind_uv_pairs(records)\n        ws_pairs = wind_ws_records_for_direct_pinn(records)\n        n_uv, n_ws = len(uv_pairs), len(ws_pairs)\n        rec_by = {(r.var, int(r.height)): r for r in records}\n\n        # Aux layout:\n        # [wrf_u_uv, wrf_v_uv, wrf_ws_uv, u_mo_uv, gate_uv,\n        #  wrf_ws_direct, u_mo_direct, gate_direct]\n        offset = 0\n        consistency_rows = []\n\n        if n_uv > 0:\n            wrf_u = aux[:, offset:offset+n_uv]; offset += n_uv\n            wrf_v = aux[:, offset:offset+n_uv]; offset += n_uv\n            wrf_ws = aux[:, offset:offset+n_uv]; offset += n_uv\n            u_mo = aux[:, offset:offset+n_uv]; offset += n_uv\n            gate_start = offset\n            gate = aux[:, gate_start:gate_start+n_uv]\n            offset += n_uv\n            new_gate = gate.copy()\n            for j, (h, _, _) in enumerate(uv_pairs):\n                phys_res = u_mo[:, j] - wrf_ws[:, j]\n                obs_res = _ws_obs_residual_for_height_code2(df, idx, int(h), wrf_ws[:, j])\n                cg = _most_obs_consistency_gate_code2(phys_res, obs_res)\n                new_gate[:, j] = gate[:, j] * cg\n                consistency_rows.append({\n                    "height_m": int(h),\n                    "pinn_source": "uv",\n                    "consistency_gate_mean": float(np.nanmean(cg)),\n                    "consistency_gate_nonzero_ratio": float((cg > 0).mean()),\n                    "gate_mean_before_consistency": float(np.nanmean(gate[:, j])),\n                    "gate_mean_after_consistency": float(np.nanmean(new_gate[:, j])),\n                })\n            aux[:, gate_start:gate_start+n_uv] = new_gate\n\n        if n_ws > 0:\n            wrf_ws_d = aux[:, offset:offset+n_ws]; offset += n_ws\n            u_mo_d = aux[:, offset:offset+n_ws]; offset += n_ws\n            gate_start = offset\n            gate_d = aux[:, gate_start:gate_start+n_ws]\n            offset += n_ws\n            new_gate_d = gate_d.copy()\n            for j, (h, _) in enumerate(ws_pairs):\n                phys_res = u_mo_d[:, j] - wrf_ws_d[:, j]\n                obs_res = _ws_obs_residual_for_height_code2(df, idx, int(h), wrf_ws_d[:, j])\n                cg = _most_obs_consistency_gate_code2(phys_res, obs_res)\n                new_gate_d[:, j] = gate_d[:, j] * cg\n                consistency_rows.append({\n                    "height_m": int(h),\n                    "pinn_source": "direct_ws",\n                    "consistency_gate_mean": float(np.nanmean(cg)),\n                    "consistency_gate_nonzero_ratio": float((cg > 0).mean()),\n                    "gate_mean_before_consistency": float(np.nanmean(gate_d[:, j])),\n                    "gate_mean_after_consistency": float(np.nanmean(new_gate_d[:, j])),\n                })\n            aux[:, gate_start:gate_start+n_ws] = new_gate_d\n\n        if isinstance(summary, pd.DataFrame) and not summary.empty and consistency_rows:\n            cdf = pd.DataFrame(consistency_rows)\n            summary = summary.merge(cdf, on=["height_m", "pinn_source"], how="left")\n            # Replace final gate diagnostics with after-consistency values where available.\n            if "gate_mean_after_consistency" in summary.columns:\n                summary["final_gate_mean_before_consistency_v6"] = summary.get("final_gate_mean", np.nan)\n                summary["final_gate_mean"] = summary["gate_mean_after_consistency"].where(summary["gate_mean_after_consistency"].notna(), summary.get("final_gate_mean", np.nan))\n                # Nonzero ratio after consistency is not exactly available after height/PBLH weights for all cases;\n                # use the consistency diagnostic as a conservative summary.\n                summary["MOST_OBS_consistency_gate_enabled_v6"] = True\n                summary["MOST_OBS_consistency_gate_mode_v6"] = MOST_OBS_CONSISTENCY_GATE_MODE\n                summary["MOST_OBS_consistency_min_abs_obs_resid_v6"] = MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID\n                summary["MOST_OBS_consistency_abs_tol_v6"] = MOST_OBS_CONSISTENCY_ABS_TOL\n    except Exception as e:\n        print(f"[C8c consistency gate v6] skipped due to: {e}")\n    return aux, summary\n\n\ndef _lambda_label_v6(val: float) -> str:\n    s = f"{float(val):.6g}".replace("-", "m").replace(".", "p")\n    return s\n\n\ndef _copy_best_profile_case_outputs_v6(best_dir: Path, out_dir: Path) -> None:\n    """Copy best lambda run outputs into the canonical case folder without recursing."""\n    best_dir = Path(best_dir)\n    out_dir = Path(out_dir)\n    out_dir.mkdir(parents=True, exist_ok=True)\n    for item in best_dir.iterdir():\n        if item.name.startswith("lam_"):\n            continue\n        dest = out_dir / item.name\n        try:\n            if item.is_dir():\n                if dest.exists():\n                    _shutil_v6.rmtree(dest)\n                _shutil_v6.copytree(item, dest)\n            else:\n                _shutil_v6.copy2(item, dest)\n        except Exception as e:\n            print(f"[profile lambda v6] copy skipped for {item}: {e}")\n\n\n_train_one_feature_mode_before_v6_final = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    """Final v6 wrapper.\n\n    - C9/C10: sweep PROFILE_CONSTRAINT_LAMBDA_CANDIDATES and choose best by\n      validation_selection_score.\n    - C8c: enable MOST-OBS consistency gate only for this diagnostic case.\n    """\n    out_dir = Path(out_dir)\n    profile_only = _is_profile_constraint_case_code2(feature_mode)\n    consistency_case = _is_consistency_gate_case_code2(feature_mode)\n\n    if profile_only:\n        old_lambda_candidates = list(globals().get("PINN_LAMBDA_MO_CANDIDATES", []))\n        old_lambda_smooth = globals().get("PINN_LAMBDA_SMOOTH", 0.0)\n        rows = []\n        best_score = np.inf\n        best_metrics = None\n        best_lambda = None\n        best_dir = None\n        cands = [float(x) for x in PROFILE_CONSTRAINT_LAMBDA_CANDIDATES]\n        # Keep unique order.\n        seen = set(); cands = [x for x in cands if not (x in seen or seen.add(x))]\n        for lam_smooth in cands:\n            run_dir = out_dir / f"lam_{_lambda_label_v6(lam_smooth)}"\n            globals()["PINN_LAMBDA_MO_CANDIDATES"] = [0.0]\n            globals()["PINN_LAMBDA_SMOOTH"] = float(lam_smooth)\n            try:\n                metrics_df = _train_one_feature_mode_before_v5_profile_constraint(\n                    df=df,\n                    target_records_all=target_records_all,\n                    feature_cols=feature_cols,\n                    site_name=site_name,\n                    model_name=model_name,\n                    feature_mode=feature_mode,\n                    out_dir=run_dir,\n                    network=network,\n                    use_pinn_mostmag=True,\n                )\n                score = validation_selection_score(metrics_df)\n            except Exception as e:\n                metrics_df = None\n                score = np.inf\n                rows.append({\n                    "lambda_profile_smooth": lam_smooth,\n                    "selection_score": score,\n                    "status": "failed",\n                    "message": repr(e),\n                    "run_dir": str(run_dir),\n                })\n                continue\n\n            row = {\n                "lambda_profile_smooth": lam_smooth,\n                "selection_score": score,\n                "selection_score_mode": PINN_LAMBDA_SELECTION_SCORE_MODE,\n                "status": "ok",\n                "run_dir": str(run_dir),\n            }\n            try:\n                sub = metrics_df[(metrics_df["split"].astype(str).str.lower() == "val") & (metrics_df["height_m"].astype(str) == "ALL_PROFILE")]\n                for _, r in sub.iterrows():\n                    var = str(r.get("variable", ""))\n                    if var:\n                        row[f"val_{var}_RMSE"] = r.get("RMSE", np.nan)\n                        row[f"val_{var}_MAE"] = r.get("MAE", np.nan)\n                        row[f"val_{var}_Skill_RMSE_pct"] = r.get("Skill_RMSE_pct", np.nan)\n            except Exception:\n                pass\n            rows.append(row)\n            if np.isfinite(score) and score < best_score:\n                best_score = float(score)\n                best_metrics = metrics_df\n                best_lambda = float(lam_smooth)\n                best_dir = run_dir\n\n        globals()["PINN_LAMBDA_MO_CANDIDATES"] = old_lambda_candidates\n        globals()["PINN_LAMBDA_SMOOTH"] = old_lambda_smooth\n\n        sweep_df = pd.DataFrame(rows)\n        out_dir.mkdir(parents=True, exist_ok=True)\n        if not sweep_df.empty:\n            sweep_df.to_csv(out_dir / "profile_constraint_lambda_sweep_v6.csv", index=False, encoding="utf-8-sig")\n            try:\n                (out_dir / "profile_constraint_lambda_sweep_v6.txt").write_text(sweep_df.to_string(index=False), encoding="utf-8")\n            except Exception:\n                pass\n\n        if best_metrics is None or best_dir is None:\n            raise RuntimeError(f"{feature_mode}: all profile constraint lambda candidates failed.")\n\n        _copy_best_profile_case_outputs_v6(best_dir, out_dir)\n        try:\n            meta_path = out_dir / "metadata.json"\n            meta = {}\n            if meta_path.exists():\n                try:\n                    meta = json.loads(meta_path.read_text(encoding="utf-8"))\n                except Exception:\n                    meta = {}\n            meta.update({\n                "script_version": "code2_profile_C0C8_WSWD_TKE_T_fixed_v6_profileConstraintSweep",\n                "profile_constraint_case": True,\n                "profile_constraint_type": "wind_speed_residual_vertical_smoothness_only",\n                "uses_MOST_magnitude_loss": False,\n                "lambda_MO_forced_to_zero": True,\n                "best_lambda_profile_smooth": best_lambda,\n                "best_profile_selection_score": best_score,\n                "profile_constraint_lambda_candidates": cands,\n                "profile_constraint_lambda_selection_score_mode": PINN_LAMBDA_SELECTION_SCORE_MODE,\n                "best_lam_run_dir": str(best_dir),\n            })\n            meta_path.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")\n        except Exception as e:\n            print(f"[profile lambda v6] metadata skipped for {feature_mode}: {e}")\n\n        try:\n            rows2 = []\n            sub = best_metrics[(best_metrics["split"].astype(str).str.lower() == "test") & (best_metrics["height_m"].astype(str) == "ALL_PROFILE")]\n            for _, r in sub.iterrows():\n                rows2.append({\n                    "diagnostic_type": "test_ALL_PROFILE_metric_best_profile_lambda",\n                    "case": feature_mode,\n                    "best_lambda_profile_smooth": best_lambda,\n                    "best_profile_selection_score": best_score,\n                    "variable": r.get("variable", ""),\n                    "RMSE": r.get("RMSE", np.nan),\n                    "MAE": r.get("MAE", np.nan),\n                    "Skill_RMSE_pct": r.get("Skill_RMSE_pct", np.nan),\n                })\n            if rows2:\n                pd.DataFrame(rows2).to_csv(out_dir / "profile_constraint_diagnostics_v6.csv", index=False, encoding="utf-8-sig")\n        except Exception as e:\n            print(f"[profile lambda v6] diagnostics skipped for {feature_mode}: {e}")\n        return best_metrics\n\n    old_gate = bool(globals().get("ENABLE_MOST_OBS_CONSISTENCY_GATE", False))\n    if consistency_case:\n        globals()["ENABLE_MOST_OBS_CONSISTENCY_GATE"] = True\n    try:\n        metrics_df = _train_one_feature_mode_before_v6_final(\n            df=df,\n            target_records_all=target_records_all,\n            feature_cols=feature_cols,\n            site_name=site_name,\n            model_name=model_name,\n            feature_mode=feature_mode,\n            out_dir=out_dir,\n            network=network,\n            use_pinn_mostmag=use_pinn_mostmag,\n        )\n    finally:\n        if consistency_case:\n            globals()["ENABLE_MOST_OBS_CONSISTENCY_GATE"] = old_gate\n\n    if consistency_case:\n        try:\n            meta_path = out_dir / "metadata.json"\n            meta = {}\n            if meta_path.exists():\n                try:\n                    meta = json.loads(meta_path.read_text(encoding="utf-8"))\n                except Exception:\n                    meta = {}\n            meta.update({\n                "MOST_OBS_consistency_gate_case": True,\n                "MOST_OBS_consistency_gate_mode": MOST_OBS_CONSISTENCY_GATE_MODE,\n                "MOST_OBS_consistency_min_abs_obs_resid": MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID,\n                "MOST_OBS_consistency_abs_tol": MOST_OBS_CONSISTENCY_ABS_TOL,\n                "diagnostic_case_label": "C8c",\n            })\n            meta_path.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")\n        except Exception as e:\n            print(f"[C8c metadata v6] skipped: {e}")\n    return metrics_df\n\n\n# Update post-summary patch to include C8c and profile lambda sweep outputs.\n_patch_profile_constraint_outputs_before_v6 = _patch_profile_constraint_outputs_v5\n\ndef _patch_profile_constraint_outputs_v5(root: Path) -> None:\n    _patch_profile_constraint_outputs_before_v6(root)\n    root = Path(root)\n    if not root.exists():\n        return\n    profile_names = {"ProfileConstraint_corrFDR", "MOSTinput_ProfileConstraint_corrFDR_forceMOST"}\n    consistency_names = {"MOSTinput_PINN_corrFDR_forceMOST_consistencyGate"}\n    for csv_path in root.rglob("ALL_cases_metrics_train_val_test.csv"):\n        try:\n            dfm = pd.read_csv(csv_path)\n            if "feature_mode" in dfm.columns:\n                mprof = dfm["feature_mode"].astype(str).isin(profile_names)\n                mgate = dfm["feature_mode"].astype(str).isin(consistency_names)\n                if mprof.any():\n                    dfm.loc[mprof, "uses_profile_constraint"] = True\n                    dfm.loc[mprof, "uses_MOST_magnitude_loss"] = False\n                    if "uses_PINN_MOSTmag" in dfm.columns:\n                        dfm.loc[mprof, "uses_PINN_MOSTmag"] = False\n                if mgate.any():\n                    dfm.loc[mgate, "uses_MOST_OBS_consistency_gate"] = True\n                dfm.to_csv(csv_path, index=False, encoding="utf-8-sig")\n        except Exception as e:\n            print(f"[v6 post] metrics flag patch skipped for {csv_path}: {e}")\n\n\n\n# =============================================================================\n# V7 PATCH: use sin/cos residual targets for direct WD in Code2 profile training\n# =============================================================================\n# Why this patch exists:\n#   The earlier Code2 direct-WD target used a circular degree residual:\n#       delta_WD = ((OBS_WD - WRF_WD + 180) % 360) - 180\n#   That is better than a naive degree difference, but the supervised target is\n#   still an angular scalar. This patch follows the final Code1 convention and\n#   replaces each direct WD target by two continuous residual components:\n#       delta_sinWD = sin(OBS_WD) - sin(WRF_WD)\n#       delta_cosWD = cos(OBS_WD) - cos(WRF_WD)\n#   During evaluation, the predicted sin/cos components are reconstructed to a\n#   physical WD angle and all metrics are still reported as WD_direct in degrees.\n#\n# Scope:\n#   - applies only to direct wind_wswd WD targets;\n#   - preserves the Code2_drop rule excluding WD/U/V targets at 4 m and 50 m;\n#   - keeps MOST-magnitude and profile-smoothness losses unchanged because they\n#     operate on WS residuals, not WD residuals.\n\nWD_TARGET_REPRESENTATION_CODE2 = str(globals().get("WD_TARGET_REPRESENTATION_CODE2", "sincos_delta")).lower()\n\n\ndef _is_wd_sincos_target_record_code2(r: TargetRecord) -> bool:\n    s = str(getattr(r, "target_col", "")).lower()\n    return str(getattr(r, "var", "")).lower() == "wd" and "target_delta_wd" in s and ("_sin_" in s or "_cos_" in s)\n\n\ndef _wd_sincos_component_code2(r: TargetRecord) -> Optional[str]:\n    s = str(getattr(r, "target_col", "")).lower()\n    if "_sin_" in s:\n        return "sin"\n    if "_cos_" in s:\n        return "cos"\n    return None\n\n\ndef _wd_sincos_pair_indices_code2(records: Sequence[TargetRecord], h: int, obs_col: str, wrf_col: str) -> Tuple[Optional[int], Optional[int]]:\n    i_sin = None\n    i_cos = None\n    for k, r in enumerate(records):\n        if int(r.height) != int(h) or r.obs_col != obs_col or r.wrf_col != wrf_col:\n            continue\n        comp = _wd_sincos_component_code2(r)\n        if comp == "sin":\n            i_sin = k\n        elif comp == "cos":\n            i_cos = k\n    return i_sin, i_cos\n\n\n_detect_targets_and_create_columns_before_sincos_wd_code2 = detect_targets_and_create_columns\n\n\ndef detect_targets_and_create_columns(\n    df: pd.DataFrame,\n    heights_m: Optional[Sequence[int]] = None,\n    target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n) -> Tuple[pd.DataFrame, List[TargetRecord], List[int]]:\n    """Create targets; replace direct WD degree residual by sin/cos residual targets."""\n    out, records, used_heights = _detect_targets_and_create_columns_before_sincos_wd_code2(\n        df, heights_m=heights_m, target_groups=target_groups\n    )\n    if WD_TARGET_REPRESENTATION_CODE2 not in {"sincos_delta", "sincos", "sin_cos_delta"}:\n        return out, records, used_heights\n\n    new_records: List[TargetRecord] = []\n    for r in records:\n        # Convert only the old direct-WD scalar target records. Code2_drop has\n        # already removed WD at excluded heights, so this does not re-add 4/50 m WD.\n        if str(r.var).lower() == "wd" and not _is_wd_sincos_target_record_code2(r):\n            h = int(r.height)\n            if r.obs_col in out.columns and r.wrf_col in out.columns:\n                obs_rad = np.deg2rad(pd.to_numeric(out[r.obs_col], errors="coerce").astype(float))\n                wrf_rad = np.deg2rad(pd.to_numeric(out[r.wrf_col], errors="coerce").astype(float))\n                c_sin = f"target_delta_WD{h}_sin_obs_minus_wrf"\n                c_cos = f"target_delta_WD{h}_cos_obs_minus_wrf"\n                out[c_sin] = np.sin(obs_rad) - np.sin(wrf_rad)\n                out[c_cos] = np.cos(obs_rad) - np.cos(wrf_rad)\n                # Keep var=\'wd\' so existing WD QC, low-wind masking, target grouping,\n                # and the 4/50 m drop-rule logic remain compatible.\n                new_records.append(TargetRecord("wd", h, r.obs_col, r.wrf_col, c_sin, "sin(deg)"))\n                new_records.append(TargetRecord("wd", h, r.obs_col, r.wrf_col, c_cos, "cos(deg)"))\n            else:\n                # Extremely defensive fallback: keep the original record if columns vanished.\n                new_records.append(r)\n        else:\n            new_records.append(r)\n\n    used_heights_new = sorted(set(int(r.height) for r in new_records))\n    return out, new_records, used_heights_new\n\n\n_apply_obs_target_qc_code2_before_sincos_wd_sync = apply_obs_target_qc_code2\n\n\ndef apply_obs_target_qc_code2(df: pd.DataFrame, records: Sequence[TargetRecord], out_dir: Path, site_name: str) -> pd.DataFrame:\n    """Run existing QC, then synchronize duplicated sin/cos WD component masks."""\n    out = _apply_obs_target_qc_code2_before_sincos_wd_sync(df, records, out_dir, site_name)\n    rows = []\n    for r in records:\n        if not _is_wd_sincos_target_record_code2(r):\n            continue\n        if r.target_col not in out.columns:\n            continue\n        invalid = np.zeros(len(out), dtype=bool)\n        if r.obs_col in out.columns:\n            invalid |= ~np.isfinite(pd.to_numeric(out[r.obs_col], errors="coerce").values.astype(float))\n        if r.wrf_col in out.columns:\n            invalid |= ~np.isfinite(pd.to_numeric(out[r.wrf_col], errors="coerce").values.astype(float))\n        n_before = int(pd.to_numeric(out[r.target_col], errors="coerce").notna().sum())\n        if invalid.any():\n            out.loc[invalid, r.target_col] = np.nan\n        n_after = int(pd.to_numeric(out[r.target_col], errors="coerce").notna().sum())\n        rows.append({\n            "site": site_name,\n            "height_m": int(r.height),\n            "target_col": r.target_col,\n            "wd_target_representation": WD_TARGET_REPRESENTATION_CODE2,\n            "n_finite_before_sync": n_before,\n            "n_finite_after_sync": n_after,\n            "n_masked_by_obs_or_wrf_nan": n_before - n_after,\n        })\n    if rows:\n        try:\n            pd.DataFrame(rows).to_csv(Path(out_dir) / "pretraining_wd_sincos_mask_sync_report.csv", index=False, encoding="utf-8-sig")\n        except Exception as e:\n            print(f"[WD sin/cos mask sync] failed to write report: {e}")\n    return out\n\n\n_supervised_multitask_loss_tf_before_sincos_wd_code2 = _supervised_multitask_loss_tf\n\n\ndef _supervised_multitask_loss_tf(y_true_concat, y_pred, n_outputs: int,\n                                  y_mean: np.ndarray, y_scale: np.ndarray,\n                                  records: Sequence[TargetRecord]):\n    """Masked supervised loss; sin/cos WD components use Huber in component space."""\n    if not any(_is_wd_sincos_target_record_code2(r) for r in records):\n        return _supervised_multitask_loss_tf_before_sincos_wd_code2(\n            y_true_concat=y_true_concat,\n            y_pred=y_pred,\n            n_outputs=n_outputs,\n            y_mean=y_mean,\n            y_scale=y_scale,\n            records=records,\n        )\n\n    tf, *_ = import_tf()\n    y_true = y_true_concat[:, 0:n_outputs]\n    mask = y_true_concat[:, n_outputs:2 * n_outputs]\n\n    y_mean_tf = tf.constant(np.asarray(y_mean, dtype=np.float32), dtype=tf.float32)\n    y_scale_tf = tf.constant(np.asarray(y_scale, dtype=np.float32), dtype=tf.float32)\n    y_true_phys = y_true * y_scale_tf[None, :] + y_mean_tf[None, :]\n    y_pred_phys = y_pred * y_scale_tf[None, :] + y_mean_tf[None, :]\n\n    def huber(e, delta=1.0):\n        abs_e = tf.abs(e)\n        return tf.where(abs_e <= delta, 0.5 * tf.square(e), delta * (abs_e - 0.5 * delta))\n\n    loss_cols = []\n    group_names = []\n    for j, r in enumerate(records):\n        if USE_WD_COSINE_ANGULAR_LOSS and str(r.var).lower() == "wd" and not _is_wd_sincos_target_record_code2(r):\n            # Backward-compatible path for scalar circular-degree WD targets.\n            angle_err_rad = (y_pred_phys[:, j] - y_true_phys[:, j]) * (math.pi / 180.0)\n            lj = WD_COSINE_LOSS_WEIGHT * (1.0 - tf.cos(angle_err_rad))\n        else:\n            # For sin/cos WD residual components, Huber in scaled component space is stable.\n            lj = huber(y_pred[:, j] - y_true[:, j], delta=1.0)\n        loss_cols.append(lj)\n        group_names.append(_task_group_from_record(r))\n\n    loss_mat = tf.stack(loss_cols, axis=1) if loss_cols else tf.zeros_like(y_pred)\n\n    if LOSS_AGGREGATION_MODE == "sample_weighted":\n        return tf.reduce_sum(mask * loss_mat) / (tf.reduce_sum(mask) + 1e-6)\n\n    group_losses = []\n    group_weights = []\n    for g in ["wind", "temp", "tke", "other"]:\n        idx = [j for j, gg in enumerate(group_names) if gg == g]\n        if not idx:\n            continue\n        target_losses = []\n        valid_flags = []\n        for j in idx:\n            mj = mask[:, j]\n            denom = tf.reduce_sum(mj)\n            valid = tf.cast(denom > 0.0, tf.float32)\n            target_losses.append(valid * tf.reduce_sum(mj * loss_mat[:, j]) / (denom + 1e-6))\n            valid_flags.append(valid)\n        valid_sum = tf.add_n(valid_flags) if valid_flags else tf.constant(0.0, dtype=tf.float32)\n        gl = tf.cond(\n            valid_sum > 0.0,\n            lambda tl=target_losses, vs=valid_sum: tf.add_n(tl) / (vs + 1e-6),\n            lambda: tf.constant(0.0, dtype=tf.float32),\n        )\n        gw = float(TASK_GROUP_WEIGHTS.get(g, 1.0))\n        group_losses.append(gl)\n        group_weights.append(tf.cast(gw, tf.float32) * tf.cast(valid_sum > 0.0, tf.float32))\n\n    if not group_losses:\n        return tf.reduce_sum(mask * loss_mat) / (tf.reduce_sum(mask) + 1e-6)\n    weighted = [w * l for w, l in zip(group_weights, group_losses)]\n    return tf.add_n(weighted) / (tf.add_n(group_weights) + 1e-6)\n\n\n_target_physical_arrays_before_sincos_wd_code2 = target_physical_arrays\n\n\ndef target_physical_arrays(df: pd.DataFrame, idx: np.ndarray, records: Sequence[TargetRecord], delta_pred: np.ndarray):\n    """Return physical arrays; reconstruct direct WD from predicted sin/cos residuals."""\n    if not any(_is_wd_sincos_target_record_code2(r) for r in records):\n        return _target_physical_arrays_before_sincos_wd_code2(df, idx, records, delta_pred)\n\n    data = []\n    handled_wd_keys = set()\n    for j, tr in enumerate(records):\n        if _is_wd_sincos_target_record_code2(tr):\n            key = (int(tr.height), tr.obs_col, tr.wrf_col)\n            if key in handled_wd_keys:\n                continue\n            i_sin, i_cos = _wd_sincos_pair_indices_code2(records, int(tr.height), tr.obs_col, tr.wrf_col)\n            if i_sin is None or i_cos is None:\n                continue\n            obs = pd.to_numeric(df.loc[idx, tr.obs_col], errors="coerce").values.astype(float)\n            base = pd.to_numeric(df.loc[idx, tr.wrf_col], errors="coerce").values.astype(float)\n            base_rad = np.deg2rad(base)\n            sin_corr = np.sin(base_rad) + delta_pred[:, i_sin]\n            cos_corr = np.cos(base_rad) + delta_pred[:, i_cos]\n            norm = np.sqrt(sin_corr ** 2 + cos_corr ** 2)\n            pred = np.full_like(base, np.nan, dtype=float)\n            ok = np.isfinite(norm) & (norm > 1e-12) & np.isfinite(sin_corr) & np.isfinite(cos_corr)\n            pred[ok] = (np.rad2deg(np.arctan2(sin_corr[ok] / norm[ok], cos_corr[ok] / norm[ok])) % 360.0)\n            delta_deg = circular_diff_deg(pred, base)\n            data.append({\n                "record": tr,\n                "var_label": "WD_direct",\n                "obs": obs,\n                "base": base,\n                "pred": pred,\n                "delta_pred": delta_deg,\n            })\n            handled_wd_keys.add(key)\n            continue\n\n        obs = pd.to_numeric(df.loc[idx, tr.obs_col], errors="coerce").values.astype(float)\n        base = pd.to_numeric(df.loc[idx, tr.wrf_col], errors="coerce").values.astype(float)\n        if tr.var == "log_tke":\n            delta = delta_pred[:, j]\n            pred = np.expm1(np.log1p(np.clip(base, 0.0, None)) + delta)\n            pred = np.clip(pred, 0.0, None)\n            var_label = "TKE"\n        elif tr.var == "ws":\n            pred = np.maximum(base + delta_pred[:, j], 0.0)\n            var_label = "WS_direct"\n        elif tr.var == "wd":\n            pred = (base + delta_pred[:, j]) % 360.0\n            var_label = "WD_direct"\n        else:\n            pred = base + delta_pred[:, j]\n            var_label = {"u": "u", "v": "v", "temp": "T"}.get(tr.var, tr.var)\n        data.append({"record": tr, "var_label": var_label, "obs": obs, "base": base, "pred": pred, "delta_pred": delta_pred[:, j]})\n    return data\n\n\n_build_prediction_table_and_metrics_before_sincos_wd_code2 = build_prediction_table_and_metrics\n\n\ndef build_prediction_table_and_metrics(\n    df: pd.DataFrame,\n    idx: np.ndarray,\n    records: Sequence[TargetRecord],\n    delta_pred: np.ndarray,\n    split_labels: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n) -> Tuple[pd.DataFrame, pd.DataFrame]:\n    """Prediction table/metrics with optional export of WD sin/cos component deltas."""\n    pred_df, metrics_df = _build_prediction_table_and_metrics_before_sincos_wd_code2(\n        df=df,\n        idx=idx,\n        records=records,\n        delta_pred=delta_pred,\n        split_labels=split_labels,\n        site_name=site_name,\n        model_name=model_name,\n        feature_mode=feature_mode,\n    )\n    if any(_is_wd_sincos_target_record_code2(r) for r in records):\n        for j, r in enumerate(records):\n            comp = _wd_sincos_component_code2(r)\n            if comp in {"sin", "cos"}:\n                pred_df[f"delta_WD{int(r.height)}_{comp}_pred"] = delta_pred[:, j]\n    return pred_df, metrics_df\n\n\n\n# =============================================================================\n# V8 PATCH: strict decomposition, WD-MAE raw-normalized scoring, and 10 m lambda diagnostics\n# =============================================================================\n# New diagnostic cases:\n#   C6m = PINN_MOSTmag_corrFDR_noSmooth\n#   C8d = MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_noSmooth\n# These keep lambda_smooth = 0, so they isolate MOST-magnitude loss from the\n# weak profile-smoothness loss used in C6/C8b/C8c.\n#\n# Scoring fix:\n#   The raw-normalized validation score now uses MAE ratio for WD keys and RMSE\n#   ratio for WS/T/TKE keys, if raw/baseline errors are available in the metrics.\n#\n# Profile-constraint diagnostics:\n#   C9/C10 still select the deployed best lambda by ALL_PROFILE, but their sweep\n#   CSV and metadata now also report an independent 10 m lambda choice. This is\n#   only a diagnostic to support Code1-vs-Code2 fair 10 m comparisons.\n\n\ndef _safe_float_v8(x, default=np.nan):\n    try:\n        y = pd.to_numeric(pd.Series([x]), errors="coerce").iloc[0]\n        return float(y) if np.isfinite(y) else default\n    except Exception:\n        return default\n\n\ndef standard_metrics(y_true, y_pred, y_base=None) -> Dict[str, float]:\n    """Final scalar metrics with raw/baseline RMSE and MAE columns for normalized scoring."""\n    yt0 = np.asarray(y_true, dtype=float).ravel()\n    yp0 = np.asarray(y_pred, dtype=float).ravel()\n    m = np.isfinite(yt0) & np.isfinite(yp0)\n    empty = {"N": int(m.sum()), "RMSE": np.nan, "MAE": np.nan, "MBE": np.nan,\n             "Pearson_r": np.nan, "NRMSE_pct": np.nan,\n             "Raw_RMSE": np.nan, "Raw_MAE": np.nan,\n             "Skill_RMSE_pct": np.nan, "Skill_MAE_pct": np.nan}\n    if m.sum() < 2:\n        return empty\n    yt = yt0[m]\n    yp = yp0[m]\n    rmse = float(np.sqrt(mean_squared_error(yt, yp)))\n    mae = float(mean_absolute_error(yt, yp))\n    mbe = float(np.mean(yp - yt))\n    pearson_r = float(np.corrcoef(yt, yp)[0, 1]) if np.std(yt) > 0 and np.std(yp) > 0 else np.nan\n    mean_obs = float(np.mean(yt))\n    nrmse = float(rmse / mean_obs * 100.0) if abs(mean_obs) > 1e-12 else np.nan\n    raw_rmse = np.nan\n    raw_mae = np.nan\n    skill_rmse = np.nan\n    skill_mae = np.nan\n    if y_base is not None:\n        yb0 = np.asarray(y_base, dtype=float).ravel()\n        yb = yb0[m]\n        mb = np.isfinite(yb)\n        if mb.sum() >= 2:\n            raw_rmse = float(np.sqrt(mean_squared_error(yt[mb], yb[mb])))\n            raw_mae = float(mean_absolute_error(yt[mb], yb[mb]))\n            pred_rmse_common = float(np.sqrt(mean_squared_error(yt[mb], yp[mb])))\n            pred_mae_common = float(mean_absolute_error(yt[mb], yp[mb]))\n            if raw_rmse > 1e-12:\n                skill_rmse = float((raw_rmse - pred_rmse_common) / raw_rmse * 100.0)\n            if raw_mae > 1e-12:\n                skill_mae = float((raw_mae - pred_mae_common) / raw_mae * 100.0)\n    return {"N": int(len(yt)), "RMSE": rmse, "MAE": mae, "MBE": mbe,\n            "Pearson_r": pearson_r, "NRMSE_pct": nrmse,\n            "Raw_RMSE": raw_rmse, "Raw_MAE": raw_mae,\n            "Skill_RMSE_pct": skill_rmse, "Skill_MAE_pct": skill_mae}\n\n\ndef direction_metrics(obs_wd, pred_wd, base_wd=None) -> Dict[str, float]:\n    """Final circular WD metrics with raw/baseline RMSE and MAE columns."""\n    obs0 = np.asarray(obs_wd, dtype=float).ravel()\n    pred0 = np.asarray(pred_wd, dtype=float).ravel()\n    m = np.isfinite(obs0) & np.isfinite(pred0)\n    empty = {"N": int(m.sum()), "RMSE": np.nan, "MAE": np.nan, "MBE": np.nan,\n             "Pearson_r": np.nan, "NRMSE_pct": np.nan,\n             "Raw_RMSE": np.nan, "Raw_MAE": np.nan,\n             "Skill_RMSE_pct": np.nan, "Skill_MAE_pct": np.nan}\n    if m.sum() < 2:\n        return empty\n    obs = obs0[m]\n    pred = pred0[m]\n    err = circular_diff_deg(pred, obs)\n    rmse = float(np.sqrt(np.mean(err ** 2)))\n    mae = float(np.mean(np.abs(err)))\n    mbe = float(np.mean(err))\n    raw_rmse = np.nan\n    raw_mae = np.nan\n    skill_rmse = np.nan\n    skill_mae = np.nan\n    if base_wd is not None:\n        base0 = np.asarray(base_wd, dtype=float).ravel()\n        base = base0[m]\n        mb = np.isfinite(base)\n        if mb.sum() >= 2:\n            base_err = circular_diff_deg(base[mb], obs[mb])\n            pred_err = circular_diff_deg(pred[mb], obs[mb])\n            raw_rmse = float(np.sqrt(np.mean(base_err ** 2)))\n            raw_mae = float(np.mean(np.abs(base_err)))\n            pred_rmse_common = float(np.sqrt(np.mean(pred_err ** 2)))\n            pred_mae_common = float(np.mean(np.abs(pred_err)))\n            if raw_rmse > 1e-12:\n                skill_rmse = float((raw_rmse - pred_rmse_common) / raw_rmse * 100.0)\n            if raw_mae > 1e-12:\n                skill_mae = float((raw_mae - pred_mae_common) / raw_mae * 100.0)\n    return {"N": int(m.sum()), "RMSE": rmse, "MAE": mae, "MBE": mbe,\n            "Pearson_r": np.nan, "NRMSE_pct": np.nan,\n            "Raw_RMSE": raw_rmse, "Raw_MAE": raw_mae,\n            "Skill_RMSE_pct": skill_rmse, "Skill_MAE_pct": skill_mae}\n\n\ndef _metric_ratio_to_raw_v8(row: pd.Series, key: str) -> float:\n    """Return model/raw error ratio using MAE for WD keys and RMSE for other keys."""\n    key = str(key)\n    use_mae = key.endswith("_MAE") or ("WD" in key and not key.endswith("_RMSE"))\n    if use_mae:\n        model_err = _safe_float_v8(row.get("MAE", np.nan))\n        raw_err = np.nan\n        for c in ["Raw_MAE", "Baseline_MAE", "WRF_MAE", "base_MAE", "raw_MAE"]:\n            if c in row.index:\n                raw_err = _safe_float_v8(row.get(c, np.nan))\n                if np.isfinite(raw_err):\n                    break\n        if np.isfinite(model_err) and np.isfinite(raw_err) and raw_err > 1e-12:\n            return float(model_err / raw_err)\n        skill_mae = _safe_float_v8(row.get("Skill_MAE_pct", np.nan))\n        if np.isfinite(skill_mae):\n            return float(max(0.0, 1.0 - skill_mae / 100.0))\n        # Defensive fallback only; should not be used once v8 metrics are active.\n        skill_rmse = _safe_float_v8(row.get("Skill_RMSE_pct", np.nan))\n        if np.isfinite(skill_rmse):\n            return float(max(0.0, 1.0 - skill_rmse / 100.0))\n        return np.nan\n\n    model_err = _safe_float_v8(row.get("RMSE", np.nan))\n    raw_err = np.nan\n    for c in ["Raw_RMSE", "Baseline_RMSE", "WRF_RMSE", "base_RMSE", "raw_RMSE"]:\n        if c in row.index:\n            raw_err = _safe_float_v8(row.get(c, np.nan))\n            if np.isfinite(raw_err):\n                break\n    if np.isfinite(model_err) and np.isfinite(raw_err) and raw_err > 1e-12:\n        return float(model_err / raw_err)\n    skill_rmse = _safe_float_v8(row.get("Skill_RMSE_pct", np.nan))\n    if np.isfinite(skill_rmse):\n        return float(max(0.0, 1.0 - skill_rmse / 100.0))\n    return np.nan\n\n\ndef validation_selection_score_for_height_v8(metrics_df: pd.DataFrame, height_m="ALL_PROFILE") -> float:\n    """Raw-normalized validation score for a chosen height or ALL_PROFILE.\n\n    WD uses MAE/raw-MAE ratio; WS/T/TKE use RMSE/raw-RMSE ratio.\n    """\n    if metrics_df is None or metrics_df.empty:\n        return np.inf\n    sub = metrics_df[\n        (metrics_df["split"].astype(str).str.lower() == "val") &\n        (metrics_df["height_m"].astype(str) == str(height_m))\n    ]\n    if sub.empty:\n        return np.inf\n    var_to_key = {\n        "WS_direct": "WS_direct_RMSE",\n        "WD_direct": "WD_direct_MAE",\n        "WS_from_uv": "WS_from_uv_RMSE",\n        "WD_from_uv": "WD_from_uv_MAE",\n        "T": "T_RMSE",\n        "TKE": "TKE_RMSE",\n    }\n    score = 0.0\n    wsum = 0.0\n    for _, row in sub.iterrows():\n        var = str(row.get("variable", ""))\n        key = var_to_key.get(var)\n        if key is None:\n            continue\n        w = float(PINN_SCORE_WEIGHTS.get(key, 0.0))\n        if w <= 0:\n            continue\n        ratio = _metric_ratio_to_raw_v8(row, key)\n        if not np.isfinite(ratio):\n            ratio = PINN_RAWNORM_FALLBACK_PENALTY\n        score += w * float(ratio)\n        wsum += w\n    return score / wsum if wsum > 0 else np.inf\n\n\ndef validation_selection_score(metrics_df: pd.DataFrame) -> float:\n    """Final v8 default: select by ALL_PROFILE raw-normalized validation score."""\n    return validation_selection_score_for_height_v8(metrics_df, height_m="ALL_PROFILE")\n\n\ndef _is_mostmag_no_smooth_case_code2(case_name: str) -> bool:\n    s = str(case_name).lower().replace("-", "_")\n    return (\n        "nosmooth" in s\n        or "no_smooth" in s\n        or s in {"c6m", "c8d"}\n    )\n\n\n# Extend case parser for pure MOSTmag no-smooth diagnostics.\n_case_mode_before_v8_nosmooth = _case_mode_v4\n\ndef _case_mode_v4(case: str):\n    c = str(case).strip().lower().replace("-", "_")\n    if c in {\n        "c6m",\n        "pinn_mostmag_corrfdr_nosmooth",\n        "pinn_mostmag_corrfdr_no_smooth",\n        "pinn_corrfdr_nosmooth",\n        "pinn_corrfdr_no_smooth",\n    }:\n        return "corrFDR", "PINN_MOSTmag_corrFDR_noSmooth", True, False, False, False\n    if c in {\n        "c8d",\n        "mostinput_pinn_mostmag_corrfdr_forcemost_nosmooth",\n        "mostinput_pinn_mostmag_corrfdr_force_most_no_smooth",\n        "mostinput_pinn_corrfdr_forcemost_nosmooth",\n        "mostinput_pinn_corrfdr_force_most_no_smooth",\n    }:\n        return "corrFDR", "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_noSmooth", True, True, False, True\n    return _case_mode_before_v8_nosmooth(case)\n\n\ndef _find_case_metrics_file_v8(run_dir: Path) -> Optional[Path]:\n    run_dir = Path(run_dir)\n    candidates = [\n        run_dir / "metrics_by_variable_train_val_test.csv",\n        run_dir / "metrics_train_val_test.csv",\n        run_dir / "ALL_cases_metrics_train_val_test.csv",\n    ]\n    for p in candidates:\n        if p.exists():\n            return p\n    hits = list(run_dir.rglob("metrics_by_variable_train_val_test.csv"))\n    if hits:\n        return hits[0]\n    hits = list(run_dir.rglob("metrics_train_val_test.csv"))\n    if hits:\n        return hits[0]\n    return None\n\n\ndef _add_height_metric_cols_to_row_v8(row: dict, metrics_df: pd.DataFrame, split: str, height_m: int, prefix: str) -> None:\n    if metrics_df is None or metrics_df.empty:\n        return\n    sub = metrics_df[\n        (metrics_df["split"].astype(str).str.lower() == str(split).lower()) &\n        (metrics_df["height_m"].astype(str) == str(height_m))\n    ]\n    for _, r in sub.iterrows():\n        var = str(r.get("variable", ""))\n        if not var:\n            continue\n        for metric in ["RMSE", "MAE", "Raw_RMSE", "Raw_MAE", "Skill_RMSE_pct", "Skill_MAE_pct"]:\n            if metric in r.index:\n                row[f"{prefix}_{var}_{metric}"] = r.get(metric, np.nan)\n\n\ndef _augment_profile_constraint_sweep_10m_v8(out_dir: Path, feature_mode: str) -> None:\n    """Add 10 m auxiliary lambda diagnostics to C9/C10 sweep outputs and metadata."""\n    out_dir = Path(out_dir)\n    sweep_path = out_dir / "profile_constraint_lambda_sweep_v6.csv"\n    if not sweep_path.exists():\n        return\n    try:\n        sw = pd.read_csv(sweep_path)\n    except Exception as e:\n        print(f"[v8 profile 10m diagnostics] cannot read {sweep_path}: {e}")\n        return\n    if sw.empty or "run_dir" not in sw.columns:\n        return\n    rows = []\n    for _, rr in sw.iterrows():\n        row = rr.to_dict()\n        run_dir = Path(str(rr.get("run_dir", "")))\n        metrics_path = _find_case_metrics_file_v8(run_dir)\n        if metrics_path is not None:\n            try:\n                md = pd.read_csv(metrics_path)\n                row["selection_score_10m_raw_normalized"] = validation_selection_score_for_height_v8(md, height_m=10)\n                _add_height_metric_cols_to_row_v8(row, md, split="val", height_m=10, prefix="val_10m")\n                _add_height_metric_cols_to_row_v8(row, md, split="test", height_m=10, prefix="test_10m")\n            except Exception as e:\n                row["selection_score_10m_raw_normalized"] = np.inf\n                row["v8_10m_read_error"] = repr(e)\n        else:\n            row["selection_score_10m_raw_normalized"] = np.inf\n            row["v8_10m_read_error"] = "metrics file not found"\n        rows.append(row)\n    out = pd.DataFrame(rows)\n    out.to_csv(out_dir / "profile_constraint_lambda_sweep_v8_with_10m.csv", index=False, encoding="utf-8-sig")\n    try:\n        (out_dir / "profile_constraint_lambda_sweep_v8_with_10m.txt").write_text(out.to_string(index=False), encoding="utf-8")\n    except Exception:\n        pass\n    try:\n        score_col = "selection_score_10m_raw_normalized"\n        ok = out[np.isfinite(pd.to_numeric(out.get(score_col, np.nan), errors="coerce"))].copy()\n        meta_path = out_dir / "metadata.json"\n        meta = {}\n        if meta_path.exists():\n            try:\n                meta = json.loads(meta_path.read_text(encoding="utf-8"))\n            except Exception:\n                meta = {}\n        if not ok.empty:\n            ok[score_col] = pd.to_numeric(ok[score_col], errors="coerce")\n            best10 = ok.sort_values(score_col, na_position="last").iloc[0]\n            meta.update({\n                "v8_profile_constraint_10m_auxiliary": True,\n                "best_lambda_profile_smooth_by_10m": _safe_float_v8(best10.get("lambda_profile_smooth", np.nan)),\n                "best_profile_selection_score_10m": _safe_float_v8(best10.get(score_col, np.nan)),\n                "profile_constraint_10m_note": (\n                    "The deployed C9/C10 best run is still selected by ALL_PROFILE. "\n                    "This 10 m result is an auxiliary diagnostic for fair Code1-vs-Code2 comparison."\n                ),\n            })\n        else:\n            meta.update({"v8_profile_constraint_10m_auxiliary": True,\n                         "profile_constraint_10m_note": "No finite 10 m lambda score was available."})\n        meta_path.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")\n    except Exception as e:\n        print(f"[v8 profile 10m diagnostics] metadata skipped for {feature_mode}: {e}")\n\n\n_train_one_feature_mode_before_v8 = train_one_feature_mode\n\ndef train_one_feature_mode(\n    df: pd.DataFrame,\n    target_records_all: Sequence[TargetRecord],\n    feature_cols: Sequence[str],\n    site_name: str,\n    model_name: str,\n    feature_mode: str,\n    out_dir: Path,\n    network: str,\n    use_pinn_mostmag: bool = False,\n) -> pd.DataFrame:\n    """Final v8 wrapper for noSmooth diagnostics and profile 10 m lambda output."""\n    no_smooth = _is_mostmag_no_smooth_case_code2(feature_mode)\n    if no_smooth:\n        old_smooth = globals().get("PINN_LAMBDA_SMOOTH", 0.0)\n        globals()["PINN_LAMBDA_SMOOTH"] = 0.0\n        try:\n            metrics_df = _train_one_feature_mode_before_v8(\n                df=df,\n                target_records_all=target_records_all,\n                feature_cols=feature_cols,\n                site_name=site_name,\n                model_name=model_name,\n                feature_mode=feature_mode,\n                out_dir=out_dir,\n                network=network,\n                use_pinn_mostmag=use_pinn_mostmag,\n            )\n        finally:\n            globals()["PINN_LAMBDA_SMOOTH"] = old_smooth\n        try:\n            if metrics_df is not None:\n                metrics_df["uses_profile_smoothness_loss"] = False\n                metrics_df["lambda_smooth_for_MOSTmag_v8"] = 0.0\n            meta_path = Path(out_dir) / "metadata.json"\n            meta = {}\n            if meta_path.exists():\n                try:\n                    meta = json.loads(meta_path.read_text(encoding="utf-8"))\n                except Exception:\n                    meta = {}\n            meta.update({\n                "script_version_v8": "code2_v8_sincosWD_noSmooth_WDmae10m",\n                "MOSTmag_noSmooth_case": True,\n                "uses_MOST_magnitude_loss": True,\n                "uses_profile_smoothness_loss": False,\n                "PINN_LAMBDA_SMOOTH_forced_to_zero": True,\n                "diagnostic_purpose": "Isolate MOST-magnitude loss from profile-smoothness regularization.",\n            })\n            meta_path.write_text(json.dumps(meta, ensure_ascii=False, indent=2), encoding="utf-8")\n        except Exception as e:\n            print(f"[v8 noSmooth metadata] skipped for {feature_mode}: {e}")\n        return metrics_df\n\n    metrics_df = _train_one_feature_mode_before_v8(\n        df=df,\n        target_records_all=target_records_all,\n        feature_cols=feature_cols,\n        site_name=site_name,\n        model_name=model_name,\n        feature_mode=feature_mode,\n        out_dir=out_dir,\n        network=network,\n        use_pinn_mostmag=use_pinn_mostmag,\n    )\n    if _is_profile_constraint_case_code2(feature_mode):\n        try:\n            _augment_profile_constraint_sweep_10m_v8(Path(out_dir), feature_mode)\n        except Exception as e:\n            print(f"[v8 profile 10m diagnostics] skipped for {feature_mode}: {e}")\n    return metrics_df\n\n# Mark the active target convention in metadata/config files where possible.\nSCRIPT_WD_TARGET_REPRESENTATION_NOTE = (\n    "Code2 direct WD targets use sin/cos residual components; WD metrics are reconstructed in degrees. "\n    "V8 uses WD MAE/raw-MAE ratio for lambda scoring, and adds noSmooth MOSTmag diagnostics plus 10 m profile-lambda diagnostics."\n)\n\n\n# =============================================================================\n# FINAL PATCH v9: Windows-safe short paths and short scenario labels\n# =============================================================================\n# This patch is appended after all v8 logic. It keeps the scientific design and\n# case semantics unchanged, but shortens directories, scenario labels and plot\n# filenames to avoid Windows MAX_PATH failures. The original requested case name\n# remains stored in case_v4_config.json and case_label_map_v9.csv/json.\n\nSCRIPT_SAFE_PATH_VERSION = "code2_v9_safePath"\n\nCASE_SHORT_LABELS_V9 = {\n    "raw_wrf": "C0",\n    "nomost_all": "C1",\n    "nomost_corrfdr": "C2",\n    "mostinput_all": "C3",\n    "mostinput_corrfdr": "C4",\n    "mostinput_corrfdr_forcemost": "C4b",\n    "pinn_mostmag_all": "C5",\n    "pinn_mostmag_corrfdr": "C6",\n    "pinn_mostmag_corrfdr_nosmooth": "C6m",\n    "mostinput_pinn_mostmag_all": "C7",\n    "mostinput_pinn_mostmag_corrfdr": "C8",\n    "mostinput_pinn_mostmag_corrfdr_forcemost": "C8b",\n    "mostinput_pinn_mostmag_corrfdr_forcemost_nosmooth": "C8d",\n    "mostinput_pinn_mostmag_corrfdr_forcemost_consistencygate": "C8c",\n    "profileconstraint_corrfdr": "C9",\n    "mostinput_profileconstraint_corrfdr_forcemost": "C10",\n    # Names produced by older parsers\n    "mostinput_pinn_corrfdr_forcemost": "C8b",\n    "mostinput_pinn_corrfdr_forcemost_consistencygate": "C8c",\n    "pinn_corrfdr": "C6",\n    "pinn_all": "C5",\n    "mostinput_pinn_all": "C7",\n    "mostinput_pinn_corrfdr": "C8",\n}\n\nCASE_LONG_LABELS_V9 = {\n    "C0": "raw_WRF",\n    "C1": "noMOST_all",\n    "C2": "noMOST_corrFDR",\n    "C3": "MOSTinput_all",\n    "C4": "MOSTinput_corrFDR",\n    "C4b": "MOSTinput_corrFDR_forceMOST",\n    "C5": "PINN_MOSTmag_all",\n    "C6": "PINN_MOSTmag_corrFDR",\n    "C6m": "PINN_MOSTmag_corrFDR_noSmooth",\n    "C7": "MOSTinput_PINN_MOSTmag_all",\n    "C8": "MOSTinput_PINN_MOSTmag_corrFDR",\n    "C8b": "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST",\n    "C8d": "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_noSmooth",\n    "C8c": "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_consistencyGate",\n    "C9": "ProfileConstraint_corrFDR",\n    "C10": "MOSTinput_ProfileConstraint_corrFDR_forceMOST",\n}\n\ndef _norm_case_key_v9(x: str) -> str:\n    return str(x).strip().lower().replace("-", "_").replace(" ", "")\n\ndef _short_case_label_v9(x: str) -> str:\n    key = _norm_case_key_v9(x)\n    if key in CASE_SHORT_LABELS_V9:\n        return CASE_SHORT_LABELS_V9[key]\n    return safe_name(str(x))[:24]\n\n_case_mode_before_v9_safePath = _case_mode_v4\n\ndef _case_mode_v4(case: str):\n    """v9 short-name parser: case logic unchanged; output label shortened."""\n    selection, feature_mode_name, use_pinn, use_most_input, is_raw, force_most = _case_mode_before_v9_safePath(case)\n    short = _short_case_label_v9(str(case))\n    # If requested case was unfamiliar but the produced feature_mode was known, use that.\n    if short == safe_name(str(case))[:24]:\n        short = _short_case_label_v9(str(feature_mode_name))\n    return selection, short, use_pinn, use_most_input, is_raw, force_most\n\n# Make profile/consistency/noSmooth detection explicit for the short labels.\ndef _is_profile_constraint_case_code2(case_name: str) -> bool:\n    s = _norm_case_key_v9(case_name)\n    return s in {"c9", "c10"} or "profileconstraint" in s or "profile_constraint" in s or "profilesmooth" in s or "profile_smooth" in s\n\ndef _is_consistency_gate_case_code2(case_name: str) -> bool:\n    s = _norm_case_key_v9(case_name)\n    return s == "c8c" or "consistencygate" in s or "consistency_gate" in s\n\ndef _is_mostmag_no_smooth_case_code2(case_name: str) -> bool:\n    s = _norm_case_key_v9(case_name)\n    return s in {"c6m", "c8d"} or "nosmooth" in s or "no_smooth" in s\n\n# Compact diagnostic plotting. This overrides the verbose v8 plotting function.\ndef _code2_plot_split_timeline(pred_csv: Path, out_dir: Path, tag: str):\n    try:\n        out_dir = ensure_dir(Path(out_dir))\n        dfp = pd.read_csv(pred_csv)\n        if "split" not in dfp.columns or TIME_COL not in dfp.columns:\n            return\n        dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n        order = ["train", "val", "test", "application"]\n        fig, ax = plt.subplots(figsize=(9.2, 2.4))\n        for i, sp in enumerate(order):\n            d = dfp[dfp["split"].astype(str).str.lower().eq(sp)]\n            if not d.empty:\n                ax.scatter(d[TIME_COL], np.full(len(d), i), s=3, label=sp)\n        ax.set_yticks(range(len(order))); ax.set_yticklabels(order)\n        ax.set_xlabel("Time"); ax.set_title(f"Split: {tag}")\n        ax.grid(True, axis="x", alpha=0.25); ax.legend(ncol=4, fontsize=7, loc="upper center", bbox_to_anchor=(0.5, -0.22))\n        fig.subplots_adjust(bottom=0.34, left=0.10, right=0.98, top=0.84)\n        fig.savefig(out_dir / "split.png", dpi=220)\n        plt.close(fig)\n    except Exception as e:\n        print(f"[plot v9] split timeline skipped: {e}")\n\ndef plot_profile_prediction_diagnostics(pred_csv: Path, out_dir: Path, feature_mode: str) -> None:\n    """v9 compact diagnostics: short filenames; creates parent dirs before saving."""\n    try:\n        out_dir = ensure_dir(Path(out_dir))\n        pred_csv = Path(pred_csv)\n        if not pred_csv.exists():\n            return\n        dfp = pd.read_csv(pred_csv)\n        if dfp.empty:\n            return\n        if "split" not in dfp.columns:\n            dfp["split"] = "all"\n        if TIME_COL in dfp.columns:\n            dfp[TIME_COL] = pd.to_datetime(dfp[TIME_COL], errors="coerce")\n        _code2_plot_split_timeline(pred_csv, out_dir, feature_mode)\n        heights = _code2_heights_from_cols(dfp)\n        specs = [\n            ("WS", "OBS_WS_direct{h}", "WRF_WS_direct{h}", "WS_direct{h}_corr_pred", "m/s", False),\n            ("WD", "OBS_WD_direct{h}", "WRF_WD_direct{h}", "WD_direct{h}_corr_pred", "deg", True),\n            ("TKE", "OBS_TKE{h}", "WRF_TKE{h}", "TKE{h}_corr_pred", "m2/s2", False),\n            ("T", "OBS_T{h}", "WRF_T{h}", "T{h}_corr_pred", "K", False),\n        ]\n        for split in ["train", "val", "test"]:\n            dft = dfp[dfp["split"].astype(str).str.lower().eq(split)].copy()\n            if dft.empty:\n                continue\n            x = dft[TIME_COL] if TIME_COL in dft.columns else np.arange(len(dft))\n            for label, ot, wt, pt, unit, is_wd in specs:\n                # compact mean profile for non-WD variables only\n                rows = []\n                for h in heights:\n                    oc, wc, pc = ot.format(h=h), wt.format(h=h), pt.format(h=h)\n                    if all(c in dft.columns for c in [oc, wc, pc]):\n                        rows.append((h, pd.to_numeric(dft[oc], errors="coerce").mean(),\n                                     pd.to_numeric(dft[wc], errors="coerce").mean(),\n                                     pd.to_numeric(dft[pc], errors="coerce").mean()))\n                if rows and not is_wd:\n                    arr = np.asarray(rows, float)\n                    fig, ax = plt.subplots(figsize=(4.8, 5.4))\n                    ax.plot(arr[:,1], arr[:,0], marker="o", label="OBS")\n                    ax.plot(arr[:,2], arr[:,0], marker="o", label="WRF")\n                    ax.plot(arr[:,3], arr[:,0], marker="o", label="Corr")\n                    ax.set_xlabel(f"{label} ({unit})"); ax.set_ylabel("Height (m)")\n                    ax.set_title(f"{feature_mode} {split} {label}")\n                    ax.grid(True, alpha=0.3); ax.legend(); fig.tight_layout()\n                    fig.savefig(out_dir / f"prof_{split}_{label}.png", dpi=220)\n                    plt.close(fig)\n                # a single representative time-series height, to reduce IO and path pressure.\n                for h in heights:\n                    oc, wc, pc = ot.format(h=h), wt.format(h=h), pt.format(h=h)\n                    if not all(c in dft.columns for c in [oc, wc, pc]):\n                        continue\n                    # Keep 10 m if present, otherwise first available height.\n                    if h != 10 and any((ot.format(h=10) in dft.columns, wt.format(h=10) in dft.columns, pt.format(h=10) in dft.columns)):\n                        continue\n                    fig, ax = plt.subplots(figsize=(10.5, 3.8))\n                    ax.plot(x, pd.to_numeric(dft[oc], errors="coerce"), label="OBS", linewidth=1.1)\n                    ax.plot(x, pd.to_numeric(dft[wc], errors="coerce"), label="WRF", linewidth=0.9, alpha=0.85)\n                    ax.plot(x, pd.to_numeric(dft[pc], errors="coerce"), label="Corr", linewidth=0.9, alpha=0.9)\n                    ax.set_xlabel("Time"); ax.set_ylabel(f"{label} {h} m ({unit})")\n                    ax.set_title(f"{feature_mode} {split}: {label} {h} m")\n                    ax.grid(True, alpha=0.3); ax.legend(); fig.tight_layout()\n                    fig.savefig(out_dir / f"ts_{split}_{label}_h{h}.png", dpi=220)\n                    plt.close(fig)\n                    break\n    except Exception as e:\n        print(f"[plot v9] profile diagnostics skipped for {feature_mode}: {e}")\n\n# Final v9 train wrapper: do not duplicate tower/height/site folders. The core adds\n# site_name once; the runner already adds network. This shortens Windows paths.\n_train_for_csv_before_v9_safePath = train_for_csv\n\ndef train_for_csv(train_csv: Path, output_root: Path, network: str = NETWORK,\n                  feature_modes: Sequence[str] = tuple(CODE_CASES),\n                  heights_m: Optional[Sequence[int]] = None,\n                  target_groups: Sequence[str] = DEFAULT_TARGET_GROUPS,\n                  date_start: Optional[str] = None,\n                  date_end: Optional[str] = None) -> pd.DataFrame:\n    train_csv = Path(train_csv)\n    root = ensure_dir(Path(output_root))\n    try:\n        # Case map at the network root for easy interpretation of short folders.\n        rows = [{"short_case": k, "full_case": v} for k, v in CASE_LONG_LABELS_V9.items()]\n        pd.DataFrame(rows).to_csv(root / "case_label_map_v9.csv", index=False, encoding="utf-8-sig")\n        (root / "case_label_map_v9.json").write_text(json.dumps(CASE_LONG_LABELS_V9, ensure_ascii=False, indent=2), encoding="utf-8")\n    except Exception as e:\n        print(f"[v9] case label map skipped: {e}")\n\n    result = _train_for_csv_code2_v4_core(\n        train_csv=train_csv,\n        output_root=root,\n        network=network,\n        feature_modes=feature_modes,\n        heights_m=heights_m,\n        target_groups=target_groups,\n        date_start=date_start,\n        date_end=date_end,\n    )\n    try:\n        plot_corrfdr_feature_screening_outputs(root)\n        plot_code2_case_timeseries_comparison(root)\n        export_effective_train_val_test_ranges_code2(root)\n        export_case_metrics_and_feature_audit_code2(root)\n        write_case_metrics_output_check_code2(root)\n        export_case_sample_consistency_check(root)\n    except Exception as e:\n        print(f"[postplot v9] skipped: {e}")\n    return result\n\nSCRIPT_WD_TARGET_REPRESENTATION_NOTE = (\n    "Code2 v9 safePath: direct WD targets use sin/cos residual components; "\n    "WD lambda selection uses MAE/raw-MAE ratio; case folders are shortened "\n    "to C0-C10 labels to avoid Windows path-length failures."\n)\n\nif __name__ == "__main__":\n    main()\n'
_SRC_C2_RUNNER = '#!/usr/bin/env python3\n# -*- coding: utf-8 -*-\n"""\nCode2_drop helper v9 safePath: C0-C8 + C4b/C8b/C8c + C9/C10 profile-constraint dual-network runner\n================================================================\n\nPurpose\n-------\nRun Code2_drop formal profile comparisons for both CNN_LSTM and TCN after the\nA0-A9 target-structure diagnosis.\n\nMain cases\n----------\nC0  raw_WRF\nC1  noMOST_all\nC2  noMOST_corrFDR\nC3  MOSTinput_all\nC4  MOSTinput_corrFDR\nC4b MOSTinput_corrFDR_forceMOST\nC5  PINN_MOSTmag_all\nC6  PINN_MOSTmag_corrFDR\nC7  MOSTinput_PINN_MOSTmag_all\nC8  MOSTinput_PINN_MOSTmag_corrFDR\nC8b MOSTinput_PINN_MOSTmag_corrFDR_forceMOST\nC8c MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_consistencyGate\nC9  ProfileConstraint_corrFDR\nC10 MOSTinput_ProfileConstraint_corrFDR_forceMOST\n\nv9 safePath changes\n----------\n1) Uses the v6 training script.\n2) Runs CNN_LSTM and TCN in one command by default.\n3) Keeps C4b/C8b diagnostic cases with MOST predictors force-kept in corrFDR.\n4) Sets PINN lambda selection to raw-WRF-normalized validation score.\n5) Adds C9/C10 independent profile-constraint cases with lambda sweep.\n6) Adds C8c: C8b plus MOST-OBS consistency gate.\n7) Keeps direct WS/WD + T + logTKE target groups fixed.\n"""\n\nfrom __future__ import annotations\n\nimport importlib.util\nimport json\nimport sys\nfrom pathlib import Path\nfrom typing import Any, Dict, List, Optional\n\n# =============================================================================\n# User configuration\n# =============================================================================\n\nCODE2_DROP_SCRIPT: Optional[Path] = Path(__file__).with_name(\n    "code2_train_profile_fair_ablation_v22_plus_perheight_metrics_drop_wd_uv_4m_50m_A8A9_directWS_PINN_C0C8_WSWD_TKE_T_fixed_v9_safePath.py"\n)\n\nFINAL_TARGET_GROUPS = ["wind_wswd", "temp", "log_tke"]\n\n# Edit this root only. Each network is written to a subfolder under it.\nBASE_OUTPUT_ROOT = Path(\n    r"D:\\wake\\WRF_RANS_wake\\xilinhaote\\result\\bias_correction\\1km\\correction\\muti_height\\training\\tower1\\t7\\c2v9"\n)\n\n# Run both. You can reduce to ["TCN"] or ["CNN_LSTM"] if needed.\nNETWORKS: List[str] = ["CNN_LSTM", "TCN"]\n\nRUN_C_CASES = [\n    "raw_WRF",\n    "noMOST_all",\n    "noMOST_corrFDR",\n    "MOSTinput_all",\n    "MOSTinput_corrFDR",\n    "MOSTinput_corrFDR_forceMOST",              # C4b diagnostic\n    "PINN_MOSTmag_all",\n    "PINN_MOSTmag_corrFDR",\n    "PINN_MOSTmag_corrFDR_noSmooth",          # C6m diagnostic: pure MOSTmag, no profile smoothness\n    "MOSTinput_PINN_MOSTmag_all",\n    "MOSTinput_PINN_MOSTmag_corrFDR",\n    "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST", # C8b diagnostic\n    "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_noSmooth", # C8d diagnostic: MOSTinput + pure MOSTmag\n    "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_consistencyGate", # C8c diagnostic\n    "ProfileConstraint_corrFDR",                  # C9 diagnostic: profile smoothness only\n    "MOSTinput_ProfileConstraint_corrFDR_forceMOST", # C10 diagnostic: MOST input + profile smoothness only\n]\n\nSTRICT_REQUIRE_MOSTINPUT_CASES = True\n\n# Optional overrides applied to the imported training module.\n# Common edits:\n#   "CODE_TRAIN_SITE_CONTAINS": "NO2_1107"\n#   "CODE_HEIGHTS_M": [4, 10, 30, 50, 70, 100]\n#   "EPOCHS": 400\n#   "BATCH_SIZE": 32\nCODE2_OVERRIDES: Dict[str, Any] = {\n    # "CODE_TRAIN_SITE_CONTAINS": "NO1_1159",\n    # "CODE_HEIGHTS_M": [4, 10, 30, 50, 70, 100],\n}\n\n# Raw-normalized PINN lambda score. Lower is better.\n# These are weights on model/raw validation-error ratios, not raw RMSE/MAE values.\n# Since the MOST loss directly constrains wind-speed magnitude, WS is emphasized.\nFORMAL_PINN_SCORE_WEIGHTS = {\n    "WS_direct_RMSE": 1.0,\n    "WD_direct_MAE": 0.3,\n    "WS_from_uv_RMSE": 1.0,   # backward compatibility only\n    "WD_from_uv_MAE": 0.3,    # backward compatibility only\n    "T_RMSE": 0.2,\n    "TKE_RMSE": 0.2,\n}\n\n# Profile-constraint-only cases C9/C10. This is a weak smoothness penalty on\n# the vertical curvature of the wind-speed correction residual profile. It does\n# not force WS_corr to match U_MO; C10 only uses MOST variables as inputs.\nPROFILE_CONSTRAINT_LAMBDA_CANDIDATES = [\n    0.0,\n    0.0001,\n    0.0003,\n    0.001,\n    0.003,\n    0.01,\n    0.03,\n    0.1,\n    0.3,\n    1.0,\n]\nPROFILE_CONSTRAINT_LAMBDA = 0.001\n\n# C8c MOST-OBS consistency gate settings. The gate is enabled only for C8c.\nMOST_OBS_CONSISTENCY_GATE_MODE = "sign_or_absdiff"\nMOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID = 0.25\nMOST_OBS_CONSISTENCY_ABS_TOL = 1.0\n\n# =============================================================================\n# Internal helpers\n# =============================================================================\n\ndef resolve_code2_drop_script() -> Path:\n    if CODE2_DROP_SCRIPT is not None:\n        p = Path(CODE2_DROP_SCRIPT)\n        if p.exists():\n            return p\n        print(f"[warning] Configured CODE2_DROP_SCRIPT not found: {p}")\n\n    candidates = [\n        Path(__file__).with_name("code2_train_profile_fair_ablation_v22_plus_perheight_metrics_drop_wd_uv_4m_50m_A8A9_directWS_PINN_C0C8_WSWD_TKE_T_fixed_v9_safePath.py"),\n        Path(__file__).with_name("code2_train_profile_fair_ablation_v22_plus_perheight_metrics_drop_wd_uv_4m_50m_A8A9_directWS_PINN_C0C8_WSWD_TKE_T_fixed_v3.py"),\n        Path(__file__).with_name("code2_train_profile_fair_ablation_v22_plus_perheight_metrics_drop_wd_uv_4m_50m_A8A9_directWS_PINN_C0C8_WSWD_TKE_T_fixed_v3(7).py"),\n        Path(__file__).with_name("code2_train_profile_fair_ablation_v22_plus_perheight_metrics_drop_wd_uv_4m_50m_A8A9_directWS_PINN_C0C8_WSWD_TKE_T.py"),\n    ]\n    for p in candidates:\n        if p.exists():\n            return p\n    raise FileNotFoundError("Cannot find Code2_drop v5 training script. Put this runner in the same folder as the training script or edit CODE2_DROP_SCRIPT.")\n\n\ndef load_code2_module(module_tag: str):\n    script = resolve_code2_drop_script()\n    mod_name = f"code2_drop_module_{module_tag}"\n    spec = importlib.util.spec_from_file_location(mod_name, str(script))\n    if spec is None or spec.loader is None:\n        raise ImportError(f"Cannot import {script}")\n    mod = importlib.util.module_from_spec(spec)\n    sys.modules[mod_name] = mod\n    spec.loader.exec_module(mod)\n    return mod, script\n\n\ndef apply_config(mod, network: str, output_root: Path) -> None:\n    for key, value in CODE2_OVERRIDES.items():\n        if value is not None:\n            setattr(mod, key, value)\n\n    output_root.mkdir(parents=True, exist_ok=True)\n\n    mod.USE_CODE_CONFIG = True\n    mod.CODE_NETWORK = str(network)\n    mod.CODE_OUTPUT_ROOT = str(output_root)\n    if hasattr(mod, "DEFAULT_OUTPUT_ROOT"):\n        mod.DEFAULT_OUTPUT_ROOT = str(output_root)\n\n    mod.CODE_CASES = list(RUN_C_CASES)\n    mod.CODE_TARGET_GROUPS = list(FINAL_TARGET_GROUPS)\n    if hasattr(mod, "DEFAULT_TARGET_GROUPS"):\n        mod.DEFAULT_TARGET_GROUPS = list(FINAL_TARGET_GROUPS)\n\n    mod.CODE_REQUIRE_MOSTINPUT_CASES = bool(STRICT_REQUIRE_MOSTINPUT_CASES)\n    mod.PINN_SCORE_WEIGHTS = dict(FORMAL_PINN_SCORE_WEIGHTS)\n    mod.PINN_LAMBDA_SELECTION_SCORE_MODE = "raw_normalized"\n    mod.FORCE_KEEP_MOST_FEATURES_IN_MOST_CORRFDR = True\n    mod.PROFILE_CONSTRAINT_LAMBDA = float(PROFILE_CONSTRAINT_LAMBDA)\n    mod.PROFILE_CONSTRAINT_LAMBDA_CANDIDATES = [float(x) for x in PROFILE_CONSTRAINT_LAMBDA_CANDIDATES]\n    mod.MOST_OBS_CONSISTENCY_GATE_MODE = str(MOST_OBS_CONSISTENCY_GATE_MODE)\n    mod.MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID = float(MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID)\n    mod.MOST_OBS_CONSISTENCY_ABS_TOL = float(MOST_OBS_CONSISTENCY_ABS_TOL)\n\n\ndef write_manifest(script_path: Path) -> None:\n    BASE_OUTPUT_ROOT.mkdir(parents=True, exist_ok=True)\n    manifest = {\n        "code2_drop_script": str(script_path),\n        "base_output_root": str(BASE_OUTPUT_ROOT),\n        "networks": NETWORKS,\n        "final_target_groups": FINAL_TARGET_GROUPS,\n        "run_cases": RUN_C_CASES,\n        "strict_require_mostinput_cases": STRICT_REQUIRE_MOSTINPUT_CASES,\n        "pinn_lambda_selection_score_mode": "raw_normalized",\n        "pinn_score_weights": FORMAL_PINN_SCORE_WEIGHTS,\n        "force_keep_most_features_in_most_corrFDR": True,\n        "diagnostic_cases": {\n            "C4b": "MOSTinput_corrFDR_forceMOST",\n            "C8b": "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST",\n            "C8c": "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_consistencyGate",\n            "C6m": "PINN_MOSTmag_corrFDR_noSmooth",\n            "C8d": "MOSTinput_PINN_MOSTmag_corrFDR_forceMOST_noSmooth",\n            "C9": "ProfileConstraint_corrFDR",\n            "C10": "MOSTinput_ProfileConstraint_corrFDR_forceMOST",\n        },\n        "profile_constraint_lambda_candidates": PROFILE_CONSTRAINT_LAMBDA_CANDIDATES,\n        "profile_constraint_lambda_default": PROFILE_CONSTRAINT_LAMBDA,\n        "MOST_OBS_consistency_gate": {\n            "C8c_enabled_only": True,\n            "mode": MOST_OBS_CONSISTENCY_GATE_MODE,\n            "min_abs_obs_resid": MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID,\n            "abs_tol": MOST_OBS_CONSISTENCY_ABS_TOL,\n        },\n        "target_structure_source": "Selected from Code2 A0-A9 first-level diagnosis: direct WS/WD + T + logTKE; WD direct targets are trained as sin/cos residual components in the v9_safePath training script.",\n        "effective_drop_rule": "Code2_drop removes WD/U/V targets and WRF_U/WRF_V/WRF_WD input features at 4 m and 50 m; WS, T, and TKE remain.",\n    }\n    with open(BASE_OUTPUT_ROOT / "manifest_v9.json", "w", encoding="utf-8") as f:\n        json.dump(manifest, f, ensure_ascii=False, indent=2)\n\n\ndef main() -> None:\n    script_for_manifest = resolve_code2_drop_script()\n    write_manifest(script_for_manifest)\n\n    print("=" * 100)\n    print("Running Code2_drop v9 safePath C0-C10 for networks:", NETWORKS)\n    print(f"FINAL_TARGET_GROUPS: {FINAL_TARGET_GROUPS}")\n    print(f"RUN_C_CASES: {RUN_C_CASES}")\n    print(f"OUTPUT_ROOT: {BASE_OUTPUT_ROOT}")\n    print(f"CODE2_DROP_SCRIPT: {script_for_manifest}")\n    print("=" * 100)\n\n    for network in NETWORKS:\n        network_root = BASE_OUTPUT_ROOT / network\n        print("=" * 100)\n        print(f"Start network: {network}")\n        print(f"Network output root: {network_root}")\n        mod, script = load_code2_module(network.lower())\n        apply_config(mod, network, network_root)\n        mod.main()\n        print(f"Finished network: {network}")\n        print("=" * 100)\n\n    print("Code2_drop v9 safePath dual-network run finished.")\n    print(f"All outputs are under: {BASE_OUTPUT_ROOT}")\n\n\nif __name__ == "__main__":\n    main()\n'


def _load_module_from_source(source: str, module_name: str):
    mod = types.ModuleType(module_name)
    mod.__file__ = str(Path(__file__).resolve())
    mod.__package__ = ""
    sys.modules[module_name] = mod
    exec(compile(source, module_name, "exec"), mod.__dict__)
    return mod


def _network_tag(network: str) -> str:
    s = str(network).upper().replace("-", "_")
    if s in {"CNN_LSTM", "CNNLSTM"}:
        return "CNN_LSTM"
    if s == "TCN":
        return "TCN"
    return s[:6]


def _new_runner(tag: str):
    return _load_module_from_source(_SRC_C2_RUNNER, f"c2_run_{tag}_{time.time_ns()}")


def _new_train(site: Dict[str, Any], network: str, tag: str):
    mod = _load_module_from_source(_SRC_C2_TRAIN, f"c2_tr_{site['tag']}_{_network_tag(network)}_{tag}_{time.time_ns()}")
    _patch_short_runtime(mod)
    return mod


def _patch_short_runtime(mod) -> None:
    """Patch embedded safe_name robustly.

    Some embedded Code2 versions define safe_name(text) without a max_len keyword,
    while later calls may pass max_len=. Also, this wrapper can be invoked more
    than once on the same embedded module, so it must be idempotent.
    """
    if hasattr(mod, "safe_name"):
        if getattr(mod.safe_name, "_xht_short_safe_name_patched", False):
            return
        _orig_safe_name = mod.safe_name

        def _short_safe_name(text, max_len=80):
            limit = min(int(max_len), int(SHORT_NAME_MAX))
            try:
                value = _orig_safe_name(text, max_len=limit)
            except TypeError:
                value = _orig_safe_name(text)
            return str(value)[:limit]

        _short_safe_name._xht_short_safe_name_patched = True
        _short_safe_name._orig_safe_name = _orig_safe_name
        mod.safe_name = _short_safe_name



# =============================================================================
# Gryning/MOST diagnostic reference injection for Code2 MOSTinput/PINN cases
# =============================================================================
# Purpose:
#   1) replace per-height wind MOST reference U_MO(h) with
#      Gryning_fixed_z0_vegetation500 diagnostic wind speed;
#   2) add per-height thermal diagnostic inputs T_MO(h) from
#      MOST_T_free_inv_z0h_theta;
#   3) extend MOSTinput feature candidates so T_MO and T_MO_minus_WRF can be used
#      by MOSTinput and MOSTinput+PINN cases. The PINN loss itself remains the
#      original wind-speed-magnitude loss unless the embedded trainer is extended
#      with a thermal PINN loss.
DIAG_REFERENCE_ROOT = Path(r"D:\wake\WRF_RANS_wake\xilinhaote\result\bias_correction\1km\inputdata\data_post_new\gryning_diagnostics")
DIAG_U_LONG_CSV = DIAG_REFERENCE_ROOT / "20_U_diagnostics" / "22_U_timeseries_long_all_methods_all_files.csv"
DIAG_T_LONG_CSV = DIAG_REFERENCE_ROOT / "30_T_diagnostics" / "32_T_timeseries_long_all_methods_all_files.csv"
DIAG_U_METHOD = "Gryning_fixed_z0_vegetation500"
DIAG_T_METHOD = "MOST_T_free_inv_z0h_theta"
DIAG_DATASET_VERSION_BY_MODE = {
    "10min": "D10_10min_original",
    "1h": "D1H_1hour_aggregated",
    "original": "D10_10min_original",
}
DIAG_REQUIRE_U_REFERENCE = True
DIAG_REQUIRE_T_REFERENCE = True


def _diag_dataset_version() -> str:
    return DIAG_DATASET_VERSION_BY_MODE.get(str(globals().get("TIME_RESOLUTION_MODE", "1h")), "D1H_1hour_aggregated")


def _diag_first_existing(df, candidates):
    for c in candidates:
        if c in df.columns:
            return c
    return None


def _diag_try_candidates(mod, name: str, h: int):
    fn = getattr(mod, name, None)
    if callable(fn):
        try:
            return list(fn(int(h)))
        except Exception:
            return []
    return []


def _diag_candidate_col(mod, df, name: str, h: int):
    return _diag_first_existing(df, _diag_try_candidates(mod, name, h))


def _diag_site_mask(df, site_key: str):
    import pandas as _pd
    m = _pd.Series(True, index=df.index)
    site_cols = [c for c in ["site_id", "relative_file", "csv_file"] if c in df.columns]
    if site_cols:
        sm = _pd.Series(False, index=df.index)
        for c in site_cols:
            sm = sm | df[c].astype(str).str.contains(str(site_key), case=False, na=False)
        m &= sm
    return m


def _diag_load_long(path: Path, method: str, site_key: str, require: bool, label: str):
    import pandas as _pd
    if not path.exists():
        if require:
            raise FileNotFoundError(f"{label} diagnostic long table not found: {path}")
        return _pd.DataFrame()
    g = _pd.read_csv(path)
    required = {"time", "method", "height_m", "pred"}
    missing = required - set(g.columns)
    if missing:
        raise ValueError(f"{label} diagnostic long table lacks required columns: {sorted(missing)}")
    g["time"] = _pd.to_datetime(g["time"], errors="coerce")
    g["height_m"] = _pd.to_numeric(g["height_m"], errors="coerce")
    g["pred"] = _pd.to_numeric(g["pred"], errors="coerce")
    m = g["method"].astype(str).eq(method)
    if "dataset_version" in g.columns:
        m &= g["dataset_version"].astype(str).eq(_diag_dataset_version())
    m &= _diag_site_mask(g, site_key)
    out = g.loc[m, ["time", "height_m", "pred"]].dropna().copy()
    if out.empty and require:
        raise ValueError(f"No {label} rows matched site={site_key}, method={method}, dataset_version={_diag_dataset_version()} in {path}")
    return out


def _diag_inject_profile_references_code2(mod, df, site: Dict[str, Any], csv_path: Path):
    import pandas as _pd
    out = df.copy()
    time_col = getattr(mod, "TIME_COL", "北京时间")
    if time_col not in out.columns:
        raise ValueError(f"ML-ready dataframe lacks time column: {time_col}")
    out[time_col] = _pd.to_datetime(out[time_col], errors="coerce")
    site_key = str(site.get("key", ""))
    report = {
        "diag_reference_root": str(DIAG_REFERENCE_ROOT),
        "dataset_version": _diag_dataset_version(),
        "u_method": DIAG_U_METHOD,
        "t_method": DIAG_T_METHOD,
        "site_key": site_key,
        "csv_path": str(csv_path),
        "u_heights": [],
        "t_heights": [],
    }

    gu = _diag_load_long(DIAG_U_LONG_CSV, DIAG_U_METHOD, site_key, DIAG_REQUIRE_U_REFERENCE, "U")
    for h0 in sorted(gu["height_m"].dropna().unique()):
        h = int(round(float(h0)))
        gh = gu.loc[gu["height_m"].round(6).eq(float(h0)), ["time", "pred"]].groupby("time", as_index=False)["pred"].mean()
        src = f"__diag_U_MO{h}"
        gh = gh.rename(columns={"pred": src})
        out = out.merge(gh, how="left", left_on=time_col, right_on="time")
        if "time" in out.columns and time_col != "time":
            out = out.drop(columns=["time"])
        u_col = f"U_MO{h} (m/s)"
        most_ws_col = f"MOST_WS{h} (m/s)"
        mo_minus_col = f"MO_minus_WRF{h} (m/s)"
        keep_col = f"GryningVeg_U_MO{h} (m/s)"
        for c in [u_col, most_ws_col, mo_minus_col]:
            if c in out.columns and f"{c}_old" not in out.columns:
                out[f"{c}_old"] = out[c]
        out[u_col] = _pd.to_numeric(out[src], errors="coerce")
        out[most_ws_col] = out[u_col]
        out[keep_col] = out[u_col]
        wrf_ws_col = _diag_candidate_col(mod, out, "wrf_ws_candidates", h)
        if wrf_ws_col is not None:
            out[mo_minus_col] = out[u_col] - _pd.to_numeric(out[wrf_ws_col], errors="coerce")
        valid = int(out[u_col].notna().sum())
        report["u_heights"].append({"height_m": h, "valid": valid, "wrf_ws_col": wrf_ws_col, "u_mo_col": u_col, "mo_minus_col": mo_minus_col})
        out = out.drop(columns=[src], errors="ignore")

    gt = _diag_load_long(DIAG_T_LONG_CSV, DIAG_T_METHOD, site_key, DIAG_REQUIRE_T_REFERENCE, "T")
    for h0 in sorted(gt["height_m"].dropna().unique()):
        h = int(round(float(h0)))
        gh = gt.loc[gt["height_m"].round(6).eq(float(h0)), ["time", "pred"]].groupby("time", as_index=False)["pred"].mean()
        src = f"__diag_T_MO{h}"
        gh = gh.rename(columns={"pred": src})
        out = out.merge(gh, how="left", left_on=time_col, right_on="time")
        if "time" in out.columns and time_col != "time":
            out = out.drop(columns=["time"])
        t_col = f"T_MO{h} (K)"
        most_t_col = f"MOST_T{h} (K)"
        t_minus_col = f"T_MO_minus_WRF{h} (K)"
        most_t_minus_col = f"MOST_T_minus_WRF{h} (K)"
        keep_col = f"GryningThermal_T_MO{h} (K)"
        for c in [t_col, most_t_col, t_minus_col, most_t_minus_col]:
            if c in out.columns and f"{c}_old" not in out.columns:
                out[f"{c}_old"] = out[c]
        out[t_col] = _pd.to_numeric(out[src], errors="coerce")
        out[most_t_col] = out[t_col]
        out[keep_col] = out[t_col]
        wrf_t_col = _diag_candidate_col(mod, out, "wrf_temp_candidates", h)
        if wrf_t_col is not None:
            out[t_minus_col] = out[t_col] - _pd.to_numeric(out[wrf_t_col], errors="coerce")
            out[most_t_minus_col] = out[t_minus_col]
        valid = int(out[t_col].notna().sum())
        report["t_heights"].append({"height_m": h, "valid": valid, "wrf_t_col": wrf_t_col, "t_mo_col": t_col, "t_minus_col": t_minus_col})
        out = out.drop(columns=[src], errors="ignore")

    out.attrs["diag_reference_injection"] = report
    return out, report


def _diag_extend_code2_most_candidates(mod) -> None:
    if hasattr(mod, "most_input_candidates_for_height") and not getattr(mod.most_input_candidates_for_height, "_diag_t_extended", False):
        _orig = mod.most_input_candidates_for_height
        def _most_input_candidates_with_t(h: int):
            vals = list(_orig(int(h)))
            vals.extend([
                f"T_MO{int(h)} (K)", f"T_MO_{int(h)}m (K)", f"T_MO{int(h)}",
                f"MOST_T{int(h)} (K)", f"MOST_T{int(h)}",
                f"T_MO_minus_WRF{int(h)} (K)", f"T_MO_minus_WRF_{int(h)}m (K)", f"T_MO_minus_WRF{int(h)}",
                f"MOST_T_minus_WRF{int(h)} (K)", f"MOST_T_minus_WRF_{int(h)}m (K)", f"MOST_T_minus_WRF{int(h)}",
                f"GryningThermal_T_MO{int(h)} (K)",
            ])
            return list(dict.fromkeys(vals))
        _most_input_candidates_with_t._diag_t_extended = True
        mod.most_input_candidates_for_height = _most_input_candidates_with_t


def _diag_numeric_summary_text(df, col: str) -> str:
    import pandas as _pd
    if col is None:
        return "MISSING"
    if col not in df.columns:
        return f"MISSING | requested={col}"
    s = _pd.to_numeric(df[col], errors="coerce")
    n = int(s.notna().sum())
    total = int(len(s))
    if n == 0:
        return f"FOUND | col={col} | valid=0/{total}"
    return (
        f"FOUND | col={col} | valid={n}/{total} | "
        f"mean={float(s.mean()):.6g} | min={float(s.min()):.6g} | max={float(s.max()):.6g}"
    )


def _diag_actual_heights_for_code2(mod, df):
    import numpy as _np
    heights = []
    cfg = getattr(mod, "CODE_HEIGHTS_M", None)
    if cfg is not None:
        try:
            heights = [int(h) for h in cfg]
        except Exception:
            heights = []
    if not heights and hasattr(mod, "auto_detect_heights"):
        try:
            heights = [int(h) for h in mod.auto_detect_heights(df)]
        except Exception:
            heights = []
    if not heights:
        heights = list(CODE_HEIGHTS_M or [])
    return sorted({int(h) for h in heights if _np.isfinite(float(h))})


def _diag_write_input_diag_txt(mod, df, site: Dict[str, Any], network: str, out_root: Path, report: Dict[str, Any]) -> None:
    """Write a detailed Code2 input-diagnostic report.

    It records diagnostic U/T reference injection, target/input column discovery,
    MOST candidate availability, and the 4 m / 50 m WD-U-V drop rule status.
    """
    try:
        import pandas as _pd
        diag_dir = Path(out_root) / "diag_inputs"
        diag_dir.mkdir(parents=True, exist_ok=True)
        txt_path = diag_dir / f"diag_input_{site.get('tag', site.get('key', 'site'))}_{network}_{Path(report.get('csv_path','input')).stem}.txt"
        heights = _diag_actual_heights_for_code2(mod, df)

        lines = []
        lines.append("Xilinhaote Code2 input diagnostics")
        lines.append("=" * 100)
        for k in ["diag_reference_root", "dataset_version", "u_method", "t_method", "site_key", "csv_path"]:
            lines.append(f"{k}: {report.get(k)}")
        lines.append(f"network: {network}")
        lines.append(f"output_root: {out_root}")
        lines.append(f"rows_after_original_load: {len(df)}")
        time_col = getattr(mod, "TIME_COL", "北京时间")
        if time_col in df.columns:
            ts = _pd.to_datetime(df[time_col], errors="coerce")
            lines.append(f"time_col: {time_col} | valid={int(ts.notna().sum())}/{len(ts)} | start={ts.min()} | end={ts.max()}")
        lines.append(f"CODE_HEIGHTS_M/effective_heights: {heights}")
        lines.append("")

        lines.append("[U diagnostic reference injection]")
        lines.append(f"source_csv: {DIAG_U_LONG_CSV}")
        for item in report.get("u_heights", []):
            h = int(item.get("height_m"))
            cols = [item.get("u_mo_col"), f"MOST_WS{h} (m/s)", item.get("mo_minus_col"), f"GryningVeg_U_MO{h} (m/s)"]
            lines.append(f"--- height {h} m | matched_valid={item.get('valid')} | wrf_ws_col={item.get('wrf_ws_col')} ---")
            for c in cols:
                lines.append(f"  {_diag_numeric_summary_text(df, c)}")
        lines.append("")

        lines.append("[T diagnostic reference injection]")
        lines.append(f"source_csv: {DIAG_T_LONG_CSV}")
        for item in report.get("t_heights", []):
            h = int(item.get("height_m"))
            cols = [item.get("t_mo_col"), f"MOST_T{h} (K)", item.get("t_minus_col"), f"MOST_T_minus_WRF{h} (K)", f"GryningThermal_T_MO{h} (K)"]
            lines.append(f"--- height {h} m | matched_valid={item.get('valid')} | wrf_t_col={item.get('wrf_t_col')} ---")
            for c in cols:
                lines.append(f"  {_diag_numeric_summary_text(df, c)}")
        lines.append("")

        lines.append("[Surface/PBL/time features]")
        for c in ["WRF_L (m)", "WRF_PBLH (m)", "WRF_Bulk_Ri", "UST (m/s)", "Z0 (m)", "HFX (W/m2)", "PSFC (Pa)", "T2 (K)", "hour_sin", "hour_cos"]:
            lines.append(f"  {_diag_numeric_summary_text(df, c)}")
        lines.append("")

        excluded_heights = set()
        try:
            excluded_heights = {int(h) for h in getattr(mod, "CODE_EXCLUDE_WD_UV_HEIGHTS_M", [4, 50])}
        except Exception:
            excluded_heights = {4, 50}
        excluded_vars = set(getattr(mod, "CODE_EXCLUDE_WD_UV_VARS", {"wd", "u", "v"}))
        lines.append("[4 m / 50 m WD-U-V drop rule]")
        lines.append(f"excluded_heights: {sorted(excluded_heights)}")
        lines.append(f"excluded_vars: {sorted(str(x) for x in excluded_vars)}")
        lines.append("Meaning: at these heights, WD/U/V targets and WRF_U/WRF_V/WRF_WD input features are excluded; WS, T, and TKE remain.")
        lines.append("")

        lines.append("[Per-height OBS/WRF target/input column discovery]")
        for h in heights:
            lines.append(f"--- height {h} m ---")
            drop_note = "YES" if int(h) in excluded_heights else "NO"
            lines.append(f"  wd_u_v_drop_for_training: {drop_note}")
            checks = [
                ("OBS_WS", _diag_candidate_col(mod, df, "obs_ws_candidates", h)),
                ("WRF_WS", _diag_candidate_col(mod, df, "wrf_ws_candidates", h)),
                ("OBS_WD", _diag_candidate_col(mod, df, "obs_wd_candidates", h)),
                ("WRF_WD", _diag_candidate_col(mod, df, "wrf_wd_candidates", h)),
                ("OBS_U", _diag_candidate_col(mod, df, "obs_u_candidates", h)),
                ("OBS_V", _diag_candidate_col(mod, df, "obs_v_candidates", h)),
                ("WRF_U", _diag_candidate_col(mod, df, "wrf_u_candidates", h)),
                ("WRF_V", _diag_candidate_col(mod, df, "wrf_v_candidates", h)),
                ("OBS_T", _diag_candidate_col(mod, df, "obs_temp_candidates", h)),
                ("WRF_T", _diag_candidate_col(mod, df, "wrf_temp_candidates", h)),
                ("OBS_TKE", _diag_candidate_col(mod, df, "obs_tke_candidates", h)),
                ("WRF_TKE", _diag_candidate_col(mod, df, "wrf_tke_candidates", h)),
            ]
            for label, col in checks:
                suffix = ""
                if int(h) in excluded_heights and label in {"OBS_WD", "WRF_WD", "OBS_U", "OBS_V", "WRF_U", "WRF_V"}:
                    suffix = " | DROP_RULE: column may exist but is not used as WD/U/V target/input at this height"
                lines.append(f"  {label}: {_diag_numeric_summary_text(df, col)}{suffix}")

            if hasattr(mod, "most_input_candidates_for_height"):
                try:
                    candidates = list(mod.most_input_candidates_for_height(int(h)))
                except Exception:
                    candidates = []
                found = [c for c in candidates if c in df.columns]
                missing = [c for c in candidates if c not in df.columns]
                lines.append(f"  MOST candidates found ({len(found)}): {found}")
                lines.append(f"  MOST candidates missing ({len(missing)}): {missing[:30]}{' ...' if len(missing) > 30 else ''}")
            lines.append("")

        txt_path.write_text("\n".join(lines), encoding="utf-8")
    except Exception as e:
        print(f"[diag] Failed to write diagnostic reference report: {e}")


def _patch_gryning_loader(mod, site: Dict[str, Any], network: str, out_root: Path) -> None:
    _diag_extend_code2_most_candidates(mod)
    if not hasattr(mod, "load_ml_ready"):
        return
    if getattr(mod.load_ml_ready, "_diag_reference_patched", False):
        return
    _orig_load_ml_ready = mod.load_ml_ready

    def _load_ml_ready_with_diag_refs(csv_path, *args, **kwargs):
        df = _orig_load_ml_ready(csv_path, *args, **kwargs)
        df, report = _diag_inject_profile_references_code2(mod, df, site, Path(csv_path))
        _diag_write_input_diag_txt(mod, df, site, network, Path(out_root), report)
        return df

    _load_ml_ready_with_diag_refs._diag_reference_patched = True
    mod.load_ml_ready = _load_ml_ready_with_diag_refs

def run_one(site: Dict[str, Any], network: str):
    runner = _new_runner("main")

    # Make the embedded training module replace the external CODE2_DROP_SCRIPT import.
    def _load_code2_module(module_tag: str):
        mod = _new_train(site, network, module_tag)
        return mod, Path(__file__).resolve()
    runner.load_code2_module = _load_code2_module
    runner.resolve_code2_drop_script = lambda: Path(__file__).resolve()

    # Patch runner-level configuration while preserving original apply_config/main logic.
    out_root = Path(BASE_OUTPUT_ROOT) / site["tag"] / _network_tag(network)
    runner.BASE_OUTPUT_ROOT = out_root
    runner.NETWORKS = [network]
    runner.RUN_C_CASES = list(RUN_C_CASES)
    runner.FINAL_TARGET_GROUPS = list(FINAL_TARGET_GROUPS)
    runner.STRICT_REQUIRE_MOSTINPUT_CASES = bool(STRICT_REQUIRE_MOSTINPUT_CASES)
    runner.FORMAL_PINN_SCORE_WEIGHTS = dict(FORMAL_PINN_SCORE_WEIGHTS)
    runner.PROFILE_CONSTRAINT_LAMBDA_CANDIDATES = [float(x) for x in PROFILE_CONSTRAINT_LAMBDA_CANDIDATES]
    runner.PROFILE_CONSTRAINT_LAMBDA = float(PROFILE_CONSTRAINT_LAMBDA)
    runner.MOST_OBS_CONSISTENCY_GATE_MODE = MOST_OBS_CONSISTENCY_GATE_MODE
    runner.MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID = float(MOST_OBS_CONSISTENCY_MIN_ABS_OBS_RESID)
    runner.MOST_OBS_CONSISTENCY_ABS_TOL = float(MOST_OBS_CONSISTENCY_ABS_TOL)
    runner.CODE2_OVERRIDES = dict(getattr(runner, "CODE2_OVERRIDES", {}))
    runner.CODE2_OVERRIDES.update({
        "CODE_ML_READY_ROOT": Path(CODE_ML_READY_ROOT),
        "CODE_TRAIN_FILE_GLOB": CODE_TRAIN_FILE_GLOB,
        "CODE_TRAIN_SITE_CONTAINS": site["key"],
        "CODE_HEIGHTS_M": list(CODE_HEIGHTS_M) if CODE_HEIGHTS_M is not None else None,
        "WINDOW_TARGET_REQUIRE_MODE": "any",
    })

    out_root.mkdir(parents=True, exist_ok=True)
    runner.write_manifest(Path(__file__).resolve())

    mod, _script = runner.load_code2_module(_network_tag(network).lower())
    runner.apply_config(mod, network, out_root)
    _patch_short_runtime(mod)
    _patch_gryning_loader(mod, site, network, out_root)

    # Ensure site selection and short output settings survive any default config in the embedded source.
    mod.CODE_ML_READY_ROOT = Path(CODE_ML_READY_ROOT)
    mod.CODE_TRAIN_FILE_GLOB = CODE_TRAIN_FILE_GLOB
    mod.CODE_TRAIN_SITE_CONTAINS = site["key"]
    mod.CODE_HEIGHTS_M = list(CODE_HEIGHTS_M) if CODE_HEIGHTS_M is not None else None
    mod.CODE_CASES = list(RUN_C_CASES)
    mod.CODE_TARGET_GROUPS = list(FINAL_TARGET_GROUPS)
    mod.CODE_OUTPUT_ROOT = str(out_root)
    mod.CODE_NETWORK = network
    mod.USE_CODE_CONFIG = True

    # Run the original Code2 main workflow.
    mod.main()
    return True


def _write_top_manifest() -> None:
    root = Path(BASE_OUTPUT_ROOT)
    root.mkdir(parents=True, exist_ok=True)
    manifest = {
        "wind_farm": "xilinhaote",
        "script": Path(__file__).name,
        "ml_ready_root": str(CODE_ML_READY_ROOT),
        "train_file_glob": CODE_TRAIN_FILE_GLOB,
        "base_output_root": str(root),
        "networks": NETWORKS,
        "sites": SITES,
        "heights_m": CODE_HEIGHTS_M,
        "final_target_groups": FINAL_TARGET_GROUPS,
        "run_cases": RUN_C_CASES,
        "short_name_policy": "Output root uses short site/network folders. Case folders use C0/C1/... labels from v9 safePath. safe_name is capped by SHORT_NAME_MAX.",
        "short_name_max": SHORT_NAME_MAX,
    }
    (root / "manifest_c2.json").write_text(json.dumps(manifest, ensure_ascii=False, indent=2), encoding="utf-8")


def main() -> None:
    _write_top_manifest()
    errors = []
    for site in SITES:
        for network in NETWORKS:
            print("=" * 100)
            print(f"Code2 XHT | site={site['key']}/{site['tag']} | network={network}")
            print(f"Output root: {Path(BASE_OUTPUT_ROOT) / site['tag'] / _network_tag(network)}")
            try:
                run_one(site, network)
            except Exception as exc:
                msg = f"site={site['key']}, network={network}, error={exc!r}"
                print("[ERROR]", msg)
                traceback.print_exc()
                errors.append(msg)
                if STOP_ON_ERROR:
                    raise
    if errors:
        err_path = Path(BASE_OUTPUT_ROOT) / "errors_c2.txt"
        err_path.parent.mkdir(parents=True, exist_ok=True)
        err_path.write_text("\n".join(errors), encoding="utf-8")
        print(f"Finished with {len(errors)} errors. See: {err_path}")
    else:
        print("Code2 XHT finished without recorded errors.")


if __name__ == "__main__":
    main()
